/// Options for a tree view.
#[derive(Debug, Clone)]
pub struct ZxTreeViewOptions {
    pub show_collapse_all: bool,
    pub can_select_many: bool,
    pub drag_and_drop: bool,
    pub manage_checkboxes: bool,
}

impl ZxTreeViewOptions {
    pub fn new() -> Self {
        Self {
            show_collapse_all: false,
            can_select_many: false,
            drag_and_drop: false,
            manage_checkboxes: false,
        }
    }
}

/// A tree view that displays a hierarchical list.
#[derive(Debug, Clone)]
pub struct ZxTreeView {
    pub view_id: String,
    pub title: String,
    pub options: ZxTreeViewOptions,
    items: Vec<ZxTreeItem>,
    root_ids: Vec<String>,
    selection: Vec<String>,
    pub is_visible: bool,
    pub message: Option<String>,
    pub badge_count: Option<u32>,
}

impl ZxTreeView {
    pub fn new(view_id: &str, title: &str, options: ZxTreeViewOptions) -> Self {
        Self {
            view_id: view_id.to_string(),
            title: title.to_string(),
            options,
            items: Vec::new(),
            root_ids: Vec::new(),
            selection: Vec::new(),
            is_visible: true,
            message: None,
            badge_count: None,
        }
    }

    pub fn add_root(&mut self, item: ZxTreeItem) {
        self.root_ids.push(item.id.clone());
        self.items.push(item);
    }

    pub fn add_child_item(&mut self, parent_id: &str, item: ZxTreeItem) {
        let child_id = item.id.clone();
        self.items.push(item);
        if let Some(parent) = self.items.iter_mut().find(|i| i.id == parent_id) {
            parent.add_child(&child_id);
        }
    }

    pub fn get_item(&self, id: &str) -> Option<&ZxTreeItem> {
        self.items.iter().find(|i| i.id == id)
    }

    pub fn root_items(&self) -> Vec<&ZxTreeItem> {
        self.root_ids.iter().filter_map(|id| self.get_item(id)).collect()
    }

    pub fn children_of(&self, parent_id: &str) -> Vec<&ZxTreeItem> {
        if let Some(parent) = self.get_item(parent_id) {
            parent.children_ids.iter().filter_map(|id| self.get_item(id)).collect()
        } else {
            Vec::new()
        }
    }

    pub fn select(&mut self, id: &str) {
        if !self.options.can_select_many {
            self.selection.clear();
        }
        if !self.selection.contains(&id.to_string()) {
            self.selection.push(id.to_string());
        }
    }

    pub fn deselect(&mut self, id: &str) {
        self.selection.retain(|s| s != id);
    }

    pub fn selection(&self) -> &[String] {
        &self.selection
    }

    pub fn set_message(&mut self, msg: &str) {
        self.message = Some(msg.to_string());
    }

    pub fn set_badge(&mut self, count: u32) {
        self.badge_count = Some(count);
    }

    pub fn item_count(&self) -> usize {
        self.items.len()
    }

    pub fn reveal(&mut self, _id: &str) {
        self.is_visible = true;
    }
}


// --- zy_ keybinding and input handling types ---

/// Modifier keys for keybindings.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct ZyModifiers {
    pub ctrl: bool,
    pub shift: bool,
    pub alt: bool,
    pub meta: bool,
}

impl ZyModifiers {
    pub fn none() -> Self {
        Self { ctrl: false, shift: false, alt: false, meta: false }
    }

    pub fn ctrl() -> Self {
        Self { ctrl: true, shift: false, alt: false, meta: false }
    }

    pub fn ctrl_shift() -> Self {
        Self { ctrl: true, shift: true, alt: false, meta: false }
    }

    pub fn alt() -> Self {
        Self { ctrl: false, shift: false, alt: true, meta: false }
    }

    pub fn has_any(&self) -> bool {
        self.ctrl || self.shift || self.alt || self.meta
    }

    pub fn to_string_repr(&self) -> String {
        let mut parts = Vec::new();
        if self.ctrl { parts.push("Ctrl"); }
        if self.shift { parts.push("Shift"); }
        if self.alt { parts.push("Alt"); }
        if self.meta { parts.push("Meta"); }
        parts.join("+")
    }
}

/// A key code.
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub enum ZyKeyCode {
    Char(char),
    Enter,
    Escape,
    Tab,
    Backspace,
    Delete,
    Up,
    Down,
    Left,
    Right,
    Home,
    End,
    PageUp,
    PageDown,
    F(u8),
    Space,
}

impl ZyKeyCode {
    pub fn label(&self) -> String {
        match self {
            Self::Char(c) => c.to_uppercase().to_string(),
            Self::Enter => "Enter".to_string(),
            Self::Escape => "Escape".to_string(),
            Self::Tab => "Tab".to_string(),
            Self::Backspace => "Backspace".to_string(),
            Self::Delete => "Delete".to_string(),
            Self::Up => "Up".to_string(),
            Self::Down => "Down".to_string(),
            Self::Left => "Left".to_string(),
            Self::Right => "Right".to_string(),
            Self::Home => "Home".to_string(),
            Self::End => "End".to_string(),
            Self::PageUp => "PageUp".to_string(),
            Self::PageDown => "PageDown".to_string(),
            Self::F(n) => format!("F{}", n),
            Self::Space => "Space".to_string(),
        }
    }
}

/// A complete key combination (modifiers + key).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ZyKeyCombination {
    pub modifiers: ZyModifiers,
    pub key: ZyKeyCode,
}

impl ZyKeyCombination {
    pub fn new(modifiers: ZyModifiers, key: ZyKeyCode) -> Self {
        Self { modifiers, key }
    }

    pub fn simple(key: ZyKeyCode) -> Self {
        Self { modifiers: ZyModifiers::none(), key }
    }

    pub fn ctrl(key: ZyKeyCode) -> Self {
        Self { modifiers: ZyModifiers::ctrl(), key }
    }

    pub fn label(&self) -> String {
        let mods = self.modifiers.to_string_repr();
        if mods.is_empty() {
            self.key.label()
        } else {
            format!("{}+{}", mods, self.key.label())
        }
    }
}

/// A keybinding that maps a key combination to a command.
#[derive(Debug, Clone)]
pub struct ZyKeybinding {
    pub key: ZyKeyCombination,
    pub command: String,
    pub when: Option<String>,
    pub args: Option<String>,
    pub source: ZyKeybindingSource,
}

/// Source of a keybinding (default, user, extension).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ZyKeybindingSource {
    Default,
    User,
    Extension,
}

impl ZyKeybinding {
    pub fn new(key: ZyKeyCombination, command: &str) -> Self {
        Self {
            key,
            command: command.to_string(),
            when: None,
            args: None,
            source: ZyKeybindingSource::Default,
        }
    }

    pub fn with_when(mut self, when: &str) -> Self {
        self.when = Some(when.to_string());
        self
    }

    pub fn with_source(mut self, source: ZyKeybindingSource) -> Self {
        self.source = source;
        self
    }

    pub fn matches_context(&self, context_keys: &[(&str, bool)]) -> bool {
        match &self.when {
            None => true,
            Some(when) => {
                // Simple single-key when-clause evaluation
                if let Some(negated) = when.strip_prefix('!') {
                    context_keys.iter().find(|(k, _)| *k == negated).map_or(true, |(_, v)| !v)
                } else {
                    context_keys.iter().find(|(k, _)| *k == when.as_str()).map_or(false, |(_, v)| *v)
                }
            }
        }
    }
}

/// A keybinding resolver that finds the matching command for a key press.
#[derive(Debug, Clone)]
pub struct ZyKeybindingResolver {
    bindings: Vec<ZyKeybinding>,
}

impl ZyKeybindingResolver {
    pub fn new() -> Self {
        Self { bindings: Vec::new() }
    }

    pub fn add(&mut self, binding: ZyKeybinding) {
        self.bindings.push(binding);
    }

    pub fn resolve(&self, key: &ZyKeyCombination, context: &[(&str, bool)]) -> Option<&str> {
        // Later bindings (user/extension) override earlier ones (default)
        self.bindings.iter().rev()
            .find(|b| b.key == *key && b.matches_context(context))
            .map(|b| b.command.as_str())
    }

    pub fn bindings_for_command(&self, command: &str) -> Vec<&ZyKeybinding> {
        self.bindings.iter().filter(|b| b.command == command).collect()
    }

    pub fn all_bindings(&self) -> &[ZyKeybinding] {
        &self.bindings
    }

    pub fn remove_command(&mut self, command: &str) {
        self.bindings.retain(|b| b.command != command);
    }

    pub fn binding_count(&self) -> usize {
        self.bindings.len()
    }
}


// --- zz_ editor layout and window management types ---

/// Editor group layout direction.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ZzLayoutDirection {
    Horizontal,
    Vertical,
}

/// An editor group (a tab container).
#[derive(Debug, Clone)]
pub struct ZzEditorGroup {
    pub id: u32,
    pub tabs: Vec<ZzEditorTab>,
    pub active_tab: Option<usize>,
    pub is_active: bool,
    pub size: f32,
}

impl ZzEditorGroup {
    pub fn new(id: u32) -> Self {
        Self { id, tabs: Vec::new(), active_tab: None, is_active: false, size: 1.0 }
    }

    pub fn open_tab(&mut self, tab: ZzEditorTab) -> usize {
        // Check if already open
        if let Some(idx) = self.tabs.iter().position(|t| t.uri == tab.uri) {
            self.active_tab = Some(idx);
            return idx;
        }
        let idx = self.tabs.len();
        self.tabs.push(tab);
        self.active_tab = Some(idx);
        idx
    }

    pub fn close_tab(&mut self, idx: usize) -> Option<ZzEditorTab> {
        if idx >= self.tabs.len() {
            return None;
        }
        let tab = self.tabs.remove(idx);
        if self.tabs.is_empty() {
            self.active_tab = None;
        } else if let Some(active) = self.active_tab {
            if active >= self.tabs.len() {
                self.active_tab = Some(self.tabs.len() - 1);
            } else if active > idx {
                self.active_tab = Some(active - 1);
            }
        }
        Some(tab)
    }

    pub fn active_tab(&self) -> Option<&ZzEditorTab> {
        self.active_tab.and_then(|i| self.tabs.get(i))
    }

    pub fn tab_count(&self) -> usize {
        self.tabs.len()
    }

    pub fn is_empty(&self) -> bool {
        self.tabs.is_empty()
    }

    pub fn has_dirty_tabs(&self) -> bool {
        self.tabs.iter().any(|t| t.is_dirty)
    }

    pub fn dirty_tab_count(&self) -> usize {
        self.tabs.iter().filter(|t| t.is_dirty).count()
    }
}

/// A tab in an editor group.
#[derive(Debug, Clone)]
pub struct ZzEditorTab {
    pub uri: String,
    pub label: String,
    pub is_dirty: bool,
    pub is_pinned: bool,
    pub is_preview: bool,
    pub icon_id: Option<String>,
}

impl ZzEditorTab {
    pub fn new(uri: &str, label: &str) -> Self {
        Self {
            uri: uri.to_string(),
            label: label.to_string(),
            is_dirty: false,
            is_pinned: false,
            is_preview: false,
            icon_id: None,
        }
    }

    pub fn preview(uri: &str, label: &str) -> Self {
        Self { is_preview: true, ..Self::new(uri, label) }
    }

    pub fn pin(&mut self) {
        self.is_pinned = true;
        self.is_preview = false;
    }

    pub fn unpin(&mut self) {
        self.is_pinned = false;
    }

    pub fn mark_dirty(&mut self) {
        self.is_dirty = true;
    }

    pub fn mark_clean(&mut self) {
        self.is_dirty = false;
    }

    pub fn promote(&mut self) {
        self.is_preview = false;
    }
}

/// A split layout of editor groups.
#[derive(Debug, Clone)]
pub struct ZzEditorLayout {
    groups: Vec<ZzEditorGroup>,
    active_group: Option<usize>,
    direction: ZzLayoutDirection,
    next_group_id: u32,
}

impl ZzEditorLayout {
    pub fn new() -> Self {
        let mut layout = Self {
            groups: Vec::new(),
            active_group: None,
            direction: ZzLayoutDirection::Horizontal,
            next_group_id: 1,
        };
        layout.add_group();
        layout
    }

    pub fn add_group(&mut self) -> usize {
        let id = self.next_group_id;
        self.next_group_id += 1;
        let idx = self.groups.len();
        let mut group = ZzEditorGroup::new(id);
        if self.active_group.is_none() {
            group.is_active = true;
            self.active_group = Some(idx);
        }
        self.groups.push(group);
        self.rebalance();
        idx
    }

    pub fn remove_group(&mut self, idx: usize) -> bool {
        if self.groups.len() <= 1 || idx >= self.groups.len() {
            return false;
        }
        self.groups.remove(idx);
        if let Some(active) = self.active_group {
            if active == idx {
                self.active_group = Some(0);
                if let Some(g) = self.groups.get_mut(0) {
                    g.is_active = true;
                }
            } else if active > idx {
                self.active_group = Some(active - 1);
            }
        }
        self.rebalance();
        true
    }

    pub fn active_group(&self) -> Option<&ZzEditorGroup> {
        self.active_group.and_then(|i| self.groups.get(i))
    }

    pub fn active_group_mut(&mut self) -> Option<&mut ZzEditorGroup> {
        self.active_group.and_then(|i| self.groups.get_mut(i))
    }

    pub fn group(&self, idx: usize) -> Option<&ZzEditorGroup> {
        self.groups.get(idx)
    }

    pub fn group_mut(&mut self, idx: usize) -> Option<&mut ZzEditorGroup> {
        self.groups.get_mut(idx)
    }

    pub fn group_count(&self) -> usize {
        self.groups.len()
    }

    pub fn set_active(&mut self, idx: usize) {
        for (i, g) in self.groups.iter_mut().enumerate() {
            g.is_active = i == idx;
        }
        self.active_group = Some(idx);
    }

    pub fn set_direction(&mut self, dir: ZzLayoutDirection) {
        self.direction = dir;
    }

    pub fn direction(&self) -> ZzLayoutDirection {
        self.direction
    }

    fn rebalance(&mut self) {
        let count = self.groups.len() as f32;
        if count > 0.0 {
            let size = 1.0 / count;
            for g in &mut self.groups {
                g.size = size;
            }
        }
    }

    pub fn total_tabs(&self) -> usize {
        self.groups.iter().map(|g| g.tab_count()).sum()
    }

    pub fn find_tab(&self, uri: &str) -> Option<(usize, usize)> {
        for (gi, group) in self.groups.iter().enumerate() {
            if let Some(ti) = group.tabs.iter().position(|t| t.uri == uri) {
                return Some((gi, ti));
            }
        }
        None
    }
}


// --- axa_ LSP protocol message types ---

/// JSON-RPC message ID.
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub enum AxaRequestId {
    Number(i64),
    String(String),
}

impl AxaRequestId {
    pub fn num(n: i64) -> Self { Self::Number(n) }
    pub fn str(s: &str) -> Self { Self::String(s.to_string()) }
}

/// A JSON-RPC request message.
#[derive(Debug, Clone)]
pub struct AxaRequest {
    pub id: AxaRequestId,
    pub method: String,
    pub params: Option<String>,
}

impl AxaRequest {
    pub fn new(id: AxaRequestId, method: &str) -> Self {
        Self { id, method: method.to_string(), params: None }
    }

    pub fn with_params(mut self, params: &str) -> Self {
        self.params = Some(params.to_string());
        self
    }

    pub fn is_initialize(&self) -> bool {
        self.method == "initialize"
    }

    pub fn is_shutdown(&self) -> bool {
        self.method == "shutdown"
    }

    pub fn to_header(&self) -> String {
        let body = self.to_json();
        format!("Content-Length: {}\r\n\r\n{}", body.len(), body)
    }

    pub fn to_json(&self) -> String {
        match &self.params {
            Some(p) => format!(
                r#"{{"jsonrpc":"2.0","id":{},"method":"{}","params":{}}}"#,
                self.id_json(), self.method, p
            ),
            None => format!(
                r#"{{"jsonrpc":"2.0","id":{},"method":"{}"}}"#,
                self.id_json(), self.method
            ),
        }
    }

    fn id_json(&self) -> String {
        match &self.id {
            AxaRequestId::Number(n) => n.to_string(),
            AxaRequestId::String(s) => format!(r#""{}""#, s),
        }
    }
}

/// A JSON-RPC response.
#[derive(Debug, Clone)]
pub struct AxaResponse {
    pub id: AxaRequestId,
    pub result: Option<String>,
    pub error: Option<AxaResponseError>,
}

/// An error in a JSON-RPC response.
#[derive(Debug, Clone)]
pub struct AxaResponseError {
    pub code: i32,
    pub message: String,
    pub data: Option<String>,
}

impl AxaResponseError {
    pub fn new(code: i32, message: &str) -> Self {
        Self { code, message: message.to_string(), data: None }
    }

    pub fn parse_error() -> Self { Self::new(-32700, "Parse error") }
    pub fn invalid_request() -> Self { Self::new(-32600, "Invalid Request") }
    pub fn method_not_found() -> Self { Self::new(-32601, "Method not found") }
    pub fn invalid_params() -> Self { Self::new(-32602, "Invalid params") }
    pub fn internal_error() -> Self { Self::new(-32603, "Internal error") }
    pub fn server_not_initialized() -> Self { Self::new(-32002, "Server not initialized") }
    pub fn request_cancelled() -> Self { Self::new(-32800, "Request cancelled") }
}

impl AxaResponse {
    pub fn success(id: AxaRequestId, result: &str) -> Self {
        Self { id, result: Some(result.to_string()), error: None }
    }

    pub fn error(id: AxaRequestId, err: AxaResponseError) -> Self {
        Self { id, result: None, error: Some(err) }
    }

    pub fn is_success(&self) -> bool {
        self.error.is_none()
    }

    pub fn to_json(&self) -> String {
        let id_json = match &self.id {
            AxaRequestId::Number(n) => n.to_string(),
            AxaRequestId::String(s) => format!(r#""{}""#, s),
        };
        if let Some(err) = &self.error {
            format!(
                r#"{{"jsonrpc":"2.0","id":{},"error":{{"code":{},"message":"{}"}}}}"#,
                id_json, err.code, err.message
            )
        } else {
            format!(
                r#"{{"jsonrpc":"2.0","id":{},"result":{}}}"#,
                id_json, self.result.as_deref().unwrap_or("null")
            )
        }
    }
}

/// A JSON-RPC notification (no id, no response expected).
#[derive(Debug, Clone)]
pub struct AxaNotification {
    pub method: String,
    pub params: Option<String>,
}

impl AxaNotification {
    pub fn new(method: &str) -> Self {
        Self { method: method.to_string(), params: None }
    }

    pub fn with_params(mut self, params: &str) -> Self {
        self.params = Some(params.to_string());
        self
    }

    pub fn is_initialized(&self) -> bool {
        self.method == "initialized"
    }

    pub fn is_exit(&self) -> bool {
        self.method == "exit"
    }

    pub fn is_did_open(&self) -> bool {
        self.method == "textDocument/didOpen"
    }

    pub fn is_did_change(&self) -> bool {
        self.method == "textDocument/didChange"
    }

    pub fn is_did_save(&self) -> bool {
        self.method == "textDocument/didSave"
    }

    pub fn is_did_close(&self) -> bool {
        self.method == "textDocument/didClose"
    }

    pub fn to_json(&self) -> String {
        match &self.params {
            Some(p) => format!(r#"{{"jsonrpc":"2.0","method":"{}","params":{}}}"#, self.method, p),
            None => format!(r#"{{"jsonrpc":"2.0","method":"{}"}}"#, self.method),
        }
    }

    pub fn to_header(&self) -> String {
        let body = self.to_json();
        format!("Content-Length: {}\r\n\r\n{}", body.len(), body)
    }
}

/// Parse a Content-Length header from LSP stream bytes.
pub fn axa_parse_content_length(header: &str) -> Option<usize> {
    for line in header.lines() {
        let lower = line.to_lowercase();
        if lower.starts_with("content-length:") {
            let val = line.split(':').nth(1)?.trim();
            return val.parse().ok();
        }
    }
    None
}

/// LSP message dispatcher that routes methods to handlers.
#[derive(Debug, Clone)]
pub struct AxaDispatcher {
    handlers: Vec<(String, bool)>, // (method, is_notification)
}

impl AxaDispatcher {
    pub fn new() -> Self {
        Self { handlers: Vec::new() }
    }

    pub fn register_request(&mut self, method: &str) {
        self.handlers.push((method.to_string(), false));
    }

    pub fn register_notification(&mut self, method: &str) {
        self.handlers.push((method.to_string(), true));
    }

    pub fn can_handle(&self, method: &str) -> bool {
        self.handlers.iter().any(|(m, _)| m == method)
    }

    pub fn is_notification_handler(&self, method: &str) -> Option<bool> {
        self.handlers.iter().find(|(m, _)| m == method).map(|(_, is_notif)| *is_notif)
    }

    pub fn registered_methods(&self) -> Vec<&str> {
        self.handlers.iter().map(|(m, _)| m.as_str()).collect()
    }

    pub fn handler_count(&self) -> usize {
        self.handlers.len()
    }
}

/// Tracks pending requests awaiting responses.
#[derive(Debug, Clone)]
pub struct AxaPendingRequests {
    pending: Vec<(AxaRequestId, String, u64)>, // (id, method, timestamp)
}

impl AxaPendingRequests {
    pub fn new() -> Self {
        Self { pending: Vec::new() }
    }

    pub fn add(&mut self, id: AxaRequestId, method: &str, timestamp: u64) {
        self.pending.push((id, method.to_string(), timestamp));
    }

    pub fn remove(&mut self, id: &AxaRequestId) -> Option<(String, u64)> {
        if let Some(idx) = self.pending.iter().position(|(pid, _, _)| pid == id) {
            let (_, method, ts) = self.pending.remove(idx);
            Some((method, ts))
        } else {
            None
        }
    }

    pub fn is_pending(&self, id: &AxaRequestId) -> bool {
        self.pending.iter().any(|(pid, _, _)| pid == id)
    }

    pub fn pending_count(&self) -> usize {
        self.pending.len()
    }

    pub fn timed_out(&self, now: u64, timeout_ms: u64) -> Vec<&AxaRequestId> {
        self.pending.iter()
            .filter(|(_, _, ts)| now.saturating_sub(*ts) > timeout_ms)
            .map(|(id, _, _)| id)
            .collect()
    }
}


// --- axb_ LSP server capabilities and initialization ---

/// Text document sync kind.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AxbTextDocumentSyncKind {
    None,
    Full,
    Incremental,
}

impl AxbTextDocumentSyncKind {
    pub fn as_u8(&self) -> u8 {
        match self { Self::None => 0, Self::Full => 1, Self::Incremental => 2 }
    }
}

/// Completion trigger kinds.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AxbCompletionTriggerKind {
    Invoked,
    TriggerCharacter,
    TriggerForIncomplete,
}

/// Capabilities that a server can declare.
#[derive(Debug, Clone)]
pub struct AxbServerCapabilities {
    pub text_document_sync: AxbTextDocumentSyncKind,
    pub completion_provider: Option<AxbCompletionOptions>,
    pub hover_provider: bool,
    pub signature_help_provider: Option<AxbSignatureHelpOptions>,
    pub definition_provider: bool,
    pub type_definition_provider: bool,
    pub implementation_provider: bool,
    pub references_provider: bool,
    pub document_highlight_provider: bool,
    pub document_symbol_provider: bool,
    pub workspace_symbol_provider: bool,
    pub code_action_provider: bool,
    pub code_lens_provider: bool,
    pub document_formatting_provider: bool,
    pub document_range_formatting_provider: bool,
    pub rename_provider: bool,
    pub folding_range_provider: bool,
    pub selection_range_provider: bool,
    pub semantic_tokens_provider: bool,
    pub inlay_hint_provider: bool,
    pub diagnostic_provider: bool,
}

impl AxbServerCapabilities {
    pub fn empty() -> Self {
        Self {
            text_document_sync: AxbTextDocumentSyncKind::None,
            completion_provider: None,
            hover_provider: false,
            signature_help_provider: None,
            definition_provider: false,
            type_definition_provider: false,
            implementation_provider: false,
            references_provider: false,
            document_highlight_provider: false,
            document_symbol_provider: false,
            workspace_symbol_provider: false,
            code_action_provider: false,
            code_lens_provider: false,
            document_formatting_provider: false,
            document_range_formatting_provider: false,
            rename_provider: false,
            folding_range_provider: false,
            selection_range_provider: false,
            semantic_tokens_provider: false,
            inlay_hint_provider: false,
            diagnostic_provider: false,
        }
    }

    pub fn full() -> Self {
        Self {
            text_document_sync: AxbTextDocumentSyncKind::Incremental,
            completion_provider: Some(AxbCompletionOptions::default()),
            hover_provider: true,
            signature_help_provider: Some(AxbSignatureHelpOptions::default()),
            definition_provider: true,
            type_definition_provider: true,
            implementation_provider: true,
            references_provider: true,
            document_highlight_provider: true,
            document_symbol_provider: true,
            workspace_symbol_provider: true,
            code_action_provider: true,
            code_lens_provider: true,
            document_formatting_provider: true,
            document_range_formatting_provider: true,
            rename_provider: true,
            folding_range_provider: true,
            selection_range_provider: true,
            semantic_tokens_provider: true,
            inlay_hint_provider: true,
            diagnostic_provider: true,
        }
    }

    pub fn capability_count(&self) -> usize {
        let mut count = 0;
        if self.hover_provider { count += 1; }
        if self.definition_provider { count += 1; }
        if self.type_definition_provider { count += 1; }
        if self.implementation_provider { count += 1; }
        if self.references_provider { count += 1; }
        if self.document_highlight_provider { count += 1; }
        if self.document_symbol_provider { count += 1; }
        if self.workspace_symbol_provider { count += 1; }
        if self.code_action_provider { count += 1; }
        if self.code_lens_provider { count += 1; }
        if self.document_formatting_provider { count += 1; }
        if self.document_range_formatting_provider { count += 1; }
        if self.rename_provider { count += 1; }
        if self.folding_range_provider { count += 1; }
        if self.selection_range_provider { count += 1; }
        if self.semantic_tokens_provider { count += 1; }
        if self.inlay_hint_provider { count += 1; }
        if self.diagnostic_provider { count += 1; }
        if self.completion_provider.is_some() { count += 1; }
        if self.signature_help_provider.is_some() { count += 1; }
        count
    }
}

