/// LSP connection state machine.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AxbConnectionState {
    Disconnected,
    Connecting,
    Initializing,
    Ready,
    ShuttingDown,
}

impl AxbConnectionState {
    pub fn is_ready(&self) -> bool {
        matches!(self, Self::Ready)
    }

    pub fn can_send_requests(&self) -> bool {
        matches!(self, Self::Ready)
    }

    pub fn next_on_initialize_response(&self) -> Self {
        match self {
            Self::Initializing => Self::Ready,
            other => *other,
        }
    }

    pub fn next_on_shutdown_response(&self) -> Self {
        match self {
            Self::ShuttingDown => Self::Disconnected,
            other => *other,
        }
    }
}


// --- axc_ text document model and versioning ---

/// Identifies a text document via URI and version.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct AxcTextDocumentIdentifier {
    pub uri: String,
}

impl AxcTextDocumentIdentifier {
    pub fn new(uri: &str) -> Self {
        Self { uri: uri.to_string() }
    }
}

/// Versioned text document identifier.
#[derive(Debug, Clone)]
pub struct AxcVersionedTextDocumentId {
    pub uri: String,
    pub version: i32,
}

impl AxcVersionedTextDocumentId {
    pub fn new(uri: &str, version: i32) -> Self {
        Self { uri: uri.to_string(), version }
    }
}

/// A text document item (full content with metadata).
#[derive(Debug, Clone)]
pub struct AxcTextDocumentItem {
    pub uri: String,
    pub language_id: String,
    pub version: i32,
    pub text: String,
}

impl AxcTextDocumentItem {
    pub fn new(uri: &str, lang: &str, version: i32, text: &str) -> Self {
        Self {
            uri: uri.to_string(),
            language_id: lang.to_string(),
            version,
            text: text.to_string(),
        }
    }

    pub fn line_count(&self) -> usize {
        self.text.lines().count().max(1)
    }

    pub fn char_count(&self) -> usize {
        self.text.len()
    }

    pub fn line_at(&self, line: usize) -> Option<&str> {
        self.text.lines().nth(line)
    }

    pub fn offset_of(&self, line: u32, col: u32) -> Option<usize> {
        let mut offset = 0;
        for (i, l) in self.text.lines().enumerate() {
            if i == line as usize {
                if col as usize <= l.len() {
                    return Some(offset + col as usize);
                }
                return None;
            }
            offset += l.len() + 1; // +1 for newline
        }
        None
    }

    pub fn position_of(&self, offset: usize) -> Option<(u32, u32)> {
        let mut current = 0;
        for (i, line) in self.text.lines().enumerate() {
            let line_end = current + line.len();
            if offset <= line_end {
                return Some((i as u32, (offset - current) as u32));
            }
            current = line_end + 1;
        }
        None
    }
}

/// A content change event (incremental or full).
#[derive(Debug, Clone)]
pub struct AxcTextDocumentContentChange {
    pub range: Option<AxcRange>,
    pub text: String,
}

/// A range in a text document.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct AxcRange {
    pub start_line: u32,
    pub start_character: u32,
    pub end_line: u32,
    pub end_character: u32,
}

impl AxcRange {
    pub fn new(sl: u32, sc: u32, el: u32, ec: u32) -> Self {
        Self { start_line: sl, start_character: sc, end_line: el, end_character: ec }
    }

    pub fn is_empty(&self) -> bool {
        self.start_line == self.end_line && self.start_character == self.end_character
    }

    pub fn single_line(&self) -> bool {
        self.start_line == self.end_line
    }

    pub fn contains(&self, line: u32, col: u32) -> bool {
        if line < self.start_line || line > self.end_line { return false; }
        if line == self.start_line && col < self.start_character { return false; }
        if line == self.end_line && col > self.end_character { return false; }
        true
    }
}

impl AxcTextDocumentContentChange {
    pub fn full(text: &str) -> Self {
        Self { range: None, text: text.to_string() }
    }

    pub fn incremental(range: AxcRange, text: &str) -> Self {
        Self { range: Some(range), text: text.to_string() }
    }

    pub fn is_full(&self) -> bool {
        self.range.is_none()
    }
}

/// A managed text document that tracks version and applies changes.
#[derive(Debug, Clone)]
pub struct AxcManagedDocument {
    pub uri: String,
    pub language_id: String,
    pub version: i32,
    pub content: String,
    is_open: bool,
}

impl AxcManagedDocument {
    pub fn open(item: AxcTextDocumentItem) -> Self {
        Self {
            uri: item.uri,
            language_id: item.language_id,
            version: item.version,
            content: item.text,
            is_open: true,
        }
    }

    pub fn apply_change(&mut self, change: &AxcTextDocumentContentChange, new_version: i32) {
        if change.is_full() {
            self.content = change.text.clone();
        } else if let Some(range) = &change.range {
            let item = AxcTextDocumentItem::new(&self.uri, &self.language_id, self.version, &self.content);
            if let (Some(start), Some(end)) = (
                item.offset_of(range.start_line, range.start_character),
                item.offset_of(range.end_line, range.end_character),
            ) {
                let mut new_content = String::new();
                new_content.push_str(&self.content[..start]);
                new_content.push_str(&change.text);
                if end <= self.content.len() {
                    new_content.push_str(&self.content[end..]);
                }
                self.content = new_content;
            }
        }
        self.version = new_version;
    }

    pub fn close(&mut self) {
        self.is_open = false;
    }

    pub fn is_open(&self) -> bool {
        self.is_open
    }

    pub fn line_count(&self) -> usize {
        self.content.lines().count().max(1)
    }
}

/// Document store managing multiple open documents.
#[derive(Debug, Clone)]
pub struct AxcDocumentStore {
    documents: Vec<AxcManagedDocument>,
}

impl AxcDocumentStore {
    pub fn new() -> Self {
        Self { documents: Vec::new() }
    }

    pub fn open(&mut self, item: AxcTextDocumentItem) {
        // Close existing if any
        self.documents.retain(|d| d.uri != item.uri);
        self.documents.push(AxcManagedDocument::open(item));
    }

    pub fn get(&self, uri: &str) -> Option<&AxcManagedDocument> {
        self.documents.iter().find(|d| d.uri == uri && d.is_open())
    }

    pub fn get_mut(&mut self, uri: &str) -> Option<&mut AxcManagedDocument> {
        self.documents.iter_mut().find(|d| d.uri == uri && d.is_open())
    }

    pub fn close(&mut self, uri: &str) {
        if let Some(doc) = self.documents.iter_mut().find(|d| d.uri == uri) {
            doc.close();
        }
    }

    pub fn open_count(&self) -> usize {
        self.documents.iter().filter(|d| d.is_open()).count()
    }

    pub fn open_uris(&self) -> Vec<&str> {
        self.documents.iter().filter(|d| d.is_open()).map(|d| d.uri.as_str()).collect()
    }

    pub fn is_open(&self, uri: &str) -> bool {
        self.documents.iter().any(|d| d.uri == uri && d.is_open())
    }
}


// --- axd_ terminal rendering primitives ---

/// A terminal color.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AxdColor {
    Reset,
    Black,
    Red,
    Green,
    Yellow,
    Blue,
    Magenta,
    Cyan,
    White,
    BrightBlack,
    BrightRed,
    BrightGreen,
    BrightYellow,
    BrightBlue,
    BrightMagenta,
    BrightCyan,
    BrightWhite,
    Ansi256(u8),
    Rgb(u8, u8, u8),
}

impl AxdColor {
    pub fn from_hex(hex: &str) -> Option<Self> {
        let hex = hex.strip_prefix('#').unwrap_or(hex);
        if hex.len() != 6 { return None; }
        let r = u8::from_str_radix(&hex[0..2], 16).ok()?;
        let g = u8::from_str_radix(&hex[2..4], 16).ok()?;
        let b = u8::from_str_radix(&hex[4..6], 16).ok()?;
        Some(Self::Rgb(r, g, b))
    }

    pub fn to_ansi_fg(&self) -> String {
        match self {
            Self::Reset => "\x1b[39m".to_string(),
            Self::Black => "\x1b[30m".to_string(),
            Self::Red => "\x1b[31m".to_string(),
            Self::Green => "\x1b[32m".to_string(),
            Self::Yellow => "\x1b[33m".to_string(),
            Self::Blue => "\x1b[34m".to_string(),
            Self::Magenta => "\x1b[35m".to_string(),
            Self::Cyan => "\x1b[36m".to_string(),
            Self::White => "\x1b[37m".to_string(),
            Self::BrightBlack => "\x1b[90m".to_string(),
            Self::BrightRed => "\x1b[91m".to_string(),
            Self::BrightGreen => "\x1b[92m".to_string(),
            Self::BrightYellow => "\x1b[93m".to_string(),
            Self::BrightBlue => "\x1b[94m".to_string(),
            Self::BrightMagenta => "\x1b[95m".to_string(),
            Self::BrightCyan => "\x1b[96m".to_string(),
            Self::BrightWhite => "\x1b[97m".to_string(),
            Self::Ansi256(n) => format!("\x1b[38;5;{}m", n),
            Self::Rgb(r, g, b) => format!("\x1b[38;2;{};{};{}m", r, g, b),
        }
    }
}

/// Text style attributes.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub struct AxdStyle {
    pub bold: bool,
    pub italic: bool,
    pub underline: bool,
    pub strikethrough: bool,
    pub dim: bool,
    pub reverse: bool,
}

impl AxdStyle {
    pub fn new() -> Self { Self::default() }
    pub fn bold() -> Self { Self { bold: true, ..Self::default() } }
    pub fn italic() -> Self { Self { italic: true, ..Self::default() } }
    pub fn underline() -> Self { Self { underline: true, ..Self::default() } }

    pub fn has_any(&self) -> bool {
        self.bold || self.italic || self.underline || self.strikethrough || self.dim || self.reverse
    }

    pub fn merge(&self, other: &Self) -> Self {
        Self {
            bold: self.bold || other.bold,
            italic: self.italic || other.italic,
            underline: self.underline || other.underline,
            strikethrough: self.strikethrough || other.strikethrough,
            dim: self.dim || other.dim,
            reverse: self.reverse || other.reverse,
        }
    }
}

/// A styled cell in the terminal screen buffer.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct AxdCell {
    pub ch: char,
    pub fg: AxdColor,
    pub bg: AxdColor,
    pub style: AxdStyle,
}

impl AxdCell {
    pub fn new(ch: char) -> Self {
        Self { ch, fg: AxdColor::Reset, bg: AxdColor::Reset, style: AxdStyle::new() }
    }

    pub fn blank() -> Self { Self::new(' ') }

    pub fn with_fg(mut self, fg: AxdColor) -> Self { self.fg = fg; self }
    pub fn with_bg(mut self, bg: AxdColor) -> Self { self.bg = bg; self }
    pub fn with_style(mut self, style: AxdStyle) -> Self { self.style = style; self }

    pub fn is_blank(&self) -> bool {
        self.ch == ' ' && self.fg == AxdColor::Reset && self.bg == AxdColor::Reset && !self.style.has_any()
    }
}

/// A screen buffer for double-buffered terminal rendering.
#[derive(Debug, Clone)]
pub struct AxdScreenBuffer {
    pub width: u16,
    pub height: u16,
    cells: Vec<AxdCell>,
}

impl AxdScreenBuffer {
    pub fn new(width: u16, height: u16) -> Self {
        let size = (width as usize) * (height as usize);
        Self { width, height, cells: vec![AxdCell::blank(); size] }
    }

    pub fn get(&self, x: u16, y: u16) -> Option<&AxdCell> {
        if x < self.width && y < self.height {
            Some(&self.cells[(y as usize) * (self.width as usize) + (x as usize)])
        } else {
            None
        }
    }

    pub fn set(&mut self, x: u16, y: u16, cell: AxdCell) {
        if x < self.width && y < self.height {
            self.cells[(y as usize) * (self.width as usize) + (x as usize)] = cell;
        }
    }

    pub fn put_str(&mut self, x: u16, y: u16, s: &str, fg: AxdColor, bg: AxdColor, style: AxdStyle) {
        for (i, ch) in s.chars().enumerate() {
            let col = x + i as u16;
            if col < self.width {
                self.set(col, y, AxdCell { ch, fg, bg, style });
            }
        }
    }

    pub fn clear(&mut self) {
        for cell in &mut self.cells {
            *cell = AxdCell::blank();
        }
    }

    pub fn resize(&mut self, width: u16, height: u16) {
        let size = (width as usize) * (height as usize);
        self.cells = vec![AxdCell::blank(); size];
        self.width = width;
        self.height = height;
    }

    pub fn diff(&self, other: &AxdScreenBuffer) -> Vec<(u16, u16, AxdCell)> {
        let mut changes = Vec::new();
        if self.width != other.width || self.height != other.height {
            return changes;
        }
        for y in 0..self.height {
            for x in 0..self.width {
                let idx = (y as usize) * (self.width as usize) + (x as usize);
                if self.cells[idx] != other.cells[idx] {
                    changes.push((x, y, self.cells[idx].clone()));
                }
            }
        }
        changes
    }

    pub fn fill_row(&mut self, y: u16, cell: &AxdCell) {
        for x in 0..self.width {
            self.set(x, y, cell.clone());
        }
    }

    pub fn cell_count(&self) -> usize {
        self.cells.len()
    }
}


// --- axe_ command palette and quick pick types ---

/// A registered command with handler info.
#[derive(Debug, Clone)]
pub struct AxeCommand {
    pub id: String,
    pub title: String,
    pub category: Option<String>,
    pub keybinding: Option<String>,
    pub enabled: bool,
    pub when: Option<String>,
}

impl AxeCommand {
    pub fn new(id: &str, title: &str) -> Self {
        Self {
            id: id.to_string(),
            title: title.to_string(),
            category: None,
            keybinding: None,
            enabled: true,
            when: None,
        }
    }

    pub fn with_category(mut self, cat: &str) -> Self {
        self.category = Some(cat.to_string());
        self
    }

    pub fn with_keybinding(mut self, kb: &str) -> Self {
        self.keybinding = Some(kb.to_string());
        self
    }

    pub fn with_when(mut self, when: &str) -> Self {
        self.when = Some(when.to_string());
        self
    }

    pub fn display_label(&self) -> String {
        match &self.category {
            Some(cat) => format!("{}: {}", cat, self.title),
            None => self.title.clone(),
        }
    }

    pub fn matches_query(&self, query: &str) -> bool {
        if query.is_empty() { return true; }
        let q = query.to_lowercase();
        self.title.to_lowercase().contains(&q)
            || self.id.to_lowercase().contains(&q)
            || self.category.as_ref().map_or(false, |c| c.to_lowercase().contains(&q))
    }

    pub fn fuzzy_score(&self, query: &str) -> u32 {
        if query.is_empty() { return 0; }
        let q = query.to_lowercase();
        let label = self.display_label().to_lowercase();
        let mut score = 0u32;
        let mut qi = 0;
        let q_chars: Vec<char> = q.chars().collect();
        for (i, ch) in label.chars().enumerate() {
            if qi < q_chars.len() && ch == q_chars[qi] {
                score += if i == 0 || label.as_bytes().get(i.wrapping_sub(1)) == Some(&b' ') { 10 } else { 1 };
                qi += 1;
            }
        }
        if qi == q_chars.len() { score } else { 0 }
    }
}

/// A quick pick item.
#[derive(Debug, Clone)]
pub struct AxeQuickPickItem {
    pub label: String,
    pub description: Option<String>,
    pub detail: Option<String>,
    pub picked: bool,
    pub always_show: bool,
    pub kind: AxeQuickPickItemKind,
}

/// Kind of quick pick item.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AxeQuickPickItemKind {
    Default,
    Separator,
}

impl AxeQuickPickItem {
    pub fn new(label: &str) -> Self {
        Self {
            label: label.to_string(),
            description: None,
            detail: None,
            picked: false,
            always_show: false,
            kind: AxeQuickPickItemKind::Default,
        }
    }

    pub fn separator(label: &str) -> Self {
        Self { kind: AxeQuickPickItemKind::Separator, ..Self::new(label) }
    }

    pub fn with_description(mut self, desc: &str) -> Self {
        self.description = Some(desc.to_string());
        self
    }

    pub fn with_detail(mut self, detail: &str) -> Self {
        self.detail = Some(detail.to_string());
        self
    }

    pub fn is_separator(&self) -> bool {
        self.kind == AxeQuickPickItemKind::Separator
    }
}

/// Quick pick options.
#[derive(Debug, Clone)]
pub struct AxeQuickPickOptions {
    pub placeholder: Option<String>,
    pub title: Option<String>,
    pub can_pick_many: bool,
    pub match_on_description: bool,
    pub match_on_detail: bool,
    pub ignore_focus_out: bool,
}

impl AxeQuickPickOptions {
    pub fn new() -> Self {
        Self {
            placeholder: None,
            title: None,
            can_pick_many: false,
            match_on_description: false,
            match_on_detail: false,
            ignore_focus_out: false,
        }
    }

    pub fn with_placeholder(mut self, ph: &str) -> Self {
        self.placeholder = Some(ph.to_string());
        self
    }

    pub fn with_title(mut self, t: &str) -> Self {
        self.title = Some(t.to_string());
        self
    }

    pub fn multi_select(mut self) -> Self {
        self.can_pick_many = true;
        self
    }
}

/// A quick pick session with filtered items.
#[derive(Debug, Clone)]
pub struct AxeQuickPick {
    pub items: Vec<AxeQuickPickItem>,
    pub options: AxeQuickPickOptions,
    pub filter: String,
    pub selected_index: usize,
    pub is_active: bool,
}

impl AxeQuickPick {
    pub fn new(items: Vec<AxeQuickPickItem>, options: AxeQuickPickOptions) -> Self {
        Self { items, options, filter: String::new(), selected_index: 0, is_active: true }
    }

    pub fn set_filter(&mut self, filter: &str) {
        self.filter = filter.to_string();
        self.selected_index = 0;
    }

    pub fn filtered_items(&self) -> Vec<(usize, &AxeQuickPickItem)> {
        if self.filter.is_empty() {
            return self.items.iter().enumerate().collect();
        }
        let q = self.filter.to_lowercase();
        self.items.iter().enumerate().filter(|(_, item)| {
            if item.is_separator() { return item.always_show; }
            item.label.to_lowercase().contains(&q)
                || (self.options.match_on_description
                    && item.description.as_ref().map_or(false, |d| d.to_lowercase().contains(&q)))
                || (self.options.match_on_detail
                    && item.detail.as_ref().map_or(false, |d| d.to_lowercase().contains(&q)))
        }).collect()
    }

    pub fn move_up(&mut self) {
        self.selected_index = self.selected_index.saturating_sub(1);
    }

    pub fn move_down(&mut self) {
        let max = self.filtered_items().len().saturating_sub(1);
        if self.selected_index < max {
            self.selected_index += 1;
        }
    }

    pub fn accept(&self) -> Option<&AxeQuickPickItem> {
        self.filtered_items().get(self.selected_index).map(|(_, item)| *item)
    }

    pub fn dismiss(&mut self) {
        self.is_active = false;
    }
}

/// Command palette (> prefix in quick pick).
#[derive(Debug, Clone)]
pub struct AxeCommandPalette {
    commands: Vec<AxeCommand>,
    pub filter: String,
}

impl AxeCommandPalette {
    pub fn new() -> Self {
        Self { commands: Vec::new(), filter: String::new() }
    }

    pub fn register(&mut self, cmd: AxeCommand) {
        self.commands.push(cmd);
    }

    pub fn set_filter(&mut self, filter: &str) {
        self.filter = filter.to_string();
    }

    pub fn filtered_commands(&self) -> Vec<&AxeCommand> {
        let mut matched: Vec<(&AxeCommand, u32)> = self.commands.iter()
            .filter(|c| c.enabled && c.matches_query(&self.filter))
            .map(|c| (c, c.fuzzy_score(&self.filter)))
            .collect();
        matched.sort_by(|a, b| b.1.cmp(&a.1));
        matched.into_iter().map(|(c, _)| c).collect()
    }

    pub fn execute(&self, id: &str) -> Option<&AxeCommand> {
        self.commands.iter().find(|c| c.id == id && c.enabled)
    }

    pub fn command_count(&self) -> usize {
        self.commands.len()
    }
}


// --- axf_ extension host process management and IPC ---

/// Extension host process state.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AxfHostState {
    NotStarted,
    Starting,
    Running,
    Crashed,
    Terminated,
}

impl AxfHostState {
    pub fn is_running(&self) -> bool { matches!(self, Self::Running) }
    pub fn is_alive(&self) -> bool { matches!(self, Self::Starting | Self::Running) }
}

/// IPC message types between main process and extension host.
#[derive(Debug, Clone)]
pub enum AxfIpcMessage {
    Request { id: u64, method: String, args: String },
    Response { id: u64, result: std::result::Result<String, String> },
    Event { event: String, data: String },
    Cancel { id: u64 },
}

impl AxfIpcMessage {
    pub fn request(id: u64, method: &str, args: &str) -> Self {
        Self::Request { id, method: method.to_string(), args: args.to_string() }
    }

    pub fn success(id: u64, result: &str) -> Self {
        Self::Response { id, result: Ok(result.to_string()) }
    }

    pub fn failure(id: u64, error: &str) -> Self {
        Self::Response { id, result: Err(error.to_string()) }
    }

    pub fn event(event: &str, data: &str) -> Self {
        Self::Event { event: event.to_string(), data: data.to_string() }
    }

    pub fn cancel(id: u64) -> Self {
        Self::Cancel { id }
    }

    pub fn is_request(&self) -> bool { matches!(self, Self::Request { .. }) }
    pub fn is_response(&self) -> bool { matches!(self, Self::Response { .. }) }
    pub fn is_event(&self) -> bool { matches!(self, Self::Event { .. }) }
}

/// An IPC channel that queues messages.
#[derive(Debug, Clone)]
pub struct AxfIpcChannel {
    outgoing: Vec<AxfIpcMessage>,
    incoming: Vec<AxfIpcMessage>,
    next_id: u64,
}

impl AxfIpcChannel {
    pub fn new() -> Self {
        Self { outgoing: Vec::new(), incoming: Vec::new(), next_id: 1 }
    }

    pub fn send_request(&mut self, method: &str, args: &str) -> u64 {
        let id = self.next_id;
        self.next_id += 1;
        self.outgoing.push(AxfIpcMessage::request(id, method, args));
        id
    }

    pub fn send_event(&mut self, event: &str, data: &str) {
        self.outgoing.push(AxfIpcMessage::event(event, data));
    }

    pub fn send_response(&mut self, id: u64, result: &str) {
        self.outgoing.push(AxfIpcMessage::success(id, result));
    }

    pub fn send_error(&mut self, id: u64, error: &str) {
        self.outgoing.push(AxfIpcMessage::failure(id, error));
    }

    pub fn receive(&mut self, msg: AxfIpcMessage) {
        self.incoming.push(msg);
    }

    pub fn drain_outgoing(&mut self) -> Vec<AxfIpcMessage> {
        std::mem::take(&mut self.outgoing)
    }

    pub fn drain_incoming(&mut self) -> Vec<AxfIpcMessage> {
        std::mem::take(&mut self.incoming)
    }

    pub fn pending_outgoing(&self) -> usize {
        self.outgoing.len()
    }

    pub fn pending_incoming(&self) -> usize {
        self.incoming.len()
    }
}

/// An extension host process descriptor.
#[derive(Debug, Clone)]
pub struct AxfExtensionHost {
    pub id: String,
    pub kind: AxfHostKind,
    pub state: AxfHostState,
    pub pid: Option<u32>,
    pub channel: AxfIpcChannel,
    pub extensions: Vec<String>,
    pub start_time: Option<u64>,
    pub crash_count: u32,
}

/// Kind of extension host.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AxfHostKind {
    Local,
    Remote,
    Web,
}

impl AxfExtensionHost {
    pub fn new(id: &str, kind: AxfHostKind) -> Self {
        Self {
            id: id.to_string(),
            kind,
            state: AxfHostState::NotStarted,
            pid: None,
            channel: AxfIpcChannel::new(),
            extensions: Vec::new(),
            start_time: None,
            crash_count: 0,
        }
    }

    pub fn start(&mut self, pid: u32, time: u64) {
        self.state = AxfHostState::Starting;
        self.pid = Some(pid);
        self.start_time = Some(time);
    }

    pub fn mark_ready(&mut self) {
        self.state = AxfHostState::Running;
    }

    pub fn crash(&mut self) {
        self.state = AxfHostState::Crashed;
        self.crash_count += 1;
    }

    pub fn terminate(&mut self) {
        self.state = AxfHostState::Terminated;
        self.pid = None;
    }

    pub fn register_extension(&mut self, ext_id: &str) {
        if !self.extensions.contains(&ext_id.to_string()) {
            self.extensions.push(ext_id.to_string());
        }
    }

    pub fn extension_count(&self) -> usize {
        self.extensions.len()
    }

    pub fn should_restart(&self) -> bool {
        self.state == AxfHostState::Crashed && self.crash_count < 3
    }

    pub fn uptime(&self, now: u64) -> Option<u64> {
        self.start_time.map(|t| now.saturating_sub(t))
    }
}

/// Extension host manager that oversees multiple hosts.
#[derive(Debug, Clone)]
pub struct AxfHostManager {
    hosts: Vec<AxfExtensionHost>,
}

impl AxfHostManager {
    pub fn new() -> Self {
        Self { hosts: Vec::new() }
    }

    pub fn create_host(&mut self, id: &str, kind: AxfHostKind) -> usize {
        let idx = self.hosts.len();
        self.hosts.push(AxfExtensionHost::new(id, kind));
        idx
    }

    pub fn host(&self, idx: usize) -> Option<&AxfExtensionHost> {
        self.hosts.get(idx)
    }

    pub fn host_mut(&mut self, idx: usize) -> Option<&mut AxfExtensionHost> {
        self.hosts.get_mut(idx)
    }

    pub fn running_hosts(&self) -> Vec<&AxfExtensionHost> {
        self.hosts.iter().filter(|h| h.state.is_running()).collect()
    }

    pub fn crashed_hosts(&self) -> Vec<&AxfExtensionHost> {
        self.hosts.iter().filter(|h| h.state == AxfHostState::Crashed).collect()
    }

    pub fn host_count(&self) -> usize {
        self.hosts.len()
    }

    pub fn total_extensions(&self) -> usize {
        self.hosts.iter().map(|h| h.extension_count()).sum()
    }

    pub fn find_host_for_extension(&self, ext_id: &str) -> Option<usize> {
        self.hosts.iter().position(|h| h.extensions.contains(&ext_id.to_string()))
    }

    pub fn terminate_all(&mut self) {
        for host in &mut self.hosts {
            if host.state.is_alive() {
                host.terminate();
            }
        }
    }
}


// --- axg_ workspace file watcher and event system ---

/// File system event type.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AxgFsEventKind {
    Created,
    Changed,
    Deleted,
    Renamed,
}

/// A file system event.
#[derive(Debug, Clone)]
pub struct AxgFsEvent {
    pub kind: AxgFsEventKind,
    pub path: String,
    pub old_path: Option<String>,
    pub timestamp: u64,
    pub is_directory: bool,
}

impl AxgFsEvent {
    pub fn created(path: &str, ts: u64, is_dir: bool) -> Self {
        Self { kind: AxgFsEventKind::Created, path: path.to_string(), old_path: None, timestamp: ts, is_directory: is_dir }
    }

    pub fn changed(path: &str, ts: u64) -> Self {
        Self { kind: AxgFsEventKind::Changed, path: path.to_string(), old_path: None, timestamp: ts, is_directory: false }
    }

    pub fn deleted(path: &str, ts: u64, is_dir: bool) -> Self {
        Self { kind: AxgFsEventKind::Deleted, path: path.to_string(), old_path: None, timestamp: ts, is_directory: is_dir }
    }

    pub fn renamed(old_path: &str, new_path: &str, ts: u64) -> Self {
        Self { kind: AxgFsEventKind::Renamed, path: new_path.to_string(), old_path: Some(old_path.to_string()), timestamp: ts, is_directory: false }
    }
}

/// A glob pattern for watching.
#[derive(Debug, Clone)]
pub struct AxgWatchPattern {
    pub base_path: String,
    pub include_pattern: String,
    pub exclude_patterns: Vec<String>,
    pub recursive: bool,
}

impl AxgWatchPattern {
    pub fn new(base: &str, include: &str) -> Self {
        Self { base_path: base.to_string(), include_pattern: include.to_string(), exclude_patterns: Vec::new(), recursive: true }
    }

    pub fn exclude(mut self, pattern: &str) -> Self {
        self.exclude_patterns.push(pattern.to_string());
        self
    }

    pub fn non_recursive(mut self) -> Self {
        self.recursive = false;
        self
    }

    /// Simple matching: checks if path starts with base and the filename matches the include pattern.
    pub fn matches(&self, path: &str) -> bool {
        if !path.starts_with(&self.base_path) { return false; }
        let relative = &path[self.base_path.len()..].trim_start_matches('/');
        if !self.recursive && relative.contains('/') { return false; }
        for ex in &self.exclude_patterns {
            if relative.contains(ex.as_str()) { return false; }
        }
        // Simple glob: * matches anything
        if self.include_pattern == "**" || self.include_pattern == "*" { return true; }
        if let Some(ext) = self.include_pattern.strip_prefix("*.") {
            return relative.ends_with(&format!(".{}", ext));
        }
        relative.contains(&self.include_pattern)
    }
}

/// A file watcher subscription.
#[derive(Debug, Clone)]
pub struct AxgWatchSubscription {
    pub id: u64,
    pub pattern: AxgWatchPattern,
    pub active: bool,
}

impl AxgWatchSubscription {
    pub fn new(id: u64, pattern: AxgWatchPattern) -> Self {
        Self { id, pattern, active: true }
    }

    pub fn pause(&mut self) { self.active = false; }
    pub fn resume(&mut self) { self.active = true; }
}

/// File watcher service managing subscriptions and dispatching events.
#[derive(Debug, Clone)]
pub struct AxgFileWatcher {
    subscriptions: Vec<AxgWatchSubscription>,
    event_queue: Vec<AxgFsEvent>,
    next_id: u64,
    debounce_ms: u64,
}

impl AxgFileWatcher {
    pub fn new(debounce_ms: u64) -> Self {
        Self { subscriptions: Vec::new(), event_queue: Vec::new(), next_id: 1, debounce_ms }
    }

    pub fn watch(&mut self, pattern: AxgWatchPattern) -> u64 {
        let id = self.next_id;
        self.next_id += 1;
        self.subscriptions.push(AxgWatchSubscription::new(id, pattern));
        id
    }

    pub fn unwatch(&mut self, id: u64) -> bool {
        let before = self.subscriptions.len();
        self.subscriptions.retain(|s| s.id != id);
        self.subscriptions.len() < before
    }

    pub fn push_event(&mut self, event: AxgFsEvent) {
        self.event_queue.push(event);
    }

    pub fn drain_events(&mut self) -> Vec<AxgFsEvent> {
        std::mem::take(&mut self.event_queue)
    }

    pub fn matching_subscriptions(&self, path: &str) -> Vec<u64> {
        self.subscriptions.iter()
            .filter(|s| s.active && s.pattern.matches(path))
            .map(|s| s.id)
            .collect()
    }

    pub fn subscription_count(&self) -> usize {
        self.subscriptions.len()
    }

    pub fn active_count(&self) -> usize {
        self.subscriptions.iter().filter(|s| s.active).count()
    }

    pub fn debounce_ms(&self) -> u64 {
        self.debounce_ms
    }

    pub fn pause_subscription(&mut self, id: u64) {
        if let Some(s) = self.subscriptions.iter_mut().find(|s| s.id == id) {
            s.pause();
        }
    }

    pub fn resume_subscription(&mut self, id: u64) {
        if let Some(s) = self.subscriptions.iter_mut().find(|s| s.id == id) {
            s.resume();
        }
    }
}


// --- axh_ output channel and logging types ---

/// Log level.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub enum AxhLogLevel {
    Trace,
    Debug,
    Info,
    Warning,
    Error,
    Off,
}

impl AxhLogLevel {
    pub fn label(&self) -> &str {
        match self {
            Self::Trace => "trace",
            Self::Debug => "debug",
            Self::Info => "info",
            Self::Warning => "warning",
            Self::Error => "error",
            Self::Off => "off",
        }
    }
}

/// An output channel that collects log messages.
#[derive(Debug, Clone)]
pub struct AxhOutputChannel {
    pub name: String,
    pub language_id: Option<String>,
    lines: Vec<String>,
    pub is_visible: bool,
    pub is_log_channel: bool,
    pub log_level: AxhLogLevel,
}

impl AxhOutputChannel {
    pub fn new(name: &str) -> Self {
        Self {
            name: name.to_string(),
            language_id: None,
            lines: Vec::new(),
            is_visible: false,
            is_log_channel: false,
            log_level: AxhLogLevel::Info,
        }
    }

    pub fn log_channel(name: &str, lang_id: &str) -> Self {
        Self {
            language_id: Some(lang_id.to_string()),
            is_log_channel: true,
            ..Self::new(name)
        }
    }

    pub fn append(&mut self, text: &str) {
        if let Some(last) = self.lines.last_mut() {
            last.push_str(text);
        } else {
            self.lines.push(text.to_string());
        }
    }

    pub fn append_line(&mut self, text: &str) {
        self.lines.push(text.to_string());
    }

    pub fn log(&mut self, level: AxhLogLevel, message: &str) {
        if level >= self.log_level {
            self.append_line(&format!("[{}] {}", level.label(), message));
        }
    }

    pub fn trace(&mut self, msg: &str) { self.log(AxhLogLevel::Trace, msg); }
    pub fn debug(&mut self, msg: &str) { self.log(AxhLogLevel::Debug, msg); }
    pub fn info(&mut self, msg: &str) { self.log(AxhLogLevel::Info, msg); }
    pub fn warn(&mut self, msg: &str) { self.log(AxhLogLevel::Warning, msg); }
    pub fn error(&mut self, msg: &str) { self.log(AxhLogLevel::Error, msg); }

    pub fn clear(&mut self) { self.lines.clear(); }
    pub fn show(&mut self) { self.is_visible = true; }
    pub fn hide(&mut self) { self.is_visible = false; }

    pub fn line_count(&self) -> usize { self.lines.len() }
    pub fn content(&self) -> String { self.lines.join("\n") }
    pub fn lines(&self) -> &[String] { &self.lines }

    pub fn replace(&mut self, text: &str) {
        self.lines.clear();
        self.lines.push(text.to_string());
    }
}

/// Registry of output channels.
#[derive(Debug, Clone)]
pub struct AxhOutputRegistry {
    channels: Vec<AxhOutputChannel>,
    active_channel: Option<usize>,
}

impl AxhOutputRegistry {
    pub fn new() -> Self {
        Self { channels: Vec::new(), active_channel: None }
    }

    pub fn create(&mut self, name: &str) -> usize {
        let idx = self.channels.len();
        self.channels.push(AxhOutputChannel::new(name));
        idx
    }

    pub fn create_log(&mut self, name: &str, lang_id: &str) -> usize {
        let idx = self.channels.len();
        self.channels.push(AxhOutputChannel::log_channel(name, lang_id));
        idx
    }

    pub fn get(&self, idx: usize) -> Option<&AxhOutputChannel> {
        self.channels.get(idx)
    }

    pub fn get_mut(&mut self, idx: usize) -> Option<&mut AxhOutputChannel> {
        self.channels.get_mut(idx)
    }

    pub fn find_by_name(&self, name: &str) -> Option<usize> {
        self.channels.iter().position(|c| c.name == name)
    }

    pub fn set_active(&mut self, idx: usize) {
        if idx < self.channels.len() {
            if let Some(old) = self.active_channel {
                if let Some(ch) = self.channels.get_mut(old) { ch.hide(); }
            }
            self.channels[idx].show();
            self.active_channel = Some(idx);
        }
    }

    pub fn active_channel(&self) -> Option<&AxhOutputChannel> {
        self.active_channel.and_then(|i| self.channels.get(i))
    }

    pub fn channel_count(&self) -> usize {
        self.channels.len()
    }

    pub fn channel_names(&self) -> Vec<&str> {
        self.channels.iter().map(|c| c.name.as_str()).collect()
    }

    pub fn dispose(&mut self, idx: usize) -> bool {
        if idx < self.channels.len() {
            self.channels.remove(idx);
            if self.active_channel == Some(idx) {
                self.active_channel = None;
            } else if let Some(active) = self.active_channel {
                if active > idx {
                    self.active_channel = Some(active - 1);
                }
            }
            true
        } else {
            false
        }
    }
}


// --- axi_ snippet and template engine ---

/// A tabstop in a snippet.
#[derive(Debug, Clone)]
pub struct AxiTabStop {
    pub index: u32,
    pub placeholder: Option<String>,
    pub choices: Vec<String>,
}

impl AxiTabStop {
    pub fn simple(index: u32) -> Self {
        Self { index, placeholder: None, choices: Vec::new() }
    }

    pub fn with_placeholder(index: u32, placeholder: &str) -> Self {
        Self { index, placeholder: Some(placeholder.to_string()), choices: Vec::new() }
    }

    pub fn with_choices(index: u32, choices: Vec<String>) -> Self {
        Self { index, placeholder: None, choices }
    }

    pub fn default_value(&self) -> &str {
        self.placeholder.as_deref()
            .or_else(|| self.choices.first().map(|s| s.as_str()))
            .unwrap_or("")
    }

    pub fn has_choices(&self) -> bool { !self.choices.is_empty() }
}

/// A parsed snippet with text and tabstops.
#[derive(Debug, Clone)]
pub struct AxiSnippet {
    pub prefix: String,
    pub name: String,
    pub description: Option<String>,
    pub body: String,
    pub scope: Option<String>,
    tabstops: Vec<AxiTabStop>,
}

impl AxiSnippet {
    pub fn new(name: &str, prefix: &str, body: &str) -> Self {
        let mut snippet = Self {
            prefix: prefix.to_string(),
            name: name.to_string(),
            description: None,
            body: body.to_string(),
            scope: None,
            tabstops: Vec::new(),
        };
        snippet.parse_tabstops();
        snippet
    }

    pub fn with_description(mut self, desc: &str) -> Self {
        self.description = Some(desc.to_string());
        self
    }

    pub fn with_scope(mut self, scope: &str) -> Self {
        self.scope = Some(scope.to_string());
        self
    }

    fn parse_tabstops(&mut self) {
        let mut idx = 0;
        let chars: Vec<char> = self.body.chars().collect();
        while idx < chars.len() {
            if chars[idx] == '$' && idx + 1 < chars.len() {
                if chars[idx + 1].is_ascii_digit() {
                    let n = (chars[idx + 1] as u32) - ('0' as u32);
                    self.tabstops.push(AxiTabStop::simple(n));
                    idx += 2;
                    continue;
                } else if chars[idx + 1] == '{' {
                    if let Some(end) = chars[idx+2..].iter().position(|&c| c == '}') {
                        let inner: String = chars[idx+2..idx+2+end].iter().collect();
                        if let Some((num_str, rest)) = inner.split_once(':') {
                            if let Ok(n) = num_str.parse::<u32>() {
                                if rest.starts_with('|') && rest.ends_with('|') {
                                    let choices: Vec<String> = rest[1..rest.len()-1].split(',').map(|s| s.to_string()).collect();
                                    self.tabstops.push(AxiTabStop::with_choices(n, choices));
                                } else {
                                    self.tabstops.push(AxiTabStop::with_placeholder(n, rest));
                                }
                            }
                        } else if let Ok(n) = inner.parse::<u32>() {
                            self.tabstops.push(AxiTabStop::simple(n));
                        }
                        idx += end + 3;
                        continue;
                    }
                }
            }
            idx += 1;
        }
    }

    pub fn tabstops(&self) -> &[AxiTabStop] { &self.tabstops }
    pub fn tabstop_count(&self) -> usize { self.tabstops.len() }
    pub fn max_tabstop(&self) -> u32 { self.tabstops.iter().map(|t| t.index).max().unwrap_or(0) }

    /// Expand the snippet, replacing tabstops with provided values.
    pub fn expand(&self, values: &[(u32, &str)]) -> String {
        let mut result = self.body.clone();
        for (idx, val) in values {
            let patterns = [
                format!("${{{}}}", idx),
                format!("${}", idx),
            ];
            for pattern in &patterns {
                result = result.replace(pattern, val);
            }
            // Also replace ${idx:placeholder}
            let prefix = format!("${{{}:", idx);
            while let Some(start) = result.find(&prefix) {
                if let Some(end) = result[start..].find('}') {
                    result = format!("{}{}{}", &result[..start], val, &result[start+end+1..]);
                } else {
                    break;
                }
            }
        }
        result
    }

    pub fn matches_prefix(&self, input: &str) -> bool {
        self.prefix.starts_with(input)
    }
}

/// A collection of snippets for a language.
#[derive(Debug, Clone)]
pub struct AxiSnippetCollection {
    pub language_id: String,
    snippets: Vec<AxiSnippet>,
}

impl AxiSnippetCollection {
    pub fn new(language_id: &str) -> Self {
        Self { language_id: language_id.to_string(), snippets: Vec::new() }
    }

    pub fn add(&mut self, snippet: AxiSnippet) {
        self.snippets.push(snippet);
    }

    pub fn find_by_prefix(&self, prefix: &str) -> Vec<&AxiSnippet> {
        self.snippets.iter().filter(|s| s.matches_prefix(prefix)).collect()
    }

    pub fn all(&self) -> &[AxiSnippet] { &self.snippets }
    pub fn count(&self) -> usize { self.snippets.len() }
}


// --- axj_ progress reporting and notification types ---

/// Location where progress should be shown.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AxjProgressLocation {
    SourceControl,
    Window,
    Notification,
}

/// A progress report update.
#[derive(Debug, Clone)]
pub struct AxjProgressReport {
    pub message: Option<String>,
    pub increment: Option<u32>,
}

impl AxjProgressReport {
    pub fn message(msg: &str) -> Self {
        Self { message: Some(msg.to_string()), increment: None }
    }

    pub fn increment(n: u32) -> Self {
        Self { message: None, increment: Some(n) }
    }

    pub fn both(msg: &str, n: u32) -> Self {
        Self { message: Some(msg.to_string()), increment: Some(n) }
    }
}

/// A progress task.
#[derive(Debug, Clone)]
pub struct AxjProgress {
    pub title: String,
    pub location: AxjProgressLocation,
    pub cancellable: bool,
    pub current: u32,
    pub total: u32,
    pub message: String,
    cancelled: bool,
    done: bool,
}

impl AxjProgress {
    pub fn new(title: &str, location: AxjProgressLocation, cancellable: bool) -> Self {
        Self {
            title: title.to_string(),
            location,
            cancellable,
            current: 0,
            total: 100,
            message: String::new(),
            cancelled: false,
            done: false,
        }
    }

    pub fn report(&mut self, report: AxjProgressReport) {
        if let Some(msg) = report.message {
            self.message = msg;
        }
        if let Some(inc) = report.increment {
            self.current = (self.current + inc).min(self.total);
        }
    }

    pub fn cancel(&mut self) {
        if self.cancellable {
            self.cancelled = true;
        }
    }

    pub fn finish(&mut self) {
        self.done = true;
        self.current = self.total;
    }

    pub fn is_cancelled(&self) -> bool { self.cancelled }
    pub fn is_done(&self) -> bool { self.done }
    pub fn percentage(&self) -> f32 { (self.current as f32 / self.total as f32) * 100.0 }
}

/// Notification severity.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AxjNotificationSeverity {
    Information,
    Warning,
    Error,
}

/// An action button on a notification.
#[derive(Debug, Clone)]
pub struct AxjNotificationAction {
    pub title: String,
    pub is_close_affordance: bool,
}

impl AxjNotificationAction {
    pub fn new(title: &str) -> Self {
        Self { title: title.to_string(), is_close_affordance: false }
    }

    pub fn close_affordance(title: &str) -> Self {
        Self { title: title.to_string(), is_close_affordance: true }
    }
}

/// A notification message.
#[derive(Debug, Clone)]
pub struct AxjNotification {
    pub severity: AxjNotificationSeverity,
    pub message: String,
    pub detail: Option<String>,
    pub actions: Vec<AxjNotificationAction>,
    pub modal: bool,
    dismissed: bool,
    pub source: Option<String>,
}

impl AxjNotification {
    pub fn info(message: &str) -> Self {
        Self::new(AxjNotificationSeverity::Information, message)
    }

    pub fn warning(message: &str) -> Self {
        Self::new(AxjNotificationSeverity::Warning, message)
    }

    pub fn error(message: &str) -> Self {
        Self::new(AxjNotificationSeverity::Error, message)
    }

    fn new(severity: AxjNotificationSeverity, message: &str) -> Self {
        Self {
            severity,
            message: message.to_string(),
            detail: None,
            actions: Vec::new(),
            modal: false,
            dismissed: false,
            source: None,
        }
    }

    pub fn with_detail(mut self, detail: &str) -> Self {
        self.detail = Some(detail.to_string());
        self
    }

    pub fn with_actions(mut self, actions: Vec<AxjNotificationAction>) -> Self {
        self.actions = actions;
        self
    }

    pub fn as_modal(mut self) -> Self {
        self.modal = true;
        self
    }

    pub fn from_source(mut self, source: &str) -> Self {
        self.source = Some(source.to_string());
        self
    }

    pub fn dismiss(&mut self) { self.dismissed = true; }
    pub fn is_dismissed(&self) -> bool { self.dismissed }
    pub fn has_actions(&self) -> bool { !self.actions.is_empty() }
}

/// Notification center collecting active notifications.
#[derive(Debug, Clone)]
pub struct AxjNotificationCenter {
    notifications: Vec<AxjNotification>,
    max_visible: usize,
}

impl AxjNotificationCenter {
    pub fn new(max_visible: usize) -> Self {
        Self { notifications: Vec::new(), max_visible }
    }

    pub fn show(&mut self, notification: AxjNotification) -> usize {
        let idx = self.notifications.len();
        self.notifications.push(notification);
        idx
    }

    pub fn dismiss(&mut self, idx: usize) {
        if let Some(n) = self.notifications.get_mut(idx) {
            n.dismiss();
        }
    }

    pub fn dismiss_all(&mut self) {
        for n in &mut self.notifications {
            n.dismiss();
        }
    }

    pub fn visible(&self) -> Vec<&AxjNotification> {
        self.notifications.iter()
            .filter(|n| !n.is_dismissed())
            .take(self.max_visible)
            .collect()
    }

    pub fn total_count(&self) -> usize { self.notifications.len() }
    pub fn active_count(&self) -> usize { self.notifications.iter().filter(|n| !n.is_dismissed()).count() }
}


// --- axk_ editor cursor model and selection logic ---

/// A cursor position in a document (line, column).
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub struct AxkCursorPosition {
    pub line: u32,
    pub column: u32,
}

impl AxkCursorPosition {
    pub fn new(line: u32, column: u32) -> Self {
        Self { line, column }
    }

    pub fn origin() -> Self { Self { line: 0, column: 0 } }

    pub fn move_right(&self, max_col: u32) -> Self {
        if self.column < max_col {
            Self { line: self.line, column: self.column + 1 }
        } else {
            *self
        }
    }

    pub fn move_left(&self) -> Self {
        Self { line: self.line, column: self.column.saturating_sub(1) }
    }

    pub fn move_up(&self) -> Self {
        Self { line: self.line.saturating_sub(1), column: self.column }
    }

    pub fn move_down(&self, max_line: u32) -> Self {
        if self.line < max_line {
            Self { line: self.line + 1, column: self.column }
        } else {
            *self
        }
    }

    pub fn start_of_line(&self) -> Self {
        Self { line: self.line, column: 0 }
    }

    pub fn end_of_line(&self, line_len: u32) -> Self {
        Self { line: self.line, column: line_len }
    }

    pub fn clamp_column(&self, line_len: u32) -> Self {
        Self { line: self.line, column: self.column.min(line_len) }
    }
}

/// A selection range with anchor and active positions.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct AxkSelection {
    pub anchor: AxkCursorPosition,
    pub active: AxkCursorPosition,
}

impl AxkSelection {
    pub fn new(anchor: AxkCursorPosition, active: AxkCursorPosition) -> Self {
        Self { anchor, active }
    }

    pub fn caret(pos: AxkCursorPosition) -> Self {
        Self { anchor: pos, active: pos }
    }

    pub fn is_empty(&self) -> bool {
        self.anchor == self.active
    }

    pub fn is_reversed(&self) -> bool {
        self.anchor > self.active
    }

    pub fn start(&self) -> AxkCursorPosition {
        if self.anchor <= self.active { self.anchor } else { self.active }
    }

    pub fn end(&self) -> AxkCursorPosition {
        if self.anchor >= self.active { self.anchor } else { self.active }
    }

    pub fn line_count(&self) -> u32 {
        let s = self.start();
        let e = self.end();
        e.line - s.line + 1
    }

    pub fn contains(&self, pos: AxkCursorPosition) -> bool {
        pos >= self.start() && pos <= self.end()
    }

    pub fn extend_to(&self, pos: AxkCursorPosition) -> Self {
        Self { anchor: self.anchor, active: pos }
    }

    pub fn select_line(line: u32, line_len: u32) -> Self {
        Self {
            anchor: AxkCursorPosition::new(line, 0),
            active: AxkCursorPosition::new(line, line_len),
        }
    }
}

/// Cursor style/shape.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AxkCursorStyle {
    Line,
    Block,
    Underline,
    LineThin,
    BlockOutline,
    UnderlineThin,
}

/// Multi-cursor state (VS Code supports multiple cursors).
#[derive(Debug, Clone)]
pub struct AxkMultiCursor {
    pub selections: Vec<AxkSelection>,
    pub style: AxkCursorStyle,
    pub desired_column: Option<u32>,
}

impl AxkMultiCursor {
    pub fn new(pos: AxkCursorPosition) -> Self {
        Self {
            selections: vec![AxkSelection::caret(pos)],
            style: AxkCursorStyle::Line,
            desired_column: None,
        }
    }

    pub fn primary(&self) -> AxkSelection {
        self.selections.last().cloned().unwrap_or_else(|| AxkSelection::caret(AxkCursorPosition::origin()))
    }

    pub fn primary_position(&self) -> AxkCursorPosition {
        self.primary().active
    }

    pub fn set_position(&mut self, pos: AxkCursorPosition) {
        self.selections = vec![AxkSelection::caret(pos)];
        self.desired_column = Some(pos.column);
    }

    pub fn set_selection(&mut self, sel: AxkSelection) {
        self.selections = vec![sel];
    }

    pub fn add_cursor(&mut self, pos: AxkCursorPosition) {
        // Don't add duplicate
        if !self.selections.iter().any(|s| s.active == pos && s.is_empty()) {
            self.selections.push(AxkSelection::caret(pos));
        }
    }

    pub fn add_selection(&mut self, sel: AxkSelection) {
        self.selections.push(sel);
    }

    pub fn remove_cursor(&mut self, idx: usize) {
        if self.selections.len() > 1 && idx < self.selections.len() {
            self.selections.remove(idx);
        }
    }

    pub fn cursor_count(&self) -> usize {
        self.selections.len()
    }

    pub fn has_multiple(&self) -> bool {
        self.selections.len() > 1
    }

    pub fn has_selection(&self) -> bool {
        self.selections.iter().any(|s| !s.is_empty())
    }

    pub fn collapse_to_single(&mut self) {
        if let Some(last) = self.selections.last().cloned() {
            self.selections = vec![last];
        }
    }

    pub fn move_all_right(&mut self, max_cols: &[u32]) {
        for (i, sel) in self.selections.iter_mut().enumerate() {
            let max = max_cols.get(sel.active.line as usize).copied().unwrap_or(0);
            let new_pos = sel.active.move_right(max);
            *sel = AxkSelection::caret(new_pos);
        }
        self.desired_column = self.selections.last().map(|s| s.active.column);
    }

    pub fn move_all_left(&mut self) {
        for sel in &mut self.selections {
            let new_pos = sel.active.move_left();
            *sel = AxkSelection::caret(new_pos);
        }
        self.desired_column = self.selections.last().map(|s| s.active.column);
    }

    pub fn move_all_up(&mut self) {
        for sel in &mut self.selections {
            let mut new_pos = sel.active.move_up();
            if let Some(dc) = self.desired_column {
                new_pos.column = dc;
            }
            *sel = AxkSelection::caret(new_pos);
        }
    }

    pub fn move_all_down(&mut self, max_line: u32) {
        for sel in &mut self.selections {
            let mut new_pos = sel.active.move_down(max_line);
            if let Some(dc) = self.desired_column {
                new_pos.column = dc;
            }
            *sel = AxkSelection::caret(new_pos);
        }
    }

    pub fn select_all_right(&mut self, max_cols: &[u32]) {
        for sel in &mut self.selections {
            let max = max_cols.get(sel.active.line as usize).copied().unwrap_or(0);
            let new_active = sel.active.move_right(max);
            sel.active = new_active;
        }
    }

    pub fn select_all_left(&mut self) {
        for sel in &mut self.selections {
            sel.active = sel.active.move_left();
        }
    }
}


// --- axl_ search and replace engine ---

/// Search options flags.
#[derive(Debug, Clone)]
pub struct AxlSearchOptions {
    pub case_sensitive: bool,
    pub whole_word: bool,
    pub is_regex: bool,
    pub preserve_case: bool,
    pub multiline: bool,
}

impl AxlSearchOptions {
    pub fn new() -> Self {
        Self { case_sensitive: false, whole_word: false, is_regex: false, preserve_case: false, multiline: false }
    }

    pub fn case_sensitive(mut self) -> Self { self.case_sensitive = true; self }
    pub fn whole_word(mut self) -> Self { self.whole_word = true; self }
    pub fn regex(mut self) -> Self { self.is_regex = true; self }
}

/// A match found in text.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct AxlSearchMatch {
    pub line: u32,
    pub start_col: u32,
    pub end_col: u32,
    pub matched_text: String,
}

impl AxlSearchMatch {
    pub fn new(line: u32, start_col: u32, end_col: u32, text: &str) -> Self {
        Self { line, start_col, end_col, matched_text: text.to_string() }
    }

    pub fn length(&self) -> u32 { self.end_col - self.start_col }
}

/// Core text search engine.
#[derive(Debug, Clone)]
pub struct AxlSearchEngine {
    pub pattern: String,
    pub options: AxlSearchOptions,
}

impl AxlSearchEngine {
    pub fn new(pattern: &str, options: AxlSearchOptions) -> Self {
        Self { pattern: pattern.to_string(), options }
    }

    /// Search within a single line. Returns all matches.
    pub fn search_line(&self, line_num: u32, text: &str) -> Vec<AxlSearchMatch> {
        let mut matches = Vec::new();
        if self.pattern.is_empty() { return matches; }

        let (search_text, search_pattern) = if self.options.case_sensitive {
            (text.to_string(), self.pattern.clone())
        } else {
            (text.to_lowercase(), self.pattern.to_lowercase())
        };

        let mut start = 0;
        while let Some(pos) = search_text[start..].find(&search_pattern) {
            let abs_pos = start + pos;
            let end_pos = abs_pos + search_pattern.len();

            if self.options.whole_word {
                let before_ok = abs_pos == 0 || !search_text.as_bytes()[abs_pos - 1].is_ascii_alphanumeric();
                let after_ok = end_pos >= search_text.len() || !search_text.as_bytes()[end_pos].is_ascii_alphanumeric();
                if !before_ok || !after_ok {
                    start = abs_pos + 1;
                    continue;
                }
            }

            let matched = &text[abs_pos..abs_pos + self.pattern.len()];
            matches.push(AxlSearchMatch::new(line_num, abs_pos as u32, end_pos as u32, matched));
            start = end_pos;
        }
        matches
    }

    /// Search all lines.
    pub fn search_all(&self, lines: &[&str]) -> Vec<AxlSearchMatch> {
        let mut all = Vec::new();
        for (i, line) in lines.iter().enumerate() {
            all.extend(self.search_line(i as u32, line));
        }
        all
    }

    pub fn match_count(&self, lines: &[&str]) -> usize {
        self.search_all(lines).len()
    }
}

/// Result of a replace operation.
#[derive(Debug, Clone)]
pub struct AxlReplaceResult {
    pub original: String,
    pub replacement: String,
    pub line: u32,
    pub start_col: u32,
    pub end_col: u32,
}

/// Search and replace engine.
#[derive(Debug, Clone)]
pub struct AxlSearchReplace {
    pub search: AxlSearchEngine,
    pub replace_pattern: String,
}

impl AxlSearchReplace {
    pub fn new(search: &str, replace: &str, options: AxlSearchOptions) -> Self {
        Self {
            search: AxlSearchEngine::new(search, options),
            replace_pattern: replace.to_string(),
        }
    }

    pub fn replace_in_line(&self, line_num: u32, text: &str) -> (String, Vec<AxlReplaceResult>) {
        let matches = self.search.search_line(line_num, text);
        if matches.is_empty() {
            return (text.to_string(), Vec::new());
        }

        let mut result = String::new();
        let mut results = Vec::new();
        let mut last_end = 0usize;

        for m in &matches {
            result.push_str(&text[last_end..m.start_col as usize]);
            result.push_str(&self.replace_pattern);
            results.push(AxlReplaceResult {
                original: m.matched_text.clone(),
                replacement: self.replace_pattern.clone(),
                line: line_num,
                start_col: m.start_col,
                end_col: m.end_col,
            });
            last_end = m.end_col as usize;
        }
        result.push_str(&text[last_end..]);
        (result, results)
    }

    pub fn replace_first_in_line(&self, line_num: u32, text: &str) -> (String, Option<AxlReplaceResult>) {
        let matches = self.search.search_line(line_num, text);
        if let Some(m) = matches.first() {
            let mut result = String::new();
            result.push_str(&text[..m.start_col as usize]);
            result.push_str(&self.replace_pattern);
            result.push_str(&text[m.end_col as usize..]);
            let rr = AxlReplaceResult {
                original: m.matched_text.clone(),
                replacement: self.replace_pattern.clone(),
                line: line_num,
                start_col: m.start_col,
                end_col: m.end_col,
            };
            (result, Some(rr))
        } else {
            (text.to_string(), None)
        }
    }
}

/// File-level search result.
#[derive(Debug, Clone)]
pub struct AxlFileSearchResult {
    pub uri: String,
    pub matches: Vec<AxlSearchMatch>,
}

impl AxlFileSearchResult {
    pub fn new(uri: &str, matches: Vec<AxlSearchMatch>) -> Self {
        Self { uri: uri.to_string(), matches }
    }

    pub fn match_count(&self) -> usize { self.matches.len() }
    pub fn line_count(&self) -> usize {
        let mut lines: Vec<u32> = self.matches.iter().map(|m| m.line).collect();
        lines.sort();
        lines.dedup();
        lines.len()
    }
}

/// Workspace-level search results.
#[derive(Debug, Clone)]
pub struct AxlWorkspaceSearchResults {
    pub results: Vec<AxlFileSearchResult>,
    pub query: String,
}

impl AxlWorkspaceSearchResults {
    pub fn new(query: &str) -> Self {
        Self { results: Vec::new(), query: query.to_string() }
    }

    pub fn add(&mut self, result: AxlFileSearchResult) {
        self.results.push(result);
    }

    pub fn total_matches(&self) -> usize { self.results.iter().map(|r| r.match_count()).sum() }
    pub fn file_count(&self) -> usize { self.results.len() }
    pub fn has_results(&self) -> bool { !self.results.is_empty() }
}


// --- axm_ Git integration types ---

/// Git file status.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AxmGitStatus {
    Unmodified,
    Modified,
    Added,
    Deleted,
    Renamed,
    Copied,
    Untracked,
    Ignored,
    Conflicted,
}

impl AxmGitStatus {
    pub fn letter(&self) -> char {
        match self {
            Self::Unmodified => ' ',
            Self::Modified => 'M',
            Self::Added => 'A',
            Self::Deleted => 'D',
            Self::Renamed => 'R',
            Self::Copied => 'C',
            Self::Untracked => '?',
            Self::Ignored => '!',
            Self::Conflicted => 'U',
        }
    }

    pub fn is_changed(&self) -> bool {
        !matches!(self, Self::Unmodified | Self::Ignored)
    }
}

/// A file in the git status.
#[derive(Debug, Clone)]
pub struct AxmStatusEntry {
    pub path: String,
    pub index_status: AxmGitStatus,
    pub working_status: AxmGitStatus,
    pub original_path: Option<String>,
}

impl AxmStatusEntry {
    pub fn new(path: &str, index: AxmGitStatus, working: AxmGitStatus) -> Self {
        Self { path: path.to_string(), index_status: index, working_status: working, original_path: None }
    }

    pub fn renamed(old_path: &str, new_path: &str) -> Self {
        Self {
            path: new_path.to_string(),
            index_status: AxmGitStatus::Renamed,
            working_status: AxmGitStatus::Unmodified,
            original_path: Some(old_path.to_string()),
        }
    }

    pub fn is_staged(&self) -> bool { self.index_status.is_changed() }
    pub fn is_unstaged(&self) -> bool { self.working_status.is_changed() }
    pub fn is_untracked(&self) -> bool { self.index_status == AxmGitStatus::Untracked }
}

/// A diff hunk.
#[derive(Debug, Clone)]
pub struct AxmDiffHunk {
    pub old_start: u32,
    pub old_count: u32,
    pub new_start: u32,
    pub new_count: u32,
    pub header: String,
    pub lines: Vec<AxmDiffLine>,
}

impl AxmDiffHunk {
    pub fn new(old_start: u32, old_count: u32, new_start: u32, new_count: u32) -> Self {
        Self {
            old_start, old_count, new_start, new_count,
            header: format!("@@ -{},{} +{},{} @@", old_start, old_count, new_start, new_count),
            lines: Vec::new(),
        }
    }

    pub fn add_line(&mut self, line: AxmDiffLine) { self.lines.push(line); }
    pub fn added_count(&self) -> usize { self.lines.iter().filter(|l| l.is_added()).count() }
    pub fn removed_count(&self) -> usize { self.lines.iter().filter(|l| l.is_removed()).count() }
}

/// A line in a diff.
#[derive(Debug, Clone)]
pub struct AxmDiffLine {
    pub kind: AxmDiffLineKind,
    pub content: String,
    pub old_line_num: Option<u32>,
    pub new_line_num: Option<u32>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AxmDiffLineKind { Context, Added, Removed }

impl AxmDiffLine {
    pub fn context(content: &str, old: u32, new: u32) -> Self {
        Self { kind: AxmDiffLineKind::Context, content: content.to_string(), old_line_num: Some(old), new_line_num: Some(new) }
    }
    pub fn added(content: &str, new: u32) -> Self {
        Self { kind: AxmDiffLineKind::Added, content: content.to_string(), old_line_num: None, new_line_num: Some(new) }
    }
    pub fn removed(content: &str, old: u32) -> Self {
        Self { kind: AxmDiffLineKind::Removed, content: content.to_string(), old_line_num: Some(old), new_line_num: None }
    }
    pub fn is_added(&self) -> bool { self.kind == AxmDiffLineKind::Added }
    pub fn is_removed(&self) -> bool { self.kind == AxmDiffLineKind::Removed }
    pub fn prefix(&self) -> char {
        match self.kind { AxmDiffLineKind::Context => ' ', AxmDiffLineKind::Added => '+', AxmDiffLineKind::Removed => '-' }
    }
}

/// A blame entry for a line.
#[derive(Debug, Clone)]
pub struct AxmBlameLine {
    pub commit_hash: String,
    pub author: String,
    pub date: String,
    pub line_number: u32,
    pub content: String,
}

impl AxmBlameLine {
    pub fn new(hash: &str, author: &str, date: &str, line: u32, content: &str) -> Self {
        Self { commit_hash: hash.to_string(), author: author.to_string(), date: date.to_string(), line_number: line, content: content.to_string() }
    }

    pub fn short_hash(&self) -> &str {
        if self.commit_hash.len() >= 7 { &self.commit_hash[..7] } else { &self.commit_hash }
    }
}

/// Git repository state.
#[derive(Debug, Clone)]
pub struct AxmGitRepo {
    pub root_path: String,
    pub branch: String,
    pub remote_branch: Option<String>,
    pub ahead: u32,
    pub behind: u32,
    pub status: Vec<AxmStatusEntry>,
    pub is_rebasing: bool,
    pub is_merging: bool,
}

impl AxmGitRepo {
    pub fn new(root: &str, branch: &str) -> Self {
        Self {
            root_path: root.to_string(),
            branch: branch.to_string(),
            remote_branch: None, ahead: 0, behind: 0,
            status: Vec::new(), is_rebasing: false, is_merging: false,
        }
    }

    pub fn staged_count(&self) -> usize { self.status.iter().filter(|s| s.is_staged()).count() }
    pub fn unstaged_count(&self) -> usize { self.status.iter().filter(|s| s.is_unstaged()).count() }
    pub fn untracked_count(&self) -> usize { self.status.iter().filter(|s| s.is_untracked()).count() }
    pub fn has_changes(&self) -> bool { !self.status.is_empty() }
    pub fn is_clean(&self) -> bool { self.status.is_empty() }
    pub fn is_in_progress(&self) -> bool { self.is_rebasing || self.is_merging }
    pub fn sync_status(&self) -> String {
        match (self.ahead, self.behind) {
            (0, 0) => "synced".to_string(),
            (a, 0) => format!("{}↑", a),
            (0, b) => format!("{}↓", b),
            (a, b) => format!("{}↑ {}↓", a, b),
        }
    }
}


// --- axn_ terminal multiplexer and PTY types ---

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum AxnShellType { Bash, Zsh, Fish, Powershell, Cmd, Custom(String) }

impl AxnShellType {
    pub fn default_path(&self) -> &str {
        match self { Self::Bash => "/bin/bash", Self::Zsh => "/bin/zsh", Self::Fish => "/usr/bin/fish", Self::Powershell => "pwsh", Self::Cmd => "cmd.exe", Self::Custom(p) => p }
    }
    pub fn label(&self) -> &str {
        match self { Self::Bash => "bash", Self::Zsh => "zsh", Self::Fish => "fish", Self::Powershell => "PowerShell", Self::Cmd => "Command Prompt", Self::Custom(_) => "Custom" }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct AxnTerminalSize { pub cols: u16, pub rows: u16 }

impl AxnTerminalSize {
    pub fn new(cols: u16, rows: u16) -> Self { Self { cols, rows } }
    pub fn default_size() -> Self { Self { cols: 80, rows: 24 } }
    pub fn cell_count(&self) -> u32 { self.cols as u32 * self.rows as u32 }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AxnTerminalState { Starting, Running, Exited(i32) }

impl AxnTerminalState {
    pub fn is_running(&self) -> bool { matches!(self, Self::Running) }
    pub fn exit_code(&self) -> Option<i32> { if let Self::Exited(c) = self { Some(*c) } else { None } }
}

#[derive(Debug, Clone)]
pub struct AxnTerminalInstance {
    pub id: u32, pub name: String, pub shell: AxnShellType, pub cwd: String,
    pub size: AxnTerminalSize, pub state: AxnTerminalState, pub pid: Option<u32>,
    output_buffer: Vec<String>, input_buffer: Vec<String>,
    pub icon: Option<String>, pub color: Option<String>,
}

impl AxnTerminalInstance {
    pub fn new(id: u32, name: &str, shell: AxnShellType, cwd: &str) -> Self {
        Self { id, name: name.to_string(), shell, cwd: cwd.to_string(), size: AxnTerminalSize::default_size(), state: AxnTerminalState::Starting, pid: None, output_buffer: Vec::new(), input_buffer: Vec::new(), icon: None, color: None }
    }
    pub fn start(&mut self, pid: u32) { self.pid = Some(pid); self.state = AxnTerminalState::Running; }
    pub fn write_output(&mut self, data: &str) { self.output_buffer.push(data.to_string()); }
    pub fn send_input(&mut self, data: &str) { self.input_buffer.push(data.to_string()); }
    pub fn drain_output(&mut self) -> Vec<String> { std::mem::take(&mut self.output_buffer) }
    pub fn drain_input(&mut self) -> Vec<String> { std::mem::take(&mut self.input_buffer) }
    pub fn resize(&mut self, size: AxnTerminalSize) { self.size = size; }
    pub fn exit(&mut self, code: i32) { self.state = AxnTerminalState::Exited(code); self.pid = None; }
    pub fn is_running(&self) -> bool { self.state.is_running() }
    pub fn set_name(&mut self, name: &str) { self.name = name.to_string(); }
    pub fn set_icon(&mut self, icon: &str) { self.icon = Some(icon.to_string()); }
    pub fn set_color(&mut self, color: &str) { self.color = Some(color.to_string()); }
}

#[derive(Debug, Clone)]
pub struct AxnTerminalManager {
    terminals: Vec<AxnTerminalInstance>, active_id: Option<u32>, next_id: u32,
    default_shell: AxnShellType, default_cwd: String,
}

impl AxnTerminalManager {
    pub fn new(default_shell: AxnShellType, default_cwd: &str) -> Self {
        Self { terminals: Vec::new(), active_id: None, next_id: 1, default_shell, default_cwd: default_cwd.to_string() }
    }
    pub fn create(&mut self, name: Option<&str>) -> u32 {
        let id = self.next_id; self.next_id += 1;
        let n = name.unwrap_or_else(|| self.default_shell.label());
        let term = AxnTerminalInstance::new(id, n, self.default_shell.clone(), &self.default_cwd);
        self.terminals.push(term);
        if self.active_id.is_none() { self.active_id = Some(id); }
        id
    }
    pub fn get(&self, id: u32) -> Option<&AxnTerminalInstance> { self.terminals.iter().find(|t| t.id == id) }
    pub fn get_mut(&mut self, id: u32) -> Option<&mut AxnTerminalInstance> { self.terminals.iter_mut().find(|t| t.id == id) }
    pub fn set_active(&mut self, id: u32) { self.active_id = Some(id); }
    pub fn active(&self) -> Option<&AxnTerminalInstance> { self.active_id.and_then(|id| self.get(id)) }
    pub fn terminate(&mut self, id: u32) { if let Some(t) = self.get_mut(id) { t.exit(-1); } }
    pub fn dispose(&mut self, id: u32) {
        self.terminals.retain(|t| t.id != id);
        if self.active_id == Some(id) { self.active_id = self.terminals.first().map(|t| t.id); }
    }
    pub fn count(&self) -> usize { self.terminals.len() }
    pub fn running_count(&self) -> usize { self.terminals.iter().filter(|t| t.is_running()).count() }
    pub fn ids(&self) -> Vec<u32> { self.terminals.iter().map(|t| t.id).collect() }
}


// --- axo_ breadcrumb navigation and symbol outline ---

/// Kind of breadcrumb element.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AxoBreadcrumbKind { File, Folder, Module, Class, Method, Function, Property, Enum, Interface, Constant, Variable, Namespace }

impl AxoBreadcrumbKind {
    pub fn icon(&self) -> &str {
        match self {
            Self::File => "file", Self::Folder => "folder", Self::Module => "module",
            Self::Class => "class", Self::Method => "method", Self::Function => "function",
            Self::Property => "property", Self::Enum => "enum", Self::Interface => "interface",
            Self::Constant => "constant", Self::Variable => "variable", Self::Namespace => "namespace",
        }
    }
    pub fn is_symbol(&self) -> bool { !matches!(self, Self::File | Self::Folder) }
}

/// A single breadcrumb element.
#[derive(Debug, Clone)]
pub struct AxoBreadcrumb {
    pub label: String,
    pub kind: AxoBreadcrumbKind,
    pub uri: Option<String>,
    pub range_start_line: Option<u32>,
    pub children: Vec<AxoBreadcrumb>,
}

impl AxoBreadcrumb {
    pub fn new(label: &str, kind: AxoBreadcrumbKind) -> Self {
        Self { label: label.to_string(), kind, uri: None, range_start_line: None, children: Vec::new() }
    }
    pub fn with_uri(mut self, uri: &str) -> Self { self.uri = Some(uri.to_string()); self }
    pub fn with_line(mut self, line: u32) -> Self { self.range_start_line = Some(line); self }
    pub fn add_child(&mut self, child: AxoBreadcrumb) { self.children.push(child); }
    pub fn has_children(&self) -> bool { !self.children.is_empty() }
}

/// A breadcrumb trail from root to current location.
#[derive(Debug, Clone)]
pub struct AxoBreadcrumbTrail {
    pub items: Vec<AxoBreadcrumb>,
    pub focused_index: Option<usize>,
}

impl AxoBreadcrumbTrail {
    pub fn new() -> Self { Self { items: Vec::new(), focused_index: None } }
    pub fn push(&mut self, item: AxoBreadcrumb) { self.items.push(item); }
    pub fn len(&self) -> usize { self.items.len() }
    pub fn is_empty(&self) -> bool { self.items.is_empty() }
    pub fn last(&self) -> Option<&AxoBreadcrumb> { self.items.last() }
    pub fn focus(&mut self, idx: usize) { if idx < self.items.len() { self.focused_index = Some(idx); } }
    pub fn unfocus(&mut self) { self.focused_index = None; }
    pub fn focused(&self) -> Option<&AxoBreadcrumb> { self.focused_index.and_then(|i| self.items.get(i)) }

    pub fn from_path(path: &str, separator: char) -> Self {
        let mut trail = Self::new();
        let parts: Vec<&str> = path.split(separator).filter(|s| !s.is_empty()).collect();
        for (i, part) in parts.iter().enumerate() {
            let kind = if i == parts.len() - 1 { AxoBreadcrumbKind::File } else { AxoBreadcrumbKind::Folder };
            trail.push(AxoBreadcrumb::new(part, kind));
        }
        trail
    }
}

/// A document symbol for the outline view.
#[derive(Debug, Clone)]
pub struct AxoOutlineSymbol {
    pub name: String,
    pub detail: Option<String>,
    pub kind: AxoBreadcrumbKind,
    pub range_start: u32,
    pub range_end: u32,
    pub selection_start: u32,
    pub children: Vec<AxoOutlineSymbol>,
}

impl AxoOutlineSymbol {
    pub fn new(name: &str, kind: AxoBreadcrumbKind, start: u32, end: u32) -> Self {
        Self { name: name.to_string(), detail: None, kind, range_start: start, range_end: end, selection_start: start, children: Vec::new() }
    }
    pub fn with_detail(mut self, detail: &str) -> Self { self.detail = Some(detail.to_string()); self }
    pub fn add_child(&mut self, child: AxoOutlineSymbol) { self.children.push(child); }
    pub fn contains_line(&self, line: u32) -> bool { line >= self.range_start && line <= self.range_end }
    pub fn depth_first(&self) -> Vec<&AxoOutlineSymbol> {
        let mut result = vec![self];
        for child in &self.children { result.extend(child.depth_first()); }
        result
    }
}

/// Outline model for a document.
#[derive(Debug, Clone)]
pub struct AxoOutlineModel {
    pub uri: String,
    pub symbols: Vec<AxoOutlineSymbol>,
}

impl AxoOutlineModel {
    pub fn new(uri: &str) -> Self { Self { uri: uri.to_string(), symbols: Vec::new() } }
    pub fn add(&mut self, sym: AxoOutlineSymbol) { self.symbols.push(sym); }
    pub fn symbol_count(&self) -> usize { self.symbols.iter().map(|s| s.depth_first().len()).sum() }
    pub fn symbols_at_line(&self, line: u32) -> Vec<&AxoOutlineSymbol> {
        let mut result = Vec::new();
        for sym in &self.symbols {
            for s in sym.depth_first() { if s.contains_line(line) { result.push(s); } }
        }
        result
    }
    pub fn breadcrumb_at_line(&self, line: u32) -> AxoBreadcrumbTrail {
        let mut trail = AxoBreadcrumbTrail::new();
        fn find_path<'a>(sym: &'a AxoOutlineSymbol, line: u32, path: &mut Vec<&'a AxoOutlineSymbol>) -> bool {
            if sym.contains_line(line) {
                path.push(sym);
                for child in &sym.children { if find_path(child, line, path) { return true; } }
                return true;
            }
            false
        }
        for sym in &self.symbols {
            let mut path = Vec::new();
            if find_path(sym, line, &mut path) {
                for s in path { trail.push(AxoBreadcrumb::new(&s.name, s.kind).with_line(s.range_start)); }
                break;
            }
        }
        trail
    }
}


// --- axp_ workspace and multi-root folder management ---

/// Workspace folder with URI and name.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct AxpWorkspaceFolder {
    pub uri: String,
    pub name: String,
    pub index: usize,
}

impl AxpWorkspaceFolder {
    pub fn new(uri: &str, name: &str, index: usize) -> Self {
        Self { uri: uri.to_string(), name: name.to_string(), index }
    }
    pub fn display_name(&self) -> &str { &self.name }
}

/// Event for folder changes.
#[derive(Debug, Clone)]
pub struct AxpFolderChangeEvent {
    pub added: Vec<AxpWorkspaceFolder>,
    pub removed: Vec<AxpWorkspaceFolder>,
}

impl AxpFolderChangeEvent {
    pub fn new() -> Self { Self { added: Vec::new(), removed: Vec::new() } }
    pub fn has_changes(&self) -> bool { !self.added.is_empty() || !self.removed.is_empty() }
}

/// Workspace state enumeration.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AxpWorkspaceState { Empty, SingleFolder, MultiRoot }

/// Configuration scope for settings resolution.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AxpConfigScope { Global, User, Workspace, WorkspaceFolder }

impl AxpConfigScope {
    pub fn precedence(&self) -> u8 {
        match self { Self::Global => 0, Self::User => 1, Self::Workspace => 2, Self::WorkspaceFolder => 3 }
    }
    pub fn overrides(&self, other: &Self) -> bool { self.precedence() > other.precedence() }
}

/// Multi-root workspace manager.
#[derive(Debug)]
pub struct AxpWorkspace {
    pub name: Option<String>,
    pub folders: Vec<AxpWorkspaceFolder>,
    pub config_path: Option<String>,
}

impl AxpWorkspace {
    pub fn new() -> Self { Self { name: None, folders: Vec::new(), config_path: None } }
    pub fn with_name(mut self, name: &str) -> Self { self.name = Some(name.to_string()); self }
    pub fn state(&self) -> AxpWorkspaceState {
        match self.folders.len() {
            0 => AxpWorkspaceState::Empty,
            1 => AxpWorkspaceState::SingleFolder,
            _ => AxpWorkspaceState::MultiRoot,
        }
    }
    pub fn add_folder(&mut self, uri: &str, name: &str) -> AxpFolderChangeEvent {
        let idx = self.folders.len();
        let folder = AxpWorkspaceFolder::new(uri, name, idx);
        let mut evt = AxpFolderChangeEvent::new();
        evt.added.push(folder.clone());
        self.folders.push(folder);
        evt
    }
    pub fn remove_folder(&mut self, uri: &str) -> AxpFolderChangeEvent {
        let mut evt = AxpFolderChangeEvent::new();
        if let Some(pos) = self.folders.iter().position(|f| f.uri == uri) {
            let removed = self.folders.remove(pos);
            evt.removed.push(removed);
            for (i, f) in self.folders.iter_mut().enumerate() { f.index = i; }
        }
        evt
    }
    pub fn find_folder(&self, uri: &str) -> Option<&AxpWorkspaceFolder> {
        self.folders.iter().find(|f| f.uri == uri)
    }
    pub fn folder_count(&self) -> usize { self.folders.len() }
    pub fn folder_for_resource(&self, resource_uri: &str) -> Option<&AxpWorkspaceFolder> {
        self.folders.iter().filter(|f| resource_uri.starts_with(&f.uri))
            .max_by_key(|f| f.uri.len())
    }
    pub fn relative_path(&self, resource_uri: &str) -> Option<String> {
        self.folder_for_resource(resource_uri)
            .map(|f| resource_uri[f.uri.len()..].trim_start_matches('/').to_string())
    }
    pub fn set_config_path(&mut self, path: &str) { self.config_path = Some(path.to_string()); }
    pub fn is_workspace_file(&self) -> bool { self.config_path.is_some() }
}


// --- axq_ editor minimap and scroll management ---

/// Scroll position in the editor.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct AxqScrollPosition {
    pub top_line: u32,
    pub left_col: u32,
    pub viewport_height: u32,
    pub viewport_width: u32,
}

impl AxqScrollPosition {
    pub fn new(height: u32, width: u32) -> Self {
        Self { top_line: 0, left_col: 0, viewport_height: height, viewport_width: width }
    }
    pub fn bottom_line(&self) -> u32 { self.top_line + self.viewport_height.saturating_sub(1) }
    pub fn is_line_visible(&self, line: u32) -> bool { line >= self.top_line && line <= self.bottom_line() }
    pub fn scroll_to(&mut self, line: u32) { self.top_line = line; }
    pub fn scroll_by(&mut self, delta: i32) {
        self.top_line = (self.top_line as i64 + delta as i64).max(0) as u32;
    }
    pub fn ensure_visible(&mut self, line: u32, margin: u32) {
        if line < self.top_line + margin { self.top_line = line.saturating_sub(margin); }
        else if line > self.bottom_line().saturating_sub(margin) {
            self.top_line = line.saturating_sub(self.viewport_height.saturating_sub(1).saturating_sub(margin));
        }
    }
    pub fn center_on(&mut self, line: u32) {
        self.top_line = line.saturating_sub(self.viewport_height / 2);
    }
    pub fn page_up(&mut self) { self.scroll_by(-(self.viewport_height as i32)); }
    pub fn page_down(&mut self) { self.scroll_by(self.viewport_height as i32); }
    pub fn half_page_up(&mut self) { self.scroll_by(-(self.viewport_height as i32 / 2)); }
    pub fn half_page_down(&mut self) { self.scroll_by(self.viewport_height as i32 / 2); }
}

/// Minimap rendering mode.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AxqMinimapMode { Proportional, Fill, Fit }

/// A minimap slider tracking current viewport position.
#[derive(Debug, Clone)]
pub struct AxqMinimapSlider {
    pub top_ratio: f64,
    pub height_ratio: f64,
}

impl AxqMinimapSlider {
    pub fn compute(scroll: &AxqScrollPosition, total_lines: u32) -> Self {
        if total_lines == 0 { return Self { top_ratio: 0.0, height_ratio: 1.0 }; }
        let top_ratio = scroll.top_line as f64 / total_lines as f64;
        let height_ratio = (scroll.viewport_height as f64 / total_lines as f64).min(1.0);
        Self { top_ratio, height_ratio }
    }
    pub fn bottom_ratio(&self) -> f64 { (self.top_ratio + self.height_ratio).min(1.0) }
}

/// Minimap model for rendering a compressed view.
#[derive(Debug)]
pub struct AxqMinimap {
    pub enabled: bool,
    pub mode: AxqMinimapMode,
    pub width: u32,
    pub line_colors: Vec<(u8, u8, u8)>,
}

impl AxqMinimap {
    pub fn new(width: u32) -> Self {
        Self { enabled: true, mode: AxqMinimapMode::Proportional, width, line_colors: Vec::new() }
    }
    pub fn set_mode(&mut self, mode: AxqMinimapMode) { self.mode = mode; }
    pub fn toggle(&mut self) { self.enabled = !self.enabled; }
    pub fn set_line_colors(&mut self, colors: Vec<(u8, u8, u8)>) { self.line_colors = colors; }
    pub fn color_for_line(&self, line: usize) -> Option<(u8, u8, u8)> { self.line_colors.get(line).copied() }
    pub fn visible_lines(&self, scroll: &AxqScrollPosition, total_lines: u32) -> (u32, u32) {
        match self.mode {
            AxqMinimapMode::Fill => (0, total_lines),
            AxqMinimapMode::Fit => (0, total_lines),
            AxqMinimapMode::Proportional => (scroll.top_line, scroll.bottom_line().min(total_lines)),
        }
    }
}

/// Smooth scroll animation state.
#[derive(Debug, Clone)]
pub struct AxqSmoothScroll {
    pub target_line: u32,
    pub current_line: f64,
    pub duration_ms: u32,
    pub elapsed_ms: u32,
}

impl AxqSmoothScroll {
    pub fn new(from: u32, to: u32, duration_ms: u32) -> Self {
        Self { target_line: to, current_line: from as f64, duration_ms, elapsed_ms: 0 }
    }
    pub fn is_complete(&self) -> bool { self.elapsed_ms >= self.duration_ms }
    pub fn tick(&mut self, delta_ms: u32) {
        self.elapsed_ms = (self.elapsed_ms + delta_ms).min(self.duration_ms);
        let t = self.elapsed_ms as f64 / self.duration_ms as f64;
        let eased = t * t * (3.0 - 2.0 * t);
        let start = self.current_line;
        let target = self.target_line as f64;
        self.current_line = start + (target - start) * eased;
    }
    pub fn current_position(&self) -> u32 { self.current_line.round() as u32 }
}


// --- axr_ language detection and grammar types ---

/// A language identifier.
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub struct AxrLanguageId(pub String);

impl AxrLanguageId {
    pub fn new(id: &str) -> Self { Self(id.to_lowercase()) }
    pub fn as_str(&self) -> &str { &self.0 }
}

/// File extension to language mapping.
#[derive(Debug)]
pub struct AxrLanguageRegistry {
    by_ext: std::collections::HashMap<String, AxrLanguageId>,
    by_filename: std::collections::HashMap<String, AxrLanguageId>,
    by_pattern: Vec<(String, AxrLanguageId)>,
    aliases: std::collections::HashMap<String, AxrLanguageId>,
}

impl AxrLanguageRegistry {
    pub fn new() -> Self {
        let mut r = Self {
            by_ext: std::collections::HashMap::new(),
            by_filename: std::collections::HashMap::new(),
            by_pattern: Vec::new(),
            aliases: std::collections::HashMap::new(),
        };
        r.register_defaults();
        r
    }
    fn register_defaults(&mut self) {
        let mappings = [
            ("rs", "rust"), ("py", "python"), ("js", "javascript"), ("ts", "typescript"),
            ("json", "json"), ("toml", "toml"), ("yaml", "yaml"), ("yml", "yaml"),
            ("md", "markdown"), ("html", "html"), ("css", "css"), ("go", "go"),
            ("c", "c"), ("cpp", "cpp"), ("h", "c"), ("hpp", "cpp"),
            ("java", "java"), ("rb", "ruby"), ("sh", "shellscript"), ("bash", "shellscript"),
            ("xml", "xml"), ("sql", "sql"), ("lua", "lua"), ("php", "php"),
        ];
        for (ext, lang) in mappings { self.by_ext.insert(ext.to_string(), AxrLanguageId::new(lang)); }
        self.by_filename.insert("Makefile".to_string(), AxrLanguageId::new("makefile"));
        self.by_filename.insert("Dockerfile".to_string(), AxrLanguageId::new("dockerfile"));
        self.by_filename.insert("Cargo.toml".to_string(), AxrLanguageId::new("toml"));
        self.aliases.insert("js".to_string(), AxrLanguageId::new("javascript"));
        self.aliases.insert("ts".to_string(), AxrLanguageId::new("typescript"));
        self.aliases.insert("py".to_string(), AxrLanguageId::new("python"));
    }
    pub fn register_extension(&mut self, ext: &str, lang: AxrLanguageId) {
        self.by_ext.insert(ext.to_string(), lang);
    }
    pub fn register_filename(&mut self, name: &str, lang: AxrLanguageId) {
        self.by_filename.insert(name.to_string(), lang);
    }
    pub fn register_pattern(&mut self, pattern: &str, lang: AxrLanguageId) {
        self.by_pattern.push((pattern.to_string(), lang));
    }
    pub fn detect(&self, filename: &str) -> Option<&AxrLanguageId> {
        if let Some(lang) = self.by_filename.get(filename) { return Some(lang); }
        if let Some(ext) = filename.rsplit('.').next() {
            if let Some(lang) = self.by_ext.get(ext) { return Some(lang); }
        }
        for (pat, lang) in &self.by_pattern {
            if filename.contains(pat) { return Some(lang); }
        }
        None
    }
    pub fn resolve_alias(&self, alias: &str) -> Option<&AxrLanguageId> { self.aliases.get(alias) }
    pub fn language_count(&self) -> usize {
        let mut langs: std::collections::HashSet<&str> = std::collections::HashSet::new();
        for lang in self.by_ext.values() { langs.insert(lang.as_str()); }
        for lang in self.by_filename.values() { langs.insert(lang.as_str()); }
        langs.len()
    }
}

/// A TextMate grammar scope.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct AxrScope(pub String);

impl AxrScope {
    pub fn new(s: &str) -> Self { Self(s.to_string()) }
    pub fn parts(&self) -> Vec<&str> { self.0.split('.').collect() }
    pub fn depth(&self) -> usize { self.parts().len() }
    pub fn is_prefix_of(&self, other: &AxrScope) -> bool { other.0.starts_with(&self.0) }
}

/// A scope stack for nested grammar contexts.
#[derive(Debug, Clone)]
pub struct AxrScopeStack {
    pub scopes: Vec<AxrScope>,
}

impl AxrScopeStack {
    pub fn new() -> Self { Self { scopes: Vec::new() } }
    pub fn push(&mut self, scope: AxrScope) { self.scopes.push(scope); }
    pub fn pop(&mut self) -> Option<AxrScope> { self.scopes.pop() }
    pub fn top(&self) -> Option<&AxrScope> { self.scopes.last() }
    pub fn depth(&self) -> usize { self.scopes.len() }
    pub fn contains(&self, scope: &AxrScope) -> bool {
        self.scopes.iter().any(|s| scope.is_prefix_of(s))
    }
    pub fn to_string_path(&self) -> String {
        self.scopes.iter().map(|s| s.0.as_str()).collect::<Vec<_>>().join(" ")
    }
}

/// Token type from grammar tokenization.
#[derive(Debug, Clone)]
pub struct AxrToken {
    pub start: u32,
    pub end: u32,
    pub scopes: Vec<AxrScope>,
}

impl AxrToken {
    pub fn new(start: u32, end: u32, scopes: Vec<AxrScope>) -> Self { Self { start, end, scopes } }
    pub fn len(&self) -> u32 { self.end - self.start }
    pub fn primary_scope(&self) -> Option<&AxrScope> { self.scopes.last() }
}


// --- axs_ theme and token colorization engine ---

/// An RGBA color value.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct AxsColor {
    pub r: u8, pub g: u8, pub b: u8, pub a: u8,
}

impl AxsColor {
    pub fn rgb(r: u8, g: u8, b: u8) -> Self { Self { r, g, b, a: 255 } }
    pub fn rgba(r: u8, g: u8, b: u8, a: u8) -> Self { Self { r, g, b, a } }
    pub fn from_hex(hex: &str) -> Option<Self> {
        let hex = hex.trim_start_matches('#');
        if hex.len() == 6 {
            let r = u8::from_str_radix(&hex[0..2], 16).ok()?;
            let g = u8::from_str_radix(&hex[2..4], 16).ok()?;
            let b = u8::from_str_radix(&hex[4..6], 16).ok()?;
            Some(Self::rgb(r, g, b))
        } else if hex.len() == 8 {
            let r = u8::from_str_radix(&hex[0..2], 16).ok()?;
            let g = u8::from_str_radix(&hex[2..4], 16).ok()?;
            let b = u8::from_str_radix(&hex[4..6], 16).ok()?;
            let a = u8::from_str_radix(&hex[6..8], 16).ok()?;
            Some(Self::rgba(r, g, b, a))
        } else { None }
    }
    pub fn to_hex(&self) -> String { format!("#{:02x}{:02x}{:02x}", self.r, self.g, self.b) }
    pub fn blend(&self, other: &AxsColor, t: f64) -> Self {
        let lerp = |a: u8, b: u8| -> u8 { (a as f64 + (b as f64 - a as f64) * t).round() as u8 };
        Self::rgba(lerp(self.r, other.r), lerp(self.g, other.g), lerp(self.b, other.b), lerp(self.a, other.a))
    }
    pub fn luminance(&self) -> f64 {
        0.2126 * (self.r as f64 / 255.0) + 0.7152 * (self.g as f64 / 255.0) + 0.0722 * (self.b as f64 / 255.0)
    }
    pub fn is_light(&self) -> bool { self.luminance() > 0.5 }
}

/// Font style flags.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct AxsFontStyle(pub u8);

impl AxsFontStyle {
    pub const NONE: Self = Self(0);
    pub const BOLD: Self = Self(1);
    pub const ITALIC: Self = Self(2);
    pub const UNDERLINE: Self = Self(4);
    pub const STRIKETHROUGH: Self = Self(8);
    pub fn has(&self, flag: AxsFontStyle) -> bool { self.0 & flag.0 != 0 }
    pub fn with(self, flag: AxsFontStyle) -> Self { Self(self.0 | flag.0) }
}

/// Token color rule matching scopes.
#[derive(Debug, Clone)]
pub struct AxsTokenColorRule {
    pub scope: String,
    pub foreground: Option<AxsColor>,
    pub background: Option<AxsColor>,
    pub font_style: AxsFontStyle,
}

impl AxsTokenColorRule {
    pub fn new(scope: &str) -> Self {
        Self { scope: scope.to_string(), foreground: None, background: None, font_style: AxsFontStyle::NONE }
    }
    pub fn with_fg(mut self, color: AxsColor) -> Self { self.foreground = Some(color); self }
    pub fn with_style(mut self, style: AxsFontStyle) -> Self { self.font_style = style; self }
    pub fn matches_scope(&self, scope_path: &str) -> bool { scope_path.starts_with(&self.scope) }
    pub fn specificity(&self) -> usize { self.scope.split('.').count() }
}

/// Theme kind.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AxsThemeKind { Light, Dark, HighContrast, HighContrastLight }

/// Complete editor theme.
#[derive(Debug)]
pub struct AxsTheme {
    pub name: String,
    pub kind: AxsThemeKind,
    pub colors: std::collections::HashMap<String, AxsColor>,
    pub token_rules: Vec<AxsTokenColorRule>,
}

impl AxsTheme {
    pub fn new(name: &str, kind: AxsThemeKind) -> Self {
        Self { name: name.to_string(), kind, colors: std::collections::HashMap::new(), token_rules: Vec::new() }
    }
    pub fn set_color(&mut self, key: &str, color: AxsColor) { self.colors.insert(key.to_string(), color); }
    pub fn get_color(&self, key: &str) -> Option<&AxsColor> { self.colors.get(key) }
    pub fn add_rule(&mut self, rule: AxsTokenColorRule) { self.token_rules.push(rule); }
    pub fn resolve_token(&self, scope_path: &str) -> Option<&AxsTokenColorRule> {
        self.token_rules.iter()
            .filter(|r| r.matches_scope(scope_path))
            .max_by_key(|r| r.specificity())
    }
    pub fn is_dark(&self) -> bool { matches!(self.kind, AxsThemeKind::Dark | AxsThemeKind::HighContrast) }
    pub fn editor_bg(&self) -> Option<&AxsColor> { self.get_color("editor.background") }
    pub fn editor_fg(&self) -> Option<&AxsColor> { self.get_color("editor.foreground") }
}

/// Theme registry for switching themes.
#[derive(Debug)]
pub struct AxsThemeRegistry {
    pub themes: Vec<AxsTheme>,
    pub active_index: usize,
}

impl AxsThemeRegistry {
    pub fn new() -> Self { Self { themes: Vec::new(), active_index: 0 } }
    pub fn add(&mut self, theme: AxsTheme) { self.themes.push(theme); }
    pub fn active(&self) -> Option<&AxsTheme> { self.themes.get(self.active_index) }
    pub fn set_active(&mut self, name: &str) -> bool {
        if let Some(idx) = self.themes.iter().position(|t| t.name == name) {
            self.active_index = idx; true
        } else { false }
    }
    pub fn theme_names(&self) -> Vec<&str> { self.themes.iter().map(|t| t.name.as_str()).collect() }
}


// --- axt_ bracket matching and indentation engine ---

/// Bracket pair kind.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum AxtBracketKind { Paren, Square, Curly, Angle }

impl AxtBracketKind {
    pub fn open_char(&self) -> char {
        match self { Self::Paren => '(', Self::Square => '[', Self::Curly => '{', Self::Angle => '<' }
    }
    pub fn close_char(&self) -> char {
        match self { Self::Paren => ')', Self::Square => ']', Self::Curly => '}', Self::Angle => '>' }
    }
    pub fn from_char(c: char) -> Option<(Self, bool)> {
        match c {
            '(' => Some((Self::Paren, true)), ')' => Some((Self::Paren, false)),
            '[' => Some((Self::Square, true)), ']' => Some((Self::Square, false)),
            '{' => Some((Self::Curly, true)), '}' => Some((Self::Curly, false)),
            '<' => Some((Self::Angle, true)), '>' => Some((Self::Angle, false)),
            _ => None,
        }
    }
}

/// A bracket at a position.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct AxtBracketPos {
    pub line: u32,
    pub col: u32,
    pub kind: AxtBracketKind,
    pub is_open: bool,
}

/// A matched bracket pair.
#[derive(Debug, Clone, Copy)]
pub struct AxtBracketPair {
    pub open: AxtBracketPos,
    pub close: AxtBracketPos,
}

impl AxtBracketPair {
    pub fn spans_lines(&self) -> bool { self.open.line != self.close.line }
    pub fn nesting_depth(&self) -> u32 { 0 }
}

/// Bracket matcher using a stack-based approach.
pub struct AxtBracketMatcher;

impl AxtBracketMatcher {
    pub fn find_matching(text: &str, line: u32, col: u32) -> Option<AxtBracketPair> {
        let lines: Vec<&str> = text.lines().collect();
        if line as usize >= lines.len() { return None; }
        let target_line = lines[line as usize];
        if col as usize >= target_line.len() { return None; }
        let ch = target_line.as_bytes()[col as usize] as char;
        let (kind, is_open) = AxtBracketKind::from_char(ch)?;
        let origin = AxtBracketPos { line, col, kind, is_open };
        if is_open {
            Self::find_close(text, &origin)
        } else {
            Self::find_open(text, &origin)
        }
    }

    fn find_close(text: &str, open: &AxtBracketPos) -> Option<AxtBracketPair> {
        let mut depth: i32 = 0;
        let open_c = open.kind.open_char();
        let close_c = open.kind.close_char();
        for (li, line) in text.lines().enumerate() {
            for (ci, ch) in line.chars().enumerate() {
                if li as u32 > open.line || (li as u32 == open.line && ci as u32 >= open.col) {
                    if ch == open_c { depth += 1; }
                    else if ch == close_c {
                        depth -= 1;
                        if depth == 0 {
                            return Some(AxtBracketPair {
                                open: *open,
                                close: AxtBracketPos { line: li as u32, col: ci as u32, kind: open.kind, is_open: false },
                            });
                        }
                    }
                }
            }
        }
        None
    }

    fn find_open(text: &str, close: &AxtBracketPos) -> Option<AxtBracketPair> {
        let mut depth: i32 = 0;
        let open_c = close.kind.open_char();
        let close_c = close.kind.close_char();
        let lines: Vec<&str> = text.lines().collect();
        for li in (0..=close.line as usize).rev() {
            let line = lines[li];
            let chars: Vec<char> = line.chars().collect();
            let end = if li == close.line as usize { close.col as usize } else { chars.len().saturating_sub(1) };
            for ci in (0..=end).rev() {
                if ci < chars.len() {
                    let ch = chars[ci];
                    if ch == close_c { depth += 1; }
                    else if ch == open_c {
                        depth -= 1;
                        if depth == 0 {
                            return Some(AxtBracketPair {
                                open: AxtBracketPos { line: li as u32, col: ci as u32, kind: close.kind, is_open: true },
                                close: *close,
                            });
                        }
                    }
                }
            }
        }
        None
    }
}

/// Indentation style detection.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AxtIndentStyle { Tabs, Spaces(u32) }

impl AxtIndentStyle {
    pub fn detect(text: &str) -> Self {
        let mut tab_lines = 0u32;
        let mut space_counts: std::collections::HashMap<u32, u32> = std::collections::HashMap::new();
        for line in text.lines() {
            if line.starts_with('\t') { tab_lines += 1; }
            else {
                let spaces = line.len() - line.trim_start_matches(' ').len();
                if spaces > 0 { *space_counts.entry(spaces as u32).or_insert(0) += 1; }
            }
        }
        let total_space_lines: u32 = space_counts.values().sum();
        if tab_lines > total_space_lines { return Self::Tabs; }
        let mut best_size = 4u32;
        let mut best_count = 0u32;
        for size in [2, 4, 8] {
            let count: u32 = space_counts.iter()
                .filter(|(k, _)| **k % size == 0).map(|(_, v)| *v).sum();
            if count > best_count { best_count = count; best_size = size; }
        }
        Self::Spaces(best_size)
    }
    pub fn indent_str(&self) -> String {
        match self { Self::Tabs => "\t".to_string(), Self::Spaces(n) => " ".repeat(*n as usize) }
    }
}

/// Auto-indent engine.
pub struct AxtAutoIndent;

impl AxtAutoIndent {
    pub fn compute_indent(prev_line: &str, style: AxtIndentStyle) -> String {
        let current = prev_line.len() - prev_line.trim_start().len();
        let trimmed = prev_line.trim_end();
        let extra = if trimmed.ends_with('{') || trimmed.ends_with('(') || trimmed.ends_with('[') || trimmed.ends_with(':') {
            style.indent_str()
        } else { String::new() };
        format!("{}{}", &prev_line[..current], extra)
    }
}


// --- axu_ editor decorations and gutter annotations ---

/// Decoration range type.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AxuDecorationType { Highlight, Underline, Border, GutterIcon, InlineText, WholeLine }

/// A decoration range in the editor.
#[derive(Debug, Clone)]
pub struct AxuDecorationRange {
    pub start_line: u32,
    pub start_col: u32,
    pub end_line: u32,
    pub end_col: u32,
    pub decoration_type: AxuDecorationType,
    pub color: Option<(u8, u8, u8)>,
    pub hover_message: Option<String>,
}

impl AxuDecorationRange {
    pub fn new(sl: u32, sc: u32, el: u32, ec: u32, dtype: AxuDecorationType) -> Self {
        Self { start_line: sl, start_col: sc, end_line: el, end_col: ec, decoration_type: dtype, color: None, hover_message: None }
    }
    pub fn with_color(mut self, r: u8, g: u8, b: u8) -> Self { self.color = Some((r, g, b)); self }
    pub fn with_hover(mut self, msg: &str) -> Self { self.hover_message = Some(msg.to_string()); self }
    pub fn is_single_line(&self) -> bool { self.start_line == self.end_line }
    pub fn contains_line(&self, line: u32) -> bool { line >= self.start_line && line <= self.end_line }
    pub fn contains_pos(&self, line: u32, col: u32) -> bool {
        if line < self.start_line || line > self.end_line { return false; }
        if line == self.start_line && col < self.start_col { return false; }
        if line == self.end_line && col > self.end_col { return false; }
        true
    }
}

/// Gutter indicator type.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AxuGutterKind { Breakpoint, Bookmark, Error, Warning, Info, GitAdded, GitModified, GitDeleted, FoldOpen, FoldClosed }

/// A gutter annotation for a line.
#[derive(Debug, Clone)]
pub struct AxuGutterAnnotation {
    pub line: u32,
    pub kind: AxuGutterKind,
    pub tooltip: Option<String>,
}

impl AxuGutterAnnotation {
    pub fn new(line: u32, kind: AxuGutterKind) -> Self { Self { line, kind, tooltip: None } }
    pub fn with_tooltip(mut self, tip: &str) -> Self { self.tooltip = Some(tip.to_string()); self }
    pub fn symbol(&self) -> &str {
        match self.kind {
            AxuGutterKind::Breakpoint => "BP", AxuGutterKind::Bookmark => "BM",
            AxuGutterKind::Error => "E!", AxuGutterKind::Warning => "W!",
            AxuGutterKind::Info => "i", AxuGutterKind::GitAdded => "+",
            AxuGutterKind::GitModified => "~", AxuGutterKind::GitDeleted => "-",
            AxuGutterKind::FoldOpen => "v", AxuGutterKind::FoldClosed => ">",
        }
    }
}

/// Decoration collection for an editor.
#[derive(Debug)]
pub struct AxuDecorationCollection {
    pub decorations: Vec<AxuDecorationRange>,
    pub gutter: Vec<AxuGutterAnnotation>,
}

impl AxuDecorationCollection {
    pub fn new() -> Self { Self { decorations: Vec::new(), gutter: Vec::new() } }
    pub fn add_decoration(&mut self, d: AxuDecorationRange) { self.decorations.push(d); }
    pub fn add_gutter(&mut self, g: AxuGutterAnnotation) { self.gutter.push(g); }
    pub fn decorations_at_line(&self, line: u32) -> Vec<&AxuDecorationRange> {
        self.decorations.iter().filter(|d| d.contains_line(line)).collect()
    }
    pub fn gutter_at_line(&self, line: u32) -> Vec<&AxuGutterAnnotation> {
        self.gutter.iter().filter(|g| g.line == line).collect()
    }
    pub fn clear_decorations(&mut self) { self.decorations.clear(); }
    pub fn clear_gutter(&mut self) { self.gutter.clear(); }
    pub fn decoration_count(&self) -> usize { self.decorations.len() }
    pub fn gutter_count(&self) -> usize { self.gutter.len() }
    pub fn remove_decorations_of_type(&mut self, dtype: AxuDecorationType) {
        self.decorations.retain(|d| d.decoration_type != dtype);
    }
    pub fn decorations_at_pos(&self, line: u32, col: u32) -> Vec<&AxuDecorationRange> {
        self.decorations.iter().filter(|d| d.contains_pos(line, col)).collect()
    }
}

/// Inline code lens annotation.
#[derive(Debug, Clone)]
pub struct AxuCodeLensAnnotation {
    pub line: u32,
    pub title: String,
    pub command_id: String,
}

impl AxuCodeLensAnnotation {
    pub fn new(line: u32, title: &str, cmd: &str) -> Self {
        Self { line, title: title.to_string(), command_id: cmd.to_string() }
    }
}


// --- axv_ task runner and problem matcher ---

/// Task source type.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AxvTaskSource { Workspace, Extension, User }

/// Task group.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AxvTaskGroup { Build, Test, Clean, None }

/// Task execution state.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AxvTaskState { Pending, Running, Succeeded, Failed, Cancelled }

/// A task definition.
#[derive(Debug, Clone)]
pub struct AxvTask {
    pub name: String,
    pub source: AxvTaskSource,
    pub group: AxvTaskGroup,
    pub command: String,
    pub args: Vec<String>,
    pub cwd: Option<String>,
    pub env: std::collections::HashMap<String, String>,
    pub state: AxvTaskState,
    pub exit_code: Option<i32>,
}

impl AxvTask {
    pub fn new(name: &str, command: &str) -> Self {
        Self {
            name: name.to_string(), source: AxvTaskSource::Workspace, group: AxvTaskGroup::None,
            command: command.to_string(), args: Vec::new(), cwd: None,
            env: std::collections::HashMap::new(), state: AxvTaskState::Pending, exit_code: None,
        }
    }
    pub fn with_group(mut self, group: AxvTaskGroup) -> Self { self.group = group; self }
    pub fn with_args(mut self, args: Vec<String>) -> Self { self.args = args; self }
    pub fn with_cwd(mut self, cwd: &str) -> Self { self.cwd = Some(cwd.to_string()); self }
    pub fn full_command(&self) -> String {
        if self.args.is_empty() { self.command.clone() }
        else { format!("{} {}", self.command, self.args.join(" ")) }
    }
    pub fn start(&mut self) { self.state = AxvTaskState::Running; }
    pub fn finish(&mut self, code: i32) {
        self.exit_code = Some(code);
        self.state = if code == 0 { AxvTaskState::Succeeded } else { AxvTaskState::Failed };
    }
    pub fn cancel(&mut self) { self.state = AxvTaskState::Cancelled; }
    pub fn is_running(&self) -> bool { self.state == AxvTaskState::Running }
    pub fn is_done(&self) -> bool { matches!(self.state, AxvTaskState::Succeeded | AxvTaskState::Failed | AxvTaskState::Cancelled) }
}

/// Problem severity.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AxvProblemSeverity { Error, Warning, Info }

/// A problem extracted from task output.
#[derive(Debug, Clone)]
pub struct AxvProblem {
    pub file: String,
    pub line: u32,
    pub col: u32,
    pub severity: AxvProblemSeverity,
    pub message: String,
    pub source: Option<String>,
}

impl AxvProblem {
    pub fn new(file: &str, line: u32, col: u32, severity: AxvProblemSeverity, message: &str) -> Self {
        Self { file: file.to_string(), line, col, severity, message: message.to_string(), source: None }
    }
    pub fn with_source(mut self, source: &str) -> Self { self.source = Some(source.to_string()); self }
    pub fn location(&self) -> String { format!("{}:{}:{}", self.file, self.line, self.col) }
}

/// Problem matcher pattern (simplified regex-like).
#[derive(Debug, Clone)]
pub struct AxvProblemPattern {
    pub file_group: usize,
    pub line_group: usize,
    pub col_group: usize,
    pub severity_group: usize,
    pub message_group: usize,
    pub pattern: String,
}

impl AxvProblemPattern {
    pub fn gcc_like() -> Self {
        Self { file_group: 1, line_group: 2, col_group: 3, severity_group: 4, message_group: 5, pattern: "^(.+):(\\d+):(\\d+):\\s+(error|warning):\\s+(.+)$".to_string() }
    }
    pub fn rustc_like() -> Self {
        Self { file_group: 1, line_group: 2, col_group: 3, severity_group: 4, message_group: 5, pattern: "^(error|warning)\\[.*\\]:\\s+(.+)$".to_string() }
    }
}

/// Task runner managing multiple tasks.
#[derive(Debug)]
pub struct AxvTaskRunner {
    pub tasks: Vec<AxvTask>,
    pub problems: Vec<AxvProblem>,
}

impl AxvTaskRunner {
    pub fn new() -> Self { Self { tasks: Vec::new(), problems: Vec::new() } }
    pub fn add_task(&mut self, task: AxvTask) -> usize { self.tasks.push(task); self.tasks.len() - 1 }
    pub fn running_count(&self) -> usize { self.tasks.iter().filter(|t| t.is_running()).count() }
    pub fn error_count(&self) -> usize { self.problems.iter().filter(|p| p.severity == AxvProblemSeverity::Error).count() }
    pub fn warning_count(&self) -> usize { self.problems.iter().filter(|p| p.severity == AxvProblemSeverity::Warning).count() }
    pub fn add_problem(&mut self, p: AxvProblem) { self.problems.push(p); }
    pub fn problems_for_file(&self, file: &str) -> Vec<&AxvProblem> { self.problems.iter().filter(|p| p.file == file).collect() }
    pub fn clear_problems(&mut self) { self.problems.clear(); }
}


// --- axw_ debug adapter protocol types ---

/// DAP message type.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
