/// Debug decoration on a line.
#[derive(Debug, Clone)]
pub struct AyvDebugDecoration {
    pub line: u32,
    pub kind: AyvDebugDecoKind,
    pub message: Option<String>,
}

/// Debug decoration kind.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AyvDebugDecoKind { CurrentLine, BreakpointHit, Exception, LogPoint }

impl AyvDebugDecoration {
    pub fn current_line(line: u32) -> Self { Self { line, kind: AyvDebugDecoKind::CurrentLine, message: None } }
    pub fn exception(line: u32, msg: &str) -> Self { Self { line, kind: AyvDebugDecoKind::Exception, message: Some(msg.to_string()) } }
    pub fn breakpoint_hit(line: u32) -> Self { Self { line, kind: AyvDebugDecoKind::BreakpointHit, message: None } }
    pub fn has_message(&self) -> bool { self.message.is_some() }
}

/// Inline value provider context.
#[derive(Debug, Clone)]
pub struct AyvInlineValueContext {
    pub stopped_line: u32,
    pub frame_id: u32,
}

impl AyvInlineValueContext {
    pub fn new(line: u32, frame: u32) -> Self { Self { stopped_line: line, frame_id: frame } }
}

/// Debug session visual state.
#[derive(Debug)]
pub struct AyvDebugVisuals {
    pub inline_values: Vec<AyvInlineValue>,
    pub decorations: Vec<AyvDebugDecoration>,
    pub exception_widget_line: Option<u32>,
    pub exception_message: Option<String>,
}

impl AyvDebugVisuals {
    pub fn new() -> Self {
        Self { inline_values: Vec::new(), decorations: Vec::new(), exception_widget_line: None, exception_message: None }
    }
    pub fn add_inline(&mut self, v: AyvInlineValue) { self.inline_values.push(v); }
    pub fn add_decoration(&mut self, d: AyvDebugDecoration) { self.decorations.push(d); }
    pub fn show_exception(&mut self, line: u32, msg: &str) {
        self.exception_widget_line = Some(line);
        self.exception_message = Some(msg.to_string());
    }
    pub fn clear(&mut self) {
        self.inline_values.clear(); self.decorations.clear();
        self.exception_widget_line = None; self.exception_message = None;
    }
    pub fn values_at_line(&self, line: u32) -> Vec<&AyvInlineValue> {
        self.inline_values.iter().filter(|v| v.line == line).collect()
    }
    pub fn decoration_at_line(&self, line: u32) -> Option<&AyvDebugDecoration> {
        self.decorations.iter().find(|d| d.line == line)
    }
    pub fn has_exception(&self) -> bool { self.exception_widget_line.is_some() }
}


// --- ayw_ notebook and cell model ---

/// Notebook cell kind.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AywCellKind { Code, Markup }

/// A single notebook cell.
#[derive(Debug, Clone)]
pub struct AywNotebookCell {
    pub kind: AywCellKind,
    pub source: String,
    pub language: String,
    pub outputs: Vec<AywCellOutput>,
    pub metadata: Vec<(String, String)>,
}

/// Cell output.
#[derive(Debug, Clone)]
pub struct AywCellOutput {
    pub mime: String,
    pub data: Vec<u8>,
}

impl AywCellOutput {
    pub fn text(s: &str) -> Self { Self { mime: "text/plain".to_string(), data: s.as_bytes().to_vec() } }
    pub fn as_text(&self) -> Option<String> {
        if self.mime == "text/plain" { String::from_utf8(self.data.clone()).ok() } else { None }
    }
}

impl AywNotebookCell {
    pub fn code(lang: &str, src: &str) -> Self {
        Self { kind: AywCellKind::Code, source: src.to_string(), language: lang.to_string(), outputs: Vec::new(), metadata: Vec::new() }
    }
    pub fn markup(src: &str) -> Self {
        Self { kind: AywCellKind::Markup, source: src.to_string(), language: "markdown".to_string(), outputs: Vec::new(), metadata: Vec::new() }
    }
    pub fn add_output(&mut self, o: AywCellOutput) { self.outputs.push(o); }
    pub fn is_code(&self) -> bool { self.kind == AywCellKind::Code }
    pub fn line_count(&self) -> usize { self.source.lines().count().max(1) }
}

/// A notebook document.
#[derive(Debug)]
pub struct AywNotebookDocument {
    pub cells: Vec<AywNotebookCell>,
    pub metadata: Vec<(String, String)>,
    pub notebook_type: String,
}

impl AywNotebookDocument {
    pub fn new(ntype: &str) -> Self {
        Self { cells: Vec::new(), metadata: Vec::new(), notebook_type: ntype.to_string() }
    }
    pub fn add_cell(&mut self, c: AywNotebookCell) { self.cells.push(c); }
    pub fn cell_count(&self) -> usize { self.cells.len() }
    pub fn code_cells(&self) -> Vec<&AywNotebookCell> { self.cells.iter().filter(|c| c.is_code()).collect() }
    pub fn markup_cells(&self) -> Vec<&AywNotebookCell> { self.cells.iter().filter(|c| !c.is_code()).collect() }
    pub fn swap_cells(&mut self, a: usize, b: usize) {
        if a < self.cells.len() && b < self.cells.len() { self.cells.swap(a, b); }
    }
    pub fn remove_cell(&mut self, idx: usize) -> Option<AywNotebookCell> {
        if idx < self.cells.len() { Some(self.cells.remove(idx)) } else { None }
    }
    pub fn insert_cell(&mut self, idx: usize, cell: AywNotebookCell) {
        let idx = idx.min(self.cells.len());
        self.cells.insert(idx, cell);
    }
    pub fn total_lines(&self) -> usize { self.cells.iter().map(|c| c.line_count()).sum() }
}

/// Notebook execution state.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AywExecState { Idle, Running, Succeeded, Failed }

/// Cell execution order tracker.
#[derive(Debug)]
pub struct AywCellExecution {
    pub cell_index: usize,
    pub state: AywExecState,
    pub order: Option<u32>,
    pub duration_ms: Option<u64>,
}

impl AywCellExecution {
    pub fn start(idx: usize) -> Self { Self { cell_index: idx, state: AywExecState::Running, order: None, duration_ms: None } }
    pub fn finish(&mut self, success: bool, order: u32, ms: u64) {
        self.state = if success { AywExecState::Succeeded } else { AywExecState::Failed };
        self.order = Some(order);
        self.duration_ms = Some(ms);
    }
    pub fn is_running(&self) -> bool { self.state == AywExecState::Running }
}


// --- ayx_ timeline and local history ---

/// Timeline entry source.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AyxTimelineSource { LocalHistory, Git, Extension }

/// A timeline entry.
#[derive(Debug, Clone)]
pub struct AyxTimelineEntry {
    pub id: String,
    pub timestamp: u64,
    pub label: String,
    pub source: AyxTimelineSource,
    pub detail: Option<String>,
}

impl AyxTimelineEntry {
    pub fn local_history(id: &str, ts: u64, label: &str) -> Self {
        Self { id: id.to_string(), timestamp: ts, label: label.to_string(), source: AyxTimelineSource::LocalHistory, detail: None }
    }
    pub fn git_commit(id: &str, ts: u64, msg: &str) -> Self {
        Self { id: id.to_string(), timestamp: ts, label: msg.to_string(), source: AyxTimelineSource::Git, detail: None }
    }
    pub fn with_detail(mut self, d: &str) -> Self { self.detail = Some(d.to_string()); self }
    pub fn is_git(&self) -> bool { self.source == AyxTimelineSource::Git }
}

/// Local history snapshot.
#[derive(Debug, Clone)]
pub struct AyxLocalHistoryEntry {
    pub entry_id: String,
    pub timestamp: u64,
    pub content_hash: u64,
    pub size_bytes: u64,
}

impl AyxLocalHistoryEntry {
    pub fn new(id: &str, ts: u64, hash: u64, size: u64) -> Self {
        Self { entry_id: id.to_string(), timestamp: ts, content_hash: hash, size_bytes: size }
    }
}

/// Timeline provider for a file.
#[derive(Debug)]
pub struct AyxTimeline {
    pub entries: Vec<AyxTimelineEntry>,
    pub file_path: String,
    pub max_entries: usize,
}

impl AyxTimeline {
    pub fn new(path: &str, max: usize) -> Self {
        Self { entries: Vec::new(), file_path: path.to_string(), max_entries: max }
    }
    pub fn add_entry(&mut self, e: AyxTimelineEntry) {
        self.entries.push(e);
        self.entries.sort_by(|a, b| b.timestamp.cmp(&a.timestamp));
        if self.entries.len() > self.max_entries { self.entries.truncate(self.max_entries); }
    }
    pub fn latest(&self) -> Option<&AyxTimelineEntry> { self.entries.first() }
    pub fn by_source(&self, src: AyxTimelineSource) -> Vec<&AyxTimelineEntry> {
        self.entries.iter().filter(|e| e.source == src).collect()
    }
    pub fn entry_count(&self) -> usize { self.entries.len() }
    pub fn clear(&mut self) { self.entries.clear(); }
    pub fn entries_between(&self, start: u64, end: u64) -> Vec<&AyxTimelineEntry> {
        self.entries.iter().filter(|e| e.timestamp >= start && e.timestamp <= end).collect()
    }
}

/// Local history store.
#[derive(Debug)]
pub struct AyxLocalHistoryStore {
    pub snapshots: Vec<AyxLocalHistoryEntry>,
    pub max_snapshots: usize,
}

impl AyxLocalHistoryStore {
    pub fn new(max: usize) -> Self { Self { snapshots: Vec::new(), max_snapshots: max } }
    pub fn add_snapshot(&mut self, s: AyxLocalHistoryEntry) {
        self.snapshots.push(s);
        if self.snapshots.len() > self.max_snapshots { self.snapshots.remove(0); }
    }
    pub fn snapshot_count(&self) -> usize { self.snapshots.len() }
    pub fn total_bytes(&self) -> u64 { self.snapshots.iter().map(|s| s.size_bytes).sum() }
    pub fn latest_snapshot(&self) -> Option<&AyxLocalHistoryEntry> { self.snapshots.last() }
}


// --- ayy_ testing framework integration ---

/// Test run state.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AyyTestState { Queued, Running, Passed, Failed, Skipped, Errored }

/// Test item kind.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AyyTestKind { Suite, Test, Case }

/// A test item in the tree.
#[derive(Debug, Clone)]
pub struct AyyTestItem {
    pub id: String,
    pub label: String,
    pub kind: AyyTestKind,
    pub uri: Option<String>,
    pub line: Option<u32>,
    pub children: Vec<String>,
    pub tags: Vec<String>,
}

impl AyyTestItem {
    pub fn suite(id: &str, label: &str) -> Self {
        Self { id: id.to_string(), label: label.to_string(), kind: AyyTestKind::Suite, uri: None, line: None, children: Vec::new(), tags: Vec::new() }
    }
    pub fn test(id: &str, label: &str, uri: &str, line: u32) -> Self {
        Self { id: id.to_string(), label: label.to_string(), kind: AyyTestKind::Test, uri: Some(uri.to_string()), line: Some(line), children: Vec::new(), tags: Vec::new() }
    }
    pub fn add_child(&mut self, child_id: &str) { self.children.push(child_id.to_string()); }
    pub fn add_tag(&mut self, tag: &str) { self.tags.push(tag.to_string()); }
    pub fn has_tag(&self, tag: &str) -> bool { self.tags.iter().any(|t| t == tag) }
    pub fn is_leaf(&self) -> bool { self.children.is_empty() }
}

/// Test run result.
#[derive(Debug, Clone)]
pub struct AyyTestResult {
    pub test_id: String,
    pub state: AyyTestState,
    pub duration_ms: Option<u64>,
    pub message: Option<String>,
    pub expected: Option<String>,
    pub actual: Option<String>,
}

impl AyyTestResult {
    pub fn passed(id: &str, ms: u64) -> Self {
        Self { test_id: id.to_string(), state: AyyTestState::Passed, duration_ms: Some(ms), message: None, expected: None, actual: None }
    }
    pub fn failed(id: &str, ms: u64, msg: &str) -> Self {
        Self { test_id: id.to_string(), state: AyyTestState::Failed, duration_ms: Some(ms), message: Some(msg.to_string()), expected: None, actual: None }
    }
    pub fn with_diff(mut self, expected: &str, actual: &str) -> Self {
        self.expected = Some(expected.to_string()); self.actual = Some(actual.to_string()); self
    }
    pub fn is_pass(&self) -> bool { self.state == AyyTestState::Passed }
    pub fn has_diff(&self) -> bool { self.expected.is_some() && self.actual.is_some() }
}

/// Test run that groups results.
#[derive(Debug)]
pub struct AyyTestRun {
    pub name: String,
    pub results: Vec<AyyTestResult>,
}

impl AyyTestRun {
    pub fn new(name: &str) -> Self { Self { name: name.to_string(), results: Vec::new() } }
    pub fn add_result(&mut self, r: AyyTestResult) { self.results.push(r); }
    pub fn passed_count(&self) -> usize { self.results.iter().filter(|r| r.is_pass()).count() }
    pub fn failed_count(&self) -> usize { self.results.iter().filter(|r| r.state == AyyTestState::Failed).count() }
    pub fn total(&self) -> usize { self.results.len() }
    pub fn total_duration_ms(&self) -> u64 { self.results.iter().filter_map(|r| r.duration_ms).sum() }
    pub fn all_passed(&self) -> bool { self.results.iter().all(|r| r.is_pass()) }
    pub fn failures(&self) -> Vec<&AyyTestResult> { self.results.iter().filter(|r| r.state == AyyTestState::Failed).collect() }
}

/// Test controller that manages items and runs.
#[derive(Debug)]
pub struct AyyTestController {
    pub id: String,
    pub items: Vec<AyyTestItem>,
    pub runs: Vec<AyyTestRun>,
}

impl AyyTestController {
    pub fn new(id: &str) -> Self { Self { id: id.to_string(), items: Vec::new(), runs: Vec::new() } }
    pub fn add_item(&mut self, item: AyyTestItem) { self.items.push(item); }
    pub fn add_run(&mut self, run: AyyTestRun) { self.runs.push(run); }
    pub fn find_item(&self, id: &str) -> Option<&AyyTestItem> { self.items.iter().find(|i| i.id == id) }
    pub fn leaf_tests(&self) -> Vec<&AyyTestItem> { self.items.iter().filter(|i| i.is_leaf()).collect() }
}


// --- ayz_ accessibility and screen reader ---

/// Accessibility role for UI elements.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AyzAccessRole { Editor, TreeItem, Button, List, ListItem, Menu, MenuItem, Tab, StatusBar, Dialog, Alert, Label }

/// Accessibility announcement urgency.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AyzUrgency { Polite, Assertive }

/// An accessible element description.
#[derive(Debug, Clone)]
pub struct AyzAccessNode {
    pub role: AyzAccessRole,
    pub label: String,
    pub value: Option<String>,
    pub description: Option<String>,
    pub focused: bool,
    pub children: Vec<AyzAccessNode>,
}

impl AyzAccessNode {
    pub fn new(role: AyzAccessRole, label: &str) -> Self {
        Self { role, label: label.to_string(), value: None, description: None, focused: false, children: Vec::new() }
    }
    pub fn with_value(mut self, v: &str) -> Self { self.value = Some(v.to_string()); self }
    pub fn with_desc(mut self, d: &str) -> Self { self.description = Some(d.to_string()); self }
    pub fn set_focused(&mut self, f: bool) { self.focused = f; }
    pub fn add_child(&mut self, c: AyzAccessNode) { self.children.push(c); }
    pub fn child_count(&self) -> usize { self.children.len() }
    pub fn announce_text(&self) -> String {
        let mut parts = vec![self.label.clone()];
        if let Some(v) = &self.value { parts.push(v.clone()); }
        if let Some(d) = &self.description { parts.push(d.clone()); }
        parts.join(", ")
    }
}

/// Screen reader announcement.
#[derive(Debug, Clone)]
pub struct AyzAnnouncement {
    pub message: String,
    pub urgency: AyzUrgency,
}

impl AyzAnnouncement {
    pub fn polite(msg: &str) -> Self { Self { message: msg.to_string(), urgency: AyzUrgency::Polite } }
    pub fn assertive(msg: &str) -> Self { Self { message: msg.to_string(), urgency: AyzUrgency::Assertive } }
}

/// Accessibility state manager.
#[derive(Debug)]
pub struct AyzAccessibilityState {
    pub screen_reader_active: bool,
    pub high_contrast: bool,
    pub reduce_motion: bool,
    pub announcements: Vec<AyzAnnouncement>,
    pub focus_path: Vec<String>,
}

impl AyzAccessibilityState {
    pub fn new() -> Self {
        Self { screen_reader_active: false, high_contrast: false, reduce_motion: false, announcements: Vec::new(), focus_path: Vec::new() }
    }
    pub fn enable_screen_reader(&mut self) { self.screen_reader_active = true; }
    pub fn set_high_contrast(&mut self, on: bool) { self.high_contrast = on; }
    pub fn announce(&mut self, a: AyzAnnouncement) { self.announcements.push(a); }
    pub fn announce_polite(&mut self, msg: &str) { self.announce(AyzAnnouncement::polite(msg)); }
    pub fn announce_assertive(&mut self, msg: &str) { self.announce(AyzAnnouncement::assertive(msg)); }
    pub fn set_focus(&mut self, path: Vec<String>) { self.focus_path = path; }
    pub fn current_focus(&self) -> Option<&str> { self.focus_path.last().map(|s| s.as_str()) }
    pub fn pending_announcements(&self) -> usize { self.announcements.len() }
    pub fn drain_announcements(&mut self) -> Vec<AyzAnnouncement> { std::mem::take(&mut self.announcements) }
}

/// Tab-stop manager for keyboard navigation.
#[derive(Debug)]
pub struct AyzTabStopList {
    pub stops: Vec<String>,
    pub current: usize,
}

impl AyzTabStopList {
    pub fn new(stops: Vec<String>) -> Self { Self { stops, current: 0 } }
    pub fn next(&mut self) -> Option<&str> {
        if self.stops.is_empty() { return None; }
        self.current = (self.current + 1) % self.stops.len();
        Some(&self.stops[self.current])
    }
    pub fn prev(&mut self) -> Option<&str> {
        if self.stops.is_empty() { return None; }
        self.current = if self.current == 0 { self.stops.len() - 1 } else { self.current - 1 };
        Some(&self.stops[self.current])
    }
    pub fn current_stop(&self) -> Option<&str> { self.stops.get(self.current).map(|s| s.as_str()) }
    pub fn stop_count(&self) -> usize { self.stops.len() }
}


// --- aza_ comment threads and annotations ---

/// Comment thread state.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AzaThreadState { Active, Resolved, Archived }

/// A comment in a thread.
#[derive(Debug, Clone)]
pub struct AzaComment {
    pub id: String,
    pub author: String,
    pub body: String,
    pub timestamp: u64,
    pub reactions: Vec<(String, u32)>,
}

impl AzaComment {
    pub fn new(id: &str, author: &str, body: &str, ts: u64) -> Self {
        Self { id: id.to_string(), author: author.to_string(), body: body.to_string(), timestamp: ts, reactions: Vec::new() }
    }
    pub fn add_reaction(&mut self, emoji: &str) {
        if let Some(r) = self.reactions.iter_mut().find(|r| r.0 == emoji) { r.1 += 1; }
        else { self.reactions.push((emoji.to_string(), 1)); }
    }
    pub fn total_reactions(&self) -> u32 { self.reactions.iter().map(|r| r.1).sum() }
    pub fn body_preview(&self, max: usize) -> String {
        if self.body.len() <= max { self.body.clone() } else { format!("{}...", &self.body[..max]) }
    }
}

/// A comment thread attached to a file location.
#[derive(Debug)]
pub struct AzaCommentThread {
    pub id: String,
    pub uri: String,
    pub line: u32,
    pub state: AzaThreadState,
    pub comments: Vec<AzaComment>,
    pub label: Option<String>,
}

impl AzaCommentThread {
    pub fn new(id: &str, uri: &str, line: u32) -> Self {
        Self { id: id.to_string(), uri: uri.to_string(), line, state: AzaThreadState::Active, comments: Vec::new(), label: None }
    }
    pub fn add_comment(&mut self, c: AzaComment) { self.comments.push(c); }
    pub fn resolve(&mut self) { self.state = AzaThreadState::Resolved; }
    pub fn archive(&mut self) { self.state = AzaThreadState::Archived; }
    pub fn is_active(&self) -> bool { self.state == AzaThreadState::Active }
    pub fn comment_count(&self) -> usize { self.comments.len() }
    pub fn latest_comment(&self) -> Option<&AzaComment> { self.comments.last() }
    pub fn set_label(&mut self, l: &str) { self.label = Some(l.to_string()); }
}

/// Comment controller managing multiple threads.
#[derive(Debug)]
pub struct AzaCommentController {
    pub id: String,
    pub label: String,
    pub threads: Vec<AzaCommentThread>,
}

impl AzaCommentController {
    pub fn new(id: &str, label: &str) -> Self {
        Self { id: id.to_string(), label: label.to_string(), threads: Vec::new() }
    }
    pub fn add_thread(&mut self, t: AzaCommentThread) { self.threads.push(t); }
    pub fn threads_for_uri(&self, uri: &str) -> Vec<&AzaCommentThread> {
        self.threads.iter().filter(|t| t.uri == uri).collect()
    }
    pub fn active_threads(&self) -> Vec<&AzaCommentThread> {
        self.threads.iter().filter(|t| t.is_active()).collect()
    }
    pub fn resolved_threads(&self) -> Vec<&AzaCommentThread> {
        self.threads.iter().filter(|t| t.state == AzaThreadState::Resolved).collect()
    }
    pub fn total_comments(&self) -> usize { self.threads.iter().map(|t| t.comment_count()).sum() }
    pub fn find_thread(&self, id: &str) -> Option<&AzaCommentThread> {
        self.threads.iter().find(|t| t.id == id)
    }
}

/// Document annotation.
#[derive(Debug, Clone)]
pub struct AzaAnnotation {
    pub line: u32,
    pub message: String,
    pub kind: AzaAnnotationKind,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AzaAnnotationKind { Info, Warning, Error, Suggestion }

impl AzaAnnotation {
    pub fn info(line: u32, msg: &str) -> Self { Self { line, message: msg.to_string(), kind: AzaAnnotationKind::Info } }
    pub fn warning(line: u32, msg: &str) -> Self { Self { line, message: msg.to_string(), kind: AzaAnnotationKind::Warning } }
    pub fn error(line: u32, msg: &str) -> Self { Self { line, message: msg.to_string(), kind: AzaAnnotationKind::Error } }
}


// --- azb_ source control graph and blame ---

/// SCM blame annotation for a single line.
#[derive(Debug, Clone)]
pub struct AzbBlameEntry {
    pub line: u32,
    pub commit_hash: String,
    pub author: String,
    pub date: String,
    pub message: String,
}

impl AzbBlameEntry {
    pub fn new(line: u32, hash: &str, author: &str, date: &str, msg: &str) -> Self {
        Self { line, commit_hash: hash.to_string(), author: author.to_string(), date: date.to_string(), message: msg.to_string() }
    }
    pub fn short_hash(&self) -> &str {
        if self.commit_hash.len() >= 7 { &self.commit_hash[..7] } else { &self.commit_hash }
    }
    pub fn summary(&self) -> String { format!("{} {} {}", self.short_hash(), self.author, self.message) }
}

/// Blame result for a file.
#[derive(Debug)]
pub struct AzbBlameResult {
    pub file_path: String,
    pub entries: Vec<AzbBlameEntry>,
}

impl AzbBlameResult {
    pub fn new(path: &str) -> Self { Self { file_path: path.to_string(), entries: Vec::new() } }
    pub fn add(&mut self, e: AzbBlameEntry) { self.entries.push(e); }
    pub fn entry_for_line(&self, line: u32) -> Option<&AzbBlameEntry> { self.entries.iter().find(|e| e.line == line) }
    pub fn unique_authors(&self) -> Vec<&str> {
        let mut authors: Vec<&str> = self.entries.iter().map(|e| e.author.as_str()).collect();
        authors.sort(); authors.dedup(); authors
    }
    pub fn unique_commits(&self) -> Vec<&str> {
        let mut commits: Vec<&str> = self.entries.iter().map(|e| e.commit_hash.as_str()).collect();
        commits.sort(); commits.dedup(); commits
    }
}

/// A node in the SCM commit graph.
#[derive(Debug, Clone)]
pub struct AzbGraphNode {
    pub commit_hash: String,
    pub parents: Vec<String>,
    pub author: String,
    pub message: String,
    pub timestamp: u64,
    pub branch: Option<String>,
}

impl AzbGraphNode {
    pub fn new(hash: &str, author: &str, msg: &str, ts: u64) -> Self {
        Self { commit_hash: hash.to_string(), parents: Vec::new(), author: author.to_string(), message: msg.to_string(), timestamp: ts, branch: None }
    }
    pub fn add_parent(&mut self, p: &str) { self.parents.push(p.to_string()); }
    pub fn is_merge(&self) -> bool { self.parents.len() > 1 }
    pub fn is_root(&self) -> bool { self.parents.is_empty() }
    pub fn set_branch(&mut self, b: &str) { self.branch = Some(b.to_string()); }
}

/// SCM commit graph.
#[derive(Debug)]
pub struct AzbCommitGraph {
    pub nodes: Vec<AzbGraphNode>,
}

impl AzbCommitGraph {
    pub fn new() -> Self { Self { nodes: Vec::new() } }
    pub fn add_node(&mut self, n: AzbGraphNode) { self.nodes.push(n); }
    pub fn find_node(&self, hash: &str) -> Option<&AzbGraphNode> { self.nodes.iter().find(|n| n.commit_hash == hash) }
    pub fn node_count(&self) -> usize { self.nodes.len() }
    pub fn merge_commits(&self) -> Vec<&AzbGraphNode> { self.nodes.iter().filter(|n| n.is_merge()).collect() }
    pub fn root_commits(&self) -> Vec<&AzbGraphNode> { self.nodes.iter().filter(|n| n.is_root()).collect() }
    pub fn by_author(&self, author: &str) -> Vec<&AzbGraphNode> { self.nodes.iter().filter(|n| n.author == author).collect() }
    pub fn latest(&self) -> Option<&AzbGraphNode> { self.nodes.iter().max_by_key(|n| n.timestamp) }
}


// --- azc_ editor sticky scroll ---

/// A sticky scroll scope (function, class, block).
#[derive(Debug, Clone)]
pub struct AzcStickyScope {
    pub label: String,
    pub start_line: u32,
    pub end_line: u32,
    pub depth: u32,
    pub kind: AzcScopeKind,
}

/// Scope kind for sticky scroll.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AzcScopeKind { Function, Class, Module, Block, Struct, Enum, Interface, Namespace }

impl AzcStickyScope {
    pub fn new(label: &str, start: u32, end: u32, depth: u32, kind: AzcScopeKind) -> Self {
        Self { label: label.to_string(), start_line: start, end_line: end, depth, kind }
    }
    pub fn contains_line(&self, line: u32) -> bool { line >= self.start_line && line <= self.end_line }
    pub fn line_span(&self) -> u32 { self.end_line.saturating_sub(self.start_line) + 1 }
}

/// Sticky scroll state for the editor.
#[derive(Debug)]
pub struct AzcStickyScrollState {
    pub scopes: Vec<AzcStickyScope>,
    pub max_lines: u32,
    pub enabled: bool,
}

impl AzcStickyScrollState {
    pub fn new(max: u32) -> Self { Self { scopes: Vec::new(), max_lines: max, enabled: true } }
    pub fn set_scopes(&mut self, s: Vec<AzcStickyScope>) { self.scopes = s; }
    pub fn toggle(&mut self) { self.enabled = !self.enabled; }
    pub fn visible_scopes_at(&self, cursor_line: u32) -> Vec<&AzcStickyScope> {
        if !self.enabled { return Vec::new(); }
        let mut active: Vec<&AzcStickyScope> = self.scopes.iter()
            .filter(|s| s.contains_line(cursor_line) && s.start_line < cursor_line)
            .collect();
        active.sort_by_key(|s| s.depth);
        active.truncate(self.max_lines as usize);
        active
    }
    pub fn sticky_line_count(&self, cursor_line: u32) -> usize { self.visible_scopes_at(cursor_line).len() }
    pub fn deepest_scope_at(&self, line: u32) -> Option<&AzcStickyScope> {
        self.scopes.iter().filter(|s| s.contains_line(line)).max_by_key(|s| s.depth)
    }
}

/// Sticky scroll renderer producing display lines.
#[derive(Debug)]
pub struct AzcStickyRenderer {
    pub indent_size: u32,
}

impl AzcStickyRenderer {
    pub fn new(indent: u32) -> Self { Self { indent_size: indent } }
    pub fn render_line(&self, scope: &AzcStickyScope) -> String {
        let indent = " ".repeat((scope.depth * self.indent_size) as usize);
        format!("{}{}", indent, scope.label)
    }
    pub fn render_all(&self, scopes: &[&AzcStickyScope]) -> Vec<String> {
        scopes.iter().map(|s| self.render_line(s)).collect()
    }
}


// --- azd_ profile management ---

/// A user profile containing settings, extensions, and keybindings.
#[derive(Debug, Clone)]
pub struct AzdProfile {
    pub id: String,
    pub name: String,
    pub settings: Vec<(String, String)>,
    pub extensions: Vec<String>,
    pub keybindings: Vec<(String, String)>,
    pub is_default: bool,
}

impl AzdProfile {
    pub fn new(id: &str, name: &str) -> Self {
        Self { id: id.to_string(), name: name.to_string(), settings: Vec::new(), extensions: Vec::new(), keybindings: Vec::new(), is_default: false }
    }
    pub fn default_profile() -> Self {
        let mut p = Self::new("default", "Default");
        p.is_default = true;
        p
    }
    pub fn add_setting(&mut self, key: &str, val: &str) { self.settings.push((key.to_string(), val.to_string())); }
    pub fn add_extension(&mut self, ext: &str) { self.extensions.push(ext.to_string()); }
    pub fn add_keybinding(&mut self, key: &str, cmd: &str) { self.keybindings.push((key.to_string(), cmd.to_string())); }
    pub fn get_setting(&self, key: &str) -> Option<&str> {
        self.settings.iter().rev().find(|s| s.0 == key).map(|s| s.1.as_str())
    }
    pub fn has_extension(&self, ext: &str) -> bool { self.extensions.iter().any(|e| e == ext) }
    pub fn extension_count(&self) -> usize { self.extensions.len() }
}

/// Profile store managing multiple profiles.
#[derive(Debug)]
pub struct AzdProfileStore {
    pub profiles: Vec<AzdProfile>,
    pub active_id: String,
}

impl AzdProfileStore {
    pub fn new() -> Self {
        let def = AzdProfile::default_profile();
        let id = def.id.clone();
        Self { profiles: vec![def], active_id: id }
    }
    pub fn add_profile(&mut self, p: AzdProfile) { self.profiles.push(p); }
    pub fn switch_profile(&mut self, id: &str) -> bool {
        if self.profiles.iter().any(|p| p.id == id) { self.active_id = id.to_string(); true } else { false }
    }
    pub fn active_profile(&self) -> Option<&AzdProfile> { self.profiles.iter().find(|p| p.id == self.active_id) }
    pub fn profile_count(&self) -> usize { self.profiles.len() }
    pub fn remove_profile(&mut self, id: &str) -> bool {
        if id == "default" { return false; }
        let before = self.profiles.len();
        self.profiles.retain(|p| p.id != id);
        if self.active_id == id { self.active_id = "default".to_string(); }
        self.profiles.len() < before
    }
    pub fn profile_names(&self) -> Vec<&str> { self.profiles.iter().map(|p| p.name.as_str()).collect() }
    pub fn find_profile(&self, id: &str) -> Option<&AzdProfile> { self.profiles.iter().find(|p| p.id == id) }
}

/// Profile export/import format.
#[derive(Debug, Clone)]
pub struct AzdProfileExport {
    pub name: String,
    pub settings_json: String,
    pub extensions_list: Vec<String>,
}

impl AzdProfileExport {
    pub fn from_profile(p: &AzdProfile) -> Self {
        let json = p.settings.iter().map(|s| format!("{}={}", s.0, s.1)).collect::<Vec<_>>().join(",");
        Self { name: p.name.clone(), settings_json: json, extensions_list: p.extensions.clone() }
    }
    pub fn has_settings(&self) -> bool { !self.settings_json.is_empty() }
    pub fn has_extensions(&self) -> bool { !self.extensions_list.is_empty() }
}


// --- aze_ editor inlay hint resolution ---

/// Inlay hint position kind.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AzeHintPosition { Before, After, Parameter, Type }

/// A part of an inlay hint label.
#[derive(Debug, Clone)]
pub struct AzeHintLabelPart {
    pub value: String,
    pub tooltip: Option<String>,
    pub command: Option<String>,
}

impl AzeHintLabelPart {
    pub fn text(v: &str) -> Self { Self { value: v.to_string(), tooltip: None, command: None } }
    pub fn with_tooltip(mut self, t: &str) -> Self { self.tooltip = Some(t.to_string()); self }
    pub fn with_command(mut self, c: &str) -> Self { self.command = Some(c.to_string()); self }
    pub fn is_clickable(&self) -> bool { self.command.is_some() }
}

/// A resolved inlay hint.
#[derive(Debug, Clone)]
pub struct AzeInlayHint {
    pub line: u32,
    pub col: u32,
    pub position: AzeHintPosition,
    pub parts: Vec<AzeHintLabelPart>,
    pub padding_left: bool,
    pub padding_right: bool,
}

impl AzeInlayHint {
    pub fn new(line: u32, col: u32, pos: AzeHintPosition) -> Self {
        Self { line, col, position: pos, parts: Vec::new(), padding_left: false, padding_right: false }
    }
    pub fn add_part(&mut self, p: AzeHintLabelPart) { self.parts.push(p); }
    pub fn with_padding(mut self, left: bool, right: bool) -> Self { self.padding_left = left; self.padding_right = right; self }
    pub fn full_label(&self) -> String { self.parts.iter().map(|p| p.value.as_str()).collect::<Vec<_>>().join("") }
    pub fn has_command(&self) -> bool { self.parts.iter().any(|p| p.is_clickable()) }
    pub fn is_type_hint(&self) -> bool { self.position == AzeHintPosition::Type }
    pub fn is_parameter_hint(&self) -> bool { self.position == AzeHintPosition::Parameter }
}

/// Inlay hint set for a document.
#[derive(Debug)]
pub struct AzeInlayHintSet {
    pub hints: Vec<AzeInlayHint>,
    pub enabled: bool,
}

impl AzeInlayHintSet {
    pub fn new() -> Self { Self { hints: Vec::new(), enabled: true } }
    pub fn set_hints(&mut self, h: Vec<AzeInlayHint>) { self.hints = h; }
    pub fn toggle(&mut self) { self.enabled = !self.enabled; }
    pub fn hints_at_line(&self, line: u32) -> Vec<&AzeInlayHint> {
        if !self.enabled { return Vec::new(); }
        self.hints.iter().filter(|h| h.line == line).collect()
    }
    pub fn type_hints(&self) -> Vec<&AzeInlayHint> { self.hints.iter().filter(|h| h.is_type_hint()).collect() }
    pub fn param_hints(&self) -> Vec<&AzeInlayHint> { self.hints.iter().filter(|h| h.is_parameter_hint()).collect() }
    pub fn total_hints(&self) -> usize { self.hints.len() }
    pub fn clear(&mut self) { self.hints.clear(); }
}


// --- azf_ color picker and color decorations ---

/// An RGBA color value.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct AzfColor {
    pub r: f64, pub g: f64, pub b: f64, pub a: f64,
}

impl AzfColor {
    pub fn rgba(r: f64, g: f64, b: f64, a: f64) -> Self { Self { r, g, b, a } }
    pub fn rgb(r: f64, g: f64, b: f64) -> Self { Self { r, g, b, a: 1.0 } }
    pub fn to_hex(&self) -> String {
        format!("#{:02x}{:02x}{:02x}", (self.r * 255.0) as u8, (self.g * 255.0) as u8, (self.b * 255.0) as u8)
    }
    pub fn luminance(&self) -> f64 { 0.2126 * self.r + 0.7152 * self.g + 0.0722 * self.b }
    pub fn is_dark(&self) -> bool { self.luminance() < 0.5 }
    pub fn with_alpha(self, a: f64) -> Self { Self { a, ..self } }
    pub fn blend(&self, other: &AzfColor, t: f64) -> AzfColor {
        AzfColor { r: self.r + (other.r - self.r) * t, g: self.g + (other.g - self.g) * t, b: self.b + (other.b - self.b) * t, a: self.a + (other.a - self.a) * t }
    }
}

/// A color occurrence in a document.
#[derive(Debug, Clone)]
pub struct AzfColorInfo {
    pub line: u32,
    pub start_col: u32,
    pub end_col: u32,
    pub color: AzfColor,
}

impl AzfColorInfo {
    pub fn new(line: u32, start: u32, end: u32, color: AzfColor) -> Self {
        Self { line, start_col: start, end_col: end, color }
    }
    pub fn span(&self) -> u32 { self.end_col - self.start_col }
}

/// Document color provider state.
#[derive(Debug)]
pub struct AzfColorDecorations {
    pub colors: Vec<AzfColorInfo>,
    pub enabled: bool,
}

impl AzfColorDecorations {
    pub fn new() -> Self { Self { colors: Vec::new(), enabled: true } }
    pub fn set_colors(&mut self, c: Vec<AzfColorInfo>) { self.colors = c; }
    pub fn toggle(&mut self) { self.enabled = !self.enabled; }
    pub fn colors_at_line(&self, line: u32) -> Vec<&AzfColorInfo> {
        if !self.enabled { return Vec::new(); }
        self.colors.iter().filter(|c| c.line == line).collect()
    }
    pub fn total(&self) -> usize { self.colors.len() }
    pub fn clear(&mut self) { self.colors.clear(); }
}

/// Color presentation (how to display a chosen color).
#[derive(Debug, Clone)]
pub struct AzfColorPresentation {
    pub label: String,
    pub text_edit: Option<String>,
}

impl AzfColorPresentation {
    pub fn hex(color: &AzfColor) -> Self { Self { label: color.to_hex(), text_edit: Some(color.to_hex()) } }
    pub fn rgb_fn(color: &AzfColor) -> Self {
        let label = format!("rgb({}, {}, {})", (color.r * 255.0) as u8, (color.g * 255.0) as u8, (color.b * 255.0) as u8);
        Self { label: label.clone(), text_edit: Some(label) }
    }
}


// --- azg_ document link and URL detection ---

/// A document link in a file.
#[derive(Debug, Clone)]
pub struct AzgDocumentLink {
    pub line: u32,
    pub start_col: u32,
    pub end_col: u32,
    pub target: Option<String>,
    pub tooltip: Option<String>,
}

impl AzgDocumentLink {
    pub fn new(line: u32, start: u32, end: u32) -> Self {
        Self { line, start_col: start, end_col: end, target: None, tooltip: None }
    }
    pub fn with_target(mut self, t: &str) -> Self { self.target = Some(t.to_string()); self }
    pub fn with_tooltip(mut self, t: &str) -> Self { self.tooltip = Some(t.to_string()); self }
    pub fn is_resolved(&self) -> bool { self.target.is_some() }
    pub fn span(&self) -> u32 { self.end_col - self.start_col }
    pub fn contains_col(&self, col: u32) -> bool { col >= self.start_col && col < self.end_col }
}

/// URL detection result.
#[derive(Debug, Clone)]
pub struct AzgUrlMatch {
    pub url: String,
    pub line: u32,
    pub start_col: u32,
    pub end_col: u32,
    pub scheme: String,
}

impl AzgUrlMatch {
    pub fn new(url: &str, line: u32, start: u32, end: u32) -> Self {
        let scheme = url.split("://").next().unwrap_or("").to_string();
        Self { url: url.to_string(), line, start_col: start, end_col: end, scheme }
    }
    pub fn is_http(&self) -> bool { self.scheme == "http" || self.scheme == "https" }
    pub fn is_file(&self) -> bool { self.scheme == "file" }
}

/// Document link provider state.
#[derive(Debug)]
pub struct AzgLinkState {
    pub links: Vec<AzgDocumentLink>,
    pub urls: Vec<AzgUrlMatch>,
    pub enabled: bool,
}

impl AzgLinkState {
    pub fn new() -> Self { Self { links: Vec::new(), urls: Vec::new(), enabled: true } }
    pub fn set_links(&mut self, l: Vec<AzgDocumentLink>) { self.links = l; }
    pub fn set_urls(&mut self, u: Vec<AzgUrlMatch>) { self.urls = u; }
    pub fn toggle(&mut self) { self.enabled = !self.enabled; }
    pub fn links_at_line(&self, line: u32) -> Vec<&AzgDocumentLink> {
        if !self.enabled { return Vec::new(); }
        self.links.iter().filter(|l| l.line == line).collect()
    }
    pub fn link_at(&self, line: u32, col: u32) -> Option<&AzgDocumentLink> {
        if !self.enabled { return None; }
        self.links.iter().find(|l| l.line == line && l.contains_col(col))
    }
    pub fn urls_at_line(&self, line: u32) -> Vec<&AzgUrlMatch> {
        self.urls.iter().filter(|u| u.line == line).collect()
    }
    pub fn all_http_urls(&self) -> Vec<&AzgUrlMatch> { self.urls.iter().filter(|u| u.is_http()).collect() }
    pub fn total_links(&self) -> usize { self.links.len() + self.urls.len() }
}


// --- azh_ selection highlight and word highlight ---

/// A highlight range in a document.
#[derive(Debug, Clone)]
pub struct AzhHighlightRange {
    pub line: u32,
    pub start_col: u32,
    pub end_col: u32,
    pub kind: AzhHighlightKind,
}

/// Highlight kind.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AzhHighlightKind { Read, Write, Text, SearchMatch, SelectionHighlight }

impl AzhHighlightRange {
    pub fn new(line: u32, start: u32, end: u32, kind: AzhHighlightKind) -> Self {
        Self { line, start_col: start, end_col: end, kind }
    }
    pub fn read(line: u32, start: u32, end: u32) -> Self { Self::new(line, start, end, AzhHighlightKind::Read) }
    pub fn write(line: u32, start: u32, end: u32) -> Self { Self::new(line, start, end, AzhHighlightKind::Write) }
    pub fn selection(line: u32, start: u32, end: u32) -> Self { Self::new(line, start, end, AzhHighlightKind::SelectionHighlight) }
    pub fn span(&self) -> u32 { self.end_col - self.start_col }
    pub fn is_write(&self) -> bool { self.kind == AzhHighlightKind::Write }
}

/// Document highlight state.
#[derive(Debug)]
pub struct AzhHighlightState {
    pub word_highlights: Vec<AzhHighlightRange>,
    pub selection_highlights: Vec<AzhHighlightRange>,
    pub search_highlights: Vec<AzhHighlightRange>,
    pub enabled: bool,
}

impl AzhHighlightState {
    pub fn new() -> Self {
        Self { word_highlights: Vec::new(), selection_highlights: Vec::new(), search_highlights: Vec::new(), enabled: true }
    }
    pub fn set_word_highlights(&mut self, h: Vec<AzhHighlightRange>) { self.word_highlights = h; }
    pub fn set_selection_highlights(&mut self, h: Vec<AzhHighlightRange>) { self.selection_highlights = h; }
    pub fn set_search_highlights(&mut self, h: Vec<AzhHighlightRange>) { self.search_highlights = h; }
    pub fn clear_all(&mut self) {
        self.word_highlights.clear(); self.selection_highlights.clear(); self.search_highlights.clear();
    }
    pub fn all_at_line(&self, line: u32) -> Vec<&AzhHighlightRange> {
        if !self.enabled { return Vec::new(); }
        let mut result: Vec<&AzhHighlightRange> = self.word_highlights.iter()
            .chain(self.selection_highlights.iter())
            .chain(self.search_highlights.iter())
            .filter(|h| h.line == line).collect();
        result.sort_by_key(|h| h.start_col);
        result
    }
    pub fn word_highlight_count(&self) -> usize { self.word_highlights.len() }
    pub fn write_references(&self) -> Vec<&AzhHighlightRange> { self.word_highlights.iter().filter(|h| h.is_write()).collect() }
    pub fn search_match_count(&self) -> usize { self.search_highlights.len() }
    pub fn toggle(&mut self) { self.enabled = !self.enabled; }
}

/// Word occurrence finder.
pub struct AzhWordFinder;

impl AzhWordFinder {
    pub fn find_occurrences(text: &str, word: &str) -> Vec<(u32, u32, u32)> {
        let mut results = Vec::new();
        for (line_idx, line) in text.lines().enumerate() {
            let mut start = 0;
            while let Some(pos) = line[start..].find(word) {
                let col = (start + pos) as u32;
                results.push((line_idx as u32, col, col + word.len() as u32));
                start += pos + word.len();
            }
        }
        results
    }
}


// --- azi_ snippet variables and transforms ---

/// Snippet variable kind.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AziVarKind { BuiltIn, Selection, Clipboard, DateTime, Random, Comment, Workspace }

/// A snippet variable.
#[derive(Debug, Clone)]
pub struct AziSnippetVar {
    pub name: String,
    pub kind: AziVarKind,
    pub default_value: Option<String>,
}

impl AziSnippetVar {
    pub fn built_in(name: &str) -> Self { Self { name: name.to_string(), kind: AziVarKind::BuiltIn, default_value: None } }
    pub fn with_default(mut self, d: &str) -> Self { self.default_value = Some(d.to_string()); self }
    pub fn resolve(&self, ctx: &AziVarContext) -> String {
        ctx.get(&self.name).unwrap_or_else(|| self.default_value.clone().unwrap_or_default())
    }
}

/// Variable resolution context.
#[derive(Debug)]
pub struct AziVarContext {
    pub values: Vec<(String, String)>,
}

impl AziVarContext {
    pub fn new() -> Self { Self { values: Vec::new() } }
    pub fn set(&mut self, name: &str, val: &str) { self.values.push((name.to_string(), val.to_string())); }
    pub fn get(&self, name: &str) -> Option<String> {
        self.values.iter().rev().find(|v| v.0 == name).map(|v| v.1.clone())
    }
    pub fn with_file_info(mut self, filename: &str, dir: &str) -> Self {
        self.set("TM_FILENAME", filename);
        self.set("TM_DIRECTORY", dir);
        if let Some(base) = filename.split('.').next() { self.set("TM_FILENAME_BASE", base); }
        self
    }
}

/// Snippet text transform.
#[derive(Debug, Clone)]
pub struct AziTransform {
    pub kind: AziTransformKind,
}

/// Transform kinds.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AziTransformKind { Upcase, Downcase, Capitalize, CamelCase, PascalCase, SnakeCase }

impl AziTransform {
    pub fn new(kind: AziTransformKind) -> Self { Self { kind } }
    pub fn apply(&self, input: &str) -> String {
        match self.kind {
            AziTransformKind::Upcase => input.to_uppercase(),
            AziTransformKind::Downcase => input.to_lowercase(),
            AziTransformKind::Capitalize => {
                let mut c = input.chars();
                match c.next() { None => String::new(), Some(f) => f.to_uppercase().to_string() + &c.as_str().to_lowercase() }
            }
            AziTransformKind::CamelCase => {
                let parts: Vec<&str> = input.split(|c: char| c == '_' || c == '-' || c == ' ').collect();
                let mut r = String::new();
                for (i, p) in parts.iter().enumerate() {
                    if i == 0 { r.push_str(&p.to_lowercase()); }
                    else {
                        let mut cs = p.chars();
                        if let Some(f) = cs.next() { r.push(f.to_uppercase().next().unwrap_or(f)); r.push_str(&cs.as_str().to_lowercase()); }
                    }
                }
                r
            }
            AziTransformKind::PascalCase => {
                input.split(|c: char| c == '_' || c == '-' || c == ' ').map(|p| {
                    let mut cs = p.chars();
                    match cs.next() { None => String::new(), Some(f) => f.to_uppercase().to_string() + &cs.as_str().to_lowercase() }
                }).collect()
            }
            AziTransformKind::SnakeCase => {
                let mut r = String::new();
                for (i, c) in input.chars().enumerate() {
                    if c.is_uppercase() && i > 0 { r.push('_'); }
                    r.push(c.to_lowercase().next().unwrap_or(c));
                }
                r
            }
        }
    }
}


// --- azj_ editor folding strategies ---

/// Folding range kind.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AzjFoldKind { Comment, Imports, Region, Code }

/// A folding range.
#[derive(Debug, Clone)]
pub struct AzjFoldingRange {
    pub start_line: u32,
    pub end_line: u32,
    pub kind: AzjFoldKind,
    pub collapsed_text: Option<String>,
}

impl AzjFoldingRange {
    pub fn new(start: u32, end: u32, kind: AzjFoldKind) -> Self {
        Self { start_line: start, end_line: end, kind, collapsed_text: None }
    }
    pub fn with_text(mut self, t: &str) -> Self { self.collapsed_text = Some(t.to_string()); self }
    pub fn line_count(&self) -> u32 { self.end_line - self.start_line + 1 }
    pub fn contains_line(&self, line: u32) -> bool { line >= self.start_line && line <= self.end_line }
    pub fn is_comment(&self) -> bool { self.kind == AzjFoldKind::Comment }
    pub fn is_region(&self) -> bool { self.kind == AzjFoldKind::Region }
}

/// Folding state for a document.
#[derive(Debug)]
pub struct AzjFoldingState {
    pub ranges: Vec<AzjFoldingRange>,
    pub collapsed: Vec<u32>,
}

impl AzjFoldingState {
    pub fn new() -> Self { Self { ranges: Vec::new(), collapsed: Vec::new() } }
    pub fn set_ranges(&mut self, r: Vec<AzjFoldingRange>) { self.ranges = r; self.collapsed.clear(); }
    pub fn toggle_fold(&mut self, start_line: u32) {
        if let Some(pos) = self.collapsed.iter().position(|l| *l == start_line) {
            self.collapsed.remove(pos);
        } else if self.ranges.iter().any(|r| r.start_line == start_line) {
            self.collapsed.push(start_line);
        }
    }
    pub fn is_collapsed(&self, start_line: u32) -> bool { self.collapsed.contains(&start_line) }
    pub fn fold_all(&mut self) {
        self.collapsed = self.ranges.iter().map(|r| r.start_line).collect();
    }
    pub fn unfold_all(&mut self) { self.collapsed.clear(); }
    pub fn fold_comments(&mut self) {
        for r in &self.ranges {
            if r.is_comment() && !self.collapsed.contains(&r.start_line) { self.collapsed.push(r.start_line); }
        }
    }
    pub fn fold_regions(&mut self) {
        for r in &self.ranges {
            if r.is_region() && !self.collapsed.contains(&r.start_line) { self.collapsed.push(r.start_line); }
        }
    }
    pub fn is_line_hidden(&self, line: u32) -> bool {
        for start in &self.collapsed {
            if let Some(r) = self.ranges.iter().find(|r| r.start_line == *start) {
                if line > r.start_line && line <= r.end_line { return true; }
            }
        }
        false
    }
    pub fn visible_line_count(&self, total: u32) -> u32 {
        (0..total).filter(|l| !self.is_line_hidden(*l)).count() as u32
    }
    pub fn collapsed_count(&self) -> usize { self.collapsed.len() }
    pub fn range_count(&self) -> usize { self.ranges.len() }
}


// --- azk_ glyph margin and breakpoint decorations ---

/// Glyph margin decoration kind.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AzkGlyphKind { Breakpoint, ConditionalBreakpoint, Logpoint, DataBreakpoint, Bookmark, Error, Warning }

/// A glyph margin decoration.
#[derive(Debug, Clone)]
pub struct AzkGlyphDecoration {
    pub line: u32,
    pub kind: AzkGlyphKind,
    pub tooltip: Option<String>,
    pub enabled: bool,
}

impl AzkGlyphDecoration {
    pub fn breakpoint(line: u32) -> Self {
        Self { line, kind: AzkGlyphKind::Breakpoint, tooltip: None, enabled: true }
    }
    pub fn conditional(line: u32, condition: &str) -> Self {
        Self { line, kind: AzkGlyphKind::ConditionalBreakpoint, tooltip: Some(condition.to_string()), enabled: true }
    }
    pub fn logpoint(line: u32, msg: &str) -> Self {
        Self { line, kind: AzkGlyphKind::Logpoint, tooltip: Some(msg.to_string()), enabled: true }
    }
    pub fn bookmark(line: u32) -> Self {
        Self { line, kind: AzkGlyphKind::Bookmark, tooltip: None, enabled: true }
    }
    pub fn toggle_enabled(&mut self) { self.enabled = !self.enabled; }
    pub fn is_breakpoint_type(&self) -> bool {
        matches!(self.kind, AzkGlyphKind::Breakpoint | AzkGlyphKind::ConditionalBreakpoint | AzkGlyphKind::Logpoint | AzkGlyphKind::DataBreakpoint)
    }
    pub fn symbol(&self) -> &str {
        match self.kind {
            AzkGlyphKind::Breakpoint => "O",
            AzkGlyphKind::ConditionalBreakpoint => "?",
            AzkGlyphKind::Logpoint => "L",
            AzkGlyphKind::DataBreakpoint => "D",
            AzkGlyphKind::Bookmark => "*",
            AzkGlyphKind::Error => "X",
            AzkGlyphKind::Warning => "!",
        }
    }
}

/// Glyph margin state for a document.
#[derive(Debug)]
pub struct AzkGlyphMargin {
    pub decorations: Vec<AzkGlyphDecoration>,
}

impl AzkGlyphMargin {
    pub fn new() -> Self { Self { decorations: Vec::new() } }
    pub fn add(&mut self, d: AzkGlyphDecoration) { self.decorations.push(d); }
    pub fn remove_at_line(&mut self, line: u32) { self.decorations.retain(|d| d.line != line); }
    pub fn at_line(&self, line: u32) -> Vec<&AzkGlyphDecoration> {
        self.decorations.iter().filter(|d| d.line == line).collect()
    }
    pub fn toggle_breakpoint(&mut self, line: u32) {
        if let Some(pos) = self.decorations.iter().position(|d| d.line == line && d.kind == AzkGlyphKind::Breakpoint) {
            self.decorations.remove(pos);
        } else {
            self.add(AzkGlyphDecoration::breakpoint(line));
        }
    }
    pub fn all_breakpoints(&self) -> Vec<&AzkGlyphDecoration> {
        self.decorations.iter().filter(|d| d.is_breakpoint_type()).collect()
    }
    pub fn all_bookmarks(&self) -> Vec<&AzkGlyphDecoration> {
        self.decorations.iter().filter(|d| d.kind == AzkGlyphKind::Bookmark).collect()
    }
    pub fn breakpoint_lines(&self) -> Vec<u32> {
        self.all_breakpoints().iter().map(|d| d.line).collect()
    }
    pub fn clear_breakpoints(&mut self) { self.decorations.retain(|d| !d.is_breakpoint_type()); }
    pub fn total(&self) -> usize { self.decorations.len() }
}


// --- azl_ editor layout and ruler configuration ---

/// Line number display mode.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AzlLineNumberMode { On, Off, Relative, Interval }

/// Minimap display mode.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AzlMinimapMode { Show, Hide, Autohide }

/// Editor ruler position.
#[derive(Debug, Clone)]
pub struct AzlRuler {
    pub column: u32,
    pub color: Option<String>,
}

impl AzlRuler {
    pub fn at(col: u32) -> Self { Self { column: col, color: None } }
    pub fn with_color(mut self, c: &str) -> Self { self.color = Some(c.to_string()); self }
}

/// Editor layout configuration.
#[derive(Debug)]
pub struct AzlEditorLayout {
    pub line_numbers: AzlLineNumberMode,
    pub minimap_mode: AzlMinimapMode,
    pub minimap_side: AzlSide,
    pub rulers: Vec<AzlRuler>,
    pub word_wrap_column: u32,
    pub tab_size: u32,
    pub insert_spaces: bool,
    pub render_whitespace: AzlWhitespace,
    pub glyph_margin: bool,
    pub line_decorations_width: u32,
}

/// Side for minimap/panels.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AzlSide { Left, Right }

/// Whitespace rendering mode.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AzlWhitespace { None, Boundary, Selection, Trailing, All }

impl AzlEditorLayout {
    pub fn default_layout() -> Self {
        Self {
            line_numbers: AzlLineNumberMode::On, minimap_mode: AzlMinimapMode::Show,
            minimap_side: AzlSide::Right, rulers: Vec::new(), word_wrap_column: 80,
            tab_size: 4, insert_spaces: true, render_whitespace: AzlWhitespace::None,
            glyph_margin: true, line_decorations_width: 2,
        }
    }
    pub fn set_line_numbers(&mut self, m: AzlLineNumberMode) { self.line_numbers = m; }
    pub fn add_ruler(&mut self, r: AzlRuler) { self.rulers.push(r); }
    pub fn set_tab_size(&mut self, s: u32) { self.tab_size = s; }
    pub fn set_minimap(&mut self, m: AzlMinimapMode) { self.minimap_mode = m; }
    pub fn has_rulers(&self) -> bool { !self.rulers.is_empty() }
    pub fn shows_line_numbers(&self) -> bool { self.line_numbers != AzlLineNumberMode::Off }
    pub fn shows_minimap(&self) -> bool { self.minimap_mode != AzlMinimapMode::Hide }
    pub fn compute_line_number(&self, current: u32, cursor: u32) -> String {
        match self.line_numbers {
            AzlLineNumberMode::On => format!("{}", current + 1),
            AzlLineNumberMode::Off => String::new(),
            AzlLineNumberMode::Relative => {
                if current == cursor { format!("{}", current + 1) }
                else { format!("{}", (current as i64 - cursor as i64).unsigned_abs()) }
            }
            AzlLineNumberMode::Interval => {
                if (current + 1) % 10 == 0 || current == 0 { format!("{}", current + 1) }
                else { String::new() }
            }
        }
    }
}


// --- azm_ call hierarchy model ---

/// Call hierarchy item kind.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AzmSymbolKind { Function, Method, Constructor, Class, Interface, Module, Property, Variable }

/// A call hierarchy item.
#[derive(Debug, Clone)]
pub struct AzmCallHierarchyItem {
    pub name: String,
    pub kind: AzmSymbolKind,
    pub uri: String,
    pub line: u32,
    pub col: u32,
    pub detail: Option<String>,
}

impl AzmCallHierarchyItem {
    pub fn new(name: &str, kind: AzmSymbolKind, uri: &str, line: u32, col: u32) -> Self {
        Self { name: name.to_string(), kind, uri: uri.to_string(), line, col, detail: None }
    }
    pub fn with_detail(mut self, d: &str) -> Self { self.detail = Some(d.to_string()); self }
    pub fn display_name(&self) -> String {
        if let Some(d) = &self.detail { format!("{} - {}", self.name, d) } else { self.name.clone() }
    }
}

/// An incoming call.
#[derive(Debug, Clone)]
pub struct AzmIncomingCall {
    pub from: AzmCallHierarchyItem,
    pub from_ranges: Vec<(u32, u32, u32)>,
}

impl AzmIncomingCall {
    pub fn new(from: AzmCallHierarchyItem) -> Self { Self { from, from_ranges: Vec::new() } }
    pub fn add_range(&mut self, line: u32, start: u32, end: u32) { self.from_ranges.push((line, start, end)); }
    pub fn call_count(&self) -> usize { self.from_ranges.len() }
}

/// An outgoing call.
#[derive(Debug, Clone)]
pub struct AzmOutgoingCall {
    pub to: AzmCallHierarchyItem,
    pub from_ranges: Vec<(u32, u32, u32)>,
}

impl AzmOutgoingCall {
    pub fn new(to: AzmCallHierarchyItem) -> Self { Self { to, from_ranges: Vec::new() } }
    pub fn add_range(&mut self, line: u32, start: u32, end: u32) { self.from_ranges.push((line, start, end)); }
    pub fn call_count(&self) -> usize { self.from_ranges.len() }
}

/// Call hierarchy tree.
#[derive(Debug)]
pub struct AzmCallHierarchy {
    pub root: AzmCallHierarchyItem,
    pub incoming: Vec<AzmIncomingCall>,
    pub outgoing: Vec<AzmOutgoingCall>,
}

impl AzmCallHierarchy {
    pub fn new(root: AzmCallHierarchyItem) -> Self { Self { root, incoming: Vec::new(), outgoing: Vec::new() } }
    pub fn set_incoming(&mut self, calls: Vec<AzmIncomingCall>) { self.incoming = calls; }
    pub fn set_outgoing(&mut self, calls: Vec<AzmOutgoingCall>) { self.outgoing = calls; }
    pub fn incoming_count(&self) -> usize { self.incoming.len() }
    pub fn outgoing_count(&self) -> usize { self.outgoing.len() }
    pub fn total_incoming_refs(&self) -> usize { self.incoming.iter().map(|c| c.call_count()).sum() }
    pub fn callers(&self) -> Vec<&str> { self.incoming.iter().map(|c| c.from.name.as_str()).collect() }
    pub fn callees(&self) -> Vec<&str> { self.outgoing.iter().map(|c| c.to.name.as_str()).collect() }
}


// --- azn_ type hierarchy model ---

/// Type hierarchy item.
#[derive(Debug, Clone)]
pub struct AznTypeHierarchyItem {
    pub name: String,
    pub kind: AznTypeKind,
    pub uri: String,
    pub line: u32,
    pub col: u32,
    pub detail: Option<String>,
    pub tags: Vec<String>,
}

/// Type kind in hierarchy.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AznTypeKind { Class, Interface, Struct, Enum, Trait, TypeAlias }

impl AznTypeHierarchyItem {
    pub fn new(name: &str, kind: AznTypeKind, uri: &str, line: u32, col: u32) -> Self {
        Self { name: name.to_string(), kind, uri: uri.to_string(), line, col, detail: None, tags: Vec::new() }
    }
    pub fn with_detail(mut self, d: &str) -> Self { self.detail = Some(d.to_string()); self }
    pub fn add_tag(&mut self, t: &str) { self.tags.push(t.to_string()); }
    pub fn is_deprecated(&self) -> bool { self.tags.iter().any(|t| t == "deprecated") }
}

/// Supertype (parent) relationship.
#[derive(Debug, Clone)]
pub struct AznSupertype {
    pub item: AznTypeHierarchyItem,
}

/// Subtype (child) relationship.
#[derive(Debug, Clone)]
pub struct AznSubtype {
    pub item: AznTypeHierarchyItem,
}

/// Type hierarchy tree.
#[derive(Debug)]
pub struct AznTypeHierarchy {
    pub root: AznTypeHierarchyItem,
    pub supertypes: Vec<AznSupertype>,
    pub subtypes: Vec<AznSubtype>,
}

impl AznTypeHierarchy {
    pub fn new(root: AznTypeHierarchyItem) -> Self {
        Self { root, supertypes: Vec::new(), subtypes: Vec::new() }
    }
    pub fn add_supertype(&mut self, item: AznTypeHierarchyItem) {
        self.supertypes.push(AznSupertype { item });
    }
    pub fn add_subtype(&mut self, item: AznTypeHierarchyItem) {
        self.subtypes.push(AznSubtype { item });
    }
    pub fn supertype_count(&self) -> usize { self.supertypes.len() }
    pub fn subtype_count(&self) -> usize { self.subtypes.len() }
    pub fn supertype_names(&self) -> Vec<&str> { self.supertypes.iter().map(|s| s.item.name.as_str()).collect() }
    pub fn subtype_names(&self) -> Vec<&str> { self.subtypes.iter().map(|s| s.item.name.as_str()).collect() }
    pub fn has_supertypes(&self) -> bool { !self.supertypes.is_empty() }
    pub fn has_subtypes(&self) -> bool { !self.subtypes.is_empty() }
    pub fn find_supertype(&self, name: &str) -> Option<&AznTypeHierarchyItem> {
        self.supertypes.iter().find(|s| s.item.name == name).map(|s| &s.item)
    }
    pub fn find_subtype(&self, name: &str) -> Option<&AznTypeHierarchyItem> {
        self.subtypes.iter().find(|s| s.item.name == name).map(|s| &s.item)
    }
}


// --- azo_ semantic token modifiers and legend ---

/// Semantic token type.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum AzoTokenType {
    Namespace, Type, Class, Enum, Interface, Struct, TypeParameter,
    Parameter, Variable, Property, EnumMember, Event, Function, Method,
    Macro, Keyword, Modifier, Comment, String, Number, Regexp, Operator,
    Decorator,
}

/// Semantic token modifier.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum AzoTokenModifier {
    Declaration, Definition, Readonly, Static, Deprecated,
    Abstract, Async, Modification, Documentation, DefaultLibrary,
}

/// Semantic token legend mapping types/modifiers to IDs.
#[derive(Debug)]
pub struct AzoSemanticTokensLegend {
    pub token_types: Vec<AzoTokenType>,
    pub token_modifiers: Vec<AzoTokenModifier>,
}

impl AzoSemanticTokensLegend {
    pub fn default_legend() -> Self {
        Self {
            token_types: vec![
                AzoTokenType::Namespace, AzoTokenType::Type, AzoTokenType::Class,
                AzoTokenType::Enum, AzoTokenType::Interface, AzoTokenType::Struct,
                AzoTokenType::TypeParameter, AzoTokenType::Parameter, AzoTokenType::Variable,
                AzoTokenType::Property, AzoTokenType::EnumMember, AzoTokenType::Function,
                AzoTokenType::Method, AzoTokenType::Macro, AzoTokenType::Keyword,
                AzoTokenType::Comment, AzoTokenType::String, AzoTokenType::Number,
                AzoTokenType::Operator,
            ],
            token_modifiers: vec![
                AzoTokenModifier::Declaration, AzoTokenModifier::Definition,
                AzoTokenModifier::Readonly, AzoTokenModifier::Static,
                AzoTokenModifier::Deprecated, AzoTokenModifier::Async,
            ],
        }
    }
    pub fn type_id(&self, t: AzoTokenType) -> Option<u32> { self.token_types.iter().position(|x| *x == t).map(|i| i as u32) }
    pub fn modifier_bit(&self, m: AzoTokenModifier) -> Option<u32> { self.token_modifiers.iter().position(|x| *x == m).map(|i| 1u32 << i) }
    pub fn type_count(&self) -> usize { self.token_types.len() }
    pub fn modifier_count(&self) -> usize { self.token_modifiers.len() }
}

/// A single semantic token (delta-encoded).
#[derive(Debug, Clone)]
pub struct AzoSemanticToken {
    pub delta_line: u32,
    pub delta_start: u32,
    pub length: u32,
    pub token_type: u32,
    pub token_modifiers: u32,
}

impl AzoSemanticToken {
    pub fn new(dl: u32, ds: u32, len: u32, tt: u32, tm: u32) -> Self {
        Self { delta_line: dl, delta_start: ds, length: len, token_type: tt, token_modifiers: tm }
    }
    pub fn has_modifier(&self, bit: u32) -> bool { self.token_modifiers & bit != 0 }
}

/// Semantic tokens data for a document.
#[derive(Debug)]
pub struct AzoSemanticTokensData {
    pub tokens: Vec<AzoSemanticToken>,
    pub result_id: Option<String>,
}

impl AzoSemanticTokensData {
    pub fn new() -> Self { Self { tokens: Vec::new(), result_id: None } }
    pub fn add(&mut self, t: AzoSemanticToken) { self.tokens.push(t); }
    pub fn token_count(&self) -> usize { self.tokens.len() }
    pub fn set_result_id(&mut self, id: &str) { self.result_id = Some(id.to_string()); }
    pub fn to_flat(&self) -> Vec<u32> {
        let mut v = Vec::with_capacity(self.tokens.len() * 5);
        for t in &self.tokens { v.extend_from_slice(&[t.delta_line, t.delta_start, t.length, t.token_type, t.token_modifiers]); }
        v
    }
}


// --- azp_ whitespace rendering and indentation guides ---

/// Whitespace character kind.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AzpWhitespaceChar { Space, Tab, NonBreakingSpace, IdeographicSpace }

/// A whitespace token in a line.
#[derive(Debug, Clone)]
pub struct AzpWhitespaceToken {
    pub col: u32,
    pub length: u32,
    pub kind: AzpWhitespaceChar,
}

impl AzpWhitespaceToken {
    pub fn space(col: u32, len: u32) -> Self { Self { col, length: len, kind: AzpWhitespaceChar::Space } }
    pub fn tab(col: u32) -> Self { Self { col, length: 1, kind: AzpWhitespaceChar::Tab } }
    pub fn end_col(&self) -> u32 { self.col + self.length }
    pub fn is_tab(&self) -> bool { self.kind == AzpWhitespaceChar::Tab }
}

/// Indentation guide.
#[derive(Debug, Clone)]
pub struct AzpIndentGuide {
    pub column: u32,
    pub start_line: u32,
    pub end_line: u32,
    pub active: bool,
    pub level: u32,
}

impl AzpIndentGuide {
    pub fn new(col: u32, start: u32, end: u32, level: u32) -> Self {
        Self { column: col, start_line: start, end_line: end, active: false, level }
    }
    pub fn set_active(&mut self, a: bool) { self.active = a; }
    pub fn contains_line(&self, line: u32) -> bool { line >= self.start_line && line <= self.end_line }
    pub fn line_span(&self) -> u32 { self.end_line - self.start_line + 1 }
}

/// Whitespace rendering state for an editor.
#[derive(Debug)]
pub struct AzpWhitespaceRenderer {
    pub mode: AzpRenderMode,
    pub indent_guides_enabled: bool,
    pub bracket_pair_guides: bool,
    pub tab_size: u32,
}

/// Rendering mode.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AzpRenderMode { None, Boundary, Selection, Trailing, All }

impl AzpWhitespaceRenderer {
    pub fn new(tab_size: u32) -> Self {
        Self { mode: AzpRenderMode::Boundary, indent_guides_enabled: true, bracket_pair_guides: true, tab_size }
    }
    pub fn set_mode(&mut self, m: AzpRenderMode) { self.mode = m; }
    pub fn should_render_space(&self, is_boundary: bool, in_selection: bool, is_trailing: bool) -> bool {
        match self.mode {
            AzpRenderMode::None => false,
            AzpRenderMode::All => true,
            AzpRenderMode::Boundary => is_boundary,
            AzpRenderMode::Selection => in_selection,
            AzpRenderMode::Trailing => is_trailing,
        }
    }
    pub fn compute_indent_guides(&self, lines: &[&str]) -> Vec<AzpIndentGuide> {
        let mut guides = Vec::new();
        let mut i = 0;
        while i < lines.len() {
            let indent = lines[i].len() - lines[i].trim_start().len();
            let levels = indent as u32 / self.tab_size;
            for l in 0..levels {
                let col = l * self.tab_size;
                let mut end = i;
                while end + 1 < lines.len() {
                    let next_indent = lines[end + 1].len() - lines[end + 1].trim_start().len();
                    if (next_indent as u32) <= col { break; }
                    end += 1;
                }
                if end > i { guides.push(AzpIndentGuide::new(col, i as u32, end as u32, l)); }
            }
            i += 1;
        }
        guides
    }
}


// --- azq_ editor cursor blinking and style ---

/// Cursor style.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AzqCursorStyle { Line, Block, Underline, LineThin, BlockOutline, UnderlineThin }

/// Cursor blink mode.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AzqBlinkMode { Blink, Smooth, Phase, Expand, Solid, Hidden }

/// Cursor state model.
#[derive(Debug)]
pub struct AzqCursorState {
    pub style: AzqCursorStyle,
    pub blink: AzqBlinkMode,
    pub blink_interval_ms: u32,
    pub visible: bool,
    pub smooth_caret: bool,
    pub width: u32,
}

impl AzqCursorState {
    pub fn new() -> Self {
        Self { style: AzqCursorStyle::Line, blink: AzqBlinkMode::Blink, blink_interval_ms: 530, visible: true, smooth_caret: true, width: 2 }
    }
    pub fn set_style(&mut self, s: AzqCursorStyle) { self.style = s; }
    pub fn set_blink(&mut self, b: AzqBlinkMode) { self.blink = b; }
    pub fn set_interval(&mut self, ms: u32) { self.blink_interval_ms = ms; }
    pub fn is_blinking(&self) -> bool { self.blink != AzqBlinkMode::Solid && self.blink != AzqBlinkMode::Hidden }
    pub fn is_visible(&self) -> bool { self.visible && self.blink != AzqBlinkMode::Hidden }
    pub fn toggle_blink(&mut self) { if self.is_blinking() { self.visible = !self.visible; } }
    pub fn reset_blink(&mut self) { self.visible = true; }
    pub fn is_block(&self) -> bool { matches!(self.style, AzqCursorStyle::Block | AzqCursorStyle::BlockOutline) }
    pub fn is_line(&self) -> bool { matches!(self.style, AzqCursorStyle::Line | AzqCursorStyle::LineThin) }
    pub fn is_underline(&self) -> bool { matches!(self.style, AzqCursorStyle::Underline | AzqCursorStyle::UnderlineThin) }
    pub fn terminal_cursor_shape(&self) -> &str {
        match self.style {
            AzqCursorStyle::Line | AzqCursorStyle::LineThin => "bar",
            AzqCursorStyle::Block | AzqCursorStyle::BlockOutline => "block",
            AzqCursorStyle::Underline | AzqCursorStyle::UnderlineThin => "underline",
        }
    }
}

/// Multi-cursor position.
#[derive(Debug, Clone)]
pub struct AzqCursorPosition {
    pub line: u32,
    pub col: u32,
    pub desired_col: Option<u32>,
}

impl AzqCursorPosition {
    pub fn new(line: u32, col: u32) -> Self { Self { line, col, desired_col: None } }
    pub fn with_desired(mut self, c: u32) -> Self { self.desired_col = Some(c); self }
    pub fn effective_col(&self) -> u32 { self.desired_col.unwrap_or(self.col) }
}

/// Multi-cursor manager.
#[derive(Debug)]
pub struct AzqMultiCursor {
    pub cursors: Vec<AzqCursorPosition>,
    pub primary: usize,
}

impl AzqMultiCursor {
    pub fn single(line: u32, col: u32) -> Self { Self { cursors: vec![AzqCursorPosition::new(line, col)], primary: 0 } }
    pub fn add_cursor(&mut self, line: u32, col: u32) { self.cursors.push(AzqCursorPosition::new(line, col)); }
    pub fn cursor_count(&self) -> usize { self.cursors.len() }
    pub fn primary_cursor(&self) -> &AzqCursorPosition { &self.cursors[self.primary] }
    pub fn is_multi(&self) -> bool { self.cursors.len() > 1 }
    pub fn collapse_to_primary(&mut self) {
        let p = self.cursors[self.primary].clone();
        self.cursors = vec![p];
        self.primary = 0;
    }
}


// --- azr_ auto-closing pairs and surround ---

/// An auto-closing pair.
#[derive(Debug, Clone)]
pub struct AzrAutoClosePair {
    pub open: String,
    pub close: String,
    pub not_in: Vec<String>,
}

impl AzrAutoClosePair {
    pub fn new(open: &str, close: &str) -> Self { Self { open: open.to_string(), close: close.to_string(), not_in: Vec::new() } }
    pub fn not_in_string(mut self) -> Self { self.not_in.push("string".to_string()); self }
    pub fn not_in_comment(mut self) -> Self { self.not_in.push("comment".to_string()); self }
    pub fn is_symmetric(&self) -> bool { self.open == self.close }
    pub fn should_close_in(&self, context: &str) -> bool { !self.not_in.iter().any(|n| n == context) }
}

/// Language bracket configuration.
#[derive(Debug)]
pub struct AzrBracketConfig {
    pub auto_closing_pairs: Vec<AzrAutoClosePair>,
    pub surrounding_pairs: Vec<(String, String)>,
    pub colorized_brackets: Vec<(String, String)>,
}

impl AzrBracketConfig {
    pub fn default_config() -> Self {
        Self {
            auto_closing_pairs: vec![
                AzrAutoClosePair::new("(", ")"),
                AzrAutoClosePair::new("[", "]"),
                AzrAutoClosePair::new("{", "}"),
                AzrAutoClosePair::new("\"", "\"").not_in_string(),
                AzrAutoClosePair::new("'", "'").not_in_string().not_in_comment(),
            ],
            surrounding_pairs: vec![
                ("(".to_string(), ")".to_string()),
                ("[".to_string(), "]".to_string()),
                ("{".to_string(), "}".to_string()),
                ("\"".to_string(), "\"".to_string()),
            ],
            colorized_brackets: vec![
                ("(".to_string(), ")".to_string()),
                ("[".to_string(), "]".to_string()),
                ("{".to_string(), "}".to_string()),
            ],
        }
    }
    pub fn find_closing(&self, open: &str) -> Option<&str> {
        self.auto_closing_pairs.iter().find(|p| p.open == open).map(|p| p.close.as_str())
    }
    pub fn find_opening(&self, close: &str) -> Option<&str> {
        self.auto_closing_pairs.iter().find(|p| p.close == close).map(|p| p.open.as_str())
    }
    pub fn is_open_bracket(&self, c: &str) -> bool { self.auto_closing_pairs.iter().any(|p| p.open == c) }
    pub fn is_close_bracket(&self, c: &str) -> bool { self.auto_closing_pairs.iter().any(|p| p.close == c) }
    pub fn pair_count(&self) -> usize { self.auto_closing_pairs.len() }
    pub fn is_surround_pair(&self, open: &str, close: &str) -> bool {
        self.surrounding_pairs.iter().any(|p| p.0 == open && p.1 == close)
    }
}

/// Auto-surround action.
#[derive(Debug)]
pub struct AzrSurroundAction {
    pub open: String,
    pub close: String,
    pub selection_start: u32,
    pub selection_end: u32,
}

impl AzrSurroundAction {
    pub fn new(open: &str, close: &str, start: u32, end: u32) -> Self {
        Self { open: open.to_string(), close: close.to_string(), selection_start: start, selection_end: end }
    }
    pub fn result_text(&self, selected: &str) -> String { format!("{}{}{}", self.open, selected, self.close) }
    pub fn new_cursor_offset(&self) -> u32 { self.open.len() as u32 }
}


// --- azs_ auto-indent and on-enter rules ---

/// Indentation action.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AzsIndentAction { None, Indent, IndentOutdent, Outdent }

/// An on-enter rule.
#[derive(Debug, Clone)]
pub struct AzsOnEnterRule {
    pub before_text_pattern: String,
    pub after_text_pattern: Option<String>,
    pub action: AzsIndentAction,
    pub append_text: Option<String>,
    pub remove_text: Option<u32>,
}

impl AzsOnEnterRule {
    pub fn new(before: &str, action: AzsIndentAction) -> Self {
        Self { before_text_pattern: before.to_string(), after_text_pattern: None, action, append_text: None, remove_text: None }
    }
    pub fn with_after(mut self, after: &str) -> Self { self.after_text_pattern = Some(after.to_string()); self }
    pub fn with_append(mut self, text: &str) -> Self { self.append_text = Some(text.to_string()); self }
    pub fn with_remove(mut self, n: u32) -> Self { self.remove_text = Some(n); self }
    pub fn matches_before(&self, text: &str) -> bool { text.contains(&self.before_text_pattern) }
    pub fn matches_after(&self, text: &str) -> bool {
        self.after_text_pattern.as_ref().map_or(true, |p| text.contains(p))
    }
}

/// Auto-indent configuration.
#[derive(Debug)]
pub struct AzsAutoIndent {
    pub rules: Vec<AzsOnEnterRule>,
    pub increase_pattern: Option<String>,
    pub decrease_pattern: Option<String>,
}

impl AzsAutoIndent {
    pub fn new() -> Self { Self { rules: Vec::new(), increase_pattern: None, decrease_pattern: None } }
    pub fn add_rule(&mut self, r: AzsOnEnterRule) { self.rules.push(r); }
    pub fn set_increase(&mut self, p: &str) { self.increase_pattern = Some(p.to_string()); }
    pub fn set_decrease(&mut self, p: &str) { self.decrease_pattern = Some(p.to_string()); }
    pub fn should_increase(&self, line: &str) -> bool {
        self.increase_pattern.as_ref().map_or(false, |p| line.contains(p))
    }
    pub fn should_decrease(&self, line: &str) -> bool {
        self.decrease_pattern.as_ref().map_or(false, |p| line.contains(p))
    }
    pub fn find_rule(&self, before: &str, after: &str) -> Option<&AzsOnEnterRule> {
        self.rules.iter().find(|r| r.matches_before(before) && r.matches_after(after))
    }
    pub fn rule_count(&self) -> usize { self.rules.len() }
}

/// Indent computation result.
#[derive(Debug, Clone)]
pub struct AzsIndentResult {
    pub action: AzsIndentAction,
    pub indent_level: u32,
    pub append_text: Option<String>,
}

impl AzsIndentResult {
    pub fn keep(level: u32) -> Self { Self { action: AzsIndentAction::None, indent_level: level, append_text: None } }
    pub fn increase(level: u32) -> Self { Self { action: AzsIndentAction::Indent, indent_level: level + 1, append_text: None } }
    pub fn decrease(level: u32) -> Self { Self { action: AzsIndentAction::Outdent, indent_level: level.saturating_sub(1), append_text: None } }
    pub fn with_text(mut self, t: &str) -> Self { self.append_text = Some(t.to_string()); self }
    pub fn indent_string(&self, tab_size: u32, use_spaces: bool) -> String {
        if use_spaces { " ".repeat((self.indent_level * tab_size) as usize) }
        else { "	".repeat(self.indent_level as usize) }
    }
}


// --- azt_ editor token classification and scope ---

/// Token classification for syntax highlighting.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AztTokenClass {
    Keyword, Identifier, StringLiteral, NumberLiteral, Comment,
    Operator, Punctuation, Type, Function, Variable, Parameter,
    Property, EnumMember, Macro, Decorator, Namespace, Label,
    RegExp, Escape, Invalid,
}

/// A classified token in a line.
#[derive(Debug, Clone)]
pub struct AztClassifiedToken {
    pub start: u32,
    pub length: u32,
    pub class: AztTokenClass,
    pub scopes: Vec<String>,
}

impl AztClassifiedToken {
    pub fn new(start: u32, length: u32, class: AztTokenClass) -> Self {
        Self { start, length, class, scopes: Vec::new() }
    }
    pub fn with_scope(mut self, s: &str) -> Self { self.scopes.push(s.to_string()); self }
    pub fn end(&self) -> u32 { self.start + self.length }
    pub fn matches_scope(&self, prefix: &str) -> bool { self.scopes.iter().any(|s| s.starts_with(prefix)) }
    pub fn is_comment(&self) -> bool { self.class == AztTokenClass::Comment }
    pub fn is_string(&self) -> bool { self.class == AztTokenClass::StringLiteral }
}

/// Token line result.
#[derive(Debug)]
pub struct AztTokenizedLine {
    pub line_number: u32,
    pub tokens: Vec<AztClassifiedToken>,
    pub end_state: u32,
}

impl AztTokenizedLine {
    pub fn new(line: u32, state: u32) -> Self { Self { line_number: line, tokens: Vec::new(), end_state: state } }
    pub fn add_token(&mut self, t: AztClassifiedToken) { self.tokens.push(t); }
    pub fn token_count(&self) -> usize { self.tokens.len() }
    pub fn token_at_offset(&self, offset: u32) -> Option<&AztClassifiedToken> {
        self.tokens.iter().find(|t| offset >= t.start && offset < t.end())
    }
    pub fn comments(&self) -> Vec<&AztClassifiedToken> { self.tokens.iter().filter(|t| t.is_comment()).collect() }
    pub fn strings(&self) -> Vec<&AztClassifiedToken> { self.tokens.iter().filter(|t| t.is_string()).collect() }
}

/// Scope selector for theme matching.
#[derive(Debug, Clone)]
pub struct AztScopeSelector {
    pub parts: Vec<String>,
}

impl AztScopeSelector {
    pub fn parse(s: &str) -> Self { Self { parts: s.split('.').map(|p| p.to_string()).collect() } }
    pub fn matches(&self, scope: &str) -> bool {
        let scope_parts: Vec<&str> = scope.split('.').collect();
        self.parts.iter().enumerate().all(|(i, p)| scope_parts.get(i).map_or(false, |sp| sp == p))
    }
    pub fn specificity(&self) -> usize { self.parts.len() }
}


// --- azu_ editor drag-drop and data transfer ---

/// Drag-drop data kind.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AzuDropKind { Text, Files, Uri, Custom }

/// Data transfer item.
#[derive(Debug, Clone)]
pub struct AzuTransferItem {
    pub kind: AzuDropKind,
    pub mime_type: String,
    pub data: Vec<u8>,
}

impl AzuTransferItem {
    pub fn text(s: &str) -> Self { Self { kind: AzuDropKind::Text, mime_type: "text/plain".to_string(), data: s.as_bytes().to_vec() } }
    pub fn uri(u: &str) -> Self { Self { kind: AzuDropKind::Uri, mime_type: "text/uri-list".to_string(), data: u.as_bytes().to_vec() } }
    pub fn files(paths: &[&str]) -> Self {
        let joined = paths.join("
");
        Self { kind: AzuDropKind::Files, mime_type: "text/uri-list".to_string(), data: joined.into_bytes() }
    }
    pub fn as_text(&self) -> Option<String> { String::from_utf8(self.data.clone()).ok() }
    pub fn is_text(&self) -> bool { self.kind == AzuDropKind::Text }
    pub fn is_files(&self) -> bool { self.kind == AzuDropKind::Files }
    pub fn byte_size(&self) -> usize { self.data.len() }
}

/// Drop target position.
#[derive(Debug, Clone)]
pub struct AzuDropTarget {
    pub line: u32,
    pub col: u32,
    pub area: AzuDropArea,
}

/// Drop area classification.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AzuDropArea { Editor, Explorer, TabBar, Terminal, Panel }

impl AzuDropTarget {
    pub fn editor(line: u32, col: u32) -> Self { Self { line, col, area: AzuDropArea::Editor } }
    pub fn explorer() -> Self { Self { line: 0, col: 0, area: AzuDropArea::Explorer } }
    pub fn tab_bar() -> Self { Self { line: 0, col: 0, area: AzuDropArea::TabBar } }
    pub fn is_editor(&self) -> bool { self.area == AzuDropArea::Editor }
}

/// Drag-drop operation state.
#[derive(Debug)]
pub struct AzuDragDropState {
    pub active: bool,
    pub items: Vec<AzuTransferItem>,
    pub target: Option<AzuDropTarget>,
    pub copy_mode: bool,
}

impl AzuDragDropState {
    pub fn new() -> Self { Self { active: false, items: Vec::new(), target: None, copy_mode: false } }
    pub fn start_drag(&mut self, items: Vec<AzuTransferItem>) { self.active = true; self.items = items; }
    pub fn update_target(&mut self, t: AzuDropTarget) { self.target = Some(t); }
    pub fn set_copy(&mut self, c: bool) { self.copy_mode = c; }
    pub fn cancel(&mut self) { self.active = false; self.items.clear(); self.target = None; }
    pub fn complete(&mut self) -> Option<(Vec<AzuTransferItem>, AzuDropTarget)> {
        if !self.active { return None; }
        self.active = false;
        let items = std::mem::take(&mut self.items);
        self.target.take().map(|t| (items, t))
    }
    pub fn item_count(&self) -> usize { self.items.len() }
    pub fn has_text(&self) -> bool { self.items.iter().any(|i| i.is_text()) }
    pub fn has_files(&self) -> bool { self.items.iter().any(|i| i.is_files()) }
}


// --- azv_ editor scroll and viewport state ---

/// Scroll direction.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AzvScrollDir { Up, Down, Left, Right }

/// Editor viewport state.
#[derive(Debug)]
pub struct AzvViewport {
    pub top_line: u32,
    pub left_col: u32,
    pub visible_lines: u32,
    pub visible_cols: u32,
    pub total_lines: u32,
    pub max_line_length: u32,
}

impl AzvViewport {
    pub fn new(visible_lines: u32, visible_cols: u32) -> Self {
        Self { top_line: 0, left_col: 0, visible_lines, visible_cols, total_lines: 0, max_line_length: 0 }
    }
    pub fn set_content(&mut self, total_lines: u32, max_len: u32) {
        self.total_lines = total_lines; self.max_line_length = max_len;
    }
    pub fn bottom_line(&self) -> u32 { (self.top_line + self.visible_lines).min(self.total_lines) }
    pub fn right_col(&self) -> u32 { self.left_col + self.visible_cols }
    pub fn is_line_visible(&self, line: u32) -> bool { line >= self.top_line && line < self.bottom_line() }
    pub fn scroll_to_line(&mut self, line: u32) {
        if line < self.top_line { self.top_line = line; }
        else if line >= self.bottom_line() { self.top_line = line.saturating_sub(self.visible_lines - 1); }
    }
    pub fn scroll_by(&mut self, dir: AzvScrollDir, amount: u32) {
        match dir {
            AzvScrollDir::Up => self.top_line = self.top_line.saturating_sub(amount),
            AzvScrollDir::Down => {
                let max = self.total_lines.saturating_sub(self.visible_lines);
                self.top_line = (self.top_line + amount).min(max);
            }
            AzvScrollDir::Left => self.left_col = self.left_col.saturating_sub(amount),
            AzvScrollDir::Right => self.left_col = (self.left_col + amount).min(self.max_line_length),
        }
    }
    pub fn page_up(&mut self) { self.scroll_by(AzvScrollDir::Up, self.visible_lines); }
    pub fn page_down(&mut self) { self.scroll_by(AzvScrollDir::Down, self.visible_lines); }
    pub fn scroll_fraction(&self) -> f64 {
        if self.total_lines <= self.visible_lines { 1.0 }
        else { self.top_line as f64 / (self.total_lines - self.visible_lines) as f64 }
    }
    pub fn scrollbar_size(&self) -> u32 {
        if self.total_lines == 0 { return self.visible_lines; }
        ((self.visible_lines as f64 / self.total_lines as f64) * self.visible_lines as f64).max(1.0) as u32
    }
    pub fn scrollbar_position(&self) -> u32 {
        if self.total_lines <= self.visible_lines { return 0; }
        let track = self.visible_lines.saturating_sub(self.scrollbar_size());
        ((self.scroll_fraction() * track as f64) as u32).min(track)
    }
}

/// Smooth scroll animation state.
#[derive(Debug)]
pub struct AzvSmoothScroll {
    pub enabled: bool,
    pub target_line: u32,
    pub current_offset: f64,
    pub velocity: f64,
}

impl AzvSmoothScroll {
    pub fn new() -> Self { Self { enabled: true, target_line: 0, current_offset: 0.0, velocity: 0.0 } }
    pub fn set_target(&mut self, line: u32) { self.target_line = line; }
    pub fn is_animating(&self) -> bool { self.enabled && (self.current_offset - self.target_line as f64).abs() > 0.5 }
    pub fn step(&mut self, dt: f64) {
        let diff = self.target_line as f64 - self.current_offset;
        self.velocity = diff * 8.0 * dt;
        self.current_offset += self.velocity;
    }
    pub fn snap(&mut self) { self.current_offset = self.target_line as f64; self.velocity = 0.0; }
}


// --- azw_ find widget and match navigation ---

/// Find match in a document.
#[derive(Debug, Clone)]
pub struct AzwFindMatch {
    pub line: u32,
    pub start_col: u32,
    pub end_col: u32,
}

impl AzwFindMatch {
    pub fn new(line: u32, start: u32, end: u32) -> Self { Self { line, start_col: start, end_col: end } }
    pub fn span(&self) -> u32 { self.end_col - self.start_col }
}

/// Find widget options.
#[derive(Debug, Clone)]
pub struct AzwFindOptions {
    pub case_sensitive: bool,
    pub whole_word: bool,
    pub regex: bool,
    pub in_selection: bool,
    pub preserve_case: bool,
}

impl AzwFindOptions {
    pub fn default_opts() -> Self {
        Self { case_sensitive: false, whole_word: false, regex: false, in_selection: false, preserve_case: false }
    }
    pub fn toggle_case(&mut self) { self.case_sensitive = !self.case_sensitive; }
    pub fn toggle_word(&mut self) { self.whole_word = !self.whole_word; }
    pub fn toggle_regex(&mut self) { self.regex = !self.regex; }
}

/// Find widget state.
#[derive(Debug)]
pub struct AzwFindState {
    pub search_term: String,
    pub replace_term: String,
    pub options: AzwFindOptions,
    pub matches: Vec<AzwFindMatch>,
    pub current_match: Option<usize>,
    pub visible: bool,
    pub replace_visible: bool,
}

impl AzwFindState {
    pub fn new() -> Self {
        Self { search_term: String::new(), replace_term: String::new(), options: AzwFindOptions::default_opts(), matches: Vec::new(), current_match: None, visible: false, replace_visible: false }
    }
    pub fn set_search(&mut self, term: &str) { self.search_term = term.to_string(); }
    pub fn set_replace(&mut self, term: &str) { self.replace_term = term.to_string(); }
    pub fn open(&mut self) { self.visible = true; }
    pub fn close(&mut self) { self.visible = false; self.replace_visible = false; }
    pub fn toggle_replace(&mut self) { self.replace_visible = !self.replace_visible; }
    pub fn set_matches(&mut self, m: Vec<AzwFindMatch>) {
        self.matches = m;
        self.current_match = if self.matches.is_empty() { None } else { Some(0) };
    }
    pub fn match_count(&self) -> usize { self.matches.len() }
    pub fn current_match_index(&self) -> Option<usize> { self.current_match }
    pub fn next_match(&mut self) {
        if let Some(idx) = self.current_match {
            self.current_match = Some((idx + 1) % self.matches.len());
        }
    }
    pub fn prev_match(&mut self) {
        if let Some(idx) = self.current_match {
            self.current_match = Some(if idx == 0 { self.matches.len() - 1 } else { idx - 1 });
        }
    }
    pub fn current(&self) -> Option<&AzwFindMatch> {
        self.current_match.and_then(|i| self.matches.get(i))
    }
    pub fn status_text(&self) -> String {
        match self.current_match {
            Some(i) => format!("{} of {}", i + 1, self.matches.len()),
            None => "No results".to_string(),
        }
    }
}


// --- azx_ editor command registration and dispatch ---

/// A registered command.
#[derive(Debug, Clone)]
pub struct AzxCommand {
    pub id: String,
    pub title: String,
    pub category: Option<String>,
    pub keybinding: Option<String>,
    pub when_clause: Option<String>,
}

impl AzxCommand {
    pub fn new(id: &str, title: &str) -> Self {
        Self { id: id.to_string(), title: title.to_string(), category: None, keybinding: None, when_clause: None }
    }
    pub fn with_category(mut self, c: &str) -> Self { self.category = Some(c.to_string()); self }
    pub fn with_keybinding(mut self, k: &str) -> Self { self.keybinding = Some(k.to_string()); self }
    pub fn with_when(mut self, w: &str) -> Self { self.when_clause = Some(w.to_string()); self }
    pub fn display_label(&self) -> String {
        if let Some(c) = &self.category { format!("{}: {}", c, self.title) } else { self.title.clone() }
    }
    pub fn has_keybinding(&self) -> bool { self.keybinding.is_some() }
}

/// Command registry.
#[derive(Debug)]
pub struct AzxCommandRegistry {
    pub commands: Vec<AzxCommand>,
}

impl AzxCommandRegistry {
    pub fn new() -> Self { Self { commands: Vec::new() } }
    pub fn register(&mut self, cmd: AzxCommand) { self.commands.push(cmd); }
    pub fn find(&self, id: &str) -> Option<&AzxCommand> { self.commands.iter().find(|c| c.id == id) }
    pub fn by_category(&self, cat: &str) -> Vec<&AzxCommand> {
        self.commands.iter().filter(|c| c.category.as_deref() == Some(cat)).collect()
    }
    pub fn with_keybindings(&self) -> Vec<&AzxCommand> { self.commands.iter().filter(|c| c.has_keybinding()).collect() }
    pub fn search(&self, query: &str) -> Vec<&AzxCommand> {
        let q = query.to_lowercase();
        self.commands.iter().filter(|c| c.title.to_lowercase().contains(&q) || c.id.to_lowercase().contains(&q)).collect()
    }
    pub fn command_count(&self) -> usize { self.commands.len() }
    pub fn categories(&self) -> Vec<&str> {
        let mut cats: Vec<&str> = self.commands.iter().filter_map(|c| c.category.as_deref()).collect();
        cats.sort(); cats.dedup(); cats
    }
    pub fn find_by_keybinding(&self, kb: &str) -> Option<&AzxCommand> {
        self.commands.iter().find(|c| c.keybinding.as_deref() == Some(kb))
    }
}

/// Command execution context.
#[derive(Debug)]
pub struct AzxCommandContext {
    pub active_editor: Option<String>,
    pub has_selection: bool,
    pub language_id: Option<String>,
}

impl AzxCommandContext {
    pub fn new() -> Self { Self { active_editor: None, has_selection: false, language_id: None } }
    pub fn with_editor(mut self, e: &str) -> Self { self.active_editor = Some(e.to_string()); self }
    pub fn with_selection(mut self) -> Self { self.has_selection = true; self }
    pub fn evaluate_when(&self, clause: &str) -> bool {
        match clause {
            "editorTextFocus" => self.active_editor.is_some(),
            "editorHasSelection" => self.has_selection,
            _ => true,
        }
    }
}


// --- azy_ editor context menu model ---

/// Context menu item kind.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AzyMenuItemKind { Action, Separator, Submenu }

/// A context menu item.
#[derive(Debug, Clone)]
pub struct AzyMenuItem {
    pub kind: AzyMenuItemKind,
    pub command_id: Option<String>,
    pub label: Option<String>,
    pub keybinding: Option<String>,
    pub group: Option<String>,
    pub order: u32,
    pub enabled: bool,
    pub children: Vec<AzyMenuItem>,
}

impl AzyMenuItem {
    pub fn action(cmd: &str, label: &str) -> Self {
        Self { kind: AzyMenuItemKind::Action, command_id: Some(cmd.to_string()), label: Some(label.to_string()), keybinding: None, group: None, order: 0, enabled: true, children: Vec::new() }
    }
    pub fn separator() -> Self {
        Self { kind: AzyMenuItemKind::Separator, command_id: None, label: None, keybinding: None, group: None, order: 0, enabled: true, children: Vec::new() }
    }
    pub fn submenu(label: &str, children: Vec<AzyMenuItem>) -> Self {
        Self { kind: AzyMenuItemKind::Submenu, command_id: None, label: Some(label.to_string()), keybinding: None, group: None, order: 0, enabled: true, children }
    }
    pub fn with_keybinding(mut self, kb: &str) -> Self { self.keybinding = Some(kb.to_string()); self }
    pub fn with_group(mut self, g: &str, order: u32) -> Self { self.group = Some(g.to_string()); self.order = order; self }
    pub fn set_enabled(&mut self, e: bool) { self.enabled = e; }
    pub fn is_separator(&self) -> bool { self.kind == AzyMenuItemKind::Separator }
    pub fn is_submenu(&self) -> bool { self.kind == AzyMenuItemKind::Submenu }
    pub fn display_text(&self) -> String {
        match (&self.label, &self.keybinding) {
            (Some(l), Some(k)) => format!("{}  {}", l, k),
            (Some(l), None) => l.clone(),
            _ => String::new(),
        }
    }
}

/// Context menu.
#[derive(Debug)]
pub struct AzyContextMenu {
    pub items: Vec<AzyMenuItem>,
    pub visible: bool,
    pub selected_index: Option<usize>,
}

impl AzyContextMenu {
    pub fn new(items: Vec<AzyMenuItem>) -> Self { Self { items, visible: false, selected_index: None } }
    pub fn show(&mut self) { self.visible = true; self.selected_index = Some(0); }
    pub fn hide(&mut self) { self.visible = false; self.selected_index = None; }
    pub fn select_next(&mut self) {
        if let Some(idx) = self.selected_index {
            let mut next = (idx + 1) % self.items.len();
            while self.items[next].is_separator() && next != idx { next = (next + 1) % self.items.len(); }
            self.selected_index = Some(next);
        }
    }
    pub fn select_prev(&mut self) {
        if let Some(idx) = self.selected_index {
            let mut prev = if idx == 0 { self.items.len() - 1 } else { idx - 1 };
            while self.items[prev].is_separator() && prev != idx { prev = if prev == 0 { self.items.len() - 1 } else { prev - 1 }; }
            self.selected_index = Some(prev);
        }
    }
    pub fn selected_item(&self) -> Option<&AzyMenuItem> {
        self.selected_index.and_then(|i| self.items.get(i))
    }
    pub fn item_count(&self) -> usize { self.items.len() }
    pub fn action_count(&self) -> usize { self.items.iter().filter(|i| i.kind == AzyMenuItemKind::Action).count() }
}


// --- azz_ editor quick input and pick model ---

/// Quick pick item.
#[derive(Debug, Clone)]
pub struct AzzQuickPickItem {
    pub label: String,
    pub description: Option<String>,
    pub detail: Option<String>,
    pub picked: bool,
    pub always_show: bool,
    pub value: Option<String>,
}

impl AzzQuickPickItem {
    pub fn new(label: &str) -> Self {
        Self { label: label.to_string(), description: None, detail: None, picked: false, always_show: false, value: None }
    }
    pub fn with_description(mut self, d: &str) -> Self { self.description = Some(d.to_string()); self }
    pub fn with_detail(mut self, d: &str) -> Self { self.detail = Some(d.to_string()); self }
    pub fn with_value(mut self, v: &str) -> Self { self.value = Some(v.to_string()); self }
    pub fn set_picked(&mut self, p: bool) { self.picked = p; }
    pub fn display_text(&self) -> String {
        if let Some(d) = &self.description { format!("{} - {}", self.label, d) } else { self.label.clone() }
    }
}

/// Quick pick state.
#[derive(Debug)]
pub struct AzzQuickPick {
    pub items: Vec<AzzQuickPickItem>,
    pub filter: String,
    pub placeholder: String,
    pub title: Option<String>,
    pub selected_index: usize,
    pub multi_select: bool,
    pub visible: bool,
}

impl AzzQuickPick {
    pub fn new(placeholder: &str) -> Self {
        Self { items: Vec::new(), filter: String::new(), placeholder: placeholder.to_string(), title: None, selected_index: 0, multi_select: false, visible: false }
    }
    pub fn set_items(&mut self, items: Vec<AzzQuickPickItem>) { self.items = items; self.selected_index = 0; }
    pub fn set_filter(&mut self, f: &str) { self.filter = f.to_string(); }
    pub fn set_title(&mut self, t: &str) { self.title = Some(t.to_string()); }
    pub fn show(&mut self) { self.visible = true; }
    pub fn hide(&mut self) { self.visible = false; }
    pub fn filtered_items(&self) -> Vec<(usize, &AzzQuickPickItem)> {
        if self.filter.is_empty() { return self.items.iter().enumerate().collect(); }
        let f = self.filter.to_lowercase();
        self.items.iter().enumerate().filter(|(_, i)| i.always_show || i.label.to_lowercase().contains(&f) || i.description.as_ref().map_or(false, |d| d.to_lowercase().contains(&f))).collect()
    }
    pub fn select_next(&mut self) {
        let count = self.filtered_items().len();
        if count > 0 { self.selected_index = (self.selected_index + 1) % count; }
    }
    pub fn select_prev(&mut self) {
        let count = self.filtered_items().len();
        if count > 0 { self.selected_index = if self.selected_index == 0 { count - 1 } else { self.selected_index - 1 }; }
    }
    pub fn toggle_pick(&mut self) {
        if self.multi_select {
            let filtered = self.filtered_items();
            if let Some((orig_idx, _)) = filtered.get(self.selected_index) {
                let idx = *orig_idx;
                self.items[idx].picked = !self.items[idx].picked;
            }
        }
    }
    pub fn picked_items(&self) -> Vec<&AzzQuickPickItem> { self.items.iter().filter(|i| i.picked).collect() }
    pub fn item_count(&self) -> usize { self.items.len() }
}

/// Quick input box.
#[derive(Debug)]
pub struct AzzInputBox {
    pub value: String,
    pub placeholder: String,
    pub title: Option<String>,
    pub password: bool,
    pub validation_message: Option<String>,
    pub visible: bool,
}

impl AzzInputBox {
    pub fn new(placeholder: &str) -> Self {
        Self { value: String::new(), placeholder: placeholder.to_string(), title: None, password: false, validation_message: None, visible: false }
    }
    pub fn set_value(&mut self, v: &str) { self.value = v.to_string(); }
    pub fn set_password(&mut self, p: bool) { self.password = p; }
    pub fn set_validation(&mut self, msg: Option<&str>) { self.validation_message = msg.map(|s| s.to_string()); }
    pub fn is_valid(&self) -> bool { self.validation_message.is_none() }
    pub fn display_value(&self) -> String { if self.password { "*".repeat(self.value.len()) } else { self.value.clone() } }
}

