        let mut t = YvBPlusTree::new();
        t.insert(3, "three");
        t.insert(1, "one");
        t.insert(2, "two");
        assert_eq!(t.get(&1), Some(&"one"));
        assert_eq!(t.get(&2), Some(&"two"));
        assert_eq!(t.get(&3), Some(&"three"));
