    fn test_yw_pool_display() {
        let p = YwThreadPool::new(4);
        let s = format!("{}", p);
        assert!(s.contains("YwThreadPool"));
    }

    #[test]
    fn test_yw_pool_default() {
        let p = YwThreadPool::default();
        assert_eq!(p.num_threads(), 4);
    }

