    // --- zy_ keybinding and input handling tests ---

    #[test]
    fn test_zy_modifiers() {
        let m = ZyModifiers::ctrl_shift();
        assert!(m.ctrl);
        assert!(m.shift);
        assert!(m.has_any());
        assert_eq!(m.to_string_repr(), "Ctrl+Shift");
        assert!(!ZyModifiers::none().has_any());
    }

    #[test]
    fn test_zy_key_code_label() {
        assert_eq!(ZyKeyCode::Char('s').label(), "S");
        assert_eq!(ZyKeyCode::F(5).label(), "F5");
        assert_eq!(ZyKeyCode::Enter.label(), "Enter");
        assert_eq!(ZyKeyCode::Space.label(), "Space");
    }

    #[test]
    fn test_zy_key_combination() {
        let kc = ZyKeyCombination::ctrl(ZyKeyCode::Char('s'));
        assert_eq!(kc.label(), "Ctrl+S");
        let simple = ZyKeyCombination::simple(ZyKeyCode::Escape);
        assert_eq!(simple.label(), "Escape");
    }

    #[test]
    fn test_zy_keybinding_when_clause() {
        let kb = ZyKeybinding::new(
            ZyKeyCombination::ctrl(ZyKeyCode::Char('b')),
            "toggleSidebar"
        ).with_when("sidebarVisible");
        assert!(kb.matches_context(&[("sidebarVisible", true)]));
        assert!(!kb.matches_context(&[("sidebarVisible", false)]));
        assert!(!kb.matches_context(&[]));
    }

    #[test]
    fn test_zy_keybinding_negated_when() {
        let kb = ZyKeybinding::new(
            ZyKeyCombination::simple(ZyKeyCode::Escape),
            "closePanel"
        ).with_when("!editorFocus");
        assert!(kb.matches_context(&[("editorFocus", false)]));
        assert!(!kb.matches_context(&[("editorFocus", true)]));
        // Missing key treated as false, so !false = true
        assert!(kb.matches_context(&[]));
    }

    #[test]
    fn test_zy_keybinding_no_when() {
        let kb = ZyKeybinding::new(
            ZyKeyCombination::ctrl(ZyKeyCode::Char('p')),
            "quickOpen"
        );
        assert!(kb.matches_context(&[]));
        assert!(kb.matches_context(&[("anything", true)]));
    }

    #[test]
    fn test_zy_keybinding_source() {
        let kb = ZyKeybinding::new(ZyKeyCombination::simple(ZyKeyCode::Tab), "indent")
            .with_source(ZyKeybindingSource::User);
        assert_eq!(kb.source, ZyKeybindingSource::User);
    }

    #[test]
    fn test_zy_resolver_basic() {
        let mut r = ZyKeybindingResolver::new();
        r.add(ZyKeybinding::new(ZyKeyCombination::ctrl(ZyKeyCode::Char('s')), "save"));
        r.add(ZyKeybinding::new(ZyKeyCombination::ctrl(ZyKeyCode::Char('z')), "undo"));
        let key = ZyKeyCombination::ctrl(ZyKeyCode::Char('s'));
        assert_eq!(r.resolve(&key, &[]), Some("save"));
        assert_eq!(r.binding_count(), 2);
    }

    #[test]
    fn test_zy_resolver_override() {
        let mut r = ZyKeybindingResolver::new();
        r.add(ZyKeybinding::new(ZyKeyCombination::ctrl(ZyKeyCode::Char('s')), "save")
            .with_source(ZyKeybindingSource::Default));
        r.add(ZyKeybinding::new(ZyKeyCombination::ctrl(ZyKeyCode::Char('s')), "customSave")
            .with_source(ZyKeybindingSource::User));
        let key = ZyKeyCombination::ctrl(ZyKeyCode::Char('s'));
        // User binding should override default (later wins)
        assert_eq!(r.resolve(&key, &[]), Some("customSave"));
    }

    #[test]
    fn test_zy_resolver_bindings_for_command() {
        let mut r = ZyKeybindingResolver::new();
        r.add(ZyKeybinding::new(ZyKeyCombination::ctrl(ZyKeyCode::Char('c')), "copy"));
        r.add(ZyKeybinding::new(ZyKeyCombination::ctrl(ZyKeyCode::Char('x')), "cut"));
        assert_eq!(r.bindings_for_command("copy").len(), 1);
        assert_eq!(r.bindings_for_command("paste").len(), 0);
    }

    #[test]
    fn test_zy_resolver_remove() {
        let mut r = ZyKeybindingResolver::new();
        r.add(ZyKeybinding::new(ZyKeyCombination::ctrl(ZyKeyCode::Char('a')), "selectAll"));
        r.remove_command("selectAll");
        assert_eq!(r.binding_count(), 0);
    }


    // --- zz_ editor layout and window management tests ---

    #[test]
    fn test_zz_editor_tab() {
        let mut tab = ZzEditorTab::new("file:///a.rs", "a.rs");
        assert!(!tab.is_dirty);
        assert!(!tab.is_pinned);
        tab.mark_dirty();
        assert!(tab.is_dirty);
        tab.pin();
        assert!(tab.is_pinned);
        tab.mark_clean();
        assert!(!tab.is_dirty);
    }

    #[test]
    fn test_zz_editor_tab_preview() {
        let mut tab = ZzEditorTab::preview("f", "f.rs");
        assert!(tab.is_preview);
        tab.promote();
        assert!(!tab.is_preview);
    }

    #[test]
    fn test_zz_editor_group() {
        let mut group = ZzEditorGroup::new(1);
        assert!(group.is_empty());
        let idx = group.open_tab(ZzEditorTab::new("f1", "f1.rs"));
        assert_eq!(idx, 0);
        assert_eq!(group.tab_count(), 1);
        assert_eq!(group.active_tab().unwrap().uri, "f1");
        // Opening same URI again doesn't duplicate
        let idx2 = group.open_tab(ZzEditorTab::new("f1", "f1.rs"));
        assert_eq!(idx2, 0);
        assert_eq!(group.tab_count(), 1);
    }

    #[test]
    fn test_zz_editor_group_close() {
        let mut group = ZzEditorGroup::new(1);
        group.open_tab(ZzEditorTab::new("a", "a"));
        group.open_tab(ZzEditorTab::new("b", "b"));
        let closed = group.close_tab(0).unwrap();
        assert_eq!(closed.uri, "a");
        assert_eq!(group.tab_count(), 1);
        assert_eq!(group.active_tab().unwrap().uri, "b");
    }

    #[test]
    fn test_zz_editor_group_dirty() {
        let mut group = ZzEditorGroup::new(1);
        group.open_tab(ZzEditorTab::new("a", "a"));
        assert!(!group.has_dirty_tabs());
        group.tabs[0].mark_dirty();
        assert!(group.has_dirty_tabs());
        assert_eq!(group.dirty_tab_count(), 1);
    }

    #[test]
    fn test_zz_editor_layout_default() {
        let layout = ZzEditorLayout::new();
        assert_eq!(layout.group_count(), 1);
        assert!(layout.active_group().is_some());
        assert_eq!(layout.direction(), ZzLayoutDirection::Horizontal);
    }

    #[test]
    fn test_zz_editor_layout_split() {
        let mut layout = ZzEditorLayout::new();
        layout.add_group();
        assert_eq!(layout.group_count(), 2);
        // Sizes should be balanced
        assert!((layout.group(0).unwrap().size - 0.5).abs() < 0.01);
        assert!((layout.group(1).unwrap().size - 0.5).abs() < 0.01);
    }

    #[test]
    fn test_zz_editor_layout_remove_group() {
        let mut layout = ZzEditorLayout::new();
        layout.add_group();
        assert!(layout.remove_group(1));
        assert_eq!(layout.group_count(), 1);
        // Cannot remove last group
        assert!(!layout.remove_group(0));
    }

    #[test]
    fn test_zz_editor_layout_active() {
        let mut layout = ZzEditorLayout::new();
        layout.add_group();
        layout.set_active(1);
        assert!(layout.group(1).unwrap().is_active);
        assert!(!layout.group(0).unwrap().is_active);
    }

    #[test]
    fn test_zz_editor_layout_find_tab() {
        let mut layout = ZzEditorLayout::new();
        layout.active_group_mut().unwrap().open_tab(ZzEditorTab::new("x", "x"));
        assert_eq!(layout.find_tab("x"), Some((0, 0)));
        assert_eq!(layout.find_tab("y"), None);
        assert_eq!(layout.total_tabs(), 1);
    }

    #[test]
    fn test_zz_editor_layout_direction() {
        let mut layout = ZzEditorLayout::new();
        layout.set_direction(ZzLayoutDirection::Vertical);
        assert_eq!(layout.direction(), ZzLayoutDirection::Vertical);
    }


    // --- axa_ LSP protocol message tests ---

    #[test]
    fn test_axa_request_id() {
        let n = AxaRequestId::num(42);
        let s = AxaRequestId::str("abc");
        assert_ne!(n, s);
        assert_eq!(n, AxaRequestId::Number(42));
    }

    #[test]
    fn test_axa_request_basic() {
        let req = AxaRequest::new(AxaRequestId::num(1), "initialize");
        assert!(req.is_initialize());
        assert!(!req.is_shutdown());
        let json = req.to_json();
        assert!(json.contains("initialize"));
        assert!(json.contains("jsonrpc"));
    }

    #[test]
    fn test_axa_request_with_params() {
        let req = AxaRequest::new(AxaRequestId::num(1), "textDocument/completion")
            .with_params(r#"{"textDocument":{"uri":"file:///a.rs"}}"#);
        assert!(req.params.is_some());
        let json = req.to_json();
        assert!(json.contains("textDocument/completion"));
        assert!(json.contains("params"));
    }

    #[test]
    fn test_axa_request_header() {
        let req = AxaRequest::new(AxaRequestId::num(1), "shutdown");
        let header = req.to_header();
        assert!(header.starts_with("Content-Length:"));
        assert!(header.contains("\r\n\r\n"));
    }

    #[test]
    fn test_axa_response_success() {
        let resp = AxaResponse::success(AxaRequestId::num(1), r#"{"capabilities":{}}"#);
        assert!(resp.is_success());
        let json = resp.to_json();
        assert!(json.contains("result"));
        assert!(!json.contains("error"));
    }

    #[test]
    fn test_axa_response_error() {
        let resp = AxaResponse::error(
            AxaRequestId::num(1),
            AxaResponseError::method_not_found(),
        );
        assert!(!resp.is_success());
        let json = resp.to_json();
        assert!(json.contains("error"));
        assert!(json.contains("-32601"));
    }

    #[test]
    fn test_axa_response_error_variants() {
        assert_eq!(AxaResponseError::parse_error().code, -32700);
        assert_eq!(AxaResponseError::invalid_request().code, -32600);
        assert_eq!(AxaResponseError::invalid_params().code, -32602);
        assert_eq!(AxaResponseError::internal_error().code, -32603);
        assert_eq!(AxaResponseError::server_not_initialized().code, -32002);
        assert_eq!(AxaResponseError::request_cancelled().code, -32800);
    }

    #[test]
    fn test_axa_notification() {
        let n = AxaNotification::new("initialized");
        assert!(n.is_initialized());
        assert!(!n.is_exit());
        let json = n.to_json();
        assert!(json.contains("initialized"));
        assert!(!json.contains("id"));
    }

    #[test]
    fn test_axa_notification_did_methods() {
        assert!(AxaNotification::new("textDocument/didOpen").is_did_open());
        assert!(AxaNotification::new("textDocument/didChange").is_did_change());
        assert!(AxaNotification::new("textDocument/didSave").is_did_save());
        assert!(AxaNotification::new("textDocument/didClose").is_did_close());
    }

    #[test]
    fn test_axa_parse_content_length() {
        assert_eq!(axa_parse_content_length("Content-Length: 42"), Some(42));
        assert_eq!(axa_parse_content_length("content-length: 100"), Some(100));
        assert_eq!(axa_parse_content_length("X-Custom: 5"), None);
        assert_eq!(axa_parse_content_length(""), None);
    }

    #[test]
    fn test_axa_dispatcher() {
        let mut d = AxaDispatcher::new();
        d.register_request("textDocument/completion");
        d.register_notification("textDocument/didOpen");
        assert!(d.can_handle("textDocument/completion"));
        assert!(d.can_handle("textDocument/didOpen"));
        assert!(!d.can_handle("unknown"));
        assert_eq!(d.is_notification_handler("textDocument/didOpen"), Some(true));
        assert_eq!(d.is_notification_handler("textDocument/completion"), Some(false));
        assert_eq!(d.handler_count(), 2);
    }

    #[test]
    fn test_axa_pending_requests() {
        let mut pr = AxaPendingRequests::new();
        pr.add(AxaRequestId::num(1), "initialize", 1000);
        pr.add(AxaRequestId::num(2), "completion", 2000);
        assert!(pr.is_pending(&AxaRequestId::num(1)));
        assert_eq!(pr.pending_count(), 2);
        let (method, ts) = pr.remove(&AxaRequestId::num(1)).unwrap();
        assert_eq!(method, "initialize");
        assert_eq!(ts, 1000);
        assert_eq!(pr.pending_count(), 1);
    }

    #[test]
    fn test_axa_pending_timeout() {
        let mut pr = AxaPendingRequests::new();
        pr.add(AxaRequestId::num(1), "slow", 100);
        pr.add(AxaRequestId::num(2), "fast", 900);
        let timedout = pr.timed_out(1000, 500);
        assert_eq!(timedout.len(), 1);
        assert_eq!(*timedout[0], AxaRequestId::num(1));
    }


