    fn test_ayc_disable_enable() {
        let mut ext = AycExtension::new("pub", "ext");
        ext.complete_install();
        ext.disable();
        assert!(ext.is_installed());
        assert!(!ext.is_enabled());
        ext.enable();
        assert!(ext.is_enabled());
    }

