// --- baa_: Editor split/group model ---

/// Direction for splitting an editor group.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum BaaSplitDirection {
    Left,
    Right,
    Up,
    Down,
}

impl BaaSplitDirection {
    pub fn is_horizontal(self) -> bool {
        matches!(self, Self::Left | Self::Right)
    }

    pub fn is_vertical(self) -> bool {
        matches!(self, Self::Up | Self::Down)
    }

    pub fn opposite(self) -> Self {
        match self {
            Self::Left => Self::Right,
            Self::Right => Self::Left,
            Self::Up => Self::Down,
            Self::Down => Self::Up,
        }
    }
}

/// Identifies an editor group within the workbench grid.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct BaaGroupId(pub u32);

/// Identifies a single editor (tab) within a group.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct BaaEditorId(pub u64);

/// Represents a single editor tab within a group.
#[derive(Debug, Clone)]
pub struct BaaEditorTab {
    pub id: BaaEditorId,
    pub label: String,
    pub resource_path: Option<String>,
    pub is_dirty: bool,
    pub is_pinned: bool,
    pub is_preview: bool,
    pub is_active: bool,
}

impl BaaEditorTab {
    pub fn new(id: BaaEditorId, label: &str) -> Self {
        Self {
            id,
            label: label.to_string(),
            resource_path: None,
            is_dirty: false,
            is_pinned: false,
            is_preview: false,
            is_active: false,
        }
    }

    pub fn with_resource(mut self, path: &str) -> Self {
        self.resource_path = Some(path.to_string());
        self
    }

    pub fn pin(&mut self) {
        self.is_pinned = true;
        self.is_preview = false;
    }

    pub fn unpin(&mut self) {
        self.is_pinned = false;
    }

    pub fn mark_dirty(&mut self) {
        self.is_dirty = true;
    }

    pub fn mark_clean(&mut self) {
        self.is_dirty = false;
    }

    pub fn set_preview(&mut self, preview: bool) {
        if !self.is_pinned {
            self.is_preview = preview;
        }
    }
}

/// An editor group holds a list of editor tabs and tracks the active one.
#[derive(Debug, Clone)]
pub struct BaaEditorGroup {
    pub id: BaaGroupId,
    pub tabs: Vec<BaaEditorTab>,
    pub active_index: Option<usize>,
    pub is_active_group: bool,
    next_editor_id: u64,
}

impl BaaEditorGroup {
    pub fn new(id: BaaGroupId) -> Self {
        Self {
            id,
            tabs: Vec::new(),
            active_index: None,
            is_active_group: false,
            next_editor_id: 1,
        }
    }

    fn alloc_editor_id(&mut self) -> BaaEditorId {
        let id = BaaEditorId(self.next_editor_id);
        self.next_editor_id += 1;
        id
    }

    pub fn open_editor(&mut self, label: &str, resource: Option<&str>, preview: bool) -> BaaEditorId {
        if preview {
            if let Some(idx) = self.tabs.iter().position(|t| t.is_preview) {
                let id = self.alloc_editor_id();
                let mut tab = BaaEditorTab::new(id, label);
                tab.is_preview = true;
                if let Some(r) = resource {
                    tab = tab.with_resource(r);
                }
                tab.is_active = true;
                for t in &mut self.tabs {
                    t.is_active = false;
                }
                self.tabs[idx] = tab;
                self.active_index = Some(idx);
                return id;
            }
        }

        if let Some(r) = resource {
            if let Some(idx) = self.tabs.iter().position(|t| {
                t.resource_path.as_deref() == Some(r)
            }) {
                self.set_active(idx);
                return self.tabs[idx].id;
            }
        }

        let id = self.alloc_editor_id();
        let mut tab = BaaEditorTab::new(id, label);
        if let Some(r) = resource {
            tab = tab.with_resource(r);
        }
        if preview {
            tab.is_preview = true;
        }
        for t in &mut self.tabs {
            t.is_active = false;
        }
        tab.is_active = true;
        self.tabs.push(tab);
        self.active_index = Some(self.tabs.len() - 1);
        id
    }

    pub fn close_editor(&mut self, editor_id: BaaEditorId) -> bool {
        if let Some(idx) = self.tabs.iter().position(|t| t.id == editor_id) {
            self.tabs.remove(idx);
            if self.tabs.is_empty() {
                self.active_index = None;
            } else if let Some(ai) = self.active_index {
                if ai == idx {
                    let new_idx = if idx >= self.tabs.len() { self.tabs.len() - 1 } else { idx };
                    self.set_active(new_idx);
                } else if ai > idx {
                    self.active_index = Some(ai - 1);
                }
            }
            true
        } else {
            false
        }
    }

    pub fn close_all(&mut self) {
        self.tabs.clear();
        self.active_index = None;
    }

    pub fn close_saved(&mut self) {
        self.tabs.retain(|t| t.is_dirty);
        if self.tabs.is_empty() {
            self.active_index = None;
        } else {
            self.active_index = Some(0);
            self.tabs[0].is_active = true;
        }
    }

    pub fn set_active(&mut self, index: usize) {
        if index < self.tabs.len() {
            for t in &mut self.tabs {
                t.is_active = false;
            }
            self.tabs[index].is_active = true;
            self.active_index = Some(index);
            if self.tabs[index].is_preview {
                self.tabs[index].is_preview = false;
            }
        }
    }

    pub fn active_tab(&self) -> Option<&BaaEditorTab> {
        self.active_index.and_then(|i| self.tabs.get(i))
    }

    pub fn tab_count(&self) -> usize {
        self.tabs.len()
    }

    pub fn dirty_count(&self) -> usize {
        self.tabs.iter().filter(|t| t.is_dirty).count()
    }

    pub fn move_tab(&mut self, from: usize, to: usize) {
        if from < self.tabs.len() && to < self.tabs.len() && from != to {
            let tab = self.tabs.remove(from);
            self.tabs.insert(to, tab);
            if let Some(ai) = self.active_index {
                if ai == from {
                    self.active_index = Some(to);
                } else if from < ai && ai <= to {
                    self.active_index = Some(ai - 1);
                } else if to <= ai && ai < from {
                    self.active_index = Some(ai + 1);
                }
            }
        }
    }

    pub fn pinned_tabs(&self) -> Vec<&BaaEditorTab> {
        self.tabs.iter().filter(|t| t.is_pinned).collect()
    }
}

/// Orientation of a grid layout split.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BaaOrientation {
    Horizontal,
    Vertical,
}

/// A node in the editor grid layout tree.
#[derive(Debug, Clone)]
pub enum BaaGridNode {
    Leaf(BaaGroupId),
    Branch {
        orientation: BaaOrientation,
        children: Vec<BaaGridNode>,
        ratios: Vec<f64>,
    },
}

impl BaaGridNode {
    pub fn leaf(group_id: BaaGroupId) -> Self {
        Self::Leaf(group_id)
    }

    pub fn branch(orientation: BaaOrientation, children: Vec<BaaGridNode>) -> Self {
        let n = children.len();
        let ratio = 1.0 / n as f64;
        Self::Branch {
            orientation,
            children,
            ratios: vec![ratio; n],
        }
    }

    pub fn group_ids(&self) -> Vec<BaaGroupId> {
        match self {
            Self::Leaf(id) => vec![*id],
            Self::Branch { children, .. } => {
                children.iter().flat_map(|c| c.group_ids()).collect()
            }
        }
    }

    pub fn group_count(&self) -> usize {
        match self {
            Self::Leaf(_) => 1,
            Self::Branch { children, .. } => {
                children.iter().map(|c| c.group_count()).sum()
            }
        }
    }

    pub fn contains_group(&self, id: BaaGroupId) -> bool {
        match self {
            Self::Leaf(gid) => *gid == id,
            Self::Branch { children, .. } => children.iter().any(|c| c.contains_group(id)),
        }
    }

    pub fn set_ratio(&mut self, index: usize, ratio: f64) {
        if let Self::Branch { ratios, .. } = self {
            if index < ratios.len() {
                ratios[index] = ratio.clamp(0.1, 0.9);
            }
        }
    }
}

/// The editor group grid manages the full layout of all editor groups.
#[derive(Debug, Clone)]
pub struct BaaEditorGrid {
    pub root: BaaGridNode,
    pub groups: Vec<BaaEditorGroup>,
    pub active_group_id: Option<BaaGroupId>,
    next_group_id: u32,
}

impl BaaEditorGrid {
    pub fn new() -> Self {
        let group_id = BaaGroupId(1);
        let group = BaaEditorGroup::new(group_id);
        Self {
            root: BaaGridNode::leaf(group_id),
            groups: vec![group],
            active_group_id: Some(group_id),
            next_group_id: 2,
        }
    }

    fn alloc_group_id(&mut self) -> BaaGroupId {
        let id = BaaGroupId(self.next_group_id);
        self.next_group_id += 1;
        id
    }

    pub fn active_group(&self) -> Option<&BaaEditorGroup> {
        self.active_group_id.and_then(|id| {
            self.groups.iter().find(|g| g.id == id)
        })
    }

    pub fn active_group_mut(&mut self) -> Option<&mut BaaEditorGroup> {
        let id = self.active_group_id?;
        self.groups.iter_mut().find(|g| g.id == id)
    }

    pub fn group(&self, id: BaaGroupId) -> Option<&BaaEditorGroup> {
        self.groups.iter().find(|g| g.id == id)
    }

    pub fn group_mut(&mut self, id: BaaGroupId) -> Option<&mut BaaEditorGroup> {
        self.groups.iter_mut().find(|g| g.id == id)
    }

    pub fn set_active_group(&mut self, id: BaaGroupId) {
        for g in &mut self.groups {
            g.is_active_group = g.id == id;
        }
        self.active_group_id = Some(id);
    }

    pub fn split_group(&mut self, source_id: BaaGroupId, direction: BaaSplitDirection) -> BaaGroupId {
        let new_id = self.alloc_group_id();
        let new_group = BaaEditorGroup::new(new_id);
        self.groups.push(new_group);

        let orientation = if direction.is_horizontal() {
            BaaOrientation::Horizontal
        } else {
            BaaOrientation::Vertical
        };

        fn split_node(node: &mut BaaGridNode, source: BaaGroupId, new_id: BaaGroupId, orientation: BaaOrientation, direction: BaaSplitDirection) -> bool {
            match node {
                BaaGridNode::Leaf(id) if *id == source => {
                    let left = BaaGridNode::leaf(source);
                    let right = BaaGridNode::leaf(new_id);
                    let children = if matches!(direction, BaaSplitDirection::Right | BaaSplitDirection::Down) {
                        vec![left, right]
                    } else {
                        vec![right, left]
                    };
                    *node = BaaGridNode::branch(orientation, children);
                    true
                }
                BaaGridNode::Branch { children, .. } => {
                    for child in children.iter_mut() {
                        if split_node(child, source, new_id, orientation, direction) {
                            return true;
                        }
                    }
                    false
                }
                _ => false,
            }
        }

        split_node(&mut self.root, source_id, new_id, orientation, direction);
        self.set_active_group(new_id);
        new_id
    }

    pub fn group_count(&self) -> usize {
        self.groups.len()
    }

    pub fn total_tab_count(&self) -> usize {
        self.groups.iter().map(|g| g.tab_count()).sum()
    }

    pub fn close_group(&mut self, id: BaaGroupId) -> bool {
        if self.groups.len() <= 1 {
            return false;
        }

        if let Some(idx) = self.groups.iter().position(|g| g.id == id) {
            self.groups.remove(idx);

            fn remove_leaf(node: &mut BaaGridNode, id: BaaGroupId) -> bool {
                if let BaaGridNode::Branch { children, ratios, .. } = node {
                    if let Some(pos) = children.iter().position(|c| matches!(c, BaaGridNode::Leaf(gid) if *gid == id)) {
                        children.remove(pos);
                        ratios.remove(pos);
                        if children.len() == 1 {
                            let remaining = children.remove(0);
                            *node = remaining;
                        } else {
                            let n = ratios.len();
                            let ratio = 1.0 / n as f64;
                            for r in ratios.iter_mut() {
                                *r = ratio;
                            }
                        }
                        return true;
                    }
                    for child in children.iter_mut() {
                        if remove_leaf(child, id) {
                            return true;
                        }
                    }
                }
                false
            }

            remove_leaf(&mut self.root, id);

            if self.active_group_id == Some(id) {
                self.active_group_id = self.groups.first().map(|g| g.id);
                if let Some(aid) = self.active_group_id {
                    self.set_active_group(aid);
                }
            }
            true
        } else {
            false
        }
    }

    pub fn move_editor_between_groups(&mut self, editor_label: &str, from: BaaGroupId, to: BaaGroupId) -> bool {
        let tab_info = {
            let from_group = match self.groups.iter().find(|g| g.id == from) {
                Some(g) => g,
                None => return false,
            };
            from_group.tabs.iter().find(|t| t.label == editor_label).map(|t| {
                (t.label.clone(), t.resource_path.clone(), t.is_dirty, t.is_pinned)
            })
        };

        let (label, resource, dirty, pinned) = match tab_info {
            Some(info) => info,
            None => return false,
        };

        // Remove from source
        if let Some(from_group) = self.groups.iter_mut().find(|g| g.id == from) {
            if let Some(idx) = from_group.tabs.iter().position(|t| t.label == label) {
                from_group.tabs.remove(idx);
                if from_group.tabs.is_empty() {
                    from_group.active_index = None;
                } else {
                    let new_active = idx.min(from_group.tabs.len() - 1);
                    from_group.set_active(new_active);
                }
            }
        }

        // Add to target
        if let Some(to_group) = self.groups.iter_mut().find(|g| g.id == to) {
            let id = to_group.open_editor(&label, resource.as_deref(), false);
            if let Some(tab) = to_group.tabs.iter_mut().find(|t| t.id == id) {
                if dirty { tab.mark_dirty(); }
                if pinned { tab.pin(); }
            }
            true
        } else {
            false
        }
    }
}

#[cfg(test)]
mod baa_tests {
    use super::*;

    #[test]
    fn test_baa_split_direction_properties() {
        assert!(BaaSplitDirection::Left.is_horizontal());
        assert!(BaaSplitDirection::Right.is_horizontal());
        assert!(BaaSplitDirection::Up.is_vertical());
        assert!(BaaSplitDirection::Down.is_vertical());
        assert_eq!(BaaSplitDirection::Left.opposite(), BaaSplitDirection::Right);
        assert_eq!(BaaSplitDirection::Up.opposite(), BaaSplitDirection::Down);
    }

    #[test]
    fn test_baa_editor_tab_creation() {
        let tab = BaaEditorTab::new(BaaEditorId(1), "test.rs");
        assert_eq!(tab.label, "test.rs");
        assert!(!tab.is_dirty);
        assert!(!tab.is_pinned);
        assert!(!tab.is_preview);

        let tab = tab.with_resource("/src/test.rs");
        assert_eq!(tab.resource_path.as_deref(), Some("/src/test.rs"));
    }

    #[test]
    fn test_baa_tab_pin_unpin() {
        let mut tab = BaaEditorTab::new(BaaEditorId(1), "file.rs");
        tab.is_preview = true;
        tab.pin();
        assert!(tab.is_pinned);
        assert!(!tab.is_preview);
        tab.unpin();
        assert!(!tab.is_pinned);
    }

    #[test]
    fn test_baa_tab_dirty_clean() {
        let mut tab = BaaEditorTab::new(BaaEditorId(1), "file.rs");
        tab.mark_dirty();
        assert!(tab.is_dirty);
        tab.mark_clean();
        assert!(!tab.is_dirty);
    }

    #[test]
    fn test_baa_group_open_close() {
        let mut group = BaaEditorGroup::new(BaaGroupId(1));
        assert_eq!(group.tab_count(), 0);

        let id1 = group.open_editor("a.rs", Some("/a.rs"), false);
        assert_eq!(group.tab_count(), 1);
        assert!(group.active_tab().is_some());
        assert_eq!(group.active_tab().unwrap().id, id1);

        let id2 = group.open_editor("b.rs", Some("/b.rs"), false);
        assert_eq!(group.tab_count(), 2);
        assert_eq!(group.active_tab().unwrap().id, id2);

        group.close_editor(id2);
        assert_eq!(group.tab_count(), 1);
    }

    #[test]
    fn test_baa_group_preview_replacement() {
        let mut group = BaaEditorGroup::new(BaaGroupId(1));
        group.open_editor("a.rs", Some("/a.rs"), true);
        assert_eq!(group.tab_count(), 1);
        assert!(group.tabs[0].is_preview);

        group.open_editor("b.rs", Some("/b.rs"), true);
        assert_eq!(group.tab_count(), 1);
        assert_eq!(group.tabs[0].label, "b.rs");
    }

    #[test]
    fn test_baa_group_reopen_existing() {
        let mut group = BaaEditorGroup::new(BaaGroupId(1));
        let id1 = group.open_editor("a.rs", Some("/a.rs"), false);
        group.open_editor("b.rs", Some("/b.rs"), false);
        let id_reopen = group.open_editor("a.rs", Some("/a.rs"), false);
        assert_eq!(id1, id_reopen);
        assert_eq!(group.tab_count(), 2);
    }

    #[test]
    fn test_baa_group_close_all_and_saved() {
        let mut group = BaaEditorGroup::new(BaaGroupId(1));
        group.open_editor("a.rs", Some("/a.rs"), false);
        let id2 = group.open_editor("b.rs", Some("/b.rs"), false);
        if let Some(tab) = group.tabs.iter_mut().find(|t| t.id == id2) {
            tab.mark_dirty();
        }
        group.close_saved();
        assert_eq!(group.tab_count(), 1);

        group.close_all();
        assert_eq!(group.tab_count(), 0);
    }

    #[test]
    fn test_baa_group_move_tab() {
        let mut group = BaaEditorGroup::new(BaaGroupId(1));
        group.open_editor("a.rs", None, false);
        group.open_editor("b.rs", None, false);
        group.open_editor("c.rs", None, false);
        assert_eq!(group.tabs[0].label, "a.rs");
        group.move_tab(2, 0);
        assert_eq!(group.tabs[0].label, "c.rs");
        assert_eq!(group.tabs[1].label, "a.rs");
    }

    #[test]
    fn test_baa_grid_node_operations() {
        let node = BaaGridNode::branch(
            BaaOrientation::Horizontal,
            vec![BaaGridNode::leaf(BaaGroupId(1)), BaaGridNode::leaf(BaaGroupId(2))],
        );
        assert_eq!(node.group_count(), 2);
        assert!(node.contains_group(BaaGroupId(1)));
        assert!(!node.contains_group(BaaGroupId(99)));
        let ids = node.group_ids();
        assert_eq!(ids, vec![BaaGroupId(1), BaaGroupId(2)]);
    }

    #[test]
    fn test_baa_editor_grid_creation() {
        let grid = BaaEditorGrid::new();
        assert_eq!(grid.group_count(), 1);
        assert!(grid.active_group().is_some());
    }

    #[test]
    fn test_baa_grid_split() {
        let mut grid = BaaEditorGrid::new();
        let initial = grid.active_group_id.unwrap();
        let new_id = grid.split_group(initial, BaaSplitDirection::Right);
        assert_eq!(grid.group_count(), 2);
        assert_eq!(grid.active_group_id, Some(new_id));
        assert_eq!(grid.root.group_count(), 2);
    }

    #[test]
    fn test_baa_grid_close_group() {
        let mut grid = BaaEditorGrid::new();
        let initial = grid.active_group_id.unwrap();
        let new_id = grid.split_group(initial, BaaSplitDirection::Right);
        assert!(grid.close_group(new_id));
        assert_eq!(grid.group_count(), 1);
        assert!(!grid.close_group(initial));
    }

    #[test]
    fn test_baa_grid_total_tabs() {
        let mut grid = BaaEditorGrid::new();
        let g1 = grid.active_group_id.unwrap();
        grid.group_mut(g1).unwrap().open_editor("a.rs", None, false);
        grid.group_mut(g1).unwrap().open_editor("b.rs", None, false);
        let g2 = grid.split_group(g1, BaaSplitDirection::Down);
        grid.group_mut(g2).unwrap().open_editor("c.rs", None, false);
        assert_eq!(grid.total_tab_count(), 3);
    }

    #[test]
    fn test_baa_group_dirty_count() {
        let mut group = BaaEditorGroup::new(BaaGroupId(1));
        group.open_editor("a.rs", None, false);
        group.open_editor("b.rs", None, false);
        group.tabs[0].mark_dirty();
        assert_eq!(group.dirty_count(), 1);
        group.tabs[1].mark_dirty();
        assert_eq!(group.dirty_count(), 2);
    }

    #[test]
    fn test_baa_group_pinned_tabs() {
        let mut group = BaaEditorGroup::new(BaaGroupId(1));
        group.open_editor("a.rs", None, false);
        group.open_editor("b.rs", None, false);
        group.tabs[0].pin();
        let pinned = group.pinned_tabs();
        assert_eq!(pinned.len(), 1);
        assert_eq!(pinned[0].label, "a.rs");
    }

    #[test]
    fn test_baa_set_preview_on_pinned() {
        let mut tab = BaaEditorTab::new(BaaEditorId(1), "file.rs");
        tab.pin();
        tab.set_preview(true);
        assert!(!tab.is_preview);
    }

    #[test]
    fn test_baa_activate_promotes_preview() {
        let mut group = BaaEditorGroup::new(BaaGroupId(1));
        group.open_editor("a.rs", None, false);
        group.open_editor("b.rs", None, true);
        assert!(group.tabs[1].is_preview);
        group.set_active(0);
        group.set_active(1);
        assert!(!group.tabs[1].is_preview);
    }

    #[test]
    fn test_baa_grid_set_ratio() {
        let mut node = BaaGridNode::branch(
            BaaOrientation::Horizontal,
            vec![BaaGridNode::leaf(BaaGroupId(1)), BaaGridNode::leaf(BaaGroupId(2))],
        );
        node.set_ratio(0, 0.7);
        if let BaaGridNode::Branch { ratios, .. } = &node {
            assert!((ratios[0] - 0.7).abs() < 0.01);
        }
    }

    #[test]
    fn test_baa_move_editor_between_groups() {
        let mut grid = BaaEditorGrid::new();
        let g1 = grid.active_group_id.unwrap();
        grid.group_mut(g1).unwrap().open_editor("a.rs", Some("/a.rs"), false);
        let g2 = grid.split_group(g1, BaaSplitDirection::Right);
        assert!(grid.move_editor_between_groups("a.rs", g1, g2));
        assert_eq!(grid.group(g1).unwrap().tab_count(), 0);
        assert_eq!(grid.group(g2).unwrap().tab_count(), 1);
    }
}


// --- bab_: Editor diff decorations ---

/// Type of change in a diff hunk.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum BabDiffChangeType {
    Added,
    Deleted,
    Modified,
}

impl BabDiffChangeType {
    pub fn indicator_char(self) -> char {
        match self {
            Self::Added => '+',
            Self::Deleted => '-',
            Self::Modified => '~',
        }
    }

    pub fn gutter_symbol(self) -> &'static str {
        match self {
            Self::Added => "\u{258c}",    // left half block
            Self::Deleted => "\u{25b6}",  // right triangle
            Self::Modified => "\u{258c}", // left half block
        }
    }
}

/// A single line range in the diff.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct BabLineRange {
    pub start: u32,
    pub count: u32,
}

impl BabLineRange {
    pub fn new(start: u32, count: u32) -> Self {
        Self { start, count }
    }

    pub fn end(&self) -> u32 {
        self.start + self.count
    }

    pub fn contains(&self, line: u32) -> bool {
        line >= self.start && line < self.end()
    }

    pub fn is_empty(&self) -> bool {
        self.count == 0
    }
}

/// A diff hunk representing a contiguous change region.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct BabDiffHunk {
    pub original: BabLineRange,
    pub modified: BabLineRange,
    pub change_type: BabDiffChangeType,
}

impl BabDiffHunk {
    pub fn new(original: BabLineRange, modified: BabLineRange) -> Self {
        let change_type = if original.is_empty() {
            BabDiffChangeType::Added
        } else if modified.is_empty() {
            BabDiffChangeType::Deleted
        } else {
            BabDiffChangeType::Modified
        };
        Self { original, modified, change_type }
    }

    pub fn added(modified_start: u32, count: u32, original_line: u32) -> Self {
        Self::new(
            BabLineRange::new(original_line, 0),
            BabLineRange::new(modified_start, count),
        )
    }

    pub fn deleted(original_start: u32, count: u32, modified_line: u32) -> Self {
        Self::new(
            BabLineRange::new(original_start, count),
            BabLineRange::new(modified_line, 0),
        )
    }

    pub fn modified(original_start: u32, original_count: u32, modified_start: u32, modified_count: u32) -> Self {
        Self::new(
            BabLineRange::new(original_start, original_count),
            BabLineRange::new(modified_start, modified_count),
        )
    }

    pub fn total_lines_changed(&self) -> u32 {
        self.original.count.max(self.modified.count)
    }
}

/// Inline character-level change within a modified line.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct BabInlineChange {
    pub line: u32,
    pub start_col: u32,
    pub end_col: u32,
    pub is_insertion: bool,
}

impl BabInlineChange {
    pub fn new(line: u32, start_col: u32, end_col: u32, is_insertion: bool) -> Self {
        Self { line, start_col, end_col, is_insertion }
    }

    pub fn char_count(&self) -> u32 {
        self.end_col.saturating_sub(self.start_col)
    }
}

/// Gutter decoration for a single line in the diff view.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct BabGutterDecoration {
    pub line: u32,
    pub change_type: BabDiffChangeType,
    pub hunk_index: usize,
}

/// Complete diff decoration model for an editor.
#[derive(Debug, Clone)]
pub struct BabDiffDecorations {
    pub hunks: Vec<BabDiffHunk>,
    pub inline_changes: Vec<BabInlineChange>,
    pub is_dirty: bool,
    original_line_count: u32,
    modified_line_count: u32,
}

impl BabDiffDecorations {
    pub fn new() -> Self {
        Self {
            hunks: Vec::new(),
            inline_changes: Vec::new(),
            is_dirty: false,
            original_line_count: 0,
            modified_line_count: 0,
        }
    }

    pub fn with_line_counts(original: u32, modified: u32) -> Self {
        Self {
            hunks: Vec::new(),
            inline_changes: Vec::new(),
            is_dirty: original != modified,
            original_line_count: original,
            modified_line_count: modified,
        }
    }

    pub fn add_hunk(&mut self, hunk: BabDiffHunk) {
        self.hunks.push(hunk);
        self.is_dirty = true;
    }

    pub fn add_inline_change(&mut self, change: BabInlineChange) {
        self.inline_changes.push(change);
    }

    pub fn hunk_count(&self) -> usize {
        self.hunks.len()
    }

    pub fn added_line_count(&self) -> u32 {
        self.hunks.iter()
            .filter(|h| h.change_type == BabDiffChangeType::Added)
            .map(|h| h.modified.count)
            .sum()
    }

    pub fn deleted_line_count(&self) -> u32 {
        self.hunks.iter()
            .filter(|h| h.change_type == BabDiffChangeType::Deleted)
            .map(|h| h.original.count)
            .sum()
    }

    pub fn modified_line_count(&self) -> u32 {
        self.hunks.iter()
            .filter(|h| h.change_type == BabDiffChangeType::Modified)
            .map(|h| h.modified.count)
            .sum()
    }

    pub fn gutter_decorations(&self) -> Vec<BabGutterDecoration> {
        let mut decorations = Vec::new();
        for (i, hunk) in self.hunks.iter().enumerate() {
            match hunk.change_type {
                BabDiffChangeType::Added => {
                    for line in hunk.modified.start..hunk.modified.end() {
                        decorations.push(BabGutterDecoration {
                            line,
                            change_type: BabDiffChangeType::Added,
                            hunk_index: i,
                        });
                    }
                }
                BabDiffChangeType::Deleted => {
                    decorations.push(BabGutterDecoration {
                        line: hunk.modified.start,
                        change_type: BabDiffChangeType::Deleted,
                        hunk_index: i,
                    });
                }
                BabDiffChangeType::Modified => {
                    for line in hunk.modified.start..hunk.modified.end() {
                        decorations.push(BabGutterDecoration {
                            line,
                            change_type: BabDiffChangeType::Modified,
                            hunk_index: i,
                        });
                    }
                }
            }
        }
        decorations
    }

    pub fn change_at_line(&self, line: u32) -> Option<BabDiffChangeType> {
        for hunk in &self.hunks {
            if hunk.change_type == BabDiffChangeType::Deleted && hunk.modified.start == line {
                return Some(BabDiffChangeType::Deleted);
            }
            if hunk.modified.contains(line) {
                return Some(hunk.change_type);
            }
        }
        None
    }

    pub fn next_hunk_from(&self, line: u32) -> Option<&BabDiffHunk> {
        self.hunks.iter().find(|h| h.modified.start > line)
    }

    pub fn prev_hunk_from(&self, line: u32) -> Option<&BabDiffHunk> {
        self.hunks.iter().rev().find(|h| h.modified.start < line)
    }

    pub fn hunk_at_line(&self, line: u32) -> Option<&BabDiffHunk> {
        self.hunks.iter().find(|h| {
            h.modified.contains(line) ||
            (h.change_type == BabDiffChangeType::Deleted && h.modified.start == line)
        })
    }

    pub fn clear(&mut self) {
        self.hunks.clear();
        self.inline_changes.clear();
        self.is_dirty = false;
    }

    pub fn summary(&self) -> BabDiffSummary {
        BabDiffSummary {
            hunks: self.hunk_count(),
            additions: self.added_line_count(),
            deletions: self.deleted_line_count(),
            modifications: self.modified_line_count(),
        }
    }
}

/// Summary statistics for a diff.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct BabDiffSummary {
    pub hunks: usize,
    pub additions: u32,
    pub deletions: u32,
    pub modifications: u32,
}

impl BabDiffSummary {
    pub fn total_changed(&self) -> u32 {
        self.additions + self.deletions + self.modifications
    }

    pub fn is_empty(&self) -> bool {
        self.hunks == 0
    }

    pub fn display_short(&self) -> String {
        format!("+{} -{} ~{}", self.additions, self.deletions, self.modifications)
    }
}

/// Side-by-side diff view model.
#[derive(Debug, Clone)]
pub struct BabSideBySideLine {
    pub left_line_num: Option<u32>,
    pub right_line_num: Option<u32>,
    pub left_content: String,
    pub right_content: String,
    pub change_type: Option<BabDiffChangeType>,
}

impl BabSideBySideLine {
    pub fn unchanged(line_num: u32, content: &str) -> Self {
        Self {
            left_line_num: Some(line_num),
            right_line_num: Some(line_num),
            left_content: content.to_string(),
            right_content: content.to_string(),
            change_type: None,
        }
    }

    pub fn added(right_num: u32, content: &str) -> Self {
        Self {
            left_line_num: None,
            right_line_num: Some(right_num),
            left_content: String::new(),
            right_content: content.to_string(),
            change_type: Some(BabDiffChangeType::Added),
        }
    }

    pub fn deleted(left_num: u32, content: &str) -> Self {
        Self {
            left_line_num: Some(left_num),
            right_line_num: None,
            left_content: content.to_string(),
            right_content: String::new(),
            change_type: Some(BabDiffChangeType::Deleted),
        }
    }

    pub fn modified(left_num: u32, right_num: u32, left: &str, right: &str) -> Self {
        Self {
            left_line_num: Some(left_num),
            right_line_num: Some(right_num),
            left_content: left.to_string(),
            right_content: right.to_string(),
            change_type: Some(BabDiffChangeType::Modified),
        }
    }

    pub fn is_changed(&self) -> bool {
        self.change_type.is_some()
    }
}

/// Manages a unified or side-by-side diff view.
#[derive(Debug, Clone)]
pub struct BabDiffView {
    pub lines: Vec<BabSideBySideLine>,
    pub visible_start: usize,
    pub visible_count: usize,
    pub current_hunk_index: Option<usize>,
}

impl BabDiffView {
    pub fn new() -> Self {
        Self {
            lines: Vec::new(),
            visible_start: 0,
            visible_count: 40,
            current_hunk_index: None,
        }
    }

    pub fn set_lines(&mut self, lines: Vec<BabSideBySideLine>) {
        self.lines = lines;
        self.visible_start = 0;
    }

    pub fn visible_lines(&self) -> &[BabSideBySideLine] {
        let end = (self.visible_start + self.visible_count).min(self.lines.len());
        &self.lines[self.visible_start..end]
    }

    pub fn scroll_down(&mut self, amount: usize) {
        let max = self.lines.len().saturating_sub(self.visible_count);
        self.visible_start = (self.visible_start + amount).min(max);
    }

    pub fn scroll_up(&mut self, amount: usize) {
        self.visible_start = self.visible_start.saturating_sub(amount);
    }

    pub fn total_lines(&self) -> usize {
        self.lines.len()
    }

    pub fn changed_line_count(&self) -> usize {
        self.lines.iter().filter(|l| l.is_changed()).count()
    }

    pub fn next_change_from(&self, line_idx: usize) -> Option<usize> {
        self.lines.iter().enumerate().skip(line_idx + 1).find(|(_, l)| l.is_changed()).map(|(i, _)| i)
    }

    pub fn prev_change_from(&self, line_idx: usize) -> Option<usize> {
        self.lines.iter().enumerate().take(line_idx).rev().find(|(_, l)| l.is_changed()).map(|(i, _)| i)
    }
}

#[cfg(test)]
mod bab_tests {
    use super::*;

    #[test]
    fn test_bab_change_type_indicator() {
        assert_eq!(BabDiffChangeType::Added.indicator_char(), '+');
        assert_eq!(BabDiffChangeType::Deleted.indicator_char(), '-');
        assert_eq!(BabDiffChangeType::Modified.indicator_char(), '~');
    }

    #[test]
    fn test_bab_line_range() {
        let r = BabLineRange::new(5, 3);
        assert_eq!(r.end(), 8);
        assert!(r.contains(5));
        assert!(r.contains(7));
        assert!(!r.contains(8));
        assert!(!r.is_empty());

        let empty = BabLineRange::new(5, 0);
        assert!(empty.is_empty());
    }

    #[test]
    fn test_bab_diff_hunk_creation() {
        let added = BabDiffHunk::added(10, 3, 9);
        assert_eq!(added.change_type, BabDiffChangeType::Added);
        assert_eq!(added.modified.count, 3);

        let deleted = BabDiffHunk::deleted(5, 2, 4);
        assert_eq!(deleted.change_type, BabDiffChangeType::Deleted);

        let modified = BabDiffHunk::modified(5, 2, 5, 3);
        assert_eq!(modified.change_type, BabDiffChangeType::Modified);
        assert_eq!(modified.total_lines_changed(), 3);
    }

    #[test]
    fn test_bab_inline_change() {
        let ic = BabInlineChange::new(10, 5, 15, true);
        assert_eq!(ic.char_count(), 10);
        assert!(ic.is_insertion);
    }

    #[test]
    fn test_bab_decorations_counts() {
        let mut dec = BabDiffDecorations::new();
        dec.add_hunk(BabDiffHunk::added(10, 5, 9));
        dec.add_hunk(BabDiffHunk::deleted(20, 3, 14));
        dec.add_hunk(BabDiffHunk::modified(25, 2, 17, 4));

        assert_eq!(dec.hunk_count(), 3);
        assert_eq!(dec.added_line_count(), 5);
        assert_eq!(dec.deleted_line_count(), 3);
        assert_eq!(dec.modified_line_count(), 4);
    }

    #[test]
    fn test_bab_gutter_decorations() {
        let mut dec = BabDiffDecorations::new();
        dec.add_hunk(BabDiffHunk::added(10, 2, 9));
        let gutters = dec.gutter_decorations();
        assert_eq!(gutters.len(), 2);
        assert_eq!(gutters[0].line, 10);
        assert_eq!(gutters[1].line, 11);
    }

    #[test]
    fn test_bab_change_at_line() {
        let mut dec = BabDiffDecorations::new();
        dec.add_hunk(BabDiffHunk::added(5, 3, 4));
        assert_eq!(dec.change_at_line(5), Some(BabDiffChangeType::Added));
        assert_eq!(dec.change_at_line(7), Some(BabDiffChangeType::Added));
        assert_eq!(dec.change_at_line(8), None);
    }

    #[test]
    fn test_bab_hunk_navigation() {
        let mut dec = BabDiffDecorations::new();
        dec.add_hunk(BabDiffHunk::added(5, 2, 4));
        dec.add_hunk(BabDiffHunk::modified(20, 1, 18, 2));

        let next = dec.next_hunk_from(6);
        assert!(next.is_some());
        assert_eq!(next.unwrap().modified.start, 20);

        let prev = dec.prev_hunk_from(25);
        assert!(prev.is_some());
        assert_eq!(prev.unwrap().modified.start, 20);
    }

    #[test]
    fn test_bab_summary() {
        let mut dec = BabDiffDecorations::new();
        dec.add_hunk(BabDiffHunk::added(5, 10, 4));
        dec.add_hunk(BabDiffHunk::deleted(20, 3, 14));
        let summary = dec.summary();
        assert_eq!(summary.total_changed(), 13);
        assert_eq!(summary.display_short(), "+10 -3 ~0");
        assert!(!summary.is_empty());
    }

    #[test]
    fn test_bab_side_by_side_line() {
        let unchanged = BabSideBySideLine::unchanged(1, "hello");
        assert!(!unchanged.is_changed());
        assert_eq!(unchanged.left_line_num, Some(1));

        let added = BabSideBySideLine::added(5, "new line");
        assert!(added.is_changed());
        assert!(added.left_line_num.is_none());

        let deleted = BabSideBySideLine::deleted(3, "old line");
        assert!(deleted.is_changed());
        assert!(deleted.right_line_num.is_none());

        let modified = BabSideBySideLine::modified(2, 2, "old", "new");
        assert!(modified.is_changed());
    }

    #[test]
    fn test_bab_diff_view_scrolling() {
        let mut view = BabDiffView::new();
        let lines: Vec<BabSideBySideLine> = (0..100)
            .map(|i| BabSideBySideLine::unchanged(i, &format!("line {}", i)))
            .collect();
        view.set_lines(lines);
        assert_eq!(view.total_lines(), 100);
        assert_eq!(view.visible_lines().len(), 40);

        view.scroll_down(10);
        assert_eq!(view.visible_start, 10);

        view.scroll_up(5);
        assert_eq!(view.visible_start, 5);
    }

    #[test]
    fn test_bab_diff_view_navigation() {
        let mut view = BabDiffView::new();
        let mut lines = Vec::new();
        for i in 0..10 {
            lines.push(BabSideBySideLine::unchanged(i, "same"));
        }
        lines.push(BabSideBySideLine::added(10, "new"));
        for i in 11..20 {
            lines.push(BabSideBySideLine::unchanged(i, "same"));
        }
        view.set_lines(lines);
        assert_eq!(view.changed_line_count(), 1);
        assert_eq!(view.next_change_from(0), Some(10));
        assert_eq!(view.prev_change_from(15), Some(10));
    }

    #[test]
    fn test_bab_clear_decorations() {
        let mut dec = BabDiffDecorations::new();
        dec.add_hunk(BabDiffHunk::added(5, 2, 4));
        assert_eq!(dec.hunk_count(), 1);
        dec.clear();
        assert_eq!(dec.hunk_count(), 0);
        assert!(!dec.is_dirty);
    }

    #[test]
    fn test_bab_with_line_counts() {
        let dec = BabDiffDecorations::with_line_counts(100, 105);
        assert!(dec.is_dirty);
        let dec2 = BabDiffDecorations::with_line_counts(100, 100);
        assert!(!dec2.is_dirty);
    }

    #[test]
    fn test_bab_hunk_at_line() {
        let mut dec = BabDiffDecorations::new();
        dec.add_hunk(BabDiffHunk::added(5, 3, 4));
        assert!(dec.hunk_at_line(6).is_some());
        assert!(dec.hunk_at_line(9).is_none());
    }

    #[test]
    fn test_bab_deleted_gutter_single_line() {
        let mut dec = BabDiffDecorations::new();
        dec.add_hunk(BabDiffHunk::deleted(5, 3, 4));
        let gutters = dec.gutter_decorations();
        assert_eq!(gutters.len(), 1); // Single marker for deletion
        assert_eq!(gutters[0].change_type, BabDiffChangeType::Deleted);
    }
}


// --- bac_: Output channel model ---

/// Output channel severity level.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub enum BacOutputLevel {
    Trace,
    Debug,
    Info,
    Warning,
    Error,
}

impl BacOutputLevel {
    pub fn as_str(&self) -> &'static str {
        match self {
            Self::Trace => "trace",
            Self::Debug => "debug",
            Self::Info => "info",
            Self::Warning => "warning",
            Self::Error => "error",
        }
    }

    pub fn prefix(&self) -> &'static str {
        match self {
            Self::Trace => "[TRACE]",
            Self::Debug => "[DEBUG]",
            Self::Info => "[INFO]",
            Self::Warning => "[WARN]",
            Self::Error => "[ERROR]",
        }
    }

    pub fn from_str_level(s: &str) -> Option<Self> {
        match s.to_lowercase().as_str() {
            "trace" => Some(Self::Trace),
            "debug" => Some(Self::Debug),
            "info" => Some(Self::Info),
            "warning" | "warn" => Some(Self::Warning),
            "error" | "err" => Some(Self::Error),
            _ => None,
        }
    }
}

/// A single output line with timestamp and level.
#[derive(Debug, Clone)]
pub struct BacOutputLine {
    pub timestamp_ms: u64,
    pub level: BacOutputLevel,
    pub text: String,
    pub source: Option<String>,
}

impl BacOutputLine {
    pub fn new(level: BacOutputLevel, text: &str, timestamp_ms: u64) -> Self {
        Self {
            timestamp_ms,
            level,
            text: text.to_string(),
            source: None,
        }
    }

    pub fn with_source(mut self, source: &str) -> Self {
        self.source = Some(source.to_string());
        self
    }

    pub fn formatted(&self) -> String {
        format!("{} {}", self.level.prefix(), self.text)
    }

    pub fn formatted_with_time(&self) -> String {
        let secs = self.timestamp_ms / 1000;
        let ms = self.timestamp_ms % 1000;
        format!("[{}.{:03}] {} {}", secs, ms, self.level.prefix(), self.text)
    }
}

/// An output channel that accumulates log lines.
#[derive(Debug, Clone)]
pub struct BacOutputChannel {
    pub name: String,
    pub language_id: Option<String>,
    lines: Vec<BacOutputLine>,
    max_lines: usize,
    is_visible: bool,
    is_log_channel: bool,
    filter_level: Option<BacOutputLevel>,
}

impl BacOutputChannel {
    pub fn new(name: &str) -> Self {
        Self {
            name: name.to_string(),
            language_id: None,
            lines: Vec::new(),
            max_lines: 10_000,
            is_visible: false,
            is_log_channel: false,
            filter_level: None,
        }
    }

    pub fn log_channel(name: &str) -> Self {
        let mut ch = Self::new(name);
        ch.is_log_channel = true;
        ch.language_id = Some("log".to_string());
        ch
    }

    pub fn append(&mut self, text: &str, level: BacOutputLevel, timestamp_ms: u64) {
        let line = BacOutputLine::new(level, text, timestamp_ms);
        self.lines.push(line);
        self.trim_lines();
    }

    pub fn append_line(&mut self, text: &str, level: BacOutputLevel, timestamp_ms: u64) {
        self.append(text, level, timestamp_ms);
    }

    fn trim_lines(&mut self) {
        if self.lines.len() > self.max_lines {
            let excess = self.lines.len() - self.max_lines;
            self.lines.drain(0..excess);
        }
    }

    pub fn clear(&mut self) {
        self.lines.clear();
    }

    pub fn line_count(&self) -> usize {
        self.lines.len()
    }

    pub fn lines(&self) -> &[BacOutputLine] {
        &self.lines
    }

    pub fn filtered_lines(&self) -> Vec<&BacOutputLine> {
        match self.filter_level {
            Some(level) => self.lines.iter().filter(|l| l.level >= level).collect(),
            None => self.lines.iter().collect(),
        }
    }

    pub fn set_filter_level(&mut self, level: Option<BacOutputLevel>) {
        self.filter_level = level;
    }

    pub fn show(&mut self) {
        self.is_visible = true;
    }

    pub fn hide(&mut self) {
        self.is_visible = false;
    }

    pub fn is_visible(&self) -> bool {
        self.is_visible
    }

    pub fn is_log_channel(&self) -> bool {
        self.is_log_channel
    }

    pub fn search(&self, query: &str) -> Vec<usize> {
        let query_lower = query.to_lowercase();
        self.lines.iter().enumerate()
            .filter(|(_, l)| l.text.to_lowercase().contains(&query_lower))
            .map(|(i, _)| i)
            .collect()
    }

    pub fn error_count(&self) -> usize {
        self.lines.iter().filter(|l| l.level == BacOutputLevel::Error).count()
    }

    pub fn warning_count(&self) -> usize {
        self.lines.iter().filter(|l| l.level == BacOutputLevel::Warning).count()
    }

    pub fn last_line(&self) -> Option<&BacOutputLine> {
        self.lines.last()
    }

    pub fn tail(&self, n: usize) -> &[BacOutputLine] {
        let start = self.lines.len().saturating_sub(n);
        &self.lines[start..]
    }
}

/// Manager for all output channels in the workbench.
#[derive(Debug, Clone)]
pub struct BacOutputChannelManager {
    pub channels: Vec<BacOutputChannel>,
    pub active_channel: Option<usize>,
}

impl BacOutputChannelManager {
    pub fn new() -> Self {
        Self {
            channels: Vec::new(),
            active_channel: None,
        }
    }

    pub fn create_channel(&mut self, name: &str) -> usize {
        if let Some(idx) = self.channel_index(name) {
            return idx;
        }
        self.channels.push(BacOutputChannel::new(name));
        self.channels.len() - 1
    }

    pub fn create_log_channel(&mut self, name: &str) -> usize {
        if let Some(idx) = self.channel_index(name) {
            return idx;
        }
        self.channels.push(BacOutputChannel::log_channel(name));
        self.channels.len() - 1
    }

    pub fn channel_index(&self, name: &str) -> Option<usize> {
        self.channels.iter().position(|c| c.name == name)
    }

    pub fn channel(&self, name: &str) -> Option<&BacOutputChannel> {
        self.channels.iter().find(|c| c.name == name)
    }

    pub fn channel_mut(&mut self, name: &str) -> Option<&mut BacOutputChannel> {
        self.channels.iter_mut().find(|c| c.name == name)
    }

    pub fn set_active(&mut self, name: &str) -> bool {
        if let Some(idx) = self.channel_index(name) {
            self.active_channel = Some(idx);
            true
        } else {
            false
        }
    }

    pub fn active_channel(&self) -> Option<&BacOutputChannel> {
        self.active_channel.and_then(|idx| self.channels.get(idx))
    }

    pub fn channel_names(&self) -> Vec<&str> {
        self.channels.iter().map(|c| c.name.as_str()).collect()
    }

    pub fn channel_count(&self) -> usize {
        self.channels.len()
    }

    pub fn remove_channel(&mut self, name: &str) -> bool {
        if let Some(idx) = self.channel_index(name) {
            self.channels.remove(idx);
            if self.active_channel == Some(idx) {
                self.active_channel = if self.channels.is_empty() { None } else { Some(0) };
            } else if let Some(ai) = self.active_channel {
                if ai > idx {
                    self.active_channel = Some(ai - 1);
                }
            }
            true
        } else {
            false
        }
    }

    pub fn total_error_count(&self) -> usize {
        self.channels.iter().map(|c| c.error_count()).sum()
    }
}

#[cfg(test)]
mod bac_tests {
    use super::*;

    #[test]
    fn test_bac_output_level_ordering() {
        assert!(BacOutputLevel::Trace < BacOutputLevel::Debug);
        assert!(BacOutputLevel::Debug < BacOutputLevel::Info);
        assert!(BacOutputLevel::Info < BacOutputLevel::Warning);
        assert!(BacOutputLevel::Warning < BacOutputLevel::Error);
    }

    #[test]
    fn test_bac_level_from_str() {
        assert_eq!(BacOutputLevel::from_str_level("info"), Some(BacOutputLevel::Info));
        assert_eq!(BacOutputLevel::from_str_level("WARN"), Some(BacOutputLevel::Warning));
        assert_eq!(BacOutputLevel::from_str_level("err"), Some(BacOutputLevel::Error));
        assert_eq!(BacOutputLevel::from_str_level("unknown"), None);
    }

    #[test]
    fn test_bac_output_line_formatting() {
        let line = BacOutputLine::new(BacOutputLevel::Info, "hello world", 1500);
        assert_eq!(line.formatted(), "[INFO] hello world");
        assert_eq!(line.formatted_with_time(), "[1.500] [INFO] hello world");
    }

    #[test]
    fn test_bac_output_line_with_source() {
        let line = BacOutputLine::new(BacOutputLevel::Error, "fail", 0)
            .with_source("extension.js");
        assert_eq!(line.source.as_deref(), Some("extension.js"));
    }

    #[test]
    fn test_bac_channel_append_and_count() {
        let mut ch = BacOutputChannel::new("Test");
        ch.append("line 1", BacOutputLevel::Info, 100);
        ch.append("line 2", BacOutputLevel::Warning, 200);
        ch.append("line 3", BacOutputLevel::Error, 300);
        assert_eq!(ch.line_count(), 3);
        assert_eq!(ch.error_count(), 1);
        assert_eq!(ch.warning_count(), 1);
    }

    #[test]
    fn test_bac_channel_trim() {
        let mut ch = BacOutputChannel::new("Test");
        ch.max_lines = 5;
        for i in 0..10 {
            ch.append(&format!("line {}", i), BacOutputLevel::Info, i as u64 * 100);
        }
        assert_eq!(ch.line_count(), 5);
        assert_eq!(ch.lines[0].text, "line 5");
    }

    #[test]
    fn test_bac_channel_filter() {
        let mut ch = BacOutputChannel::new("Test");
        ch.append("trace", BacOutputLevel::Trace, 100);
        ch.append("info", BacOutputLevel::Info, 200);
        ch.append("error", BacOutputLevel::Error, 300);

        ch.set_filter_level(Some(BacOutputLevel::Info));
        let filtered = ch.filtered_lines();
        assert_eq!(filtered.len(), 2);
    }

    #[test]
    fn test_bac_channel_search() {
        let mut ch = BacOutputChannel::new("Test");
        ch.append("hello world", BacOutputLevel::Info, 100);
        ch.append("goodbye world", BacOutputLevel::Info, 200);
        ch.append("hello again", BacOutputLevel::Info, 300);

        let results = ch.search("hello");
        assert_eq!(results, vec![0, 2]);
    }

    #[test]
    fn test_bac_channel_visibility() {
        let mut ch = BacOutputChannel::new("Test");
        assert!(!ch.is_visible());
        ch.show();
        assert!(ch.is_visible());
        ch.hide();
        assert!(!ch.is_visible());
    }

    #[test]
    fn test_bac_channel_tail() {
        let mut ch = BacOutputChannel::new("Test");
        for i in 0..10 {
            ch.append(&format!("line {}", i), BacOutputLevel::Info, i as u64 * 100);
        }
        let tail = ch.tail(3);
        assert_eq!(tail.len(), 3);
        assert_eq!(tail[0].text, "line 7");
    }

    #[test]
    fn test_bac_log_channel() {
        let ch = BacOutputChannel::log_channel("Git");
        assert!(ch.is_log_channel());
        assert_eq!(ch.language_id.as_deref(), Some("log"));
    }

    #[test]
    fn test_bac_manager_create_and_find() {
        let mut mgr = BacOutputChannelManager::new();
        let idx1 = mgr.create_channel("Output");
        let idx2 = mgr.create_channel("Git");
        assert_eq!(idx1, 0);
        assert_eq!(idx2, 1);
        assert_eq!(mgr.channel_count(), 2);

        // Duplicate returns existing
        let idx3 = mgr.create_channel("Output");
        assert_eq!(idx3, 0);
        assert_eq!(mgr.channel_count(), 2);
    }

    #[test]
    fn test_bac_manager_active() {
        let mut mgr = BacOutputChannelManager::new();
        mgr.create_channel("A");
        mgr.create_channel("B");
        assert!(mgr.set_active("B"));
        assert_eq!(mgr.active_channel().unwrap().name, "B");
        assert!(!mgr.set_active("C"));
    }

    #[test]
    fn test_bac_manager_remove() {
        let mut mgr = BacOutputChannelManager::new();
        mgr.create_channel("A");
        mgr.create_channel("B");
        mgr.set_active("A");
        assert!(mgr.remove_channel("A"));
        assert_eq!(mgr.channel_count(), 1);
        assert_eq!(mgr.active_channel().unwrap().name, "B");
    }

    #[test]
    fn test_bac_manager_names() {
        let mut mgr = BacOutputChannelManager::new();
        mgr.create_channel("Alpha");
        mgr.create_channel("Beta");
        let names = mgr.channel_names();
        assert_eq!(names, vec!["Alpha", "Beta"]);
    }

    #[test]
    fn test_bac_manager_total_errors() {
        let mut mgr = BacOutputChannelManager::new();
        mgr.create_channel("A");
        mgr.create_channel("B");
        mgr.channel_mut("A").unwrap().append("err1", BacOutputLevel::Error, 100);
        mgr.channel_mut("B").unwrap().append("err2", BacOutputLevel::Error, 200);
        mgr.channel_mut("B").unwrap().append("info", BacOutputLevel::Info, 300);
        assert_eq!(mgr.total_error_count(), 2);
    }

    #[test]
    fn test_bac_channel_clear() {
        let mut ch = BacOutputChannel::new("Test");
        ch.append("line", BacOutputLevel::Info, 100);
        assert_eq!(ch.line_count(), 1);
        ch.clear();
        assert_eq!(ch.line_count(), 0);
    }

    #[test]
    fn test_bac_channel_last_line() {
        let mut ch = BacOutputChannel::new("Test");
        assert!(ch.last_line().is_none());
        ch.append("first", BacOutputLevel::Info, 100);
        ch.append("second", BacOutputLevel::Info, 200);
        assert_eq!(ch.last_line().unwrap().text, "second");
    }
}


// --- bad_: Debug console model ---

/// Debug console output kind.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum BadConsoleOutputKind {
    Stdout,
    Stderr,
    Console,
    Important,
    Warning,
    Error,
    StartGroup,
    StartGroupCollapsed,
    EndGroup,
}

impl BadConsoleOutputKind {
    pub fn is_error_like(&self) -> bool {
        matches!(self, Self::Stderr | Self::Error | Self::Warning)
    }

    pub fn prefix(&self) -> &'static str {
        match self {
            Self::Stdout => "",
            Self::Stderr => "[stderr]",
            Self::Console => "",
            Self::Important => "[!]",
            Self::Warning => "[warn]",
            Self::Error => "[error]",
            Self::StartGroup => "> ",
            Self::StartGroupCollapsed => "> ",
            Self::EndGroup => "",
        }
    }
}

/// A single entry in the debug console.
#[derive(Debug, Clone)]
pub struct BadConsoleEntry {
    pub kind: BadConsoleOutputKind,
    pub text: String,
    pub source: Option<String>,
    pub line: Option<u32>,
    pub column: Option<u32>,
    pub timestamp_ms: u64,
    pub group_depth: u32,
}

impl BadConsoleEntry {
    pub fn new(kind: BadConsoleOutputKind, text: &str, timestamp_ms: u64) -> Self {
        Self {
            kind,
            text: text.to_string(),
            source: None,
            line: None,
            column: None,
            timestamp_ms,
            group_depth: 0,
        }
    }

    pub fn with_location(mut self, source: &str, line: u32, column: u32) -> Self {
        self.source = Some(source.to_string());
        self.line = Some(line);
        self.column = Some(column);
        self
    }

    pub fn has_location(&self) -> bool {
        self.source.is_some() && self.line.is_some()
    }

    pub fn formatted(&self) -> String {
        let prefix = self.kind.prefix();
        if prefix.is_empty() {
            self.text.clone()
        } else {
            format!("{} {}", prefix, self.text)
        }
    }

    pub fn location_string(&self) -> Option<String> {
        match (&self.source, self.line, self.column) {
            (Some(src), Some(l), Some(c)) => Some(format!("{}:{}:{}", src, l, c)),
            (Some(src), Some(l), None) => Some(format!("{}:{}", src, l)),
            (Some(src), None, _) => Some(src.clone()),
            _ => None,
        }
    }
}

/// An expression evaluation result in the debug console.
#[derive(Debug, Clone)]
pub struct BadEvalResult {
    pub expression: String,
    pub result: String,
    pub type_name: Option<String>,
    pub is_error: bool,
    pub variables_reference: u64,
    pub timestamp_ms: u64,
}

impl BadEvalResult {
    pub fn success(expression: &str, result: &str, timestamp_ms: u64) -> Self {
        Self {
            expression: expression.to_string(),
            result: result.to_string(),
            type_name: None,
            is_error: false,
            variables_reference: 0,
            timestamp_ms,
        }
    }

    pub fn error(expression: &str, message: &str, timestamp_ms: u64) -> Self {
        Self {
            expression: expression.to_string(),
            result: message.to_string(),
            type_name: None,
            is_error: true,
            variables_reference: 0,
            timestamp_ms,
        }
    }

    pub fn with_type(mut self, type_name: &str) -> Self {
        self.type_name = Some(type_name.to_string());
        self
    }

    pub fn has_children(&self) -> bool {
        self.variables_reference > 0
    }
}

/// Debug console item — either output or an eval result.
#[derive(Debug, Clone)]
pub enum BadConsoleItem {
    Output(BadConsoleEntry),
    Eval(BadEvalResult),
}

impl BadConsoleItem {
    pub fn timestamp_ms(&self) -> u64 {
        match self {
            Self::Output(e) => e.timestamp_ms,
            Self::Eval(r) => r.timestamp_ms,
        }
    }

    pub fn display_text(&self) -> String {
        match self {
            Self::Output(e) => e.formatted(),
            Self::Eval(r) => {
                if r.is_error {
                    format!("! {} => {}", r.expression, r.result)
                } else {
                    format!("> {} => {}", r.expression, r.result)
                }
            }
        }
    }

    pub fn is_error(&self) -> bool {
        match self {
            Self::Output(e) => e.kind.is_error_like(),
            Self::Eval(r) => r.is_error,
        }
    }
}

/// The debug console model.
#[derive(Debug, Clone)]
pub struct BadDebugConsole {
    items: Vec<BadConsoleItem>,
    max_items: usize,
    group_depth: u32,
    input_history: Vec<String>,
    history_index: Option<usize>,
    current_input: String,
    filter_text: Option<String>,
    word_wrap: bool,
}

impl BadDebugConsole {
    pub fn new() -> Self {
        Self {
            items: Vec::new(),
            max_items: 10_000,
            group_depth: 0,
            input_history: Vec::new(),
            history_index: None,
            current_input: String::new(),
            filter_text: None,
            word_wrap: true,
        }
    }

    pub fn append_output(&mut self, kind: BadConsoleOutputKind, text: &str, timestamp_ms: u64) {
        match kind {
            BadConsoleOutputKind::StartGroup | BadConsoleOutputKind::StartGroupCollapsed => {
                let mut entry = BadConsoleEntry::new(kind, text, timestamp_ms);
                entry.group_depth = self.group_depth;
                self.items.push(BadConsoleItem::Output(entry));
                self.group_depth += 1;
            }
            BadConsoleOutputKind::EndGroup => {
                if self.group_depth > 0 {
                    self.group_depth -= 1;
                }
                let mut entry = BadConsoleEntry::new(kind, text, timestamp_ms);
                entry.group_depth = self.group_depth;
                self.items.push(BadConsoleItem::Output(entry));
            }
            _ => {
                let mut entry = BadConsoleEntry::new(kind, text, timestamp_ms);
                entry.group_depth = self.group_depth;
                self.items.push(BadConsoleItem::Output(entry));
            }
        }
        self.trim_items();
    }

    pub fn append_eval(&mut self, result: BadEvalResult) {
        if self.input_history.last().map(|s| s.as_str()) != Some(&result.expression) {
            self.input_history.push(result.expression.clone());
        }
        self.items.push(BadConsoleItem::Eval(result));
        self.trim_items();
    }

    fn trim_items(&mut self) {
        if self.items.len() > self.max_items {
            let excess = self.items.len() - self.max_items;
            self.items.drain(0..excess);
        }
    }

    pub fn item_count(&self) -> usize {
        self.items.len()
    }

    pub fn items(&self) -> &[BadConsoleItem] {
        &self.items
    }

    pub fn filtered_items(&self) -> Vec<&BadConsoleItem> {
        match &self.filter_text {
            Some(filter) => {
                let f = filter.to_lowercase();
                self.items.iter()
                    .filter(|item| item.display_text().to_lowercase().contains(&f))
                    .collect()
            }
            None => self.items.iter().collect(),
        }
    }

    pub fn set_filter(&mut self, filter: Option<String>) {
        self.filter_text = filter;
    }

    pub fn clear(&mut self) {
        self.items.clear();
        self.group_depth = 0;
    }

    pub fn error_count(&self) -> usize {
        self.items.iter().filter(|i| i.is_error()).count()
    }

    pub fn set_input(&mut self, text: &str) {
        self.current_input = text.to_string();
    }

    pub fn current_input(&self) -> &str {
        &self.current_input
    }

    pub fn history_prev(&mut self) -> Option<&str> {
        if self.input_history.is_empty() {
            return None;
        }
        let idx = match self.history_index {
            Some(i) => i.saturating_sub(1),
            None => self.input_history.len() - 1,
        };
        self.history_index = Some(idx);
        Some(&self.input_history[idx])
    }

    pub fn history_next(&mut self) -> Option<&str> {
        match self.history_index {
            Some(i) if i + 1 < self.input_history.len() => {
                self.history_index = Some(i + 1);
                Some(&self.input_history[i + 1])
            }
            _ => {
                self.history_index = None;
                None
            }
        }
    }

    pub fn history_count(&self) -> usize {
        self.input_history.len()
    }

    pub fn set_word_wrap(&mut self, wrap: bool) {
        self.word_wrap = wrap;
    }

    pub fn word_wrap(&self) -> bool {
        self.word_wrap
    }

    pub fn tail(&self, n: usize) -> &[BadConsoleItem] {
        let start = self.items.len().saturating_sub(n);
        &self.items[start..]
    }
}

#[cfg(test)]
mod bad_tests {
    use super::*;

    #[test]
    fn test_bad_output_kind_error_like() {
        assert!(BadConsoleOutputKind::Stderr.is_error_like());
        assert!(BadConsoleOutputKind::Error.is_error_like());
        assert!(BadConsoleOutputKind::Warning.is_error_like());
        assert!(!BadConsoleOutputKind::Stdout.is_error_like());
        assert!(!BadConsoleOutputKind::Console.is_error_like());
    }

    #[test]
    fn test_bad_console_entry_creation() {
        let entry = BadConsoleEntry::new(BadConsoleOutputKind::Stdout, "hello", 1000);
        assert_eq!(entry.formatted(), "hello");
        assert!(!entry.has_location());
    }

    #[test]
    fn test_bad_entry_with_location() {
        let entry = BadConsoleEntry::new(BadConsoleOutputKind::Error, "fail", 500)
            .with_location("main.js", 42, 10);
        assert!(entry.has_location());
        assert_eq!(entry.location_string(), Some("main.js:42:10".to_string()));
    }

    #[test]
    fn test_bad_entry_location_variants() {
        let e1 = BadConsoleEntry::new(BadConsoleOutputKind::Stdout, "x", 0);
        assert_eq!(e1.location_string(), None);

        let mut e2 = BadConsoleEntry::new(BadConsoleOutputKind::Stdout, "x", 0);
        e2.source = Some("file.js".to_string());
        e2.line = Some(10);
        assert_eq!(e2.location_string(), Some("file.js:10".to_string()));
    }

    #[test]
    fn test_bad_eval_result_success() {
        let eval = BadEvalResult::success("2+2", "4", 100).with_type("number");
        assert!(!eval.is_error);
        assert_eq!(eval.type_name.as_deref(), Some("number"));
        assert!(!eval.has_children());
    }

    #[test]
    fn test_bad_eval_result_error() {
        let eval = BadEvalResult::error("foo()", "ReferenceError", 200);
        assert!(eval.is_error);
    }

    #[test]
    fn test_bad_console_item_display() {
        let output = BadConsoleItem::Output(
            BadConsoleEntry::new(BadConsoleOutputKind::Error, "oops", 100)
        );
        assert!(output.display_text().contains("oops"));
        assert!(output.is_error());

        let eval = BadConsoleItem::Eval(BadEvalResult::success("1+1", "2", 200));
        assert_eq!(eval.display_text(), "> 1+1 => 2");
        assert!(!eval.is_error());
    }

    #[test]
    fn test_bad_debug_console_append() {
        let mut console = BadDebugConsole::new();
        console.append_output(BadConsoleOutputKind::Stdout, "hello", 100);
        console.append_output(BadConsoleOutputKind::Error, "fail", 200);
        assert_eq!(console.item_count(), 2);
        assert_eq!(console.error_count(), 1);
    }

    #[test]
    fn test_bad_console_grouping() {
        let mut console = BadDebugConsole::new();
        console.append_output(BadConsoleOutputKind::StartGroup, "group1", 100);
        console.append_output(BadConsoleOutputKind::Stdout, "inside", 200);
        console.append_output(BadConsoleOutputKind::EndGroup, "", 300);
        console.append_output(BadConsoleOutputKind::Stdout, "outside", 400);

        if let BadConsoleItem::Output(e) = &console.items()[1] {
            assert_eq!(e.group_depth, 1);
        }
        if let BadConsoleItem::Output(e) = &console.items()[3] {
            assert_eq!(e.group_depth, 0);
        }
    }

    #[test]
    fn test_bad_console_eval() {
        let mut console = BadDebugConsole::new();
        console.append_eval(BadEvalResult::success("x", "42", 100));
        assert_eq!(console.item_count(), 1);
        assert_eq!(console.history_count(), 1);
    }

    #[test]
    fn test_bad_console_filter() {
        let mut console = BadDebugConsole::new();
        console.append_output(BadConsoleOutputKind::Stdout, "hello world", 100);
        console.append_output(BadConsoleOutputKind::Stdout, "goodbye", 200);

        console.set_filter(Some("hello".to_string()));
        assert_eq!(console.filtered_items().len(), 1);
    }

    #[test]
    fn test_bad_console_history() {
        let mut console = BadDebugConsole::new();
        console.append_eval(BadEvalResult::success("a", "1", 100));
        console.append_eval(BadEvalResult::success("b", "2", 200));

        let prev = console.history_prev().map(|s| s.to_string());
        assert_eq!(prev.as_deref(), Some("b"));
        let prev = console.history_prev().map(|s| s.to_string());
        assert_eq!(prev.as_deref(), Some("a"));
        let next = console.history_next().map(|s| s.to_string());
        assert_eq!(next.as_deref(), Some("b"));
    }

    #[test]
    fn test_bad_console_clear() {
        let mut console = BadDebugConsole::new();
        console.append_output(BadConsoleOutputKind::Stdout, "test", 100);
        console.append_output(BadConsoleOutputKind::StartGroup, "g", 200);
        console.clear();
        assert_eq!(console.item_count(), 0);
    }

    #[test]
    fn test_bad_console_tail() {
        let mut console = BadDebugConsole::new();
        for i in 0..10 {
            console.append_output(BadConsoleOutputKind::Stdout, &format!("line {}", i), i * 100);
        }
        let tail = console.tail(3);
        assert_eq!(tail.len(), 3);
    }

    #[test]
    fn test_bad_console_word_wrap() {
        let mut console = BadDebugConsole::new();
        assert!(console.word_wrap());
        console.set_word_wrap(false);
        assert!(!console.word_wrap());
    }

    #[test]
    fn test_bad_console_input() {
        let mut console = BadDebugConsole::new();
        console.set_input("x + 1");
        assert_eq!(console.current_input(), "x + 1");
    }

    #[test]
    fn test_bad_console_trim() {
        let mut console = BadDebugConsole::new();
        console.max_items = 5;
        for i in 0..10 {
            console.append_output(BadConsoleOutputKind::Stdout, &format!("{}", i), i * 100);
        }
        assert_eq!(console.item_count(), 5);
    }

    #[test]
    fn test_bad_console_timestamp() {
        let item = BadConsoleItem::Output(
            BadConsoleEntry::new(BadConsoleOutputKind::Stdout, "x", 12345)
        );
        assert_eq!(item.timestamp_ms(), 12345);
    }
}


// --- bae_: SCM change set model ---

/// SCM resource state (file status in source control).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum BaeScmStatus {
    Untracked,
    Added,
    Modified,
    Deleted,
    Renamed,
    Copied,
    Ignored,
    Conflicting,
    TypeChanged,
}

impl BaeScmStatus {
    pub fn letter(&self) -> char {
        match self {
            Self::Untracked => '?',
            Self::Added => 'A',
            Self::Modified => 'M',
            Self::Deleted => 'D',
            Self::Renamed => 'R',
            Self::Copied => 'C',
            Self::Ignored => '!',
            Self::Conflicting => 'U',
            Self::TypeChanged => 'T',
        }
    }

    pub fn label(&self) -> &'static str {
        match self {
            Self::Untracked => "Untracked",
            Self::Added => "Added",
            Self::Modified => "Modified",
            Self::Deleted => "Deleted",
            Self::Renamed => "Renamed",
            Self::Copied => "Copied",
            Self::Ignored => "Ignored",
            Self::Conflicting => "Conflict",
            Self::TypeChanged => "Type Changed",
        }
    }

    pub fn is_dirty(&self) -> bool {
        !matches!(self, Self::Ignored | Self::Untracked)
    }
}

/// A resource in the SCM view.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct BaeScmResource {
    pub path: String,
    pub original_path: Option<String>,
    pub status: BaeScmStatus,
    pub is_staged: bool,
}

impl BaeScmResource {
    pub fn new(path: &str, status: BaeScmStatus) -> Self {
        Self {
            path: path.to_string(),
            original_path: None,
            status,
            is_staged: false,
        }
    }

    pub fn renamed(original: &str, new_path: &str) -> Self {
        Self {
            path: new_path.to_string(),
            original_path: Some(original.to_string()),
            status: BaeScmStatus::Renamed,
            is_staged: false,
        }
    }

    pub fn stage(&mut self) {
        self.is_staged = true;
    }

    pub fn unstage(&mut self) {
        self.is_staged = false;
    }

    pub fn filename(&self) -> &str {
        self.path.rsplit('/').next().unwrap_or(&self.path)
    }

    pub fn directory(&self) -> &str {
        match self.path.rsplit_once('/') {
            Some((dir, _)) => dir,
            None => "",
        }
    }
}

/// A resource group in the SCM view (e.g., "Changes", "Staged Changes").
#[derive(Debug, Clone)]
pub struct BaeScmResourceGroup {
    pub id: String,
    pub label: String,
    pub resources: Vec<BaeScmResource>,
    pub hide_when_empty: bool,
}

impl BaeScmResourceGroup {
    pub fn new(id: &str, label: &str) -> Self {
        Self {
            id: id.to_string(),
            label: label.to_string(),
            resources: Vec::new(),
            hide_when_empty: true,
        }
    }

    pub fn add_resource(&mut self, resource: BaeScmResource) {
        self.resources.push(resource);
    }

    pub fn remove_resource(&mut self, path: &str) -> bool {
        if let Some(idx) = self.resources.iter().position(|r| r.path == path) {
            self.resources.remove(idx);
            true
        } else {
            false
        }
    }

    pub fn resource_count(&self) -> usize {
        self.resources.len()
    }

    pub fn is_empty(&self) -> bool {
        self.resources.is_empty()
    }

    pub fn is_visible(&self) -> bool {
        !self.hide_when_empty || !self.resources.is_empty()
    }

    pub fn resources_by_status(&self, status: BaeScmStatus) -> Vec<&BaeScmResource> {
        self.resources.iter().filter(|r| r.status == status).collect()
    }

    pub fn sort_by_path(&mut self) {
        self.resources.sort_by(|a, b| a.path.cmp(&b.path));
    }

    pub fn sort_by_status(&mut self) {
        self.resources.sort_by(|a, b| a.status.letter().cmp(&b.status.letter()));
    }
}

/// Represents a commit in the SCM log.
#[derive(Debug, Clone)]
pub struct BaeScmCommit {
    pub hash: String,
    pub short_hash: String,
    pub author_name: String,
    pub author_email: String,
    pub timestamp: u64,
    pub message: String,
    pub parent_hashes: Vec<String>,
}

impl BaeScmCommit {
    pub fn new(hash: &str, message: &str, author: &str, email: &str, timestamp: u64) -> Self {
        Self {
            hash: hash.to_string(),
            short_hash: hash.chars().take(7).collect(),
            author_name: author.to_string(),
            author_email: email.to_string(),
            timestamp,
            message: message.to_string(),
            parent_hashes: Vec::new(),
        }
    }

    pub fn subject(&self) -> &str {
        self.message.lines().next().unwrap_or("")
    }

    pub fn is_merge(&self) -> bool {
        self.parent_hashes.len() > 1
    }
}

/// The SCM provider model (e.g., Git).
#[derive(Debug, Clone)]
pub struct BaeScmProvider {
    pub id: String,
    pub label: String,
    pub root_uri: String,
    pub groups: Vec<BaeScmResourceGroup>,
    pub commit_input: String,
    pub branch_name: Option<String>,
    pub ahead_behind: Option<(u32, u32)>,
}

impl BaeScmProvider {
    pub fn new(id: &str, label: &str, root: &str) -> Self {
        Self {
            id: id.to_string(),
            label: label.to_string(),
            root_uri: root.to_string(),
            groups: Vec::new(),
            commit_input: String::new(),
            branch_name: None,
            ahead_behind: None,
        }
    }

    pub fn add_group(&mut self, group: BaeScmResourceGroup) {
        self.groups.push(group);
    }

    pub fn group(&self, id: &str) -> Option<&BaeScmResourceGroup> {
        self.groups.iter().find(|g| g.id == id)
    }

    pub fn group_mut(&mut self, id: &str) -> Option<&mut BaeScmResourceGroup> {
        self.groups.iter_mut().find(|g| g.id == id)
    }

    pub fn total_resource_count(&self) -> usize {
        self.groups.iter().map(|g| g.resource_count()).sum()
    }

    pub fn dirty_resource_count(&self) -> usize {
        self.groups.iter()
            .flat_map(|g| g.resources.iter())
            .filter(|r| r.status.is_dirty())
            .count()
    }

    pub fn set_branch(&mut self, name: &str) {
        self.branch_name = Some(name.to_string());
    }

    pub fn set_ahead_behind(&mut self, ahead: u32, behind: u32) {
        self.ahead_behind = Some((ahead, behind));
    }

    pub fn status_summary(&self) -> String {
        let dirty = self.dirty_resource_count();
        match &self.branch_name {
            Some(branch) => {
                let ab = match self.ahead_behind {
                    Some((a, b)) if a > 0 && b > 0 => format!(" {}↑ {}↓", a, b),
                    Some((a, 0)) if a > 0 => format!(" {}↑", a),
                    Some((0, b)) if b > 0 => format!(" {}↓", b),
                    _ => String::new(),
                };
                if dirty > 0 {
                    format!("{}{} ({})", branch, ab, dirty)
                } else {
                    format!("{}{}", branch, ab)
                }
            }
            None => {
                if dirty > 0 {
                    format!("({})", dirty)
                } else {
                    String::new()
                }
            }
        }
    }

    pub fn set_commit_message(&mut self, msg: &str) {
        self.commit_input = msg.to_string();
    }
}

#[cfg(test)]
mod bae_tests {
    use super::*;

    #[test]
    fn test_bae_status_letter() {
        assert_eq!(BaeScmStatus::Modified.letter(), 'M');
        assert_eq!(BaeScmStatus::Added.letter(), 'A');
        assert_eq!(BaeScmStatus::Deleted.letter(), 'D');
        assert_eq!(BaeScmStatus::Untracked.letter(), '?');
    }

    #[test]
    fn test_bae_status_dirty() {
        assert!(BaeScmStatus::Modified.is_dirty());
        assert!(BaeScmStatus::Added.is_dirty());
        assert!(!BaeScmStatus::Ignored.is_dirty());
        assert!(!BaeScmStatus::Untracked.is_dirty());
    }

    #[test]
    fn test_bae_resource_creation() {
        let r = BaeScmResource::new("src/main.rs", BaeScmStatus::Modified);
        assert_eq!(r.filename(), "main.rs");
        assert_eq!(r.directory(), "src");
        assert!(!r.is_staged);
    }

    #[test]
    fn test_bae_resource_renamed() {
        let r = BaeScmResource::renamed("old.rs", "new.rs");
        assert_eq!(r.status, BaeScmStatus::Renamed);
        assert_eq!(r.original_path.as_deref(), Some("old.rs"));
    }

    #[test]
    fn test_bae_resource_stage_unstage() {
        let mut r = BaeScmResource::new("file.rs", BaeScmStatus::Modified);
        r.stage();
        assert!(r.is_staged);
        r.unstage();
        assert!(!r.is_staged);
    }

    #[test]
    fn test_bae_group_operations() {
        let mut group = BaeScmResourceGroup::new("changes", "Changes");
        assert!(group.is_empty());
        assert!(!group.is_visible()); // hide_when_empty = true

        group.add_resource(BaeScmResource::new("a.rs", BaeScmStatus::Modified));
        group.add_resource(BaeScmResource::new("b.rs", BaeScmStatus::Added));
        assert_eq!(group.resource_count(), 2);
        assert!(group.is_visible());

        assert!(group.remove_resource("a.rs"));
        assert_eq!(group.resource_count(), 1);
        assert!(!group.remove_resource("nonexistent"));
    }

    #[test]
    fn test_bae_group_filter_by_status() {
        let mut group = BaeScmResourceGroup::new("changes", "Changes");
        group.add_resource(BaeScmResource::new("a.rs", BaeScmStatus::Modified));
        group.add_resource(BaeScmResource::new("b.rs", BaeScmStatus::Added));
        group.add_resource(BaeScmResource::new("c.rs", BaeScmStatus::Modified));

        let modified = group.resources_by_status(BaeScmStatus::Modified);
        assert_eq!(modified.len(), 2);
    }

    #[test]
    fn test_bae_group_sort() {
        let mut group = BaeScmResourceGroup::new("changes", "Changes");
        group.add_resource(BaeScmResource::new("c.rs", BaeScmStatus::Modified));
        group.add_resource(BaeScmResource::new("a.rs", BaeScmStatus::Added));
        group.add_resource(BaeScmResource::new("b.rs", BaeScmStatus::Deleted));
        group.sort_by_path();
        assert_eq!(group.resources[0].path, "a.rs");

        group.sort_by_status();
        assert_eq!(group.resources[0].status, BaeScmStatus::Added);
    }

    #[test]
    fn test_bae_commit() {
        let mut commit = BaeScmCommit::new(
            "abc1234567890", "Fix bug\n\nDetails here", "Alice", "alice@example.com", 1700000000,
        );
        assert_eq!(commit.short_hash, "abc1234");
        assert_eq!(commit.subject(), "Fix bug");
        assert!(!commit.is_merge());

        commit.parent_hashes.push("parent1".to_string());
        commit.parent_hashes.push("parent2".to_string());
        assert!(commit.is_merge());
    }

    #[test]
    fn test_bae_provider_creation() {
        let provider = BaeScmProvider::new("git", "Git", "/workspace");
        assert_eq!(provider.total_resource_count(), 0);
        assert_eq!(provider.dirty_resource_count(), 0);
    }

    #[test]
    fn test_bae_provider_with_groups() {
        let mut provider = BaeScmProvider::new("git", "Git", "/ws");
        let mut staged = BaeScmResourceGroup::new("staged", "Staged Changes");
        staged.add_resource(BaeScmResource::new("a.rs", BaeScmStatus::Added));
        let mut changes = BaeScmResourceGroup::new("changes", "Changes");
        changes.add_resource(BaeScmResource::new("b.rs", BaeScmStatus::Modified));
        changes.add_resource(BaeScmResource::new("c.rs", BaeScmStatus::Modified));

        provider.add_group(staged);
        provider.add_group(changes);

        assert_eq!(provider.total_resource_count(), 3);
        assert_eq!(provider.dirty_resource_count(), 3);
        assert!(provider.group("staged").is_some());
    }

    #[test]
    fn test_bae_provider_status_summary() {
        let mut provider = BaeScmProvider::new("git", "Git", "/ws");
        provider.set_branch("main");
        assert_eq!(provider.status_summary(), "main");

        provider.set_ahead_behind(2, 1);
        assert_eq!(provider.status_summary(), "main 2↑ 1↓");

        let mut changes = BaeScmResourceGroup::new("changes", "Changes");
        changes.add_resource(BaeScmResource::new("a.rs", BaeScmStatus::Modified));
        provider.add_group(changes);
        assert_eq!(provider.status_summary(), "main 2↑ 1↓ (1)");
    }

    #[test]
    fn test_bae_provider_commit_message() {
        let mut provider = BaeScmProvider::new("git", "Git", "/ws");
        provider.set_commit_message("Initial commit");
        assert_eq!(provider.commit_input, "Initial commit");
    }

    #[test]
    fn test_bae_resource_directory_root() {
        let r = BaeScmResource::new("file.rs", BaeScmStatus::Added);
        assert_eq!(r.directory(), "");
        assert_eq!(r.filename(), "file.rs");
    }

    #[test]
    fn test_bae_status_label() {
        assert_eq!(BaeScmStatus::Modified.label(), "Modified");
        assert_eq!(BaeScmStatus::Conflicting.label(), "Conflict");
        assert_eq!(BaeScmStatus::TypeChanged.label(), "Type Changed");
    }
}


// --- baf_: Notification/toast model ---

/// Severity level for a notification.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum BafNotificationSeverity {
    Info,
    Warning,
    Error,
}

impl BafNotificationSeverity {
    pub fn icon(&self) -> &'static str {
        match self {
            Self::Info => "ℹ",
            Self::Warning => "⚠",
            Self::Error => "✗",
        }
    }

    pub fn label(&self) -> &'static str {
        match self {
            Self::Info => "Info",
            Self::Warning => "Warning",
            Self::Error => "Error",
        }
    }
}

/// An action button on a notification.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct BafNotificationAction {
    pub label: String,
    pub command_id: Option<String>,
    pub is_primary: bool,
}

impl BafNotificationAction {
    pub fn new(label: &str) -> Self {
        Self {
            label: label.to_string(),
            command_id: None,
            is_primary: false,
        }
    }

    pub fn primary(label: &str) -> Self {
        Self {
            label: label.to_string(),
            command_id: None,
            is_primary: true,
        }
    }

    pub fn with_command(mut self, command_id: &str) -> Self {
        self.command_id = Some(command_id.to_string());
        self
    }
}

/// State of a notification.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BafNotificationState {
    Pending,
    Visible,
    Dismissed,
    Closed,
}

/// A notification (toast) in the workbench.
#[derive(Debug, Clone)]
pub struct BafNotification {
    pub id: u64,
    pub severity: BafNotificationSeverity,
    pub message: String,
    pub source: Option<String>,
    pub actions: Vec<BafNotificationAction>,
    pub state: BafNotificationState,
    pub is_sticky: bool,
    pub has_progress: bool,
    pub progress_percent: Option<f64>,
    pub created_at_ms: u64,
    pub details: Option<String>,
}

impl BafNotification {
    pub fn new(id: u64, severity: BafNotificationSeverity, message: &str, created_at_ms: u64) -> Self {
        Self {
            id,
            severity,
            message: message.to_string(),
            source: None,
            actions: Vec::new(),
            state: BafNotificationState::Pending,
            is_sticky: false,
            has_progress: false,
            progress_percent: None,
            created_at_ms,
            details: None,
        }
    }

    pub fn with_source(mut self, source: &str) -> Self {
        self.source = Some(source.to_string());
        self
    }

    pub fn with_action(mut self, action: BafNotificationAction) -> Self {
        self.actions.push(action);
        self
    }

    pub fn with_details(mut self, details: &str) -> Self {
        self.details = Some(details.to_string());
        self
    }

    pub fn set_sticky(mut self) -> Self {
        self.is_sticky = true;
        self
    }

    pub fn with_progress(mut self) -> Self {
        self.has_progress = true;
        self
    }

    pub fn update_progress(&mut self, percent: f64) {
        self.progress_percent = Some(percent.clamp(0.0, 100.0));
    }

    pub fn show(&mut self) {
        self.state = BafNotificationState::Visible;
    }

    pub fn dismiss(&mut self) {
        self.state = BafNotificationState::Dismissed;
    }

    pub fn close(&mut self) {
        self.state = BafNotificationState::Closed;
    }

    pub fn is_visible(&self) -> bool {
        self.state == BafNotificationState::Visible
    }

    pub fn is_closed(&self) -> bool {
        matches!(self.state, BafNotificationState::Closed | BafNotificationState::Dismissed)
    }

    pub fn age_ms(&self, now_ms: u64) -> u64 {
        now_ms.saturating_sub(self.created_at_ms)
    }

    pub fn should_auto_dismiss(&self, now_ms: u64, timeout_ms: u64) -> bool {
        !self.is_sticky && !self.has_progress && self.age_ms(now_ms) >= timeout_ms
    }
}

/// Manages all notifications in the workbench.
#[derive(Debug, Clone)]
pub struct BafNotificationCenter {
    notifications: Vec<BafNotification>,
    next_id: u64,
    auto_dismiss_ms: u64,
    do_not_disturb: bool,
}

impl BafNotificationCenter {
    pub fn new() -> Self {
        Self {
            notifications: Vec::new(),
            next_id: 1,
            auto_dismiss_ms: 10_000,
            do_not_disturb: false,
        }
    }

    pub fn notify(&mut self, severity: BafNotificationSeverity, message: &str, timestamp_ms: u64) -> u64 {
        let id = self.next_id;
        self.next_id += 1;
        let mut notif = BafNotification::new(id, severity, message, timestamp_ms);
        if !self.do_not_disturb {
            notif.show();
        }
        self.notifications.push(notif);
        id
    }

    pub fn info(&mut self, message: &str, timestamp_ms: u64) -> u64 {
        self.notify(BafNotificationSeverity::Info, message, timestamp_ms)
    }

    pub fn warn(&mut self, message: &str, timestamp_ms: u64) -> u64 {
        self.notify(BafNotificationSeverity::Warning, message, timestamp_ms)
    }

    pub fn error(&mut self, message: &str, timestamp_ms: u64) -> u64 {
        self.notify(BafNotificationSeverity::Error, message, timestamp_ms)
    }

    pub fn get(&self, id: u64) -> Option<&BafNotification> {
        self.notifications.iter().find(|n| n.id == id)
    }

    pub fn get_mut(&mut self, id: u64) -> Option<&mut BafNotification> {
        self.notifications.iter_mut().find(|n| n.id == id)
    }

    pub fn dismiss(&mut self, id: u64) {
        if let Some(n) = self.get_mut(id) {
            n.dismiss();
        }
    }

    pub fn dismiss_all(&mut self) {
        for n in &mut self.notifications {
            if n.is_visible() {
                n.dismiss();
            }
        }
    }

    pub fn visible_notifications(&self) -> Vec<&BafNotification> {
        self.notifications.iter().filter(|n| n.is_visible()).collect()
    }

    pub fn visible_count(&self) -> usize {
        self.notifications.iter().filter(|n| n.is_visible()).count()
    }

    pub fn all_notifications(&self) -> &[BafNotification] {
        &self.notifications
    }

    pub fn unread_count(&self) -> usize {
        self.notifications.iter()
            .filter(|n| !n.is_closed())
            .count()
    }

    pub fn tick(&mut self, now_ms: u64) {
        let timeout = self.auto_dismiss_ms;
        for n in &mut self.notifications {
            if n.is_visible() && n.should_auto_dismiss(now_ms, timeout) {
                n.dismiss();
            }
        }
    }

    pub fn set_do_not_disturb(&mut self, dnd: bool) {
        self.do_not_disturb = dnd;
    }

    pub fn is_do_not_disturb(&self) -> bool {
        self.do_not_disturb
    }

    pub fn clear_closed(&mut self) {
        self.notifications.retain(|n| !n.is_closed());
    }

    pub fn error_count(&self) -> usize {
        self.notifications.iter()
            .filter(|n| n.severity == BafNotificationSeverity::Error && !n.is_closed())
            .count()
    }
}

#[cfg(test)]
mod baf_tests {
    use super::*;

    #[test]
    fn test_baf_severity_icon() {
        assert_eq!(BafNotificationSeverity::Info.icon(), "\u{2139}");
        assert_eq!(BafNotificationSeverity::Warning.icon(), "\u{26a0}");
        assert_eq!(BafNotificationSeverity::Error.icon(), "\u{2717}");
    }

    #[test]
    fn test_baf_action_creation() {
        let action = BafNotificationAction::primary("Retry")
            .with_command("workbench.action.retry");
        assert!(action.is_primary);
        assert_eq!(action.command_id.as_deref(), Some("workbench.action.retry"));
    }

    #[test]
    fn test_baf_notification_creation() {
        let notif = BafNotification::new(1, BafNotificationSeverity::Info, "Hello", 1000);
        assert_eq!(notif.state, BafNotificationState::Pending);
        assert!(!notif.is_sticky);
        assert!(!notif.has_progress);
    }

    #[test]
    fn test_baf_notification_lifecycle() {
        let mut notif = BafNotification::new(1, BafNotificationSeverity::Info, "Test", 1000);
        assert!(!notif.is_visible());
        notif.show();
        assert!(notif.is_visible());
        notif.dismiss();
        assert!(!notif.is_visible());
        assert!(notif.is_closed());
    }

    #[test]
    fn test_baf_notification_progress() {
        let mut notif = BafNotification::new(1, BafNotificationSeverity::Info, "Loading", 1000)
            .with_progress();
        notif.update_progress(50.0);
        assert_eq!(notif.progress_percent, Some(50.0));
        notif.update_progress(150.0);
        assert_eq!(notif.progress_percent, Some(100.0));
    }

    #[test]
    fn test_baf_notification_auto_dismiss() {
        let notif = BafNotification::new(1, BafNotificationSeverity::Info, "Auto", 1000);
        assert!(notif.should_auto_dismiss(12000, 10000));
        assert!(!notif.should_auto_dismiss(5000, 10000));

        let sticky = BafNotification::new(2, BafNotificationSeverity::Info, "Sticky", 1000)
            .set_sticky();
        assert!(!sticky.should_auto_dismiss(12000, 10000));
    }

    #[test]
    fn test_baf_notification_with_builders() {
        let notif = BafNotification::new(1, BafNotificationSeverity::Warning, "msg", 0)
            .with_source("Git")
            .with_details("Details here")
            .with_action(BafNotificationAction::new("OK"));
        assert_eq!(notif.source.as_deref(), Some("Git"));
        assert_eq!(notif.details.as_deref(), Some("Details here"));
        assert_eq!(notif.actions.len(), 1);
    }

    #[test]
    fn test_baf_center_notify() {
        let mut center = BafNotificationCenter::new();
        let id = center.info("Hello", 1000);
        assert_eq!(center.visible_count(), 1);
        assert_eq!(center.unread_count(), 1);
        assert!(center.get(id).is_some());
    }

    #[test]
    fn test_baf_center_dismiss() {
        let mut center = BafNotificationCenter::new();
        let id = center.info("Hello", 1000);
        center.dismiss(id);
        assert_eq!(center.visible_count(), 0);
    }

    #[test]
    fn test_baf_center_dismiss_all() {
        let mut center = BafNotificationCenter::new();
        center.info("A", 1000);
        center.info("B", 2000);
        center.warn("C", 3000);
        assert_eq!(center.visible_count(), 3);
        center.dismiss_all();
        assert_eq!(center.visible_count(), 0);
    }

    #[test]
    fn test_baf_center_tick_auto_dismiss() {
        let mut center = BafNotificationCenter::new();
        center.auto_dismiss_ms = 5000;
        center.info("Old", 1000);
        center.info("New", 4000);
        center.tick(7000);
        // "Old" at 1000 should be dismissed at 7000 (age=6000 > 5000)
        // "New" at 4000 should still be visible (age=3000 < 5000)
        assert_eq!(center.visible_count(), 1);
    }

    #[test]
    fn test_baf_center_do_not_disturb() {
        let mut center = BafNotificationCenter::new();
        center.set_do_not_disturb(true);
        center.info("Silenced", 1000);
        assert_eq!(center.visible_count(), 0);
        assert_eq!(center.unread_count(), 1);
    }

    #[test]
    fn test_baf_center_clear_closed() {
        let mut center = BafNotificationCenter::new();
        let id = center.info("Test", 1000);
        center.dismiss(id);
        assert_eq!(center.all_notifications().len(), 1);
        center.clear_closed();
        assert_eq!(center.all_notifications().len(), 0);
    }

    #[test]
    fn test_baf_center_error_count() {
        let mut center = BafNotificationCenter::new();
        center.error("Fail 1", 1000);
        center.error("Fail 2", 2000);
        center.info("OK", 3000);
        assert_eq!(center.error_count(), 2);
    }

    #[test]
    fn test_baf_notification_age() {
        let notif = BafNotification::new(1, BafNotificationSeverity::Info, "Test", 5000);
        assert_eq!(notif.age_ms(8000), 3000);
        assert_eq!(notif.age_ms(3000), 0); // Can't be negative
    }
}


// --- bag_: Workspace search model ---

/// Search match location within a file.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct BagSearchMatch {
    pub line: u32,
    pub start_col: u32,
    pub end_col: u32,
    pub preview_text: String,
}

impl BagSearchMatch {
    pub fn new(line: u32, start_col: u32, end_col: u32, preview: &str) -> Self {
        Self {
            line,
            start_col,
            end_col,
            preview_text: preview.to_string(),
        }
    }

    pub fn match_length(&self) -> u32 {
        self.end_col.saturating_sub(self.start_col)
    }
}

/// A file result containing all matches within that file.
#[derive(Debug, Clone)]
pub struct BagFileResult {
    pub file_path: String,
    pub matches: Vec<BagSearchMatch>,
    pub is_expanded: bool,
}

impl BagFileResult {
    pub fn new(path: &str) -> Self {
        Self {
            file_path: path.to_string(),
            matches: Vec::new(),
            is_expanded: true,
        }
    }

    pub fn add_match(&mut self, m: BagSearchMatch) {
        self.matches.push(m);
    }

    pub fn match_count(&self) -> usize {
        self.matches.len()
    }

    pub fn filename(&self) -> &str {
        self.file_path.rsplit('/').next().unwrap_or(&self.file_path)
    }

    pub fn directory(&self) -> &str {
        match self.file_path.rsplit_once('/') {
            Some((dir, _)) => dir,
            None => "",
        }
    }

    pub fn toggle_expand(&mut self) {
        self.is_expanded = !self.is_expanded;
    }
}

/// Search options for workspace search.
#[derive(Debug, Clone)]
pub struct BagSearchOptions {
    pub query: String,
    pub is_regex: bool,
    pub is_case_sensitive: bool,
    pub is_whole_word: bool,
    pub include_pattern: Option<String>,
    pub exclude_pattern: Option<String>,
    pub max_results: usize,
    pub use_ignore_files: bool,
    pub search_in_open_editors_only: bool,
}

impl BagSearchOptions {
    pub fn new(query: &str) -> Self {
        Self {
            query: query.to_string(),
            is_regex: false,
            is_case_sensitive: false,
            is_whole_word: false,
            include_pattern: None,
            exclude_pattern: None,
            max_results: 20_000,
            use_ignore_files: true,
            search_in_open_editors_only: false,
        }
    }

    pub fn regex(mut self) -> Self {
        self.is_regex = true;
        self
    }

    pub fn case_sensitive(mut self) -> Self {
        self.is_case_sensitive = true;
        self
    }

    pub fn whole_word(mut self) -> Self {
        self.is_whole_word = true;
        self
    }

    pub fn with_include(mut self, pattern: &str) -> Self {
        self.include_pattern = Some(pattern.to_string());
        self
    }

    pub fn with_exclude(mut self, pattern: &str) -> Self {
        self.exclude_pattern = Some(pattern.to_string());
        self
    }

    pub fn is_empty(&self) -> bool {
        self.query.is_empty()
    }
}

/// Replace options extend search with replacement text.
#[derive(Debug, Clone)]
pub struct BagReplaceOptions {
    pub search: BagSearchOptions,
    pub replace_text: String,
    pub preserve_case: bool,
}

impl BagReplaceOptions {
    pub fn new(query: &str, replace: &str) -> Self {
        Self {
            search: BagSearchOptions::new(query),
            replace_text: replace.to_string(),
            preserve_case: false,
        }
    }

    pub fn with_preserve_case(mut self) -> Self {
        self.preserve_case = true;
        self
    }
}

/// Search progress state.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BagSearchState {
    Idle,
    Searching,
    Complete,
    Cancelled,
}

/// The workspace search model.
#[derive(Debug, Clone)]
pub struct BagSearchModel {
    pub options: BagSearchOptions,
    pub results: Vec<BagFileResult>,
    pub state: BagSearchState,
    pub total_match_count: usize,
    pub files_searched: usize,
    pub search_duration_ms: Option<u64>,
    pub replace_text: Option<String>,
    pub history: Vec<String>,
    max_history: usize,
}

impl BagSearchModel {
    pub fn new() -> Self {
        Self {
            options: BagSearchOptions::new(""),
            results: Vec::new(),
            state: BagSearchState::Idle,
            total_match_count: 0,
            files_searched: 0,
            search_duration_ms: None,
            replace_text: None,
            history: Vec::new(),
            max_history: 50,
        }
    }

    pub fn start_search(&mut self, options: BagSearchOptions) {
        self.options = options;
        self.results.clear();
        self.total_match_count = 0;
        self.files_searched = 0;
        self.state = BagSearchState::Searching;
        self.search_duration_ms = None;

        // Add to history
        if !self.options.query.is_empty() {
            if self.history.last().map(|s| s.as_str()) != Some(&self.options.query) {
                self.history.push(self.options.query.clone());
                if self.history.len() > self.max_history {
                    self.history.remove(0);
                }
            }
        }
    }

    pub fn add_file_result(&mut self, result: BagFileResult) {
        self.total_match_count += result.match_count();
        self.files_searched += 1;
        self.results.push(result);
    }

    pub fn complete(&mut self, duration_ms: u64) {
        self.state = BagSearchState::Complete;
        self.search_duration_ms = Some(duration_ms);
    }

    pub fn cancel(&mut self) {
        self.state = BagSearchState::Cancelled;
    }

    pub fn clear(&mut self) {
        self.results.clear();
        self.total_match_count = 0;
        self.files_searched = 0;
        self.state = BagSearchState::Idle;
        self.search_duration_ms = None;
    }

    pub fn is_searching(&self) -> bool {
        self.state == BagSearchState::Searching
    }

    pub fn file_count(&self) -> usize {
        self.results.len()
    }

    pub fn status_text(&self) -> String {
        match self.state {
            BagSearchState::Idle => "Ready".to_string(),
            BagSearchState::Searching => format!("Searching... {} results in {} files",
                self.total_match_count, self.file_count()),
            BagSearchState::Complete => {
                let dur = self.search_duration_ms.map(|d| format!(" in {}ms", d)).unwrap_or_default();
                format!("{} results in {} files{}", self.total_match_count, self.file_count(), dur)
            }
            BagSearchState::Cancelled => format!("{} results (cancelled)", self.total_match_count),
        }
    }

    pub fn collapse_all(&mut self) {
        for r in &mut self.results {
            r.is_expanded = false;
        }
    }

    pub fn expand_all(&mut self) {
        for r in &mut self.results {
            r.is_expanded = true;
        }
    }

    pub fn result_at_path(&self, path: &str) -> Option<&BagFileResult> {
        self.results.iter().find(|r| r.file_path == path)
    }

    pub fn set_replace_text(&mut self, text: &str) {
        self.replace_text = Some(text.to_string());
    }

    pub fn search_history(&self) -> &[String] {
        &self.history
    }
}

#[cfg(test)]
mod bag_tests {
    use super::*;

    #[test]
    fn test_bag_search_match() {
        let m = BagSearchMatch::new(10, 5, 12, "let foo = bar;");
        assert_eq!(m.match_length(), 7);
        assert_eq!(m.line, 10);
    }

    #[test]
    fn test_bag_file_result() {
        let mut fr = BagFileResult::new("src/main.rs");
        assert_eq!(fr.filename(), "main.rs");
        assert_eq!(fr.directory(), "src");

        fr.add_match(BagSearchMatch::new(1, 0, 3, "foo"));
        fr.add_match(BagSearchMatch::new(5, 2, 5, "foo"));
        assert_eq!(fr.match_count(), 2);

        fr.toggle_expand();
        assert!(!fr.is_expanded);
    }

    #[test]
    fn test_bag_search_options() {
        let opts = BagSearchOptions::new("hello")
            .case_sensitive()
            .whole_word()
            .with_include("*.rs")
            .with_exclude("target/**");
        assert!(opts.is_case_sensitive);
        assert!(opts.is_whole_word);
        assert_eq!(opts.include_pattern.as_deref(), Some("*.rs"));
        assert!(!opts.is_empty());
    }

    #[test]
    fn test_bag_search_options_regex() {
        let opts = BagSearchOptions::new("fn\\s+\\w+").regex();
        assert!(opts.is_regex);
    }

    #[test]
    fn test_bag_replace_options() {
        let opts = BagReplaceOptions::new("old", "new").with_preserve_case();
        assert!(opts.preserve_case);
        assert_eq!(opts.replace_text, "new");
    }

    #[test]
    fn test_bag_search_model_lifecycle() {
        let mut model = BagSearchModel::new();
        assert_eq!(model.state, BagSearchState::Idle);

        model.start_search(BagSearchOptions::new("test"));
        assert!(model.is_searching());

        let mut fr = BagFileResult::new("a.rs");
        fr.add_match(BagSearchMatch::new(1, 0, 4, "test"));
        fr.add_match(BagSearchMatch::new(3, 0, 4, "test"));
        model.add_file_result(fr);

        let mut fr2 = BagFileResult::new("b.rs");
        fr2.add_match(BagSearchMatch::new(5, 0, 4, "test"));
        model.add_file_result(fr2);

        model.complete(150);
        assert_eq!(model.state, BagSearchState::Complete);
        assert_eq!(model.total_match_count, 3);
        assert_eq!(model.file_count(), 2);
        assert!(model.status_text().contains("3 results"));
    }

    #[test]
    fn test_bag_search_cancel() {
        let mut model = BagSearchModel::new();
        model.start_search(BagSearchOptions::new("query"));
        model.cancel();
        assert_eq!(model.state, BagSearchState::Cancelled);
    }

    #[test]
    fn test_bag_search_clear() {
        let mut model = BagSearchModel::new();
        model.start_search(BagSearchOptions::new("x"));
        model.add_file_result(BagFileResult::new("a.rs"));
        model.clear();
        assert_eq!(model.file_count(), 0);
        assert_eq!(model.state, BagSearchState::Idle);
    }

    #[test]
    fn test_bag_collapse_expand() {
        let mut model = BagSearchModel::new();
        model.start_search(BagSearchOptions::new("x"));
        model.add_file_result(BagFileResult::new("a.rs"));
        model.add_file_result(BagFileResult::new("b.rs"));
        model.collapse_all();
        assert!(model.results.iter().all(|r| !r.is_expanded));
        model.expand_all();
        assert!(model.results.iter().all(|r| r.is_expanded));
    }

    #[test]
    fn test_bag_search_history() {
        let mut model = BagSearchModel::new();
        model.start_search(BagSearchOptions::new("first"));
        model.start_search(BagSearchOptions::new("second"));
        model.start_search(BagSearchOptions::new("second")); // Duplicate not added
        assert_eq!(model.search_history().len(), 2);
    }

    #[test]
    fn test_bag_result_at_path() {
        let mut model = BagSearchModel::new();
        model.start_search(BagSearchOptions::new("x"));
        model.add_file_result(BagFileResult::new("src/lib.rs"));
        assert!(model.result_at_path("src/lib.rs").is_some());
        assert!(model.result_at_path("nonexistent").is_none());
    }

    #[test]
    fn test_bag_replace_text() {
        let mut model = BagSearchModel::new();
        model.set_replace_text("replacement");
        assert_eq!(model.replace_text.as_deref(), Some("replacement"));
    }

    #[test]
    fn test_bag_file_result_root() {
        let fr = BagFileResult::new("file.txt");
        assert_eq!(fr.filename(), "file.txt");
        assert_eq!(fr.directory(), "");
    }

    #[test]
    fn test_bag_status_text_idle() {
        let model = BagSearchModel::new();
        assert_eq!(model.status_text(), "Ready");
    }

    #[test]
    fn test_bag_empty_query() {
        let opts = BagSearchOptions::new("");
        assert!(opts.is_empty());
    }
}


// --- bah_: Editor marker/bookmark model ---

/// Type of editor marker.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum BahMarkerType {
    Bookmark,
    Breakpoint,
    ConditionalBreakpoint,
    Logpoint,
    Error,
    Warning,
    Info,
    Hint,
    Custom,
}

impl BahMarkerType {
    pub fn glyph(&self) -> &'static str {
        match self {
            Self::Bookmark => "\u{1f4d6}",
            Self::Breakpoint => "\u{1f534}",
            Self::ConditionalBreakpoint => "\u{1f7e1}",
            Self::Logpoint => "\u{25c7}",
            Self::Error => "\u{2717}",
            Self::Warning => "\u{26a0}",
            Self::Info => "\u{2139}",
            Self::Hint => "\u{1f4a1}",
            Self::Custom => "\u{25cf}",
        }
    }

    pub fn priority(&self) -> u8 {
        match self {
            Self::Error => 1,
            Self::Breakpoint => 2,
            Self::ConditionalBreakpoint => 3,
            Self::Warning => 4,
            Self::Logpoint => 5,
            Self::Info => 6,
            Self::Bookmark => 7,
            Self::Hint => 8,
            Self::Custom => 9,
        }
    }
}

/// A single editor marker on a line.
#[derive(Debug, Clone)]
pub struct BahMarker {
    pub id: u64,
    pub marker_type: BahMarkerType,
    pub line: u32,
    pub column: Option<u32>,
    pub end_line: Option<u32>,
    pub message: Option<String>,
    pub condition: Option<String>,
    pub is_enabled: bool,
    pub source: Option<String>,
}

impl BahMarker {
    pub fn new(id: u64, marker_type: BahMarkerType, line: u32) -> Self {
        Self {
            id,
            marker_type,
            line,
            column: None,
            end_line: None,
            message: None,
            condition: None,
            is_enabled: true,
            source: None,
        }
    }

    pub fn bookmark(id: u64, line: u32) -> Self {
        Self::new(id, BahMarkerType::Bookmark, line)
    }

    pub fn breakpoint(id: u64, line: u32) -> Self {
        Self::new(id, BahMarkerType::Breakpoint, line)
    }

    pub fn conditional_breakpoint(id: u64, line: u32, condition: &str) -> Self {
        let mut m = Self::new(id, BahMarkerType::ConditionalBreakpoint, line);
        m.condition = Some(condition.to_string());
        m
    }

    pub fn logpoint(id: u64, line: u32, message: &str) -> Self {
        let mut m = Self::new(id, BahMarkerType::Logpoint, line);
        m.message = Some(message.to_string());
        m
    }

    pub fn with_message(mut self, msg: &str) -> Self {
        self.message = Some(msg.to_string());
        self
    }

    pub fn with_source(mut self, source: &str) -> Self {
        self.source = Some(source.to_string());
        self
    }

    pub fn with_range(mut self, end_line: u32) -> Self {
        self.end_line = Some(end_line);
        self
    }

    pub fn toggle_enabled(&mut self) {
        self.is_enabled = !self.is_enabled;
    }

    pub fn is_on_line(&self, line: u32) -> bool {
        if let Some(end) = self.end_line {
            line >= self.line && line <= end
        } else {
            line == self.line
        }
    }

    pub fn line_span(&self) -> u32 {
        match self.end_line {
            Some(end) => end.saturating_sub(self.line) + 1,
            None => 1,
        }
    }

    pub fn shift_line(&mut self, delta: i32) {
        let new_line = (self.line as i64 + delta as i64).max(0) as u32;
        if let Some(end) = self.end_line {
            let end_delta = (end as i64 + delta as i64).max(new_line as i64) as u32;
            self.end_line = Some(end_delta);
        }
        self.line = new_line;
    }
}

/// Collection of markers for a file.
#[derive(Debug, Clone)]
pub struct BahMarkerCollection {
    pub file_path: String,
    markers: Vec<BahMarker>,
    next_id: u64,
}

impl BahMarkerCollection {
    pub fn new(path: &str) -> Self {
        Self {
            file_path: path.to_string(),
            markers: Vec::new(),
            next_id: 1,
        }
    }

    fn alloc_id(&mut self) -> u64 {
        let id = self.next_id;
        self.next_id += 1;
        id
    }

    pub fn add_bookmark(&mut self, line: u32) -> u64 {
        let id = self.alloc_id();
        self.markers.push(BahMarker::bookmark(id, line));
        id
    }

    pub fn add_breakpoint(&mut self, line: u32) -> u64 {
        let id = self.alloc_id();
        self.markers.push(BahMarker::breakpoint(id, line));
        id
    }

    pub fn add_marker(&mut self, marker: BahMarker) -> u64 {
        let id = marker.id;
        self.markers.push(marker);
        if id >= self.next_id {
            self.next_id = id + 1;
        }
        id
    }

    pub fn remove(&mut self, id: u64) -> bool {
        if let Some(idx) = self.markers.iter().position(|m| m.id == id) {
            self.markers.remove(idx);
            true
        } else {
            false
        }
    }

    pub fn get(&self, id: u64) -> Option<&BahMarker> {
        self.markers.iter().find(|m| m.id == id)
    }

    pub fn get_mut(&mut self, id: u64) -> Option<&mut BahMarker> {
        self.markers.iter_mut().find(|m| m.id == id)
    }

    pub fn markers_at_line(&self, line: u32) -> Vec<&BahMarker> {
        self.markers.iter().filter(|m| m.is_on_line(line)).collect()
    }

    pub fn markers_of_type(&self, t: BahMarkerType) -> Vec<&BahMarker> {
        self.markers.iter().filter(|m| m.marker_type == t).collect()
    }

    pub fn all_markers(&self) -> &[BahMarker] {
        &self.markers
    }

    pub fn count(&self) -> usize {
        self.markers.len()
    }

    pub fn bookmark_count(&self) -> usize {
        self.markers.iter().filter(|m| m.marker_type == BahMarkerType::Bookmark).count()
    }

    pub fn breakpoint_count(&self) -> usize {
        self.markers.iter().filter(|m| matches!(m.marker_type,
            BahMarkerType::Breakpoint | BahMarkerType::ConditionalBreakpoint | BahMarkerType::Logpoint
        )).count()
    }

    pub fn toggle_bookmark_at(&mut self, line: u32) -> Option<u64> {
        if let Some(idx) = self.markers.iter().position(|m| m.marker_type == BahMarkerType::Bookmark && m.line == line) {
            let id = self.markers[idx].id;
            self.markers.remove(idx);
            None // Removed
        } else {
            Some(self.add_bookmark(line)) // Added
        }
    }

    pub fn clear_type(&mut self, t: BahMarkerType) {
        self.markers.retain(|m| m.marker_type != t);
    }

    pub fn clear_all(&mut self) {
        self.markers.clear();
    }

    pub fn next_marker_from(&self, line: u32) -> Option<&BahMarker> {
        self.markers.iter().filter(|m| m.line > line).min_by_key(|m| m.line)
    }

    pub fn prev_marker_from(&self, line: u32) -> Option<&BahMarker> {
        self.markers.iter().filter(|m| m.line < line).max_by_key(|m| m.line)
    }

    pub fn sort_by_line(&mut self) {
        self.markers.sort_by_key(|m| (m.line, m.marker_type.priority()));
    }

    pub fn shift_markers_after(&mut self, after_line: u32, delta: i32) {
        for m in &mut self.markers {
            if m.line > after_line {
                m.shift_line(delta);
            }
        }
    }

    pub fn highest_priority_at(&self, line: u32) -> Option<&BahMarker> {
        self.markers_at_line(line).into_iter().min_by_key(|m| m.marker_type.priority())
    }
}

#[cfg(test)]
mod bah_tests {
    use super::*;

    #[test]
    fn test_bah_marker_type_priority() {
        assert!(BahMarkerType::Error.priority() < BahMarkerType::Bookmark.priority());
        assert!(BahMarkerType::Breakpoint.priority() < BahMarkerType::Warning.priority());
    }

    #[test]
    fn test_bah_marker_creation() {
        let m = BahMarker::bookmark(1, 10);
        assert_eq!(m.marker_type, BahMarkerType::Bookmark);
        assert_eq!(m.line, 10);
        assert!(m.is_enabled);
    }

    #[test]
    fn test_bah_conditional_breakpoint() {
        let m = BahMarker::conditional_breakpoint(1, 20, "x > 5");
        assert_eq!(m.condition.as_deref(), Some("x > 5"));
    }

    #[test]
    fn test_bah_logpoint() {
        let m = BahMarker::logpoint(1, 15, "value={x}");
        assert_eq!(m.message.as_deref(), Some("value={x}"));
    }

    #[test]
    fn test_bah_marker_range() {
        let m = BahMarker::new(1, BahMarkerType::Error, 5).with_range(10);
        assert!(m.is_on_line(5));
        assert!(m.is_on_line(7));
        assert!(m.is_on_line(10));
        assert!(!m.is_on_line(11));
        assert_eq!(m.line_span(), 6);
    }

    #[test]
    fn test_bah_marker_toggle() {
        let mut m = BahMarker::breakpoint(1, 10);
        assert!(m.is_enabled);
        m.toggle_enabled();
        assert!(!m.is_enabled);
    }

    #[test]
    fn test_bah_shift_line() {
        let mut m = BahMarker::bookmark(1, 10);
        m.shift_line(5);
        assert_eq!(m.line, 15);
        m.shift_line(-20);
        assert_eq!(m.line, 0);
    }

    #[test]
    fn test_bah_collection_basic() {
        let mut col = BahMarkerCollection::new("test.rs");
        let id1 = col.add_bookmark(5);
        let id2 = col.add_breakpoint(10);
        assert_eq!(col.count(), 2);
        assert_eq!(col.bookmark_count(), 1);
        assert_eq!(col.breakpoint_count(), 1);
        assert!(col.get(id1).is_some());
        assert!(col.remove(id2));
        assert_eq!(col.count(), 1);
    }

    #[test]
    fn test_bah_markers_at_line() {
        let mut col = BahMarkerCollection::new("test.rs");
        col.add_bookmark(5);
        col.add_breakpoint(5);
        col.add_bookmark(10);
        assert_eq!(col.markers_at_line(5).len(), 2);
        assert_eq!(col.markers_at_line(10).len(), 1);
        assert_eq!(col.markers_at_line(15).len(), 0);
    }

    #[test]
    fn test_bah_toggle_bookmark() {
        let mut col = BahMarkerCollection::new("test.rs");
        let added = col.toggle_bookmark_at(10);
        assert!(added.is_some());
        assert_eq!(col.bookmark_count(), 1);

        let removed = col.toggle_bookmark_at(10);
        assert!(removed.is_none());
        assert_eq!(col.bookmark_count(), 0);
    }

    #[test]
    fn test_bah_clear_type() {
        let mut col = BahMarkerCollection::new("test.rs");
        col.add_bookmark(5);
        col.add_bookmark(10);
        col.add_breakpoint(15);
        col.clear_type(BahMarkerType::Bookmark);
        assert_eq!(col.count(), 1);
    }

    #[test]
    fn test_bah_navigation() {
        let mut col = BahMarkerCollection::new("test.rs");
        col.add_bookmark(5);
        col.add_bookmark(15);
        col.add_bookmark(25);
        let next = col.next_marker_from(10);
        assert_eq!(next.unwrap().line, 15);
        let prev = col.prev_marker_from(20);
        assert_eq!(prev.unwrap().line, 15);
    }

    #[test]
    fn test_bah_sort() {
        let mut col = BahMarkerCollection::new("test.rs");
        col.add_bookmark(20);
        col.add_breakpoint(5);
        col.add_bookmark(10);
        col.sort_by_line();
        assert_eq!(col.all_markers()[0].line, 5);
        assert_eq!(col.all_markers()[1].line, 10);
    }

    #[test]
    fn test_bah_shift_after() {
        let mut col = BahMarkerCollection::new("test.rs");
        col.add_bookmark(5);
        col.add_bookmark(10);
        col.add_bookmark(15);
        col.shift_markers_after(8, 3);
        // Line 5 unchanged, lines 10 and 15 shifted
        assert_eq!(col.all_markers()[0].line, 5);
        assert_eq!(col.all_markers()[1].line, 13);
        assert_eq!(col.all_markers()[2].line, 18);
    }

    #[test]
    fn test_bah_highest_priority() {
        let mut col = BahMarkerCollection::new("test.rs");
        col.add_bookmark(5);
        col.add_breakpoint(5);
        let top = col.highest_priority_at(5);
        assert_eq!(top.unwrap().marker_type, BahMarkerType::Breakpoint);
    }

    #[test]
    fn test_bah_markers_of_type() {
        let mut col = BahMarkerCollection::new("test.rs");
        col.add_bookmark(5);
        col.add_bookmark(10);
        col.add_breakpoint(15);
        assert_eq!(col.markers_of_type(BahMarkerType::Bookmark).len(), 2);
    }

    #[test]
    fn test_bah_with_builders() {
        let m = BahMarker::new(1, BahMarkerType::Error, 42)
            .with_message("syntax error")
            .with_source("rustc");
        assert_eq!(m.message.as_deref(), Some("syntax error"));
        assert_eq!(m.source.as_deref(), Some("rustc"));
    }
}


// --- bai_: Editor suggestion/completion widget model ---

/// Completion item kind matching VS Code's CompletionItemKind.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum BaiCompletionKind {
    Text,
    Method,
    Function,
    Constructor,
    Field,
    Variable,
    Class,
    Interface,
    Module,
    Property,
    Unit,
    Value,
    Enum,
    Keyword,
    Snippet,
    Color,
    File,
    Reference,
    Folder,
    EnumMember,
    Constant,
    Struct,
    Event,
    Operator,
    TypeParameter,
}

impl BaiCompletionKind {
    pub fn icon(&self) -> &'static str {
        match self {
            Self::Method | Self::Function => "f",
            Self::Constructor => "C",
            Self::Field | Self::Property => "p",
            Self::Variable => "v",
            Self::Class | Self::Struct => "c",
            Self::Interface => "i",
            Self::Module => "m",
            Self::Enum | Self::EnumMember => "e",
            Self::Keyword => "k",
            Self::Snippet => "s",
            Self::Constant => "K",
            Self::TypeParameter => "T",
            _ => " ",
        }
    }

    pub fn sort_group(&self) -> u8 {
        match self {
            Self::Variable | Self::Field | Self::Property => 0,
            Self::Method | Self::Function => 1,
            Self::Class | Self::Struct | Self::Interface | Self::Enum => 2,
            Self::Keyword => 3,
            Self::Snippet => 4,
            _ => 5,
        }
    }
}

/// A single completion suggestion item.
#[derive(Debug, Clone)]
pub struct BaiSuggestionItem {
    pub label: String,
    pub kind: BaiCompletionKind,
    pub detail: Option<String>,
    pub documentation: Option<String>,
    pub insert_text: Option<String>,
    pub filter_text: Option<String>,
    pub sort_text: Option<String>,
    pub is_snippet: bool,
    pub preselect: bool,
    pub deprecated: bool,
    score: f64,
}

impl BaiSuggestionItem {
    pub fn new(label: &str, kind: BaiCompletionKind) -> Self {
        Self {
            label: label.to_string(),
            kind,
            detail: None,
            documentation: None,
            insert_text: None,
            filter_text: None,
            sort_text: None,
            is_snippet: false,
            preselect: false,
            deprecated: false,
            score: 0.0,
        }
    }

    pub fn with_detail(mut self, detail: &str) -> Self {
        self.detail = Some(detail.to_string());
        self
    }

    pub fn with_documentation(mut self, doc: &str) -> Self {
        self.documentation = Some(doc.to_string());
        self
    }

    pub fn with_insert_text(mut self, text: &str) -> Self {
        self.insert_text = Some(text.to_string());
        self
    }

    pub fn as_snippet(mut self) -> Self {
        self.is_snippet = true;
        self
    }

    pub fn text_to_insert(&self) -> &str {
        self.insert_text.as_deref().unwrap_or(&self.label)
    }

    pub fn filter_label(&self) -> &str {
        self.filter_text.as_deref().unwrap_or(&self.label)
    }

    pub fn sort_key(&self) -> String {
        self.sort_text.as_deref().unwrap_or(&self.label).to_string()
    }

    pub fn set_score(&mut self, score: f64) {
        self.score = score;
    }

    pub fn score(&self) -> f64 {
        self.score
    }
}

/// State of the suggestion widget.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BaiWidgetState {
    Hidden,
    Loading,
    Visible,
    Details,
}

/// The suggestion/completion widget model.
#[derive(Debug, Clone)]
pub struct BaiSuggestionWidget {
    items: Vec<BaiSuggestionItem>,
    filtered_indices: Vec<usize>,
    selected_index: Option<usize>,
    state: BaiWidgetState,
    prefix: String,
    line: u32,
    column: u32,
    max_visible: usize,
    scroll_offset: usize,
}

impl BaiSuggestionWidget {
    pub fn new() -> Self {
        Self {
            items: Vec::new(),
            filtered_indices: Vec::new(),
            selected_index: None,
            state: BaiWidgetState::Hidden,
            prefix: String::new(),
            line: 0,
            column: 0,
            max_visible: 12,
            scroll_offset: 0,
        }
    }

    pub fn show(&mut self, items: Vec<BaiSuggestionItem>, line: u32, column: u32, prefix: &str) {
        self.items = items;
        self.line = line;
        self.column = column;
        self.prefix = prefix.to_string();
        self.filter_items();
        self.state = if self.filtered_indices.is_empty() {
            BaiWidgetState::Hidden
        } else {
            BaiWidgetState::Visible
        };
        self.scroll_offset = 0;
    }

    pub fn hide(&mut self) {
        self.state = BaiWidgetState::Hidden;
        self.items.clear();
        self.filtered_indices.clear();
        self.selected_index = None;
    }

    pub fn is_visible(&self) -> bool {
        matches!(self.state, BaiWidgetState::Visible | BaiWidgetState::Details)
    }

    pub fn state(&self) -> BaiWidgetState {
        self.state
    }

    pub fn update_prefix(&mut self, prefix: &str) {
        self.prefix = prefix.to_string();
        self.filter_items();
        if self.filtered_indices.is_empty() {
            self.state = BaiWidgetState::Hidden;
        }
    }

    fn filter_items(&mut self) {
        let prefix_lower = self.prefix.to_lowercase();
        self.filtered_indices.clear();

        for (i, item) in self.items.iter_mut().enumerate() {
            let label = item.filter_label().to_lowercase();
            if prefix_lower.is_empty() || label.contains(&prefix_lower) {
                let score = if item.preselect {
                    1000.0
                } else if label.starts_with(&prefix_lower) {
                    100.0 + (1.0 / (label.len() as f64 + 1.0))
                } else {
                    50.0 + (1.0 / (label.len() as f64 + 1.0))
                };
                item.set_score(score);
                self.filtered_indices.push(i);
            }
        }

        // Sort by score descending, then by sort_key
        let items_ref = &self.items;
        self.filtered_indices.sort_by(|a, b| {
            let sa = &items_ref[*a];
            let sb = &items_ref[*b];
            sb.score().partial_cmp(&sa.score())
                .unwrap_or(std::cmp::Ordering::Equal)
                .then_with(|| sa.sort_key().cmp(&sb.sort_key()))
        });

        self.selected_index = if self.filtered_indices.is_empty() {
            None
        } else {
            Some(0)
        };
    }

    pub fn filtered_count(&self) -> usize {
        self.filtered_indices.len()
    }

    pub fn selected_item(&self) -> Option<&BaiSuggestionItem> {
        self.selected_index
            .and_then(|si| self.filtered_indices.get(si))
            .map(|idx| &self.items[*idx])
    }

    pub fn visible_items(&self) -> Vec<&BaiSuggestionItem> {
        let start = self.scroll_offset;
        let end = (start + self.max_visible).min(self.filtered_indices.len());
        self.filtered_indices[start..end]
            .iter()
            .map(|idx| &self.items[*idx])
            .collect()
    }

    pub fn select_next(&mut self) {
        if let Some(idx) = self.selected_index {
            if idx + 1 < self.filtered_indices.len() {
                self.selected_index = Some(idx + 1);
                if idx + 1 >= self.scroll_offset + self.max_visible {
                    self.scroll_offset += 1;
                }
            }
        }
    }

    pub fn select_prev(&mut self) {
        if let Some(idx) = self.selected_index {
            if idx > 0 {
                self.selected_index = Some(idx - 1);
                if idx - 1 < self.scroll_offset {
                    self.scroll_offset = idx - 1;
                }
            }
        }
    }

    pub fn select_index(&mut self, index: usize) {
        if index < self.filtered_indices.len() {
            self.selected_index = Some(index);
        }
    }

    pub fn accept_selected(&self) -> Option<&BaiSuggestionItem> {
        self.selected_item()
    }

    pub fn show_details(&mut self) {
        if self.state == BaiWidgetState::Visible {
            self.state = BaiWidgetState::Details;
        }
    }

    pub fn hide_details(&mut self) {
        if self.state == BaiWidgetState::Details {
            self.state = BaiWidgetState::Visible;
        }
    }

    pub fn position(&self) -> (u32, u32) {
        (self.line, self.column)
    }
}

#[cfg(test)]
mod bai_tests {
    use super::*;

    #[test]
    fn test_bai_completion_kind_icon() {
        assert_eq!(BaiCompletionKind::Function.icon(), "f");
        assert_eq!(BaiCompletionKind::Variable.icon(), "v");
        assert_eq!(BaiCompletionKind::Class.icon(), "c");
        assert_eq!(BaiCompletionKind::Keyword.icon(), "k");
    }

    #[test]
    fn test_bai_suggestion_item() {
        let item = BaiSuggestionItem::new("println", BaiCompletionKind::Function)
            .with_detail("macro")
            .with_documentation("Print to stdout");
        assert_eq!(item.label, "println");
        assert_eq!(item.detail.as_deref(), Some("macro"));
        assert_eq!(item.text_to_insert(), "println");
    }

    #[test]
    fn test_bai_item_insert_text() {
        let item = BaiSuggestionItem::new("for", BaiCompletionKind::Snippet)
            .with_insert_text("for ${1:item} in ${2:iter} {\n\t$0\n}")
            .as_snippet();
        assert!(item.is_snippet);
        assert_ne!(item.text_to_insert(), "for");
    }

    #[test]
    fn test_bai_widget_show_hide() {
        let mut widget = BaiSuggestionWidget::new();
        assert!(!widget.is_visible());

        let items = vec![
            BaiSuggestionItem::new("foo", BaiCompletionKind::Variable),
            BaiSuggestionItem::new("bar", BaiCompletionKind::Function),
        ];
        widget.show(items, 10, 5, "");
        assert!(widget.is_visible());
        assert_eq!(widget.filtered_count(), 2);
        assert_eq!(widget.position(), (10, 5));

        widget.hide();
        assert!(!widget.is_visible());
    }

    #[test]
    fn test_bai_widget_filtering() {
        let mut widget = BaiSuggestionWidget::new();
        let items = vec![
            BaiSuggestionItem::new("foo_bar", BaiCompletionKind::Variable),
            BaiSuggestionItem::new("foo_baz", BaiCompletionKind::Variable),
            BaiSuggestionItem::new("qux", BaiCompletionKind::Variable),
        ];
        widget.show(items, 1, 1, "foo");
        assert_eq!(widget.filtered_count(), 2);
    }

    #[test]
    fn test_bai_widget_navigation() {
        let mut widget = BaiSuggestionWidget::new();
        let items = vec![
            BaiSuggestionItem::new("a", BaiCompletionKind::Variable),
            BaiSuggestionItem::new("b", BaiCompletionKind::Variable),
            BaiSuggestionItem::new("c", BaiCompletionKind::Variable),
        ];
        widget.show(items, 1, 1, "");
        assert_eq!(widget.selected_index, Some(0));

        widget.select_next();
        assert_eq!(widget.selected_index, Some(1));

        widget.select_next();
        assert_eq!(widget.selected_index, Some(2));

        widget.select_prev();
        assert_eq!(widget.selected_index, Some(1));
    }

    #[test]
    fn test_bai_widget_preselect() {
        let mut widget = BaiSuggestionWidget::new();
        let mut preselected = BaiSuggestionItem::new("preferred", BaiCompletionKind::Variable);
        preselected.preselect = true;
        let items = vec![
            BaiSuggestionItem::new("alpha", BaiCompletionKind::Variable),
            preselected,
        ];
        widget.show(items, 1, 1, "");
        // Preselected item should be first (highest score)
        assert_eq!(widget.selected_item().unwrap().label, "preferred");
    }

    #[test]
    fn test_bai_widget_details() {
        let mut widget = BaiSuggestionWidget::new();
        let items = vec![
            BaiSuggestionItem::new("test", BaiCompletionKind::Function),
        ];
        widget.show(items, 1, 1, "");
        widget.show_details();
        assert_eq!(widget.state(), BaiWidgetState::Details);
        widget.hide_details();
        assert_eq!(widget.state(), BaiWidgetState::Visible);
    }

    #[test]
    fn test_bai_widget_update_prefix() {
        let mut widget = BaiSuggestionWidget::new();
        let items = vec![
            BaiSuggestionItem::new("hello", BaiCompletionKind::Variable),
            BaiSuggestionItem::new("help", BaiCompletionKind::Function),
            BaiSuggestionItem::new("world", BaiCompletionKind::Variable),
        ];
        widget.show(items, 1, 1, "");
        assert_eq!(widget.filtered_count(), 3);

        widget.update_prefix("hel");
        assert_eq!(widget.filtered_count(), 2);

        widget.update_prefix("xyz");
        assert!(!widget.is_visible()); // No matches
    }

    #[test]
    fn test_bai_widget_accept() {
        let mut widget = BaiSuggestionWidget::new();
        let items = vec![
            BaiSuggestionItem::new("accept_me", BaiCompletionKind::Function),
        ];
        widget.show(items, 1, 1, "");
        let accepted = widget.accept_selected();
        assert_eq!(accepted.unwrap().label, "accept_me");
    }

    #[test]
    fn test_bai_widget_empty() {
        let mut widget = BaiSuggestionWidget::new();
        widget.show(vec![], 1, 1, "");
        assert!(!widget.is_visible());
        assert!(widget.selected_item().is_none());
    }

    #[test]
    fn test_bai_widget_visible_items() {
        let mut widget = BaiSuggestionWidget::new();
        widget.max_visible = 3;
        let items = (0..10)
            .map(|i| BaiSuggestionItem::new(&format!("item_{}", i), BaiCompletionKind::Variable))
            .collect();
        widget.show(items, 1, 1, "");
        assert_eq!(widget.visible_items().len(), 3);
    }

    #[test]
    fn test_bai_sort_group() {
        assert!(BaiCompletionKind::Variable.sort_group() < BaiCompletionKind::Keyword.sort_group());
        assert!(BaiCompletionKind::Function.sort_group() < BaiCompletionKind::Snippet.sort_group());
    }

    #[test]
    fn test_bai_deprecated_item() {
        let mut item = BaiSuggestionItem::new("old_fn", BaiCompletionKind::Function);
        item.deprecated = true;
        assert!(item.deprecated);
    }

    #[test]
    fn test_bai_select_index() {
        let mut widget = BaiSuggestionWidget::new();
        let items = vec![
            BaiSuggestionItem::new("a", BaiCompletionKind::Variable),
            BaiSuggestionItem::new("b", BaiCompletionKind::Variable),
        ];
        widget.show(items, 1, 1, "");
        widget.select_index(1);
        assert_eq!(widget.selected_index, Some(1));
    }
}


// --- baj_: Terminal link detection model ---

/// Type of link detected in terminal output.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum BajTerminalLinkType {
    Url,
    FilePath,
    FilePathWithLine,
    FilePathWithLineCol,
    Command,
    Search,
}

impl BajTerminalLinkType {
    pub fn is_file_link(&self) -> bool {
        matches!(self, Self::FilePath | Self::FilePathWithLine | Self::FilePathWithLineCol)
    }

    pub fn is_url(&self) -> bool {
        matches!(self, Self::Url)
    }

    pub fn label(&self) -> &'static str {
        match self {
            Self::Url => "URL",
            Self::FilePath => "File",
            Self::FilePathWithLine => "File:Line",
            Self::FilePathWithLineCol => "File:Line:Col",
            Self::Command => "Command",
            Self::Search => "Search",
        }
    }
}

/// A detected link in terminal output.
#[derive(Debug, Clone)]
pub struct BajTerminalLink {
    pub link_type: BajTerminalLinkType,
    pub text: String,
    pub start_col: u32,
    pub end_col: u32,
    pub line_in_terminal: u32,
    pub target_path: Option<String>,
    pub target_line: Option<u32>,
    pub target_column: Option<u32>,
    pub url: Option<String>,
    pub tooltip: Option<String>,
}

impl BajTerminalLink {
    pub fn url(text: &str, start: u32, end: u32, line: u32) -> Self {
        Self {
            link_type: BajTerminalLinkType::Url,
            text: text.to_string(),
            start_col: start,
            end_col: end,
            line_in_terminal: line,
            target_path: None,
            target_line: None,
            target_column: None,
            url: Some(text.to_string()),
            tooltip: Some(format!("Open {}", text)),
        }
    }

    pub fn file(text: &str, path: &str, start: u32, end: u32, line: u32) -> Self {
        Self {
            link_type: BajTerminalLinkType::FilePath,
            text: text.to_string(),
            start_col: start,
            end_col: end,
            line_in_terminal: line,
            target_path: Some(path.to_string()),
            target_line: None,
            target_column: None,
            url: None,
            tooltip: Some(format!("Open {}", path)),
        }
    }

    pub fn file_with_line(text: &str, path: &str, target_line: u32, start: u32, end: u32, term_line: u32) -> Self {
        Self {
            link_type: BajTerminalLinkType::FilePathWithLine,
            text: text.to_string(),
            start_col: start,
            end_col: end,
            line_in_terminal: term_line,
            target_path: Some(path.to_string()),
            target_line: Some(target_line),
            target_column: None,
            url: None,
            tooltip: Some(format!("{}:{}", path, target_line)),
        }
    }

    pub fn file_with_line_col(text: &str, path: &str, target_line: u32, target_col: u32, start: u32, end: u32, term_line: u32) -> Self {
        Self {
            link_type: BajTerminalLinkType::FilePathWithLineCol,
            text: text.to_string(),
            start_col: start,
            end_col: end,
            line_in_terminal: term_line,
            target_path: Some(path.to_string()),
            target_line: Some(target_line),
            target_column: Some(target_col),
            url: None,
            tooltip: Some(format!("{}:{}:{}", path, target_line, target_col)),
        }
    }

    pub fn length(&self) -> u32 {
        self.end_col.saturating_sub(self.start_col)
    }

    pub fn contains_col(&self, col: u32) -> bool {
        col >= self.start_col && col < self.end_col
    }
}

/// Detector for links in terminal output lines.
#[derive(Debug, Clone)]
pub struct BajLinkDetector {
    pub url_schemes: Vec<String>,
    pub file_extensions: Vec<String>,
    pub cwd: String,
}

impl BajLinkDetector {
    pub fn new(cwd: &str) -> Self {
        Self {
            url_schemes: vec!["http".to_string(), "https".to_string(), "file".to_string()],
            file_extensions: vec![
                "rs".to_string(), "ts".to_string(), "js".to_string(),
                "py".to_string(), "go".to_string(), "c".to_string(),
                "cpp".to_string(), "h".to_string(), "java".to_string(),
                "rb".to_string(), "sh".to_string(), "toml".to_string(),
                "json".to_string(), "yaml".to_string(), "yml".to_string(),
                "md".to_string(), "txt".to_string(),
            ],
            cwd: cwd.to_string(),
        }
    }

    pub fn detect_urls(&self, text: &str, line: u32) -> Vec<BajTerminalLink> {
        let mut links = Vec::new();
        for scheme in &self.url_schemes {
            let prefix = format!("{}://", scheme);
            let mut start = 0;
            while let Some(pos) = text[start..].find(&prefix) {
                let abs_start = start + pos;
                let url_end = text[abs_start..].find(|c: char| c.is_whitespace() || c == ')' || c == ']' || c == '>' || c == '"' || c == '\'')
                    .map(|e| abs_start + e)
                    .unwrap_or(text.len());
                let url_text = &text[abs_start..url_end];
                if url_text.len() > prefix.len() {
                    links.push(BajTerminalLink::url(url_text, abs_start as u32, url_end as u32, line));
                }
                start = url_end;
            }
        }
        links
    }

    pub fn detect_file_paths(&self, text: &str, line: u32) -> Vec<BajTerminalLink> {
        let mut links = Vec::new();
        // Simple pattern: look for path:line:col or path:line patterns
        let words: Vec<&str> = text.split_whitespace().collect();
        let mut col_offset: u32 = 0;
        for word in &words {
            let clean = word.trim_matches(|c: char| c == '(' || c == ')' || c == ',' || c == ';' || c == ':' && !word.contains('/'));
            let parts: Vec<&str> = clean.splitn(3, ':').collect();
            if let Some(path) = parts.first() {
                let has_ext = self.file_extensions.iter().any(|ext| {
                    path.ends_with(&format!(".{}", ext))
                });
                let looks_like_path = path.contains('/') || path.contains('\\') || has_ext;

                if looks_like_path && !path.is_empty() {
                    let start = text.find(clean).unwrap_or(col_offset as usize) as u32;
                    let end = start + clean.len() as u32;

                    match parts.len() {
                        3 => {
                            if let (Ok(l), Ok(c)) = (parts[1].parse::<u32>(), parts[2].parse::<u32>()) {
                                links.push(BajTerminalLink::file_with_line_col(clean, path, l, c, start, end, line));
                            }
                        }
                        2 => {
                            if let Ok(l) = parts[1].parse::<u32>() {
                                links.push(BajTerminalLink::file_with_line(clean, path, l, start, end, line));
                            }
                        }
                        _ => {
                            if has_ext {
                                links.push(BajTerminalLink::file(clean, path, start, end, line));
                            }
                        }
                    }
                }
            }
            col_offset += word.len() as u32 + 1;
        }
        links
    }

    pub fn detect_all(&self, text: &str, line: u32) -> Vec<BajTerminalLink> {
        let mut links = self.detect_urls(text, line);
        links.extend(self.detect_file_paths(text, line));
        links.sort_by_key(|l| l.start_col);
        links
    }
}

/// Manages detected links for a terminal session.
#[derive(Debug, Clone)]
pub struct BajTerminalLinkManager {
    pub links: Vec<BajTerminalLink>,
    pub detector: BajLinkDetector,
    pub highlighted_link: Option<usize>,
}

impl BajTerminalLinkManager {
    pub fn new(cwd: &str) -> Self {
        Self {
            links: Vec::new(),
            detector: BajLinkDetector::new(cwd),
            highlighted_link: None,
        }
    }

    pub fn process_line(&mut self, text: &str, line: u32) {
        let detected = self.detector.detect_all(text, line);
        self.links.extend(detected);
    }

    pub fn link_at(&self, line: u32, col: u32) -> Option<&BajTerminalLink> {
        self.links.iter().find(|l| l.line_in_terminal == line && l.contains_col(col))
    }

    pub fn links_on_line(&self, line: u32) -> Vec<&BajTerminalLink> {
        self.links.iter().filter(|l| l.line_in_terminal == line).collect()
    }

    pub fn highlight_at(&mut self, line: u32, col: u32) -> bool {
        self.highlighted_link = self.links.iter().position(|l| l.line_in_terminal == line && l.contains_col(col));
        self.highlighted_link.is_some()
    }

    pub fn clear_highlight(&mut self) {
        self.highlighted_link = None;
    }

    pub fn total_links(&self) -> usize {
        self.links.len()
    }

    pub fn url_count(&self) -> usize {
        self.links.iter().filter(|l| l.link_type.is_url()).count()
    }

    pub fn file_link_count(&self) -> usize {
        self.links.iter().filter(|l| l.link_type.is_file_link()).count()
    }

    pub fn clear(&mut self) {
        self.links.clear();
        self.highlighted_link = None;
    }
}

#[cfg(test)]
mod baj_tests {
    use super::*;

    #[test]
    fn test_baj_link_type() {
        assert!(BajTerminalLinkType::FilePath.is_file_link());
        assert!(BajTerminalLinkType::FilePathWithLine.is_file_link());
        assert!(!BajTerminalLinkType::Url.is_file_link());
        assert!(BajTerminalLinkType::Url.is_url());
    }

    #[test]
    fn test_baj_terminal_link_url() {
        let link = BajTerminalLink::url("https://example.com", 5, 25, 0);
        assert_eq!(link.link_type, BajTerminalLinkType::Url);
        assert_eq!(link.length(), 20);
        assert!(link.contains_col(10));
        assert!(!link.contains_col(25));
    }

    #[test]
    fn test_baj_terminal_link_file() {
        let link = BajTerminalLink::file("src/main.rs", "src/main.rs", 0, 11, 3);
        assert_eq!(link.target_path.as_deref(), Some("src/main.rs"));
    }

    #[test]
    fn test_baj_file_with_line_col() {
        let link = BajTerminalLink::file_with_line_col("src/lib.rs:42:10", "src/lib.rs", 42, 10, 0, 16, 5);
        assert_eq!(link.target_line, Some(42));
        assert_eq!(link.target_column, Some(10));
        assert_eq!(link.tooltip.as_deref(), Some("src/lib.rs:42:10"));
    }

    #[test]
    fn test_baj_detect_urls() {
        let detector = BajLinkDetector::new("/home/user");
        let links = detector.detect_urls("Visit https://example.com for more info", 0);
        assert_eq!(links.len(), 1);
        assert_eq!(links[0].text, "https://example.com");
    }

    #[test]
    fn test_baj_detect_file_paths() {
        let detector = BajLinkDetector::new("/workspace");
        let links = detector.detect_file_paths("error at src/main.rs:42:10 failed", 0);
        assert!(!links.is_empty());
        let file_link = &links[0];
        assert!(file_link.link_type.is_file_link());
    }

    #[test]
    fn test_baj_detect_all() {
        let detector = BajLinkDetector::new("/workspace");
        let links = detector.detect_all("See https://docs.rs and src/lib.rs:10", 0);
        assert!(links.len() >= 2);
    }

    #[test]
    fn test_baj_link_manager() {
        let mut mgr = BajTerminalLinkManager::new("/workspace");
        mgr.process_line("Visit https://example.com now", 0);
        mgr.process_line("Error at src/main.rs:10:5", 1);
        assert!(mgr.total_links() >= 2);
        assert!(mgr.url_count() >= 1);
    }

    #[test]
    fn test_baj_link_at() {
        let mut mgr = BajTerminalLinkManager::new("/ws");
        mgr.process_line("See https://example.com here", 0);
        let link = mgr.link_at(0, 6);
        assert!(link.is_some());
        assert!(mgr.link_at(0, 0).is_none()); // Before the URL
    }

    #[test]
    fn test_baj_highlight() {
        let mut mgr = BajTerminalLinkManager::new("/ws");
        mgr.process_line("See https://example.com here", 0);
        assert!(mgr.highlight_at(0, 6));
        assert!(mgr.highlighted_link.is_some());
        mgr.clear_highlight();
        assert!(mgr.highlighted_link.is_none());
    }

    #[test]
    fn test_baj_manager_clear() {
        let mut mgr = BajTerminalLinkManager::new("/ws");
        mgr.process_line("https://a.com", 0);
        mgr.clear();
        assert_eq!(mgr.total_links(), 0);
    }

    #[test]
    fn test_baj_links_on_line() {
        let mut mgr = BajTerminalLinkManager::new("/ws");
        mgr.process_line("https://a.com https://b.com", 0);
        mgr.process_line("Nothing here", 1);
        assert!(mgr.links_on_line(0).len() >= 2);
        assert_eq!(mgr.links_on_line(1).len(), 0);
    }

    #[test]
    fn test_baj_file_extension_detection() {
        let detector = BajLinkDetector::new("/ws");
        let links = detector.detect_file_paths("Failed: test.py crashed", 0);
        assert!(!links.is_empty());
        assert_eq!(links[0].link_type, BajTerminalLinkType::FilePath);
    }
}


// --- bak_: Editor parameter hints model ---

/// A single parameter in a signature.
#[derive(Debug, Clone)]
pub struct BakParameter {
    pub label: String,
    pub documentation: Option<String>,
    pub type_annotation: Option<String>,
    pub is_optional: bool,
    pub is_rest: bool,
    pub default_value: Option<String>,
}

impl BakParameter {
    pub fn new(label: &str) -> Self {
        Self {
            label: label.to_string(),
            documentation: None,
            type_annotation: None,
            is_optional: false,
            is_rest: false,
            default_value: None,
        }
    }

    pub fn with_type(mut self, type_ann: &str) -> Self {
        self.type_annotation = Some(type_ann.to_string());
        self
    }

    pub fn with_doc(mut self, doc: &str) -> Self {
        self.documentation = Some(doc.to_string());
        self
    }

    pub fn optional(mut self) -> Self {
        self.is_optional = true;
        self
    }

    pub fn rest(mut self) -> Self {
        self.is_rest = true;
        self
    }

    pub fn with_default(mut self, val: &str) -> Self {
        self.default_value = Some(val.to_string());
        self.is_optional = true;
        self
    }

    pub fn display_label(&self) -> String {
        let mut s = String::new();
        if self.is_rest {
            s.push_str("...");
        }
        s.push_str(&self.label);
        if let Some(t) = &self.type_annotation {
            s.push_str(": ");
            s.push_str(t);
        }
        if let Some(d) = &self.default_value {
            s.push_str(" = ");
            s.push_str(d);
        }
        if self.is_optional && self.default_value.is_none() {
            s.push('?');
        }
        s
    }
}

/// A function/method signature.
#[derive(Debug, Clone)]
pub struct BakSignature {
    pub label: String,
    pub documentation: Option<String>,
    pub parameters: Vec<BakParameter>,
    pub return_type: Option<String>,
}

impl BakSignature {
    pub fn new(label: &str) -> Self {
        Self {
            label: label.to_string(),
            documentation: None,
            parameters: Vec::new(),
            return_type: None,
        }
    }

    pub fn with_doc(mut self, doc: &str) -> Self {
        self.documentation = Some(doc.to_string());
        self
    }

    pub fn with_return_type(mut self, rt: &str) -> Self {
        self.return_type = Some(rt.to_string());
        self
    }

    pub fn add_param(&mut self, param: BakParameter) {
        self.parameters.push(param);
    }

    pub fn param_count(&self) -> usize {
        self.parameters.len()
    }

    pub fn required_param_count(&self) -> usize {
        self.parameters.iter().filter(|p| !p.is_optional).count()
    }

    pub fn param_at(&self, index: usize) -> Option<&BakParameter> {
        self.parameters.get(index)
    }

    pub fn full_signature(&self) -> String {
        let params: Vec<String> = self.parameters.iter().map(|p| p.display_label()).collect();
        let params_str = params.join(", ");
        match &self.return_type {
            Some(rt) => format!("{}({}) -> {}", self.label, params_str, rt),
            None => format!("{}({})", self.label, params_str),
        }
    }
}

/// State of the parameter hint widget.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BakHintState {
    Hidden,
    Visible,
}

/// The parameter hints widget model.
#[derive(Debug, Clone)]
pub struct BakParameterHints {
    pub signatures: Vec<BakSignature>,
    pub active_signature: usize,
    pub active_parameter: usize,
    pub state: BakHintState,
    pub trigger_char: Option<char>,
    pub line: u32,
    pub column: u32,
}

impl BakParameterHints {
    pub fn new() -> Self {
        Self {
            signatures: Vec::new(),
            active_signature: 0,
            active_parameter: 0,
            state: BakHintState::Hidden,
            trigger_char: None,
            line: 0,
            column: 0,
        }
    }

    pub fn show(&mut self, signatures: Vec<BakSignature>, line: u32, column: u32, trigger: Option<char>) {
        if signatures.is_empty() {
            self.hide();
            return;
        }
        self.signatures = signatures;
        self.active_signature = 0;
        self.active_parameter = 0;
        self.state = BakHintState::Visible;
        self.trigger_char = trigger;
        self.line = line;
        self.column = column;
    }

    pub fn hide(&mut self) {
        self.state = BakHintState::Hidden;
        self.signatures.clear();
    }

    pub fn is_visible(&self) -> bool {
        self.state == BakHintState::Visible
    }

    pub fn active_sig(&self) -> Option<&BakSignature> {
        self.signatures.get(self.active_signature)
    }

    pub fn active_param(&self) -> Option<&BakParameter> {
        self.active_sig().and_then(|s| s.param_at(self.active_parameter))
    }

    pub fn next_signature(&mut self) {
        if !self.signatures.is_empty() {
            self.active_signature = (self.active_signature + 1) % self.signatures.len();
        }
    }

    pub fn prev_signature(&mut self) {
        if !self.signatures.is_empty() {
            self.active_signature = if self.active_signature == 0 {
                self.signatures.len() - 1
            } else {
                self.active_signature - 1
            };
        }
    }

    pub fn set_active_parameter(&mut self, index: usize) {
        self.active_parameter = index;
    }

    pub fn advance_parameter(&mut self) {
        if let Some(sig) = self.active_sig() {
            if self.active_parameter + 1 < sig.param_count() {
                self.active_parameter += 1;
            }
        }
    }

    pub fn retreat_parameter(&mut self) {
        if self.active_parameter > 0 {
            self.active_parameter -= 1;
        }
    }

    pub fn signature_count(&self) -> usize {
        self.signatures.len()
    }

    pub fn signature_label(&self) -> String {
        if self.signatures.len() <= 1 {
            String::new()
        } else {
            format!("{}/{}", self.active_signature + 1, self.signatures.len())
        }
    }
}

#[cfg(test)]
mod bak_tests {
    use super::*;

    #[test]
    fn test_bak_parameter_creation() {
        let p = BakParameter::new("name")
            .with_type("&str")
            .with_doc("The name parameter");
        assert_eq!(p.label, "name");
        assert_eq!(p.type_annotation.as_deref(), Some("&str"));
        assert!(!p.is_optional);
    }

    #[test]
    fn test_bak_parameter_optional() {
        let p = BakParameter::new("count").with_type("usize").optional();
        assert!(p.is_optional);
        assert!(p.display_label().contains('?'));
    }

    #[test]
    fn test_bak_parameter_default() {
        let p = BakParameter::new("size").with_type("u32").with_default("10");
        assert!(p.is_optional);
        assert!(p.display_label().contains("= 10"));
    }

    #[test]
    fn test_bak_parameter_rest() {
        let p = BakParameter::new("args").rest();
        assert!(p.display_label().starts_with("..."));
    }

    #[test]
    fn test_bak_signature_creation() {
        let mut sig = BakSignature::new("foo")
            .with_doc("Does foo things")
            .with_return_type("bool");
        sig.add_param(BakParameter::new("x").with_type("i32"));
        sig.add_param(BakParameter::new("y").with_type("i32"));
        assert_eq!(sig.param_count(), 2);
        assert_eq!(sig.required_param_count(), 2);
        assert!(sig.full_signature().contains("foo(x: i32, y: i32) -> bool"));
    }

    #[test]
    fn test_bak_signature_required_count() {
        let mut sig = BakSignature::new("bar");
        sig.add_param(BakParameter::new("a").with_type("i32"));
        sig.add_param(BakParameter::new("b").with_type("i32").optional());
        assert_eq!(sig.required_param_count(), 1);
        assert_eq!(sig.param_count(), 2);
    }

    #[test]
    fn test_bak_hints_show_hide() {
        let mut hints = BakParameterHints::new();
        assert!(!hints.is_visible());

        let sig = BakSignature::new("test");
        hints.show(vec![sig], 10, 5, Some('('));
        assert!(hints.is_visible());
        assert_eq!(hints.trigger_char, Some('('));

        hints.hide();
        assert!(!hints.is_visible());
    }

    #[test]
    fn test_bak_hints_empty_signatures() {
        let mut hints = BakParameterHints::new();
        hints.show(vec![], 1, 1, None);
        assert!(!hints.is_visible());
    }

    #[test]
    fn test_bak_hints_navigation() {
        let mut hints = BakParameterHints::new();
        let sig1 = BakSignature::new("foo");
        let sig2 = BakSignature::new("bar");
        hints.show(vec![sig1, sig2], 1, 1, None);
        assert_eq!(hints.active_signature, 0);

        hints.next_signature();
        assert_eq!(hints.active_signature, 1);

        hints.next_signature();
        assert_eq!(hints.active_signature, 0); // Wraps

        hints.prev_signature();
        assert_eq!(hints.active_signature, 1); // Wraps back
    }

    #[test]
    fn test_bak_parameter_advance() {
        let mut hints = BakParameterHints::new();
        let mut sig = BakSignature::new("foo");
        sig.add_param(BakParameter::new("a"));
        sig.add_param(BakParameter::new("b"));
        sig.add_param(BakParameter::new("c"));
        hints.show(vec![sig], 1, 1, None);

        assert_eq!(hints.active_parameter, 0);
        hints.advance_parameter();
        assert_eq!(hints.active_parameter, 1);
        hints.advance_parameter();
        assert_eq!(hints.active_parameter, 2);
        hints.advance_parameter();
        assert_eq!(hints.active_parameter, 2); // Can't go past last

        hints.retreat_parameter();
        assert_eq!(hints.active_parameter, 1);
    }

    #[test]
    fn test_bak_active_param() {
        let mut hints = BakParameterHints::new();
        let mut sig = BakSignature::new("test");
        sig.add_param(BakParameter::new("x").with_type("i32"));
        hints.show(vec![sig], 1, 1, None);
        let p = hints.active_param();
        assert_eq!(p.unwrap().label, "x");
    }

    #[test]
    fn test_bak_signature_label() {
        let mut hints = BakParameterHints::new();
        hints.show(vec![BakSignature::new("a"), BakSignature::new("b")], 1, 1, None);
        assert_eq!(hints.signature_label(), "1/2");
        hints.next_signature();
        assert_eq!(hints.signature_label(), "2/2");
    }

    #[test]
    fn test_bak_single_signature_label() {
        let mut hints = BakParameterHints::new();
        hints.show(vec![BakSignature::new("only")], 1, 1, None);
        assert_eq!(hints.signature_label(), "");
    }

    #[test]
    fn test_bak_parameter_display() {
        let p = BakParameter::new("data")
            .with_type("Vec<u8>")
            .with_default("vec![]");
        let display = p.display_label();
        assert!(display.contains("data"));
        assert!(display.contains("Vec<u8>"));
        assert!(display.contains("vec![]"));
    }
}


// --- bal_: Editor code lens model ---

/// A code lens action command.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct BalCodeLensCommand {
    pub title: String,
    pub command_id: String,
    pub arguments: Vec<String>,
    pub tooltip: Option<String>,
}

impl BalCodeLensCommand {
    pub fn new(title: &str, command_id: &str) -> Self {
        Self {
            title: title.to_string(),
            command_id: command_id.to_string(),
            arguments: Vec::new(),
            tooltip: None,
        }
    }

    pub fn with_arg(mut self, arg: &str) -> Self {
        self.arguments.push(arg.to_string());
        self
    }

    pub fn with_tooltip(mut self, tooltip: &str) -> Self {
        self.tooltip = Some(tooltip.to_string());
        self
    }
}

/// A code lens displayed above a line of code.
#[derive(Debug, Clone)]
pub struct BalCodeLens {
    pub line: u32,
    pub start_col: u32,
    pub end_col: u32,
    pub command: Option<BalCodeLensCommand>,
    pub provider_id: String,
    pub is_resolved: bool,
}

impl BalCodeLens {
    pub fn new(line: u32, provider_id: &str) -> Self {
        Self {
            line,
            start_col: 0,
            end_col: 0,
            command: None,
            provider_id: provider_id.to_string(),
            is_resolved: false,
        }
    }

    pub fn with_range(mut self, start: u32, end: u32) -> Self {
        self.start_col = start;
        self.end_col = end;
        self
    }

    pub fn resolve(&mut self, command: BalCodeLensCommand) {
        self.command = Some(command);
        self.is_resolved = true;
    }

    pub fn display_text(&self) -> &str {
        self.command.as_ref().map(|c| c.title.as_str()).unwrap_or("...")
    }

    pub fn is_clickable(&self) -> bool {
        self.command.is_some()
    }
}

/// Manages code lenses for a document.
#[derive(Debug, Clone)]
pub struct BalCodeLensModel {
    lenses: Vec<BalCodeLens>,
    is_enabled: bool,
    is_loading: bool,
}

impl BalCodeLensModel {
    pub fn new() -> Self {
        Self {
            lenses: Vec::new(),
            is_enabled: true,
            is_loading: false,
        }
    }

    pub fn set_lenses(&mut self, lenses: Vec<BalCodeLens>) {
        self.lenses = lenses;
        self.lenses.sort_by_key(|l| l.line);
        self.is_loading = false;
    }

    pub fn start_loading(&mut self) {
        self.is_loading = true;
    }

    pub fn is_loading(&self) -> bool {
        self.is_loading
    }

    pub fn lenses_at_line(&self, line: u32) -> Vec<&BalCodeLens> {
        self.lenses.iter().filter(|l| l.line == line).collect()
    }

    pub fn all_lenses(&self) -> &[BalCodeLens] {
        &self.lenses
    }

    pub fn lens_count(&self) -> usize {
        self.lenses.len()
    }

    pub fn unresolved_count(&self) -> usize {
        self.lenses.iter().filter(|l| !l.is_resolved).count()
    }

    pub fn lines_with_lenses(&self) -> Vec<u32> {
        let mut lines: Vec<u32> = self.lenses.iter().map(|l| l.line).collect();
        lines.dedup();
        lines
    }

    pub fn resolve_lens(&mut self, index: usize, command: BalCodeLensCommand) -> bool {
        if let Some(lens) = self.lenses.get_mut(index) {
            lens.resolve(command);
            true
        } else {
            false
        }
    }

    pub fn clear(&mut self) {
        self.lenses.clear();
    }

    pub fn set_enabled(&mut self, enabled: bool) {
        self.is_enabled = enabled;
    }

    pub fn is_enabled(&self) -> bool {
        self.is_enabled
    }

    pub fn shift_lines(&mut self, after_line: u32, delta: i32) {
        for lens in &mut self.lenses {
            if lens.line > after_line {
                lens.line = (lens.line as i64 + delta as i64).max(0) as u32;
            }
        }
    }

    pub fn lenses_in_range(&self, start_line: u32, end_line: u32) -> Vec<&BalCodeLens> {
        self.lenses.iter().filter(|l| l.line >= start_line && l.line <= end_line).collect()
    }
}

#[cfg(test)]
mod bal_tests {
    use super::*;

    #[test]
    fn test_bal_command_creation() {
        let cmd = BalCodeLensCommand::new("Run Test", "test.run")
            .with_arg("test_name")
            .with_tooltip("Click to run");
        assert_eq!(cmd.title, "Run Test");
        assert_eq!(cmd.arguments.len(), 1);
        assert_eq!(cmd.tooltip.as_deref(), Some("Click to run"));
    }

    #[test]
    fn test_bal_code_lens_creation() {
        let lens = BalCodeLens::new(10, "test-provider").with_range(0, 20);
        assert_eq!(lens.line, 10);
        assert!(!lens.is_resolved);
        assert!(!lens.is_clickable());
        assert_eq!(lens.display_text(), "...");
    }

    #[test]
    fn test_bal_code_lens_resolve() {
        let mut lens = BalCodeLens::new(10, "refs");
        lens.resolve(BalCodeLensCommand::new("3 references", "editor.showReferences"));
        assert!(lens.is_resolved);
        assert!(lens.is_clickable());
        assert_eq!(lens.display_text(), "3 references");
    }

    #[test]
    fn test_bal_model_basic() {
        let mut model = BalCodeLensModel::new();
        assert!(model.is_enabled());
        assert_eq!(model.lens_count(), 0);

        let lenses = vec![
            BalCodeLens::new(5, "refs"),
            BalCodeLens::new(10, "test"),
            BalCodeLens::new(10, "debug"),
        ];
        model.set_lenses(lenses);
        assert_eq!(model.lens_count(), 3);
    }

    #[test]
    fn test_bal_model_at_line() {
        let mut model = BalCodeLensModel::new();
        model.set_lenses(vec![
            BalCodeLens::new(5, "a"),
            BalCodeLens::new(10, "b"),
            BalCodeLens::new(10, "c"),
        ]);
        assert_eq!(model.lenses_at_line(10).len(), 2);
        assert_eq!(model.lenses_at_line(5).len(), 1);
        assert_eq!(model.lenses_at_line(20).len(), 0);
    }

    #[test]
    fn test_bal_model_unresolved() {
        let mut model = BalCodeLensModel::new();
        model.set_lenses(vec![
            BalCodeLens::new(5, "a"),
            BalCodeLens::new(10, "b"),
        ]);
        assert_eq!(model.unresolved_count(), 2);
        model.resolve_lens(0, BalCodeLensCommand::new("Resolved", "cmd"));
        assert_eq!(model.unresolved_count(), 1);
    }

    #[test]
    fn test_bal_model_lines() {
        let mut model = BalCodeLensModel::new();
        model.set_lenses(vec![
            BalCodeLens::new(5, "a"),
            BalCodeLens::new(5, "b"),
            BalCodeLens::new(15, "c"),
        ]);
        let lines = model.lines_with_lenses();
        assert_eq!(lines, vec![5, 15]);
    }

    #[test]
    fn test_bal_model_shift() {
        let mut model = BalCodeLensModel::new();
        model.set_lenses(vec![
            BalCodeLens::new(5, "a"),
            BalCodeLens::new(10, "b"),
        ]);
        model.shift_lines(7, 3);
        assert_eq!(model.all_lenses()[0].line, 5);
        assert_eq!(model.all_lenses()[1].line, 13);
    }

    #[test]
    fn test_bal_model_range() {
        let mut model = BalCodeLensModel::new();
        model.set_lenses(vec![
            BalCodeLens::new(5, "a"),
            BalCodeLens::new(10, "b"),
            BalCodeLens::new(20, "c"),
        ]);
        assert_eq!(model.lenses_in_range(5, 15).len(), 2);
    }

    #[test]
    fn test_bal_model_loading() {
        let mut model = BalCodeLensModel::new();
        model.start_loading();
        assert!(model.is_loading());
        model.set_lenses(vec![]);
        assert!(!model.is_loading());
    }

    #[test]
    fn test_bal_model_clear() {
        let mut model = BalCodeLensModel::new();
        model.set_lenses(vec![BalCodeLens::new(1, "a")]);
        model.clear();
        assert_eq!(model.lens_count(), 0);
    }

    #[test]
    fn test_bal_model_disable() {
        let mut model = BalCodeLensModel::new();
        model.set_enabled(false);
        assert!(!model.is_enabled());
    }
}


// --- bam_: Workspace file system watcher model ---

/// Type of file system event.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum BamFsEventType {
    Created,
    Changed,
    Deleted,
}

impl BamFsEventType {
    pub fn label(&self) -> &'static str {
        match self {
            Self::Created => "created",
            Self::Changed => "changed",
            Self::Deleted => "deleted",
        }
    }
}

/// A file system event.
#[derive(Debug, Clone)]
pub struct BamFsEvent {
    pub event_type: BamFsEventType,
    pub path: String,
    pub is_directory: bool,
    pub timestamp_ms: u64,
}

impl BamFsEvent {
    pub fn created(path: &str, is_dir: bool, timestamp_ms: u64) -> Self {
        Self {
            event_type: BamFsEventType::Created,
            path: path.to_string(),
            is_directory: is_dir,
            timestamp_ms,
        }
    }

    pub fn changed(path: &str, timestamp_ms: u64) -> Self {
        Self {
            event_type: BamFsEventType::Changed,
            path: path.to_string(),
            is_directory: false,
            timestamp_ms,
        }
    }

    pub fn deleted(path: &str, is_dir: bool, timestamp_ms: u64) -> Self {
        Self {
            event_type: BamFsEventType::Deleted,
            path: path.to_string(),
            is_directory: is_dir,
            timestamp_ms,
        }
    }

    pub fn filename(&self) -> &str {
        self.path.rsplit('/').next().unwrap_or(&self.path)
    }

    pub fn extension(&self) -> Option<&str> {
        self.filename().rsplit_once('.').map(|(_, ext)| ext)
    }
}

/// A glob pattern for watching files.
#[derive(Debug, Clone)]
pub struct BamWatchPattern {
    pub glob: String,
    pub recursive: bool,
    pub exclude: bool,
}

impl BamWatchPattern {
    pub fn include(glob: &str) -> Self {
        Self {
            glob: glob.to_string(),
            recursive: true,
            exclude: false,
        }
    }

    pub fn exclude(glob: &str) -> Self {
        Self {
            glob: glob.to_string(),
            recursive: true,
            exclude: true,
        }
    }

    pub fn matches_simple(&self, path: &str) -> bool {
        let filename = path.rsplit('/').next().unwrap_or(path);
        if self.glob.starts_with("**") {
            let pattern = self.glob.trim_start_matches("**/");
            if pattern.starts_with("*.") {
                let ext = pattern.trim_start_matches("*.");
                return filename.ends_with(&format!(".{}", ext));
            }
            return path.contains(pattern);
        }
        if self.glob.starts_with("*.") {
            let ext = self.glob.trim_start_matches("*.");
            return filename.ends_with(&format!(".{}", ext));
        }
        filename == self.glob || path.ends_with(&self.glob)
    }
}

/// A file system watcher subscription.
#[derive(Debug, Clone)]
pub struct BamWatcher {
    pub id: u64,
    pub base_path: String,
    pub patterns: Vec<BamWatchPattern>,
    pub is_active: bool,
}

impl BamWatcher {
    pub fn new(id: u64, base_path: &str) -> Self {
        Self {
            id,
            base_path: base_path.to_string(),
            patterns: Vec::new(),
            is_active: true,
        }
    }

    pub fn add_include(&mut self, glob: &str) {
        self.patterns.push(BamWatchPattern::include(glob));
    }

    pub fn add_exclude(&mut self, glob: &str) {
        self.patterns.push(BamWatchPattern::exclude(glob));
    }

    pub fn should_report(&self, path: &str) -> bool {
        if !self.is_active {
            return false;
        }
        if !path.starts_with(&self.base_path) {
            return false;
        }
        let includes: Vec<_> = self.patterns.iter().filter(|p| !p.exclude).collect();
        let excludes: Vec<_> = self.patterns.iter().filter(|p| p.exclude).collect();

        // Check excludes first
        for excl in &excludes {
            if excl.matches_simple(path) {
                return false;
            }
        }

        if includes.is_empty() {
            return true; // No includes = match all
        }

        includes.iter().any(|p| p.matches_simple(path))
    }

    pub fn suspend(&mut self) {
        self.is_active = false;
    }

    pub fn resume(&mut self) {
        self.is_active = true;
    }
}

/// Manages all file system watchers.
#[derive(Debug, Clone)]
pub struct BamFsWatcherManager {
    watchers: Vec<BamWatcher>,
    event_queue: Vec<BamFsEvent>,
    next_id: u64,
    max_queue_size: usize,
    is_throttled: bool,
    throttle_ms: u64,
    last_event_ms: u64,
}

impl BamFsWatcherManager {
    pub fn new() -> Self {
        Self {
            watchers: Vec::new(),
            event_queue: Vec::new(),
            next_id: 1,
            max_queue_size: 10_000,
            is_throttled: false,
            throttle_ms: 100,
            last_event_ms: 0,
        }
    }

    pub fn create_watcher(&mut self, base_path: &str) -> u64 {
        let id = self.next_id;
        self.next_id += 1;
        self.watchers.push(BamWatcher::new(id, base_path));
        id
    }

    pub fn remove_watcher(&mut self, id: u64) -> bool {
        if let Some(idx) = self.watchers.iter().position(|w| w.id == id) {
            self.watchers.remove(idx);
            true
        } else {
            false
        }
    }

    pub fn watcher(&self, id: u64) -> Option<&BamWatcher> {
        self.watchers.iter().find(|w| w.id == id)
    }

    pub fn watcher_mut(&mut self, id: u64) -> Option<&mut BamWatcher> {
        self.watchers.iter_mut().find(|w| w.id == id)
    }

    pub fn report_event(&mut self, event: BamFsEvent) {
        if self.is_throttled && event.timestamp_ms - self.last_event_ms < self.throttle_ms {
            return;
        }
        self.last_event_ms = event.timestamp_ms;

        // Check if any watcher wants this event
        let relevant = self.watchers.iter().any(|w| w.should_report(&event.path));
        if relevant {
            self.event_queue.push(event);
            if self.event_queue.len() > self.max_queue_size {
                self.event_queue.remove(0);
            }
        }
    }

    pub fn drain_events(&mut self) -> Vec<BamFsEvent> {
        std::mem::take(&mut self.event_queue)
    }

    pub fn pending_event_count(&self) -> usize {
        self.event_queue.len()
    }

    pub fn watcher_count(&self) -> usize {
        self.watchers.len()
    }

    pub fn set_throttle(&mut self, ms: u64) {
        self.throttle_ms = ms;
        self.is_throttled = ms > 0;
    }

    pub fn suspend_all(&mut self) {
        for w in &mut self.watchers {
            w.suspend();
        }
    }

    pub fn resume_all(&mut self) {
        for w in &mut self.watchers {
            w.resume();
        }
    }
}

#[cfg(test)]
mod bam_tests {
    use super::*;

    #[test]
    fn test_bam_fs_event_creation() {
        let e = BamFsEvent::created("/ws/src/main.rs", false, 1000);
        assert_eq!(e.event_type, BamFsEventType::Created);
        assert_eq!(e.filename(), "main.rs");
        assert_eq!(e.extension(), Some("rs"));
    }

    #[test]
    fn test_bam_event_types() {
        let e1 = BamFsEvent::changed("/ws/file.txt", 100);
        assert_eq!(e1.event_type, BamFsEventType::Changed);
        let e2 = BamFsEvent::deleted("/ws/old", true, 200);
        assert!(e2.is_directory);
    }

    #[test]
    fn test_bam_watch_pattern_simple() {
        let p = BamWatchPattern::include("*.rs");
        assert!(p.matches_simple("src/main.rs"));
        assert!(!p.matches_simple("src/main.py"));
    }

    #[test]
    fn test_bam_watch_pattern_recursive() {
        let p = BamWatchPattern::include("**/*.rs");
        assert!(p.matches_simple("deep/nested/file.rs"));
        assert!(!p.matches_simple("file.py"));
    }

    #[test]
    fn test_bam_watcher_should_report() {
        let mut w = BamWatcher::new(1, "/workspace");
        w.add_include("*.rs");
        w.add_exclude("**/target/**");
        assert!(w.should_report("/workspace/src/main.rs"));
        assert!(!w.should_report("/workspace/src/main.py"));
        assert!(!w.should_report("/other/file.rs"));
    }

    #[test]
    fn test_bam_watcher_no_patterns() {
        let w = BamWatcher::new(1, "/workspace");
        assert!(w.should_report("/workspace/any_file.txt"));
    }

    #[test]
    fn test_bam_watcher_suspend_resume() {
        let mut w = BamWatcher::new(1, "/workspace");
        assert!(w.should_report("/workspace/file.txt"));
        w.suspend();
        assert!(!w.should_report("/workspace/file.txt"));
        w.resume();
        assert!(w.should_report("/workspace/file.txt"));
    }

    #[test]
    fn test_bam_manager_create_remove() {
        let mut mgr = BamFsWatcherManager::new();
        let id = mgr.create_watcher("/ws");
        assert_eq!(mgr.watcher_count(), 1);
        assert!(mgr.remove_watcher(id));
        assert_eq!(mgr.watcher_count(), 0);
    }

    #[test]
    fn test_bam_manager_events() {
        let mut mgr = BamFsWatcherManager::new();
        mgr.create_watcher("/ws");
        mgr.report_event(BamFsEvent::changed("/ws/file.rs", 100));
        mgr.report_event(BamFsEvent::created("/ws/new.rs", false, 200));
        assert_eq!(mgr.pending_event_count(), 2);

        let events = mgr.drain_events();
        assert_eq!(events.len(), 2);
        assert_eq!(mgr.pending_event_count(), 0);
    }

    #[test]
    fn test_bam_manager_irrelevant_events() {
        let mut mgr = BamFsWatcherManager::new();
        mgr.create_watcher("/workspace");
        mgr.report_event(BamFsEvent::changed("/other/file.rs", 100));
        assert_eq!(mgr.pending_event_count(), 0);
    }

    #[test]
    fn test_bam_manager_throttle() {
        let mut mgr = BamFsWatcherManager::new();
        mgr.create_watcher("/ws");
        mgr.set_throttle(100);

        mgr.report_event(BamFsEvent::changed("/ws/a.rs", 1000));
        mgr.report_event(BamFsEvent::changed("/ws/b.rs", 1050)); // Throttled
        mgr.report_event(BamFsEvent::changed("/ws/c.rs", 1200)); // OK
        assert_eq!(mgr.pending_event_count(), 2);
    }

    #[test]
    fn test_bam_manager_suspend_resume() {
        let mut mgr = BamFsWatcherManager::new();
        mgr.create_watcher("/ws");
        mgr.suspend_all();
        mgr.report_event(BamFsEvent::changed("/ws/file.rs", 100));
        assert_eq!(mgr.pending_event_count(), 0);
        mgr.resume_all();
        mgr.report_event(BamFsEvent::changed("/ws/file.rs", 200));
        assert_eq!(mgr.pending_event_count(), 1);
    }

    #[test]
    fn test_bam_event_label() {
        assert_eq!(BamFsEventType::Created.label(), "created");
        assert_eq!(BamFsEventType::Changed.label(), "changed");
        assert_eq!(BamFsEventType::Deleted.label(), "deleted");
    }
}


// --- ban_: Editor problem/diagnostics panel model ---

/// Diagnostic severity level.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub enum BanDiagSeverity {
    Error,
    Warning,
    Info,
    Hint,
}

impl BanDiagSeverity {
    pub fn icon(&self) -> &'static str {
        match self {
            Self::Error => "\u{2717}",
            Self::Warning => "\u{26a0}",
            Self::Info => "\u{2139}",
            Self::Hint => "\u{1f4a1}",
        }
    }

    pub fn label(&self) -> &'static str {
        match self {
            Self::Error => "Error",
            Self::Warning => "Warning",
            Self::Info => "Information",
            Self::Hint => "Hint",
        }
    }
}

/// A single diagnostic within a file.
#[derive(Debug, Clone)]
pub struct BanDiagnostic {
    pub severity: BanDiagSeverity,
    pub message: String,
    pub source: Option<String>,
    pub code: Option<String>,
    pub line: u32,
    pub start_col: u32,
    pub end_line: u32,
    pub end_col: u32,
    pub related_info: Vec<BanRelatedInfo>,
    pub tags: Vec<BanDiagTag>,
}

/// Tag modifying diagnostic display.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum BanDiagTag {
    Unnecessary,
    Deprecated,
}

/// Related information for a diagnostic.
#[derive(Debug, Clone)]
pub struct BanRelatedInfo {
    pub path: String,
    pub line: u32,
    pub column: u32,
    pub message: String,
}

impl BanRelatedInfo {
    pub fn new(path: &str, line: u32, col: u32, msg: &str) -> Self {
        Self { path: path.to_string(), line, column: col, message: msg.to_string() }
    }
}

impl BanDiagnostic {
    pub fn new(severity: BanDiagSeverity, message: &str, line: u32, start_col: u32) -> Self {
        Self {
            severity,
            message: message.to_string(),
            source: None,
            code: None,
            line,
            start_col,
            end_line: line,
            end_col: start_col + 1,
            related_info: Vec::new(),
            tags: Vec::new(),
        }
    }

    pub fn with_source(mut self, source: &str) -> Self {
        self.source = Some(source.to_string());
        self
    }

    pub fn with_code(mut self, code: &str) -> Self {
        self.code = Some(code.to_string());
        self
    }

    pub fn with_end(mut self, end_line: u32, end_col: u32) -> Self {
        self.end_line = end_line;
        self.end_col = end_col;
        self
    }

    pub fn with_tag(mut self, tag: BanDiagTag) -> Self {
        self.tags.push(tag);
        self
    }

    pub fn is_multiline(&self) -> bool {
        self.end_line > self.line
    }

    pub fn is_deprecated(&self) -> bool {
        self.tags.contains(&BanDiagTag::Deprecated)
    }

    pub fn is_unnecessary(&self) -> bool {
        self.tags.contains(&BanDiagTag::Unnecessary)
    }

    pub fn location_string(&self) -> String {
        format!("[Ln {}, Col {}]", self.line + 1, self.start_col + 1)
    }
}

/// Diagnostics for a single file.
#[derive(Debug, Clone)]
pub struct BanFileDiagnostics {
    pub file_path: String,
    pub diagnostics: Vec<BanDiagnostic>,
}

impl BanFileDiagnostics {
    pub fn new(path: &str) -> Self {
        Self { file_path: path.to_string(), diagnostics: Vec::new() }
    }

    pub fn add(&mut self, diag: BanDiagnostic) {
        self.diagnostics.push(diag);
    }

    pub fn error_count(&self) -> usize {
        self.diagnostics.iter().filter(|d| d.severity == BanDiagSeverity::Error).count()
    }

    pub fn warning_count(&self) -> usize {
        self.diagnostics.iter().filter(|d| d.severity == BanDiagSeverity::Warning).count()
    }

    pub fn total(&self) -> usize {
        self.diagnostics.len()
    }

    pub fn at_line(&self, line: u32) -> Vec<&BanDiagnostic> {
        self.diagnostics.iter().filter(|d| d.line == line).collect()
    }

    pub fn sort_by_severity(&mut self) {
        self.diagnostics.sort_by_key(|d| d.severity);
    }

    pub fn sort_by_line(&mut self) {
        self.diagnostics.sort_by_key(|d| (d.line, d.start_col));
    }

    pub fn filename(&self) -> &str {
        self.file_path.rsplit('/').next().unwrap_or(&self.file_path)
    }
}

/// The problems panel model.
#[derive(Debug, Clone)]
pub struct BanProblemsPanel {
    pub files: Vec<BanFileDiagnostics>,
    pub filter_text: Option<String>,
    pub show_errors: bool,
    pub show_warnings: bool,
    pub show_infos: bool,
    pub active_file: Option<usize>,
}

impl BanProblemsPanel {
    pub fn new() -> Self {
        Self {
            files: Vec::new(),
            filter_text: None,
            show_errors: true,
            show_warnings: true,
            show_infos: true,
            active_file: None,
        }
    }

    pub fn set_diagnostics(&mut self, path: &str, diagnostics: Vec<BanDiagnostic>) {
        if let Some(fd) = self.files.iter_mut().find(|f| f.file_path == path) {
            fd.diagnostics = diagnostics;
        } else {
            let mut fd = BanFileDiagnostics::new(path);
            fd.diagnostics = diagnostics;
            self.files.push(fd);
        }
        // Remove empty files
        self.files.retain(|f| !f.diagnostics.is_empty());
    }

    pub fn clear_file(&mut self, path: &str) {
        self.files.retain(|f| f.file_path != path);
    }

    pub fn clear_all(&mut self) {
        self.files.clear();
    }

    pub fn total_errors(&self) -> usize {
        self.files.iter().map(|f| f.error_count()).sum()
    }

    pub fn total_warnings(&self) -> usize {
        self.files.iter().map(|f| f.warning_count()).sum()
    }

    pub fn total_diagnostics(&self) -> usize {
        self.files.iter().map(|f| f.total()).sum()
    }

    pub fn file_count(&self) -> usize {
        self.files.len()
    }

    pub fn filtered_files(&self) -> Vec<&BanFileDiagnostics> {
        self.files.iter().filter(|f| {
            if let Some(filter) = &self.filter_text {
                let fl = filter.to_lowercase();
                f.file_path.to_lowercase().contains(&fl) ||
                f.diagnostics.iter().any(|d| d.message.to_lowercase().contains(&fl))
            } else {
                true
            }
        }).collect()
    }

    pub fn set_filter(&mut self, text: Option<String>) {
        self.filter_text = text;
    }

    pub fn status_bar_text(&self) -> String {
        let e = self.total_errors();
        let w = self.total_warnings();
        format!("{} {} {}", BanDiagSeverity::Error.icon(), e, w)
    }

    pub fn diagnostics_for(&self, path: &str) -> Option<&BanFileDiagnostics> {
        self.files.iter().find(|f| f.file_path == path)
    }
}

#[cfg(test)]
mod ban_tests {
    use super::*;

    #[test]
    fn test_ban_severity_ordering() {
        assert!(BanDiagSeverity::Error < BanDiagSeverity::Warning);
        assert!(BanDiagSeverity::Warning < BanDiagSeverity::Info);
    }

    #[test]
    fn test_ban_diagnostic_creation() {
        let d = BanDiagnostic::new(BanDiagSeverity::Error, "expected ';'", 10, 5)
            .with_source("rustc")
            .with_code("E0001")
            .with_end(10, 20);
        assert_eq!(d.source.as_deref(), Some("rustc"));
        assert_eq!(d.code.as_deref(), Some("E0001"));
        assert!(!d.is_multiline());
        assert_eq!(d.location_string(), "[Ln 11, Col 6]");
    }

    #[test]
    fn test_ban_diagnostic_tags() {
        let d = BanDiagnostic::new(BanDiagSeverity::Hint, "unused", 5, 0)
            .with_tag(BanDiagTag::Unnecessary);
        assert!(d.is_unnecessary());
        assert!(!d.is_deprecated());
    }

    #[test]
    fn test_ban_diagnostic_multiline() {
        let d = BanDiagnostic::new(BanDiagSeverity::Error, "block error", 5, 0)
            .with_end(10, 5);
        assert!(d.is_multiline());
    }

    #[test]
    fn test_ban_file_diagnostics() {
        let mut fd = BanFileDiagnostics::new("src/main.rs");
        fd.add(BanDiagnostic::new(BanDiagSeverity::Error, "err1", 1, 0));
        fd.add(BanDiagnostic::new(BanDiagSeverity::Warning, "warn1", 5, 0));
        fd.add(BanDiagnostic::new(BanDiagSeverity::Error, "err2", 10, 0));

        assert_eq!(fd.error_count(), 2);
        assert_eq!(fd.warning_count(), 1);
        assert_eq!(fd.total(), 3);
        assert_eq!(fd.filename(), "main.rs");
    }

    #[test]
    fn test_ban_file_diagnostics_at_line() {
        let mut fd = BanFileDiagnostics::new("test.rs");
        fd.add(BanDiagnostic::new(BanDiagSeverity::Error, "a", 5, 0));
        fd.add(BanDiagnostic::new(BanDiagSeverity::Warning, "b", 5, 10));
        fd.add(BanDiagnostic::new(BanDiagSeverity::Error, "c", 10, 0));
        assert_eq!(fd.at_line(5).len(), 2);
    }

    #[test]
    fn test_ban_file_sort() {
        let mut fd = BanFileDiagnostics::new("test.rs");
        fd.add(BanDiagnostic::new(BanDiagSeverity::Warning, "w", 10, 0));
        fd.add(BanDiagnostic::new(BanDiagSeverity::Error, "e", 5, 0));
        fd.sort_by_severity();
        assert_eq!(fd.diagnostics[0].severity, BanDiagSeverity::Error);

        fd.sort_by_line();
        assert_eq!(fd.diagnostics[0].line, 5);
    }

    #[test]
    fn test_ban_panel_set_diagnostics() {
        let mut panel = BanProblemsPanel::new();
        panel.set_diagnostics("a.rs", vec![
            BanDiagnostic::new(BanDiagSeverity::Error, "err", 1, 0),
        ]);
        assert_eq!(panel.file_count(), 1);
        assert_eq!(panel.total_errors(), 1);

        // Update
        panel.set_diagnostics("a.rs", vec![
            BanDiagnostic::new(BanDiagSeverity::Warning, "warn", 1, 0),
        ]);
        assert_eq!(panel.total_errors(), 0);
        assert_eq!(panel.total_warnings(), 1);
    }

    #[test]
    fn test_ban_panel_clear() {
        let mut panel = BanProblemsPanel::new();
        panel.set_diagnostics("a.rs", vec![
            BanDiagnostic::new(BanDiagSeverity::Error, "err", 1, 0),
        ]);
        panel.clear_file("a.rs");
        assert_eq!(panel.file_count(), 0);
    }

    #[test]
    fn test_ban_panel_filter() {
        let mut panel = BanProblemsPanel::new();
        panel.set_diagnostics("a.rs", vec![
            BanDiagnostic::new(BanDiagSeverity::Error, "missing semicolon", 1, 0),
        ]);
        panel.set_diagnostics("b.rs", vec![
            BanDiagnostic::new(BanDiagSeverity::Warning, "unused variable", 1, 0),
        ]);

        panel.set_filter(Some("semicolon".to_string()));
        assert_eq!(panel.filtered_files().len(), 1);
    }

    #[test]
    fn test_ban_panel_status() {
        let mut panel = BanProblemsPanel::new();
        panel.set_diagnostics("a.rs", vec![
            BanDiagnostic::new(BanDiagSeverity::Error, "e", 1, 0),
            BanDiagnostic::new(BanDiagSeverity::Warning, "w", 2, 0),
        ]);
        let status = panel.status_bar_text();
        assert!(status.contains("1"));
    }

    #[test]
    fn test_ban_related_info() {
        let ri = BanRelatedInfo::new("other.rs", 5, 10, "defined here");
        assert_eq!(ri.path, "other.rs");
        assert_eq!(ri.line, 5);
    }

    #[test]
    fn test_ban_panel_empty_removal() {
        let mut panel = BanProblemsPanel::new();
        panel.set_diagnostics("a.rs", vec![
            BanDiagnostic::new(BanDiagSeverity::Error, "e", 1, 0),
        ]);
        panel.set_diagnostics("a.rs", vec![]); // Clear by setting empty
        assert_eq!(panel.file_count(), 0);
    }
}


// --- bao_: Editor timeline/local history model ---

/// Source of a timeline entry.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum BaoTimelineSource {
    LocalHistory,
    Git,
    Extension,
}

impl BaoTimelineSource {
    pub fn label(&self) -> &'static str {
        match self {
            Self::LocalHistory => "Local History",
            Self::Git => "Git History",
            Self::Extension => "Extension",
        }
    }
}

/// A single timeline entry.
#[derive(Debug, Clone)]
pub struct BaoTimelineEntry {
    pub id: String,
    pub timestamp_ms: u64,
    pub label: String,
    pub description: Option<String>,
    pub source: BaoTimelineSource,
    pub icon: Option<String>,
    pub is_current: bool,
}

impl BaoTimelineEntry {
    pub fn new(id: &str, label: &str, timestamp_ms: u64, source: BaoTimelineSource) -> Self {
        Self {
            id: id.to_string(),
            timestamp_ms,
            label: label.to_string(),
            description: None,
            source,
            icon: None,
            is_current: false,
        }
    }

    pub fn with_description(mut self, desc: &str) -> Self {
        self.description = Some(desc.to_string());
        self
    }

    pub fn relative_time(&self, now_ms: u64) -> String {
        let diff = now_ms.saturating_sub(self.timestamp_ms);
        let secs = diff / 1000;
        if secs < 60 {
            "just now".to_string()
        } else if secs < 3600 {
            format!("{} min ago", secs / 60)
        } else if secs < 86400 {
            format!("{} hours ago", secs / 3600)
        } else {
            format!("{} days ago", secs / 86400)
        }
    }
}

/// Local history entry with content snapshot.
#[derive(Debug, Clone)]
pub struct BaoLocalHistoryEntry {
    pub id: String,
    pub file_path: String,
    pub timestamp_ms: u64,
    pub content_hash: String,
    pub size_bytes: u64,
    pub label: Option<String>,
}

impl BaoLocalHistoryEntry {
    pub fn new(id: &str, path: &str, timestamp_ms: u64, hash: &str, size: u64) -> Self {
        Self {
            id: id.to_string(),
            file_path: path.to_string(),
            timestamp_ms,
            content_hash: hash.to_string(),
            size_bytes: size,
            label: None,
        }
    }

    pub fn with_label(mut self, label: &str) -> Self {
        self.label = Some(label.to_string());
        self
    }

    pub fn display_label(&self) -> String {
        match &self.label {
            Some(l) => l.clone(),
            None => {
                let secs = self.timestamp_ms / 1000;
                format!("Save at {}", secs)
            }
        }
    }
}

/// Manages local history entries for files.
#[derive(Debug, Clone)]
pub struct BaoLocalHistory {
    entries: Vec<BaoLocalHistoryEntry>,
    max_entries_per_file: usize,
    max_total_entries: usize,
    is_enabled: bool,
}

impl BaoLocalHistory {
    pub fn new() -> Self {
        Self {
            entries: Vec::new(),
            max_entries_per_file: 50,
            max_total_entries: 5000,
            is_enabled: true,
        }
    }

    pub fn add_entry(&mut self, entry: BaoLocalHistoryEntry) {
        if !self.is_enabled {
            return;
        }
        self.entries.push(entry);
        self.trim();
    }

    fn trim(&mut self) {
        if self.entries.len() > self.max_total_entries {
            let excess = self.entries.len() - self.max_total_entries;
            self.entries.drain(0..excess);
        }
    }

    pub fn entries_for_file(&self, path: &str) -> Vec<&BaoLocalHistoryEntry> {
        self.entries.iter().filter(|e| e.file_path == path).collect()
    }

    pub fn latest_for_file(&self, path: &str) -> Option<&BaoLocalHistoryEntry> {
        self.entries.iter().rev().find(|e| e.file_path == path)
    }

    pub fn entry_count(&self) -> usize {
        self.entries.len()
    }

    pub fn file_count(&self) -> usize {
        let mut paths: Vec<&str> = self.entries.iter().map(|e| e.file_path.as_str()).collect();
        paths.sort();
        paths.dedup();
        paths.len()
    }

    pub fn remove_entries_for(&mut self, path: &str) {
        self.entries.retain(|e| e.file_path != path);
    }

    pub fn clear(&mut self) {
        self.entries.clear();
    }

    pub fn set_enabled(&mut self, enabled: bool) {
        self.is_enabled = enabled;
    }

    pub fn is_enabled(&self) -> bool {
        self.is_enabled
    }

    pub fn total_size_bytes(&self) -> u64 {
        self.entries.iter().map(|e| e.size_bytes).sum()
    }
}

/// The timeline view model combining multiple sources.
#[derive(Debug, Clone)]
pub struct BaoTimelineView {
    pub entries: Vec<BaoTimelineEntry>,
    pub file_path: Option<String>,
    pub enabled_sources: Vec<BaoTimelineSource>,
    pub is_loading: bool,
}

impl BaoTimelineView {
    pub fn new() -> Self {
        Self {
            entries: Vec::new(),
            file_path: None,
            enabled_sources: vec![BaoTimelineSource::LocalHistory, BaoTimelineSource::Git],
            is_loading: false,
        }
    }

    pub fn set_file(&mut self, path: &str) {
        self.file_path = Some(path.to_string());
        self.entries.clear();
    }

    pub fn add_entries(&mut self, entries: Vec<BaoTimelineEntry>) {
        self.entries.extend(entries);
        self.entries.sort_by(|a, b| b.timestamp_ms.cmp(&a.timestamp_ms));
    }

    pub fn entry_count(&self) -> usize {
        self.entries.len()
    }

    pub fn entries_from_source(&self, source: BaoTimelineSource) -> Vec<&BaoTimelineEntry> {
        self.entries.iter().filter(|e| e.source == source).collect()
    }

    pub fn is_source_enabled(&self, source: BaoTimelineSource) -> bool {
        self.enabled_sources.contains(&source)
    }

    pub fn toggle_source(&mut self, source: BaoTimelineSource) {
        if let Some(idx) = self.enabled_sources.iter().position(|s| *s == source) {
            self.enabled_sources.remove(idx);
        } else {
            self.enabled_sources.push(source);
        }
    }

    pub fn filtered_entries(&self) -> Vec<&BaoTimelineEntry> {
        self.entries.iter()
            .filter(|e| self.enabled_sources.contains(&e.source))
            .collect()
    }

    pub fn clear(&mut self) {
        self.entries.clear();
    }
}

#[cfg(test)]
mod bao_tests {
    use super::*;

    #[test]
    fn test_bao_timeline_source() {
        assert_eq!(BaoTimelineSource::Git.label(), "Git History");
        assert_eq!(BaoTimelineSource::LocalHistory.label(), "Local History");
    }

    #[test]
    fn test_bao_timeline_entry() {
        let e = BaoTimelineEntry::new("e1", "Initial commit", 1000, BaoTimelineSource::Git)
            .with_description("First commit");
        assert_eq!(e.relative_time(2000), "just now");
        assert_eq!(e.relative_time(100_000), "1 min ago");
    }

    #[test]
    fn test_bao_relative_time() {
        let e = BaoTimelineEntry::new("e1", "test", 0, BaoTimelineSource::Git);
        assert_eq!(e.relative_time(30_000), "just now");
        assert_eq!(e.relative_time(120_000), "2 min ago");
        assert_eq!(e.relative_time(7_200_000), "2 hours ago");
        assert_eq!(e.relative_time(172_800_000), "2 days ago");
    }

    #[test]
    fn test_bao_local_history_entry() {
        let e = BaoLocalHistoryEntry::new("h1", "src/main.rs", 5000, "abc123", 1024)
            .with_label("Before refactor");
        assert_eq!(e.display_label(), "Before refactor");

        let e2 = BaoLocalHistoryEntry::new("h2", "src/main.rs", 5000, "def456", 512);
        assert!(e2.display_label().contains("5"));
    }

    #[test]
    fn test_bao_local_history_add() {
        let mut hist = BaoLocalHistory::new();
        hist.add_entry(BaoLocalHistoryEntry::new("1", "a.rs", 1000, "h1", 100));
        hist.add_entry(BaoLocalHistoryEntry::new("2", "a.rs", 2000, "h2", 200));
        hist.add_entry(BaoLocalHistoryEntry::new("3", "b.rs", 3000, "h3", 300));

        assert_eq!(hist.entry_count(), 3);
        assert_eq!(hist.file_count(), 2);
        assert_eq!(hist.entries_for_file("a.rs").len(), 2);
    }

    #[test]
    fn test_bao_local_history_latest() {
        let mut hist = BaoLocalHistory::new();
        hist.add_entry(BaoLocalHistoryEntry::new("1", "a.rs", 1000, "h1", 100));
        hist.add_entry(BaoLocalHistoryEntry::new("2", "a.rs", 2000, "h2", 200));
        let latest = hist.latest_for_file("a.rs");
        assert_eq!(latest.unwrap().id, "2");
    }

    #[test]
    fn test_bao_local_history_remove() {
        let mut hist = BaoLocalHistory::new();
        hist.add_entry(BaoLocalHistoryEntry::new("1", "a.rs", 1000, "h1", 100));
        hist.add_entry(BaoLocalHistoryEntry::new("2", "b.rs", 2000, "h2", 200));
        hist.remove_entries_for("a.rs");
        assert_eq!(hist.entry_count(), 1);
    }

    #[test]
    fn test_bao_local_history_disabled() {
        let mut hist = BaoLocalHistory::new();
        hist.set_enabled(false);
        hist.add_entry(BaoLocalHistoryEntry::new("1", "a.rs", 1000, "h1", 100));
        assert_eq!(hist.entry_count(), 0);
    }

    #[test]
    fn test_bao_local_history_size() {
        let mut hist = BaoLocalHistory::new();
        hist.add_entry(BaoLocalHistoryEntry::new("1", "a.rs", 1000, "h1", 100));
        hist.add_entry(BaoLocalHistoryEntry::new("2", "b.rs", 2000, "h2", 200));
        assert_eq!(hist.total_size_bytes(), 300);
    }

    #[test]
    fn test_bao_timeline_view() {
        let mut view = BaoTimelineView::new();
        view.set_file("src/main.rs");
        view.add_entries(vec![
            BaoTimelineEntry::new("1", "commit A", 2000, BaoTimelineSource::Git),
            BaoTimelineEntry::new("2", "save", 1000, BaoTimelineSource::LocalHistory),
            BaoTimelineEntry::new("3", "commit B", 3000, BaoTimelineSource::Git),
        ]);
        assert_eq!(view.entry_count(), 3);
        // Sorted by timestamp desc
        assert_eq!(view.entries[0].label, "commit B");
    }

    #[test]
    fn test_bao_timeline_filter_source() {
        let mut view = BaoTimelineView::new();
        view.add_entries(vec![
            BaoTimelineEntry::new("1", "commit", 2000, BaoTimelineSource::Git),
            BaoTimelineEntry::new("2", "save", 1000, BaoTimelineSource::LocalHistory),
        ]);
        assert_eq!(view.filtered_entries().len(), 2);

        view.toggle_source(BaoTimelineSource::Git);
        assert_eq!(view.filtered_entries().len(), 1);
        assert_eq!(view.filtered_entries()[0].source, BaoTimelineSource::LocalHistory);
    }

    #[test]
    fn test_bao_timeline_entries_from_source() {
        let mut view = BaoTimelineView::new();
        view.add_entries(vec![
            BaoTimelineEntry::new("1", "a", 1000, BaoTimelineSource::Git),
            BaoTimelineEntry::new("2", "b", 2000, BaoTimelineSource::Git),
            BaoTimelineEntry::new("3", "c", 3000, BaoTimelineSource::LocalHistory),
        ]);
        assert_eq!(view.entries_from_source(BaoTimelineSource::Git).len(), 2);
    }

    #[test]
    fn test_bao_timeline_clear() {
        let mut view = BaoTimelineView::new();
        view.add_entries(vec![
            BaoTimelineEntry::new("1", "a", 1000, BaoTimelineSource::Git),
        ]);
        view.clear();
        assert_eq!(view.entry_count(), 0);
    }
}


// --- bap_: Editor accessibility/screen reader model ---

/// Accessibility role for a UI element.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum BapAccessRole {
    Editor,
    TreeView,
    List,
    ListItem,
    Button,
    Checkbox,
    Textbox,
    Tab,
    TabList,
    Menu,
    MenuItem,
    Dialog,
    Alert,
    Status,
    Toolbar,
    Tooltip,
    Label,
    Group,
}

impl BapAccessRole {
    pub fn aria_role(&self) -> &'static str {
        match self {
            Self::Editor => "textbox",
            Self::TreeView => "tree",
            Self::List => "list",
            Self::ListItem => "listitem",
            Self::Button => "button",
            Self::Checkbox => "checkbox",
            Self::Textbox => "textbox",
            Self::Tab => "tab",
            Self::TabList => "tablist",
            Self::Menu => "menu",
            Self::MenuItem => "menuitem",
            Self::Dialog => "dialog",
            Self::Alert => "alert",
            Self::Status => "status",
            Self::Toolbar => "toolbar",
            Self::Tooltip => "tooltip",
            Self::Label => "label",
            Self::Group => "group",
        }
    }
}

/// An accessible element in the UI.
#[derive(Debug, Clone)]
pub struct BapAccessElement {
    pub id: String,
    pub role: BapAccessRole,
    pub label: String,
    pub value: Option<String>,
    pub description: Option<String>,
    pub is_focused: bool,
    pub is_selected: bool,
    pub is_expanded: Option<bool>,
    pub is_disabled: bool,
    pub level: Option<u32>,
    pub position_in_set: Option<u32>,
    pub set_size: Option<u32>,
}

impl BapAccessElement {
    pub fn new(id: &str, role: BapAccessRole, label: &str) -> Self {
        Self {
            id: id.to_string(),
            role,
            label: label.to_string(),
            value: None,
            description: None,
            is_focused: false,
            is_selected: false,
            is_expanded: None,
            is_disabled: false,
            level: None,
            position_in_set: None,
            set_size: None,
        }
    }

    pub fn with_value(mut self, value: &str) -> Self {
        self.value = Some(value.to_string());
        self
    }

    pub fn with_description(mut self, desc: &str) -> Self {
        self.description = Some(desc.to_string());
        self
    }

    pub fn with_set_info(mut self, position: u32, size: u32) -> Self {
        self.position_in_set = Some(position);
        self.set_size = Some(size);
        self
    }

    pub fn with_level(mut self, level: u32) -> Self {
        self.level = Some(level);
        self
    }

    pub fn announce(&self) -> String {
        let mut parts = Vec::new();
        parts.push(self.label.clone());
        if let Some(v) = &self.value {
            parts.push(v.clone());
        }
        parts.push(self.role.aria_role().to_string());
        if let Some(expanded) = self.is_expanded {
            parts.push(if expanded { "expanded" } else { "collapsed" }.to_string());
        }
        if self.is_selected {
            parts.push("selected".to_string());
        }
        if self.is_disabled {
            parts.push("disabled".to_string());
        }
        if let (Some(pos), Some(size)) = (self.position_in_set, self.set_size) {
            parts.push(format!("{} of {}", pos, size));
        }
        parts.join(", ")
    }
}

/// Screen reader announcement priority.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub enum BapAnnouncePriority {
    Polite,
    Assertive,
}

/// A screen reader announcement.
#[derive(Debug, Clone)]
pub struct BapAnnouncement {
    pub message: String,
    pub priority: BapAnnouncePriority,
    pub timestamp_ms: u64,
}

impl BapAnnouncement {
    pub fn polite(message: &str, timestamp_ms: u64) -> Self {
        Self { message: message.to_string(), priority: BapAnnouncePriority::Polite, timestamp_ms }
    }

    pub fn assertive(message: &str, timestamp_ms: u64) -> Self {
        Self { message: message.to_string(), priority: BapAnnouncePriority::Assertive, timestamp_ms }
    }
}

/// Accessibility settings.
#[derive(Debug, Clone)]
pub struct BapAccessSettings {
    pub screen_reader_detected: bool,
    pub high_contrast: bool,
    pub reduce_motion: bool,
    pub tab_focus_mode: bool,
    pub font_size_factor: f64,
    pub cursor_width: u32,
    pub line_highlight: bool,
}

impl BapAccessSettings {
    pub fn default_settings() -> Self {
        Self {
            screen_reader_detected: false,
            high_contrast: false,
            reduce_motion: false,
            tab_focus_mode: false,
            font_size_factor: 1.0,
            cursor_width: 2,
            line_highlight: true,
        }
    }

    pub fn screen_reader_mode() -> Self {
        Self {
            screen_reader_detected: true,
            high_contrast: true,
            reduce_motion: true,
            tab_focus_mode: true,
            font_size_factor: 1.2,
            cursor_width: 3,
            line_highlight: true,
        }
    }

    pub fn needs_accessibility_mode(&self) -> bool {
        self.screen_reader_detected || self.high_contrast
    }
}

/// Manages accessibility state for the workbench.
#[derive(Debug, Clone)]
pub struct BapAccessibilityManager {
    pub settings: BapAccessSettings,
    pub announcements: Vec<BapAnnouncement>,
    pub focus_path: Vec<String>,
    max_announcements: usize,
}

impl BapAccessibilityManager {
    pub fn new() -> Self {
        Self {
            settings: BapAccessSettings::default_settings(),
            announcements: Vec::new(),
            focus_path: Vec::new(),
            max_announcements: 100,
        }
    }

    pub fn announce(&mut self, message: &str, priority: BapAnnouncePriority, timestamp_ms: u64) {
        let ann = BapAnnouncement {
            message: message.to_string(),
            priority,
            timestamp_ms,
        };
        self.announcements.push(ann);
        if self.announcements.len() > self.max_announcements {
            self.announcements.remove(0);
        }
    }

    pub fn announce_polite(&mut self, message: &str, timestamp_ms: u64) {
        self.announce(message, BapAnnouncePriority::Polite, timestamp_ms);
    }

    pub fn announce_assertive(&mut self, message: &str, timestamp_ms: u64) {
        self.announce(message, BapAnnouncePriority::Assertive, timestamp_ms);
    }

    pub fn set_focus_path(&mut self, path: Vec<String>) {
        self.focus_path = path;
    }

    pub fn focus_description(&self) -> String {
        self.focus_path.join(" > ")
    }

    pub fn latest_announcement(&self) -> Option<&BapAnnouncement> {
        self.announcements.last()
    }

    pub fn pending_assertive(&self) -> Vec<&BapAnnouncement> {
        self.announcements.iter()
            .filter(|a| a.priority == BapAnnouncePriority::Assertive)
            .collect()
    }

    pub fn clear_announcements(&mut self) {
        self.announcements.clear();
    }

    pub fn is_screen_reader_active(&self) -> bool {
        self.settings.screen_reader_detected
    }

    pub fn enable_screen_reader(&mut self) {
        self.settings = BapAccessSettings::screen_reader_mode();
    }
}

