// --- bbx_: Workspace edit/refactoring preview model ---

/// Kind of workspace file operation.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BbxFileOp { Create, Rename, Delete }

impl BbxFileOp {
    pub fn label(&self) -> &'static str {
        match self { Self::Create => "Create", Self::Rename => "Rename", Self::Delete => "Delete" }
    }
}

/// A text edit within a file.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct BbxTextEdit {
    pub start_line: u32,
    pub start_col: u32,
    pub end_line: u32,
    pub end_col: u32,
    pub new_text: String,
}

impl BbxTextEdit {
    pub fn new(sl: u32, sc: u32, el: u32, ec: u32, text: &str) -> Self {
        Self { start_line: sl, start_col: sc, end_line: el, end_col: ec, new_text: text.to_string() }
    }

    pub fn is_insert(&self) -> bool { self.start_line == self.end_line && self.start_col == self.end_col }
    pub fn is_delete(&self) -> bool { self.new_text.is_empty() }
    pub fn is_replace(&self) -> bool { !self.is_insert() && !self.is_delete() }
}

/// Edits for a single file.
#[derive(Debug, Clone)]
pub struct BbxFileEdits {
    pub file_path: String,
    pub edits: Vec<BbxTextEdit>,
    pub checked: bool,
}

impl BbxFileEdits {
    pub fn new(path: &str, edits: Vec<BbxTextEdit>) -> Self {
        Self { file_path: path.to_string(), edits, checked: true }
    }

    pub fn edit_count(&self) -> usize { self.edits.len() }
    pub fn toggle(&mut self) { self.checked = !self.checked; }
}

/// A file operation (create/rename/delete).
#[derive(Debug, Clone)]
pub struct BbxFileOperation {
    pub op: BbxFileOp,
    pub path: String,
    pub new_path: Option<String>,
    pub checked: bool,
}

impl BbxFileOperation {
    pub fn create(path: &str) -> Self {
        Self { op: BbxFileOp::Create, path: path.to_string(), new_path: None, checked: true }
    }

    pub fn rename(old: &str, new: &str) -> Self {
        Self { op: BbxFileOp::Rename, path: old.to_string(), new_path: Some(new.to_string()), checked: true }
    }

    pub fn delete(path: &str) -> Self {
        Self { op: BbxFileOp::Delete, path: path.to_string(), new_path: None, checked: true }
    }

    pub fn display_text(&self) -> String {
        match self.op {
            BbxFileOp::Create => format!("Create {}", self.path),
            BbxFileOp::Rename => format!("Rename {} → {}", self.path, self.new_path.as_deref().unwrap_or("?")),
            BbxFileOp::Delete => format!("Delete {}", self.path),
        }
    }
}

/// The workspace edit preview model.
#[derive(Debug)]
pub struct BbxEditPreview {
    pub label: String,
    file_edits: Vec<BbxFileEdits>,
    file_ops: Vec<BbxFileOperation>,
    confirmed: bool,
}

impl BbxEditPreview {
    pub fn new(label: &str) -> Self {
        Self { label: label.to_string(), file_edits: Vec::new(), file_ops: Vec::new(), confirmed: false }
    }

    pub fn add_file_edits(&mut self, fe: BbxFileEdits) { self.file_edits.push(fe); }
    pub fn add_file_op(&mut self, op: BbxFileOperation) { self.file_ops.push(op); }

    pub fn file_count(&self) -> usize { self.file_edits.len() }
    pub fn total_edits(&self) -> usize { self.file_edits.iter().map(|f| f.edit_count()).sum() }
    pub fn file_op_count(&self) -> usize { self.file_ops.len() }

    pub fn checked_edits(&self) -> usize {
        self.file_edits.iter().filter(|f| f.checked).map(|f| f.edit_count()).sum()
    }

    pub fn toggle_file(&mut self, idx: usize) {
        if idx < self.file_edits.len() { self.file_edits[idx].toggle(); }
    }

    pub fn confirm(&mut self) { self.confirmed = true; }
    pub fn is_confirmed(&self) -> bool { self.confirmed }

    pub fn file_edits(&self) -> &[BbxFileEdits] { &self.file_edits }
    pub fn file_ops(&self) -> &[BbxFileOperation] { &self.file_ops }

    pub fn status_text(&self) -> String {
        format!("{}: {} files, {} edits", self.label, self.file_count(), self.total_edits())
    }
}

#[cfg(test)]
mod bbx_tests {
    use super::*;

    #[test]
    fn test_bbx_text_edit() {
        let ins = BbxTextEdit::new(1, 5, 1, 5, "hello");
        assert!(ins.is_insert());
        let del = BbxTextEdit::new(1, 0, 1, 5, "");
        assert!(del.is_delete());
        let rep = BbxTextEdit::new(1, 0, 1, 5, "world");
        assert!(rep.is_replace());
    }

    #[test]
    fn test_bbx_file_edits() {
        let mut fe = BbxFileEdits::new("x.rs", vec![
            BbxTextEdit::new(1, 0, 1, 5, "new"),
        ]);
        assert!(fe.checked);
        fe.toggle();
        assert!(!fe.checked);
    }

    #[test]
    fn test_bbx_file_op_create() {
        let op = BbxFileOperation::create("new_file.rs");
        assert_eq!(op.display_text(), "Create new_file.rs");
    }

    #[test]
    fn test_bbx_file_op_rename() {
        let op = BbxFileOperation::rename("old.rs", "new.rs");
        assert!(op.display_text().contains("→"));
    }

    #[test]
    fn test_bbx_preview_basic() {
        let mut p = BbxEditPreview::new("Rename Symbol");
        p.add_file_edits(BbxFileEdits::new("a.rs", vec![BbxTextEdit::new(1, 0, 1, 3, "foo")]));
        p.add_file_edits(BbxFileEdits::new("b.rs", vec![
            BbxTextEdit::new(5, 0, 5, 3, "foo"),
            BbxTextEdit::new(10, 0, 10, 3, "foo"),
        ]));
        assert_eq!(p.file_count(), 2);
        assert_eq!(p.total_edits(), 3);
    }

    #[test]
    fn test_bbx_preview_toggle() {
        let mut p = BbxEditPreview::new("test");
        p.add_file_edits(BbxFileEdits::new("a.rs", vec![BbxTextEdit::new(1, 0, 1, 3, "x")]));
        assert_eq!(p.checked_edits(), 1);
        p.toggle_file(0);
        assert_eq!(p.checked_edits(), 0);
    }

    #[test]
    fn test_bbx_preview_confirm() {
        let mut p = BbxEditPreview::new("test");
        assert!(!p.is_confirmed());
        p.confirm();
        assert!(p.is_confirmed());
    }

    #[test]
    fn test_bbx_preview_status() {
        let mut p = BbxEditPreview::new("Refactor");
        p.add_file_edits(BbxFileEdits::new("a.rs", vec![BbxTextEdit::new(1, 0, 1, 3, "x")]));
        assert_eq!(p.status_text(), "Refactor: 1 files, 1 edits");
    }

    #[test]
    fn test_bbx_file_op_delete() {
        let op = BbxFileOperation::delete("old.rs");
        assert_eq!(op.display_text(), "Delete old.rs");
    }
}


// --- bby_: Editor keybinding model ---

/// Modifier keys.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct BbyModifiers {
    pub ctrl: bool,
    pub shift: bool,
    pub alt: bool,
    pub meta: bool,
}

impl BbyModifiers {
    pub fn none() -> Self { Self { ctrl: false, shift: false, alt: false, meta: false } }
    pub fn ctrl() -> Self { Self { ctrl: true, ..Self::none() } }
    pub fn ctrl_shift() -> Self { Self { ctrl: true, shift: true, ..Self::none() } }
    pub fn alt() -> Self { Self { alt: true, ..Self::none() } }

    pub fn display(&self) -> String {
        let mut parts = Vec::new();
        if self.ctrl { parts.push("Ctrl"); }
        if self.shift { parts.push("Shift"); }
        if self.alt { parts.push("Alt"); }
        if self.meta { parts.push("Meta"); }
        parts.join("+")
    }

    pub fn has_any(&self) -> bool { self.ctrl || self.shift || self.alt || self.meta }
}

/// A key chord (modifier + key).
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub struct BbyKeyChord {
    pub modifiers: BbyModifiers,
    pub key: String,
}

impl BbyKeyChord {
    pub fn new(mods: BbyModifiers, key: &str) -> Self {
        Self { modifiers: mods, key: key.to_string() }
    }

    pub fn simple(key: &str) -> Self { Self::new(BbyModifiers::none(), key) }

    pub fn display(&self) -> String {
        if self.modifiers.has_any() {
            format!("{}+{}", self.modifiers.display(), self.key)
        } else {
            self.key.clone()
        }
    }
}

/// A keybinding (one or two chords).
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub struct BbyKeybinding {
    pub first: BbyKeyChord,
    pub second: Option<BbyKeyChord>,
}

impl BbyKeybinding {
    pub fn single(chord: BbyKeyChord) -> Self { Self { first: chord, second: None } }
    pub fn two_part(first: BbyKeyChord, second: BbyKeyChord) -> Self {
        Self { first, second: Some(second) }
    }

    pub fn is_chord(&self) -> bool { self.second.is_some() }

    pub fn display(&self) -> String {
        match &self.second {
            Some(s) => format!("{} {}", self.first.display(), s.display()),
            None => self.first.display(),
        }
    }
}

/// A keybinding rule.
#[derive(Debug, Clone)]
pub struct BbyKeybindingRule {
    pub keybinding: BbyKeybinding,
    pub command: String,
    pub when: Option<String>,
    pub args: Option<String>,
    pub source: BbyKeybindingSource,
}

/// Source of a keybinding.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BbyKeybindingSource { Default, User, Extension }

impl BbyKeybindingRule {
    pub fn new(kb: BbyKeybinding, command: &str) -> Self {
        Self { keybinding: kb, command: command.to_string(), when: None, args: None, source: BbyKeybindingSource::Default }
    }

    pub fn with_when(mut self, w: &str) -> Self { self.when = Some(w.to_string()); self }
    pub fn from_user(mut self) -> Self { self.source = BbyKeybindingSource::User; self }

    pub fn matches_key(&self, chord: &BbyKeyChord) -> bool {
        self.keybinding.first == *chord && self.keybinding.second.is_none()
    }
}

/// The keybinding resolver.
#[derive(Debug)]
pub struct BbyKeybindingResolver {
    rules: Vec<BbyKeybindingRule>,
    pending_chord: Option<BbyKeyChord>,
}

impl BbyKeybindingResolver {
    pub fn new() -> Self { Self { rules: Vec::new(), pending_chord: None } }

    pub fn add_rule(&mut self, rule: BbyKeybindingRule) { self.rules.push(rule); }
    pub fn rule_count(&self) -> usize { self.rules.len() }

    pub fn resolve(&mut self, chord: &BbyKeyChord) -> Option<String> {
        if let Some(first) = &self.pending_chord {
            // Two-chord resolution
            for rule in self.rules.iter().rev() {
                if rule.keybinding.first == *first {
                    if let Some(second) = &rule.keybinding.second {
                        if second == chord {
                            self.pending_chord = None;
                            return Some(rule.command.clone());
                        }
                    }
                }
            }
            self.pending_chord = None;
            return None;
        }

        // Check for chord starters
        let has_chord = self.rules.iter().any(|r| r.keybinding.first == *chord && r.keybinding.second.is_some());
        if has_chord {
            self.pending_chord = Some(chord.clone());
            return None; // Wait for second chord
        }

        // Single chord resolution (last match wins — user overrides default)
        self.rules.iter().rev().find(|r| r.matches_key(chord)).map(|r| r.command.clone())
    }

    pub fn is_waiting_chord(&self) -> bool { self.pending_chord.is_some() }
    pub fn cancel_chord(&mut self) { self.pending_chord = None; }

    pub fn bindings_for_command(&self, cmd: &str) -> Vec<&BbyKeybinding> {
        self.rules.iter().filter(|r| r.command == cmd).map(|r| &r.keybinding).collect()
    }

    pub fn search(&self, query: &str) -> Vec<&BbyKeybindingRule> {
        let ql = query.to_lowercase();
        self.rules.iter().filter(|r| {
            r.command.to_lowercase().contains(&ql) || r.keybinding.display().to_lowercase().contains(&ql)
        }).collect()
    }
}

#[cfg(test)]
mod bby_tests {
    use super::*;

    #[test]
    fn test_bby_modifiers() {
        let m = BbyModifiers::ctrl_shift();
        assert_eq!(m.display(), "Ctrl+Shift");
        assert!(m.has_any());
        assert!(!BbyModifiers::none().has_any());
    }

    #[test]
    fn test_bby_chord() {
        let c = BbyKeyChord::new(BbyModifiers::ctrl(), "S");
        assert_eq!(c.display(), "Ctrl+S");
    }

    #[test]
    fn test_bby_keybinding_single() {
        let kb = BbyKeybinding::single(BbyKeyChord::new(BbyModifiers::ctrl(), "P"));
        assert!(!kb.is_chord());
        assert_eq!(kb.display(), "Ctrl+P");
    }

    #[test]
    fn test_bby_keybinding_two_part() {
        let kb = BbyKeybinding::two_part(
            BbyKeyChord::new(BbyModifiers::ctrl(), "K"),
            BbyKeyChord::new(BbyModifiers::ctrl(), "S"),
        );
        assert!(kb.is_chord());
        assert_eq!(kb.display(), "Ctrl+K Ctrl+S");
    }

    #[test]
    fn test_bby_resolve_single() {
        let mut r = BbyKeybindingResolver::new();
        r.add_rule(BbyKeybindingRule::new(
            BbyKeybinding::single(BbyKeyChord::new(BbyModifiers::ctrl(), "S")),
            "workbench.action.files.save"
        ));
        let cmd = r.resolve(&BbyKeyChord::new(BbyModifiers::ctrl(), "S"));
        assert_eq!(cmd, Some("workbench.action.files.save".to_string()));
    }

    #[test]
    fn test_bby_resolve_two_part() {
        let mut r = BbyKeybindingResolver::new();
        r.add_rule(BbyKeybindingRule::new(
            BbyKeybinding::two_part(
                BbyKeyChord::new(BbyModifiers::ctrl(), "K"),
                BbyKeyChord::new(BbyModifiers::ctrl(), "S"),
            ),
            "workbench.action.keybindings"
        ));
        // First chord — returns None, waiting
        let cmd = r.resolve(&BbyKeyChord::new(BbyModifiers::ctrl(), "K"));
        assert!(cmd.is_none());
        assert!(r.is_waiting_chord());
        // Second chord — resolves
        let cmd = r.resolve(&BbyKeyChord::new(BbyModifiers::ctrl(), "S"));
        assert_eq!(cmd, Some("workbench.action.keybindings".to_string()));
    }

    #[test]
    fn test_bby_user_override() {
        let mut r = BbyKeybindingResolver::new();
        r.add_rule(BbyKeybindingRule::new(
            BbyKeybinding::single(BbyKeyChord::new(BbyModifiers::ctrl(), "S")),
            "default.save"
        ));
        r.add_rule(BbyKeybindingRule::new(
            BbyKeybinding::single(BbyKeyChord::new(BbyModifiers::ctrl(), "S")),
            "custom.save"
        ).from_user());
        let cmd = r.resolve(&BbyKeyChord::new(BbyModifiers::ctrl(), "S"));
        assert_eq!(cmd, Some("custom.save".to_string())); // User wins
    }

    #[test]
    fn test_bby_bindings_for_command() {
        let mut r = BbyKeybindingResolver::new();
        r.add_rule(BbyKeybindingRule::new(
            BbyKeybinding::single(BbyKeyChord::new(BbyModifiers::ctrl(), "S")),
            "save"
        ));
        assert_eq!(r.bindings_for_command("save").len(), 1);
    }

    #[test]
    fn test_bby_search() {
        let mut r = BbyKeybindingResolver::new();
        r.add_rule(BbyKeybindingRule::new(
            BbyKeybinding::single(BbyKeyChord::new(BbyModifiers::ctrl(), "P")),
            "workbench.quickOpen"
        ));
        assert_eq!(r.search("quickOpen").len(), 1);
    }

    #[test]
    fn test_bby_cancel_chord() {
        let mut r = BbyKeybindingResolver::new();
        r.add_rule(BbyKeybindingRule::new(
            BbyKeybinding::two_part(
                BbyKeyChord::new(BbyModifiers::ctrl(), "K"),
                BbyKeyChord::new(BbyModifiers::ctrl(), "S"),
            ),
            "x"
        ));
        r.resolve(&BbyKeyChord::new(BbyModifiers::ctrl(), "K"));
        r.cancel_chord();
        assert!(!r.is_waiting_chord());
    }
}


// --- bbz_: Editor status bar model ---

/// Status bar alignment.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum BbzAlignment { Left, Right }

/// Priority for status bar items (higher = further left/right).
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub struct BbzPriority(pub i32);

/// A status bar item.
#[derive(Debug, Clone)]
pub struct BbzStatusItem {
    pub id: String,
    pub text: String,
    pub tooltip: Option<String>,
    pub command: Option<String>,
    pub alignment: BbzAlignment,
    pub priority: BbzPriority,
    pub visible: bool,
    pub color: Option<String>,
    pub background_color: Option<String>,
}

impl BbzStatusItem {
    pub fn new(id: &str, text: &str, align: BbzAlignment, priority: i32) -> Self {
        Self {
            id: id.to_string(), text: text.to_string(),
            tooltip: None, command: None, alignment: align,
            priority: BbzPriority(priority), visible: true,
            color: None, background_color: None,
        }
    }

    pub fn left(id: &str, text: &str, priority: i32) -> Self {
        Self::new(id, text, BbzAlignment::Left, priority)
    }

    pub fn right(id: &str, text: &str, priority: i32) -> Self {
        Self::new(id, text, BbzAlignment::Right, priority)
    }

    pub fn with_tooltip(mut self, t: &str) -> Self { self.tooltip = Some(t.to_string()); self }
    pub fn with_command(mut self, c: &str) -> Self { self.command = Some(c.to_string()); self }
    pub fn with_color(mut self, c: &str) -> Self { self.color = Some(c.to_string()); self }

    pub fn set_text(&mut self, text: &str) { self.text = text.to_string(); }
    pub fn show(&mut self) { self.visible = true; }
    pub fn hide(&mut self) { self.visible = false; }
    pub fn is_clickable(&self) -> bool { self.command.is_some() }

    pub fn display_width(&self) -> usize { self.text.chars().count() + 2 } // padding
}

/// The status bar model.
#[derive(Debug)]
pub struct BbzStatusBar {
    items: Vec<BbzStatusItem>,
    background_color: Option<String>,
}

impl BbzStatusBar {
    pub fn new() -> Self { Self { items: Vec::new(), background_color: None } }

    pub fn add_item(&mut self, item: BbzStatusItem) { self.items.push(item); }

    pub fn remove_item(&mut self, id: &str) { self.items.retain(|i| i.id != id); }

    pub fn find_item(&self, id: &str) -> Option<&BbzStatusItem> {
        self.items.iter().find(|i| i.id == id)
    }

    pub fn find_item_mut(&mut self, id: &str) -> Option<&mut BbzStatusItem> {
        self.items.iter_mut().find(|i| i.id == id)
    }

    pub fn update_text(&mut self, id: &str, text: &str) {
        if let Some(item) = self.find_item_mut(id) { item.set_text(text); }
    }

    pub fn left_items(&self) -> Vec<&BbzStatusItem> {
        let mut items: Vec<_> = self.items.iter()
            .filter(|i| i.alignment == BbzAlignment::Left && i.visible)
            .collect();
        items.sort_by(|a, b| b.priority.cmp(&a.priority));
        items
    }

    pub fn right_items(&self) -> Vec<&BbzStatusItem> {
        let mut items: Vec<_> = self.items.iter()
            .filter(|i| i.alignment == BbzAlignment::Right && i.visible)
            .collect();
        items.sort_by(|a, b| b.priority.cmp(&a.priority));
        items
    }

    pub fn item_count(&self) -> usize { self.items.len() }
    pub fn visible_count(&self) -> usize { self.items.iter().filter(|i| i.visible).count() }

    pub fn item_at_col(&self, col: usize, total_width: usize) -> Option<&BbzStatusItem> {
        let mut offset = 0;
        for item in self.left_items() {
            let w = item.display_width();
            if col >= offset && col < offset + w { return Some(item); }
            offset += w;
        }
        let mut right_offset = total_width;
        for item in self.right_items() {
            let w = item.display_width();
            right_offset -= w;
            if col >= right_offset && col < right_offset + w { return Some(item); }
        }
        None
    }

    pub fn set_background(&mut self, color: Option<String>) { self.background_color = color; }

    pub fn render_line(&self, width: usize) -> String {
        let left: String = self.left_items().iter().map(|i| format!(" {} ", i.text)).collect();
        let right: String = self.right_items().iter().map(|i| format!(" {} ", i.text)).collect();
        let gap = width.saturating_sub(left.len() + right.len());
        format!("{}{}{}", left, " ".repeat(gap), right)
    }
}

