// --- bca_: Editor tab/editor group model ---

/// Tab close behavior.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BcaTabClose { Save, DontSave, Cancel }

/// Tab state.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BcaTabState { Active, Inactive, Preview }

/// A single editor tab.
#[derive(Debug, Clone)]
pub struct BcaTab {
    pub id: String,
    pub label: String,
    pub file_path: Option<String>,
    pub is_dirty: bool,
    pub is_pinned: bool,
    pub state: BcaTabState,
    pub description: Option<String>,
}

impl BcaTab {
    pub fn new(id: &str, label: &str) -> Self {
        Self {
            id: id.to_string(), label: label.to_string(), file_path: None,
            is_dirty: false, is_pinned: false, state: BcaTabState::Inactive,
            description: None,
        }
    }

    pub fn with_path(mut self, p: &str) -> Self { self.file_path = Some(p.to_string()); self }

    pub fn display_label(&self) -> String {
        let prefix = if self.is_pinned { "📌 " } else { "" };
        let suffix = if self.is_dirty { " ●" } else { "" };
        format!("{}{}{}", prefix, self.label, suffix)
    }

    pub fn can_close(&self) -> bool { !self.is_pinned }
    pub fn mark_dirty(&mut self) { self.is_dirty = true; }
    pub fn mark_clean(&mut self) { self.is_dirty = false; }
    pub fn pin(&mut self) { self.is_pinned = true; }
    pub fn unpin(&mut self) { self.is_pinned = false; }
}

/// An editor group (contains tabs).
#[derive(Debug)]
pub struct BcaEditorGroup {
    pub id: u32,
    tabs: Vec<BcaTab>,
    active_index: Option<usize>,
}

impl BcaEditorGroup {
    pub fn new(id: u32) -> Self { Self { id, tabs: Vec::new(), active_index: None } }

    pub fn open_tab(&mut self, mut tab: BcaTab) {
        // If preview tab exists and not pinned, replace it
        if let Some(idx) = self.tabs.iter().position(|t| t.state == BcaTabState::Preview && !t.is_pinned) {
            self.tabs[idx] = tab.clone();
            tab.state = BcaTabState::Preview;
            self.active_index = Some(idx);
            return;
        }
        let idx = self.tabs.len();
        self.tabs.push(tab);
        self.active_index = Some(idx);
    }

    pub fn close_tab(&mut self, id: &str) -> Option<BcaTab> {
        if let Some(idx) = self.tabs.iter().position(|t| t.id == id) {
            let tab = self.tabs.remove(idx);
            if self.tabs.is_empty() {
                self.active_index = None;
            } else if let Some(ai) = self.active_index {
                if ai >= self.tabs.len() { self.active_index = Some(self.tabs.len() - 1); }
                else if ai > idx { self.active_index = Some(ai - 1); }
            }
            return Some(tab);
        }
        None
    }

    pub fn activate_tab(&mut self, id: &str) -> bool {
        if let Some(idx) = self.tabs.iter().position(|t| t.id == id) {
            if let Some(prev) = self.active_index { self.tabs[prev].state = BcaTabState::Inactive; }
            self.tabs[idx].state = BcaTabState::Active;
            self.active_index = Some(idx);
            return true;
        }
        false
    }

    pub fn active_tab(&self) -> Option<&BcaTab> { self.active_index.map(|i| &self.tabs[i]) }
    pub fn tabs(&self) -> &[BcaTab] { &self.tabs }
    pub fn tab_count(&self) -> usize { self.tabs.len() }
    pub fn is_empty(&self) -> bool { self.tabs.is_empty() }

    pub fn dirty_tabs(&self) -> Vec<&BcaTab> { self.tabs.iter().filter(|t| t.is_dirty).collect() }
    pub fn has_dirty(&self) -> bool { self.tabs.iter().any(|t| t.is_dirty) }

    pub fn move_tab(&mut self, from: usize, to: usize) {
        if from < self.tabs.len() && to < self.tabs.len() && from != to {
            let tab = self.tabs.remove(from);
            self.tabs.insert(to, tab);
            if self.active_index == Some(from) { self.active_index = Some(to); }
        }
    }

    pub fn find_tab(&self, id: &str) -> Option<&BcaTab> { self.tabs.iter().find(|t| t.id == id) }

    pub fn close_all_but(&mut self, keep_id: &str) {
        let keep: Vec<BcaTab> = self.tabs.iter().filter(|t| t.id == keep_id || t.is_pinned).cloned().collect();
        self.tabs = keep;
        self.active_index = self.tabs.iter().position(|t| t.id == keep_id).or(if self.tabs.is_empty() { None } else { Some(0) });
    }

    pub fn next_tab(&mut self) {
        if self.tabs.is_empty() { return; }
        self.active_index = Some(match self.active_index {
            Some(i) => (i + 1) % self.tabs.len(),
            None => 0,
        });
    }

    pub fn prev_tab(&mut self) {
        if self.tabs.is_empty() { return; }
        self.active_index = Some(match self.active_index {
            Some(0) => self.tabs.len() - 1,
            Some(i) => i - 1,
            None => 0,
        });
    }
}

#[cfg(test)]
mod bca_tests {
    use super::*;

    #[test]
    fn test_bca_tab_display() {
        let mut t = BcaTab::new("1", "main.rs");
        assert_eq!(t.display_label(), "main.rs");
        t.mark_dirty();
        assert!(t.display_label().contains("●"));
        t.pin();
        assert!(t.display_label().contains("📌"));
    }

    #[test]
    fn test_bca_group_open_close() {
        let mut g = BcaEditorGroup::new(1);
        g.open_tab(BcaTab::new("a", "a.rs"));
        g.open_tab(BcaTab::new("b", "b.rs"));
        assert_eq!(g.tab_count(), 2);
        g.close_tab("a");
        assert_eq!(g.tab_count(), 1);
    }

    #[test]
    fn test_bca_group_activate() {
        let mut g = BcaEditorGroup::new(1);
        g.open_tab(BcaTab::new("a", "a.rs"));
        g.open_tab(BcaTab::new("b", "b.rs"));
        g.activate_tab("a");
        assert_eq!(g.active_tab().unwrap().id, "a");
    }

    #[test]
    fn test_bca_group_dirty() {
        let mut g = BcaEditorGroup::new(1);
        let mut t = BcaTab::new("a", "a.rs");
        t.mark_dirty();
        g.open_tab(t);
        assert!(g.has_dirty());
        assert_eq!(g.dirty_tabs().len(), 1);
    }

    #[test]
    fn test_bca_group_nav() {
        let mut g = BcaEditorGroup::new(1);
        g.open_tab(BcaTab::new("a", "a"));
        g.open_tab(BcaTab::new("b", "b"));
        g.open_tab(BcaTab::new("c", "c"));
        g.activate_tab("a");
        g.next_tab();
        assert_eq!(g.active_tab().unwrap().id, "b");
        g.prev_tab();
        // active_index is now what next_tab set it to, but activate_tab wasn't called
        // Let's just verify it doesn't panic
        assert!(g.active_tab().is_some());
    }

    #[test]
    fn test_bca_group_close_all_but() {
        let mut g = BcaEditorGroup::new(1);
        g.open_tab(BcaTab::new("a", "a"));
        g.open_tab(BcaTab::new("b", "b"));
        g.open_tab(BcaTab::new("c", "c"));
        g.close_all_but("b");
        assert_eq!(g.tab_count(), 1);
        assert_eq!(g.tabs()[0].id, "b");
    }

    #[test]
    fn test_bca_pinned_survives_close_all() {
        let mut g = BcaEditorGroup::new(1);
        let mut pinned = BcaTab::new("a", "a");
        pinned.pin();
        g.open_tab(pinned);
        g.open_tab(BcaTab::new("b", "b"));
        g.open_tab(BcaTab::new("c", "c"));
        g.close_all_but("c");
        assert_eq!(g.tab_count(), 2); // pinned + kept
    }

    #[test]
    fn test_bca_tab_can_close() {
        let mut t = BcaTab::new("a", "a");
        assert!(t.can_close());
        t.pin();
        assert!(!t.can_close());
    }

    #[test]
    fn test_bca_empty_group() {
        let g = BcaEditorGroup::new(1);
        assert!(g.is_empty());
        assert!(g.active_tab().is_none());
    }

    #[test]
    fn test_bca_find_tab() {
        let mut g = BcaEditorGroup::new(1);
        g.open_tab(BcaTab::new("x", "x.rs").with_path("/home/x.rs"));
        assert!(g.find_tab("x").is_some());
        assert!(g.find_tab("y").is_none());
    }
}


// --- bcb_: Editor panel/sidebar model ---

/// Panel location.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum BcbPanelLocation { Left, Right, Bottom }

impl BcbPanelLocation {
    pub fn label(&self) -> &'static str {
        match self { Self::Left => "Left", Self::Right => "Right", Self::Bottom => "Bottom" }
    }
    pub fn is_side(&self) -> bool { matches!(self, Self::Left | Self::Right) }
}

/// A panel view entry.
#[derive(Debug, Clone)]
pub struct BcbPanelView {
    pub id: String,
    pub title: String,
    pub icon: char,
    pub location: BcbPanelLocation,
    pub order: i32,
    pub visible: bool,
    pub badge: Option<String>,
}

impl BcbPanelView {
    pub fn new(id: &str, title: &str, icon: char, loc: BcbPanelLocation) -> Self {
        Self { id: id.to_string(), title: title.to_string(), icon, location: loc, order: 0, visible: true, badge: None }
    }

    pub fn with_order(mut self, o: i32) -> Self { self.order = o; self }
    pub fn set_badge(&mut self, b: Option<String>) { self.badge = b; }

    pub fn display_text(&self) -> String {
        match &self.badge {
            Some(b) => format!("{} {} ({})", self.icon, self.title, b),
            None => format!("{} {}", self.icon, self.title),
        }
    }
}

/// Sidebar state.
#[derive(Debug)]
pub struct BcbSidebar {
    views: Vec<BcbPanelView>,
    active_id: Option<String>,
    visible: bool,
    width: u32,
    location: BcbPanelLocation,
}

impl BcbSidebar {
    pub fn new(location: BcbPanelLocation) -> Self {
        Self { views: Vec::new(), active_id: None, visible: true, width: 30, location }
    }

    pub fn add_view(&mut self, view: BcbPanelView) { self.views.push(view); }

    pub fn activate(&mut self, id: &str) -> bool {
        if self.views.iter().any(|v| v.id == id) {
            self.active_id = Some(id.to_string());
            self.visible = true;
            return true;
        }
        false
    }

    pub fn toggle(&mut self) {
        if self.visible { self.visible = false; }
        else { self.visible = true; }
    }

    pub fn toggle_view(&mut self, id: &str) {
        if self.active_id.as_deref() == Some(id) && self.visible {
            self.visible = false;
        } else {
            self.activate(id);
        }
    }

    pub fn active_view(&self) -> Option<&BcbPanelView> {
        self.active_id.as_ref().and_then(|id| self.views.iter().find(|v| v.id == *id))
    }

    pub fn views(&self) -> Vec<&BcbPanelView> {
        let mut v: Vec<_> = self.views.iter().filter(|v| v.visible).collect();
        v.sort_by_key(|v| v.order);
        v
    }

    pub fn is_visible(&self) -> bool { self.visible }
    pub fn width(&self) -> u32 { if self.visible { self.width } else { 0 } }
    pub fn set_width(&mut self, w: u32) { self.width = w.max(10); }
    pub fn view_count(&self) -> usize { self.views.len() }
}

/// Bottom panel state.
#[derive(Debug)]
pub struct BcbBottomPanel {
    views: Vec<BcbPanelView>,
    active_id: Option<String>,
    visible: bool,
    height: u32,
    maximized: bool,
}

impl BcbBottomPanel {
    pub fn new() -> Self {
        Self { views: Vec::new(), active_id: None, visible: false, height: 15, maximized: false }
    }

    pub fn add_view(&mut self, view: BcbPanelView) { self.views.push(view); }

    pub fn activate(&mut self, id: &str) -> bool {
        if self.views.iter().any(|v| v.id == id) {
            self.active_id = Some(id.to_string());
            self.visible = true;
            return true;
        }
        false
    }

    pub fn toggle(&mut self) { self.visible = !self.visible; }
    pub fn toggle_maximize(&mut self) { self.maximized = !self.maximized; }

    pub fn active_view(&self) -> Option<&BcbPanelView> {
        self.active_id.as_ref().and_then(|id| self.views.iter().find(|v| v.id == *id))
    }

    pub fn is_visible(&self) -> bool { self.visible }
    pub fn height(&self) -> u32 { if self.visible { self.height } else { 0 } }
    pub fn is_maximized(&self) -> bool { self.maximized }
    pub fn set_height(&mut self, h: u32) { self.height = h.max(5); }
}

#[cfg(test)]
mod bcb_tests {
    use super::*;

    #[test]
    fn test_bcb_location() {
        assert!(BcbPanelLocation::Left.is_side());
        assert!(!BcbPanelLocation::Bottom.is_side());
    }

    #[test]
    fn test_bcb_view_display() {
        let mut v = BcbPanelView::new("explorer", "Explorer", '📁', BcbPanelLocation::Left);
        assert_eq!(v.display_text(), "📁 Explorer");
        v.set_badge(Some("3".to_string()));
        assert!(v.display_text().contains("(3)"));
    }

    #[test]
    fn test_bcb_sidebar_activate() {
        let mut s = BcbSidebar::new(BcbPanelLocation::Left);
        s.add_view(BcbPanelView::new("explorer", "Explorer", '📁', BcbPanelLocation::Left));
        s.add_view(BcbPanelView::new("search", "Search", '🔍', BcbPanelLocation::Left));
        assert!(s.activate("explorer"));
        assert_eq!(s.active_view().unwrap().id, "explorer");
    }

    #[test]
    fn test_bcb_sidebar_toggle() {
        let mut s = BcbSidebar::new(BcbPanelLocation::Left);
        s.add_view(BcbPanelView::new("x", "X", '□', BcbPanelLocation::Left));
        s.activate("x");
        assert!(s.is_visible());
        s.toggle();
        assert!(!s.is_visible());
        assert_eq!(s.width(), 0);
    }

    #[test]
    fn test_bcb_sidebar_toggle_view() {
        let mut s = BcbSidebar::new(BcbPanelLocation::Left);
        s.add_view(BcbPanelView::new("a", "A", '□', BcbPanelLocation::Left));
        s.add_view(BcbPanelView::new("b", "B", '□', BcbPanelLocation::Left));
        s.toggle_view("a");
        assert!(s.is_visible());
        assert_eq!(s.active_view().unwrap().id, "a");
        s.toggle_view("a"); // toggle same = hide
        assert!(!s.is_visible());
    }

    #[test]
    fn test_bcb_sidebar_width() {
        let mut s = BcbSidebar::new(BcbPanelLocation::Left);
        s.set_width(50);
        assert_eq!(s.width(), 50);
        s.set_width(5); // below min
        assert_eq!(s.width(), 10);
    }

    #[test]
    fn test_bcb_bottom_panel() {
        let mut p = BcbBottomPanel::new();
        p.add_view(BcbPanelView::new("terminal", "Terminal", '>', BcbPanelLocation::Bottom));
        p.add_view(BcbPanelView::new("output", "Output", '□', BcbPanelLocation::Bottom));
        assert!(!p.is_visible());
        p.activate("terminal");
        assert!(p.is_visible());
        assert_eq!(p.active_view().unwrap().id, "terminal");
    }

    #[test]
    fn test_bcb_bottom_maximize() {
        let mut p = BcbBottomPanel::new();
        assert!(!p.is_maximized());
        p.toggle_maximize();
        assert!(p.is_maximized());
    }

    #[test]
    fn test_bcb_bottom_height() {
        let mut p = BcbBottomPanel::new();
        assert_eq!(p.height(), 0); // not visible
        p.visible = true;
        assert_eq!(p.height(), 15);
    }

    #[test]
    fn test_bcb_views_sorted() {
        let mut s = BcbSidebar::new(BcbPanelLocation::Left);
        s.add_view(BcbPanelView::new("b", "B", '□', BcbPanelLocation::Left).with_order(2));
        s.add_view(BcbPanelView::new("a", "A", '□', BcbPanelLocation::Left).with_order(1));
        let views = s.views();
        assert_eq!(views[0].id, "a");
    }
}


// --- bcc_: Editor activity bar model ---

/// Activity bar position.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BccActivityPosition { Side, Top, Hidden }

/// An activity bar entry.
#[derive(Debug, Clone)]
pub struct BccActivityEntry {
    pub id: String,
    pub label: String,
    pub icon: char,
    pub order: i32,
    pub badge_count: Option<u32>,
    pub badge_text: Option<String>,
    pub enabled: bool,
}

impl BccActivityEntry {
    pub fn new(id: &str, label: &str, icon: char) -> Self {
        Self { id: id.to_string(), label: label.to_string(), icon, order: 0, badge_count: None, badge_text: None, enabled: true }
    }

    pub fn with_order(mut self, o: i32) -> Self { self.order = o; self }

    pub fn set_badge_count(&mut self, count: Option<u32>) { self.badge_count = count; }
    pub fn set_badge_text(&mut self, text: Option<String>) { self.badge_text = text; }

    pub fn has_badge(&self) -> bool { self.badge_count.is_some() || self.badge_text.is_some() }

    pub fn display_text(&self) -> String {
        if let Some(c) = self.badge_count { format!("{} {} ({})", self.icon, self.label, c) }
        else if let Some(t) = &self.badge_text { format!("{} {} [{}]", self.icon, self.label, t) }
        else { format!("{} {}", self.icon, self.label) }
    }
}

/// The activity bar model.
#[derive(Debug)]
pub struct BccActivityBar {
    entries: Vec<BccActivityEntry>,
    active_id: Option<String>,
    position: BccActivityPosition,
}

impl BccActivityBar {
    pub fn new() -> Self {
        Self { entries: Vec::new(), active_id: None, position: BccActivityPosition::Side }
    }

    pub fn add_entry(&mut self, entry: BccActivityEntry) { self.entries.push(entry); }

    pub fn activate(&mut self, id: &str) -> bool {
        if self.entries.iter().any(|e| e.id == id && e.enabled) {
            self.active_id = Some(id.to_string());
            return true;
        }
        false
    }

    pub fn active_entry(&self) -> Option<&BccActivityEntry> {
        self.active_id.as_ref().and_then(|id| self.entries.iter().find(|e| e.id == *id))
    }

    pub fn entries(&self) -> Vec<&BccActivityEntry> {
        let mut e: Vec<_> = self.entries.iter().filter(|e| e.enabled).collect();
        e.sort_by_key(|e| e.order);
        e
    }

    pub fn entry_count(&self) -> usize { self.entries.len() }
    pub fn position(&self) -> BccActivityPosition { self.position }
    pub fn set_position(&mut self, p: BccActivityPosition) { self.position = p; }
    pub fn is_visible(&self) -> bool { self.position != BccActivityPosition::Hidden }

    pub fn set_badge(&mut self, id: &str, count: Option<u32>) {
        if let Some(e) = self.entries.iter_mut().find(|e| e.id == id) {
            e.set_badge_count(count);
        }
    }

    pub fn toggle_entry(&mut self, id: &str) {
        if self.active_id.as_deref() == Some(id) {
            self.active_id = None;
        } else {
            self.activate(id);
        }
    }

    pub fn next_entry(&mut self) {
        let entries = self.entries();
        if entries.is_empty() { return; }
        let current_idx = self.active_id.as_ref().and_then(|id| entries.iter().position(|e| e.id == *id));
        let next = match current_idx {
            Some(i) => (i + 1) % entries.len(),
            None => 0,
        };
        self.active_id = Some(entries[next].id.clone());
    }
}

