// --- bdd_: Editor inline chat / AI assistant model ---

/// Chat message role.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BddChatRole { User, Assistant, System }

/// A chat message.
#[derive(Debug, Clone)]
pub struct BddChatMessage {
    pub role: BddChatRole,
    pub content: String,
    pub timestamp: u64,
}

impl BddChatMessage {
    pub fn user(content: &str) -> Self { Self { role: BddChatRole::User, content: content.to_string(), timestamp: 0 } }
    pub fn assistant(content: &str) -> Self { Self { role: BddChatRole::Assistant, content: content.to_string(), timestamp: 0 } }
    pub fn system(content: &str) -> Self { Self { role: BddChatRole::System, content: content.to_string(), timestamp: 0 } }

    pub fn is_user(&self) -> bool { self.role == BddChatRole::User }
    pub fn is_assistant(&self) -> bool { self.role == BddChatRole::Assistant }

    pub fn render_prefix(&self) -> &str {
        match self.role { BddChatRole::User => "You: ", BddChatRole::Assistant => "AI: ", BddChatRole::System => "Sys: " }
    }
}

/// An inline chat session state.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BddInlineState { Idle, Waiting, Streaming, Done, Error }

/// Inline chat widget model.
#[derive(Debug)]
pub struct BddInlineChat {
    pub file: String,
    pub line: u32,
    pub prompt: String,
    pub response: String,
    pub state: BddInlineState,
    pub accepted: bool,
}

impl BddInlineChat {
    pub fn new(file: &str, line: u32) -> Self {
        Self { file: file.to_string(), line, prompt: String::new(), response: String::new(), state: BddInlineState::Idle, accepted: false }
    }

    pub fn set_prompt(&mut self, p: &str) { self.prompt = p.to_string(); }
    pub fn submit(&mut self) { self.state = BddInlineState::Waiting; }
    pub fn stream_chunk(&mut self, chunk: &str) { self.response.push_str(chunk); self.state = BddInlineState::Streaming; }
    pub fn finish(&mut self) { self.state = BddInlineState::Done; }
    pub fn set_error(&mut self) { self.state = BddInlineState::Error; }
    pub fn accept(&mut self) { self.accepted = true; }
    pub fn discard(&mut self) { self.response.clear(); self.state = BddInlineState::Idle; }
}

/// The chat panel model.
#[derive(Debug)]
pub struct BddChatPanel {
    messages: Vec<BddChatMessage>,
    input: String,
    streaming: bool,
    title: String,
    participants: Vec<String>,
}

impl BddChatPanel {
    pub fn new() -> Self {
        Self { messages: Vec::new(), input: String::new(), streaming: false, title: "Chat".to_string(), participants: vec!["copilot".to_string()] }
    }

    pub fn add_message(&mut self, msg: BddChatMessage) { self.messages.push(msg); }

    pub fn submit_input(&mut self) -> Option<String> {
        if self.input.is_empty() { return None; }
        let text = self.input.clone();
        self.add_message(BddChatMessage::user(&text));
        self.input.clear();
        self.streaming = true;
        Some(text)
    }

    pub fn stream_response(&mut self, chunk: &str) {
        if let Some(last) = self.messages.last_mut() {
            if last.is_assistant() { last.content.push_str(chunk); return; }
        }
        self.messages.push(BddChatMessage::assistant(chunk));
    }

    pub fn finish_stream(&mut self) { self.streaming = false; }
    pub fn is_streaming(&self) -> bool { self.streaming }

    pub fn set_input(&mut self, text: &str) { self.input = text.to_string(); }
    pub fn input(&self) -> &str { &self.input }
    pub fn messages(&self) -> &[BddChatMessage] { &self.messages }
    pub fn message_count(&self) -> usize { self.messages.len() }
    pub fn clear(&mut self) { self.messages.clear(); }

    pub fn add_participant(&mut self, name: &str) { self.participants.push(name.to_string()); }
    pub fn participants(&self) -> &[String] { &self.participants }
}

#[cfg(test)]
mod bdd_tests {
    use super::*;

    #[test]
    fn test_bdd_message() {
        let m = BddChatMessage::user("Hello");
        assert!(m.is_user());
        assert_eq!(m.render_prefix(), "You: ");
    }

    #[test]
    fn test_bdd_assistant() {
        let m = BddChatMessage::assistant("Here's the fix");
        assert!(m.is_assistant());
    }

    #[test]
    fn test_bdd_inline_chat() {
        let mut ic = BddInlineChat::new("main.rs", 10);
        ic.set_prompt("Fix this function");
        ic.submit();
        assert_eq!(ic.state, BddInlineState::Waiting);
    }

    #[test]
    fn test_bdd_inline_stream() {
        let mut ic = BddInlineChat::new("lib.rs", 5);
        ic.stream_chunk("fn ");
        ic.stream_chunk("fixed()");
        assert_eq!(ic.response, "fn fixed()");
        assert_eq!(ic.state, BddInlineState::Streaming);
    }

    #[test]
    fn test_bdd_inline_accept() {
        let mut ic = BddInlineChat::new("a.rs", 1);
        ic.stream_chunk("code");
        ic.finish();
        ic.accept();
        assert!(ic.accepted);
    }

    #[test]
    fn test_bdd_inline_discard() {
        let mut ic = BddInlineChat::new("a.rs", 1);
        ic.stream_chunk("code");
        ic.discard();
        assert!(ic.response.is_empty());
    }

    #[test]
    fn test_bdd_panel() {
        let mut p = BddChatPanel::new();
        p.set_input("How do I fix this?");
        let q = p.submit_input().unwrap();
        assert_eq!(q, "How do I fix this?");
        assert!(p.is_streaming());
    }

    #[test]
    fn test_bdd_panel_stream() {
        let mut p = BddChatPanel::new();
        p.add_message(BddChatMessage::user("q"));
        p.stream_response("part1 ");
        p.stream_response("part2");
        p.finish_stream();
        assert_eq!(p.messages().last().unwrap().content, "part1 part2");
    }

    #[test]
    fn test_bdd_panel_clear() {
        let mut p = BddChatPanel::new();
        p.add_message(BddChatMessage::user("x"));
        p.clear();
        assert_eq!(p.message_count(), 0);
    }

    #[test]
    fn test_bdd_participants() {
        let mut p = BddChatPanel::new();
        p.add_participant("workspace");
        assert_eq!(p.participants().len(), 2);
    }
}


// --- bde_: Editor multi-cursor editing model ---

/// A cursor position.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct BdeCursorPos { pub line: u32, pub col: u32 }

impl BdeCursorPos {
    pub fn new(line: u32, col: u32) -> Self { Self { line, col } }
}

impl PartialOrd for BdeCursorPos {
    fn partial_cmp(&self, other: &Self) -> Option<std::cmp::Ordering> { Some(self.cmp(other)) }
}

impl Ord for BdeCursorPos {
    fn cmp(&self, other: &Self) -> std::cmp::Ordering { self.line.cmp(&other.line).then(self.col.cmp(&other.col)) }
}

/// A selection range with anchor and active positions.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct BdeSelection {
    pub anchor: BdeCursorPos,
    pub active: BdeCursorPos,
}

impl BdeSelection {
    pub fn cursor(line: u32, col: u32) -> Self {
        let p = BdeCursorPos::new(line, col);
        Self { anchor: p, active: p }
    }

    pub fn range(anchor: BdeCursorPos, active: BdeCursorPos) -> Self { Self { anchor, active } }

    pub fn is_empty(&self) -> bool { self.anchor == self.active }
    pub fn is_reversed(&self) -> bool { self.active < self.anchor }

    pub fn start(&self) -> BdeCursorPos { if self.is_reversed() { self.active } else { self.anchor } }
    pub fn end(&self) -> BdeCursorPos { if self.is_reversed() { self.anchor } else { self.active } }

    pub fn contains(&self, pos: BdeCursorPos) -> bool { pos >= self.start() && pos <= self.end() }
}

/// Multi-cursor state.
#[derive(Debug)]
pub struct BdeMultiCursor {
    selections: Vec<BdeSelection>,
}

impl BdeMultiCursor {
    pub fn new() -> Self { Self { selections: vec![BdeSelection::cursor(0, 0)] } }

    pub fn from_cursor(line: u32, col: u32) -> Self { Self { selections: vec![BdeSelection::cursor(line, col)] } }

    pub fn primary(&self) -> &BdeSelection { &self.selections[self.selections.len() - 1] }

    pub fn selections(&self) -> &[BdeSelection] { &self.selections }
    pub fn count(&self) -> usize { self.selections.len() }

    pub fn add_cursor(&mut self, line: u32, col: u32) {
        let sel = BdeSelection::cursor(line, col);
        if !self.selections.contains(&sel) { self.selections.push(sel); }
    }

    pub fn add_selection(&mut self, sel: BdeSelection) {
        if !self.selections.contains(&sel) { self.selections.push(sel); }
    }

    pub fn add_cursor_above(&mut self) {
        let min_line = self.selections.iter().map(|s| s.active.line).min().unwrap_or(0);
        let col = self.selections.iter().find(|s| s.active.line == min_line).map(|s| s.active.col).unwrap_or(0);
        if min_line > 0 { self.add_cursor(min_line - 1, col); }
    }

    pub fn add_cursor_below(&mut self) {
        let max_line = self.selections.iter().map(|s| s.active.line).max().unwrap_or(0);
        let col = self.selections.iter().find(|s| s.active.line == max_line).map(|s| s.active.col).unwrap_or(0);
        self.add_cursor(max_line + 1, col);
    }

    pub fn collapse_to_primary(&mut self) {
        if let Some(last) = self.selections.last().cloned() {
            self.selections = vec![last];
        }
    }

    pub fn sort_selections(&mut self) {
        self.selections.sort_by_key(|s| s.start());
        self.selections.dedup();
    }

    pub fn move_all(&mut self, d_line: i32, d_col: i32) {
        for sel in &mut self.selections {
            sel.anchor.line = (sel.anchor.line as i32 + d_line).max(0) as u32;
            sel.anchor.col = (sel.anchor.col as i32 + d_col).max(0) as u32;
            sel.active.line = (sel.active.line as i32 + d_line).max(0) as u32;
            sel.active.col = (sel.active.col as i32 + d_col).max(0) as u32;
        }
    }

    pub fn has_multiple(&self) -> bool { self.selections.len() > 1 }
}

#[cfg(test)]
mod bde_tests {
    use super::*;

    #[test]
    fn test_bde_cursor_pos() {
        let a = BdeCursorPos::new(1, 5);
        let b = BdeCursorPos::new(1, 10);
        assert!(a < b);
    }

    #[test]
    fn test_bde_selection_empty() {
        let s = BdeSelection::cursor(0, 0);
        assert!(s.is_empty());
    }

    #[test]
    fn test_bde_selection_range() {
        let s = BdeSelection::range(BdeCursorPos::new(1, 0), BdeCursorPos::new(1, 5));
        assert!(!s.is_empty());
        assert!(s.contains(BdeCursorPos::new(1, 3)));
    }

    #[test]
    fn test_bde_selection_reversed() {
        let s = BdeSelection::range(BdeCursorPos::new(5, 0), BdeCursorPos::new(1, 0));
        assert!(s.is_reversed());
        assert_eq!(s.start().line, 1);
    }

    #[test]
    fn test_bde_multi_new() {
        let mc = BdeMultiCursor::new();
        assert_eq!(mc.count(), 1);
        assert!(!mc.has_multiple());
    }

    #[test]
    fn test_bde_add_cursor() {
        let mut mc = BdeMultiCursor::from_cursor(0, 0);
        mc.add_cursor(1, 0);
        mc.add_cursor(2, 0);
        assert_eq!(mc.count(), 3);
        assert!(mc.has_multiple());
    }

    #[test]
    fn test_bde_add_above_below() {
        let mut mc = BdeMultiCursor::from_cursor(5, 10);
        mc.add_cursor_above(); // adds 4,10
        mc.add_cursor_below(); // adds 6,10 (max is still 5)
        assert_eq!(mc.count(), 3);
    }

    #[test]
    fn test_bde_collapse() {
        let mut mc = BdeMultiCursor::from_cursor(0, 0);
        mc.add_cursor(1, 0);
        mc.collapse_to_primary();
        assert_eq!(mc.count(), 1);
    }

    #[test]
    fn test_bde_move_all() {
        let mut mc = BdeMultiCursor::from_cursor(5, 5);
        mc.add_cursor(10, 5);
        mc.move_all(0, 1);
        assert_eq!(mc.selections()[0].active.col, 6);
        assert_eq!(mc.selections()[1].active.col, 6);
    }

    #[test]
    fn test_bde_no_duplicate() {
        let mut mc = BdeMultiCursor::from_cursor(0, 0);
        mc.add_cursor(0, 0);
        assert_eq!(mc.count(), 1);
    }
}


// --- bdf_: Editor snippet insertion model ---

/// Snippet placeholder kind.
#[derive(Debug, Clone)]
pub enum BdfSnippetPart {
    Text(String),
    Tabstop(u32),
    Placeholder { index: u32, default: String },
    Choice { index: u32, options: Vec<String> },
    Variable { name: String, default: Option<String> },
    FinalTabstop,
}

/// A parsed snippet template.
#[derive(Debug)]
pub struct BdfSnippetTemplate {
    pub name: String,
    pub prefix: String,
    pub description: Option<String>,
    pub parts: Vec<BdfSnippetPart>,
    pub scope: Option<String>,
}

impl BdfSnippetTemplate {
    pub fn new(name: &str, prefix: &str, body: &str) -> Self {
        let parts = Self::parse_body(body);
        Self { name: name.to_string(), prefix: prefix.to_string(), description: None, parts, scope: None }
    }

    pub fn with_description(mut self, d: &str) -> Self { self.description = Some(d.to_string()); self }
    pub fn with_scope(mut self, s: &str) -> Self { self.scope = Some(s.to_string()); self }

    fn parse_body(body: &str) -> Vec<BdfSnippetPart> {
        // Simplified parser: just treat the whole body as text
        vec![BdfSnippetPart::Text(body.to_string())]
    }

    pub fn tabstop_count(&self) -> usize {
        self.parts.iter().filter(|p| matches!(p, BdfSnippetPart::Tabstop(_) | BdfSnippetPart::Placeholder { .. } | BdfSnippetPart::Choice { .. })).count()
    }

    pub fn expand(&self) -> String {
        self.parts.iter().map(|p| match p {
            BdfSnippetPart::Text(t) => t.clone(),
            BdfSnippetPart::Tabstop(_) | BdfSnippetPart::FinalTabstop => String::new(),
            BdfSnippetPart::Placeholder { default, .. } => default.clone(),
            BdfSnippetPart::Choice { options, .. } => options.first().cloned().unwrap_or_default(),
            BdfSnippetPart::Variable { default, .. } => default.clone().unwrap_or_default(),
        }).collect()
    }
}

/// Active snippet session during insertion.
#[derive(Debug)]
pub struct BdfSnippetSession {
    template: BdfSnippetTemplate,
    current_tabstop: u32,
    active: bool,
    values: Vec<(u32, String)>,
}

impl BdfSnippetSession {
    pub fn new(template: BdfSnippetTemplate) -> Self {
        Self { template, current_tabstop: 1, active: true, values: Vec::new() }
    }

    pub fn is_active(&self) -> bool { self.active }
    pub fn current_tabstop(&self) -> u32 { self.current_tabstop }

    pub fn next_tabstop(&mut self) -> bool {
        let max = self.template.tabstop_count() as u32;
        if self.current_tabstop < max { self.current_tabstop += 1; true }
        else { self.active = false; false }
    }

    pub fn prev_tabstop(&mut self) -> bool {
        if self.current_tabstop > 1 { self.current_tabstop -= 1; true }
        else { false }
    }

    pub fn set_value(&mut self, tabstop: u32, value: &str) {
        if let Some(v) = self.values.iter_mut().find(|(t, _)| *t == tabstop) { v.1 = value.to_string(); }
        else { self.values.push((tabstop, value.to_string())); }
    }

    pub fn finish(&mut self) { self.active = false; }
    pub fn cancel(&mut self) { self.active = false; self.values.clear(); }

    pub fn expanded_text(&self) -> String { self.template.expand() }
    pub fn template_name(&self) -> &str { &self.template.name }
}

#[cfg(test)]
mod bdf_tests {
    use super::*;

    #[test]
    fn test_bdf_template() {
        let t = BdfSnippetTemplate::new("for loop", "for", "for (let i = 0; i < n; i++) {}");
        assert_eq!(t.name, "for loop");
        assert_eq!(t.prefix, "for");
    }

    #[test]
    fn test_bdf_expand() {
        let t = BdfSnippetTemplate::new("test", "t", "hello world");
        assert_eq!(t.expand(), "hello world");
    }

    #[test]
    fn test_bdf_description() {
        let t = BdfSnippetTemplate::new("t", "t", "").with_description("A test snippet");
        assert_eq!(t.description.as_deref(), Some("A test snippet"));
    }

    #[test]
    fn test_bdf_scope() {
        let t = BdfSnippetTemplate::new("t", "t", "").with_scope("rust");
        assert_eq!(t.scope.as_deref(), Some("rust"));
    }

    #[test]
    fn test_bdf_session() {
        let t = BdfSnippetTemplate::new("t", "t", "body");
        let session = BdfSnippetSession::new(t);
        assert!(session.is_active());
        assert_eq!(session.current_tabstop(), 1);
    }

    #[test]
    fn test_bdf_session_nav() {
        let mut t = BdfSnippetTemplate::new("t", "t", "body");
        t.parts = vec![BdfSnippetPart::Tabstop(1), BdfSnippetPart::Tabstop(2), BdfSnippetPart::Text("end".to_string())];
        let mut s = BdfSnippetSession::new(t);
        assert!(s.next_tabstop());
        assert_eq!(s.current_tabstop(), 2);
        assert!(s.prev_tabstop());
        assert_eq!(s.current_tabstop(), 1);
    }

    #[test]
    fn test_bdf_session_finish() {
        let t = BdfSnippetTemplate::new("t", "t", "body");
        let mut s = BdfSnippetSession::new(t);
        s.finish();
        assert!(!s.is_active());
    }

    #[test]
    fn test_bdf_session_cancel() {
        let t = BdfSnippetTemplate::new("t", "t", "body");
        let mut s = BdfSnippetSession::new(t);
        s.set_value(1, "val");
        s.cancel();
        assert!(s.values.is_empty());
    }

    #[test]
    fn test_bdf_set_value() {
        let t = BdfSnippetTemplate::new("t", "t", "body");
        let mut s = BdfSnippetSession::new(t);
        s.set_value(1, "hello");
        s.set_value(1, "world"); // override
        assert_eq!(s.values.len(), 1);
    }

    #[test]
    fn test_bdf_template_name() {
        let t = BdfSnippetTemplate::new("my-snippet", "ms", "body");
        let s = BdfSnippetSession::new(t);
        assert_eq!(s.template_name(), "my-snippet");
    }
}


// --- bdg_: Editor linked editing ranges model ---

/// A text range (line, start_col, end_col).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct BdgRange {
    pub line: u32,
    pub start_col: u32,
    pub end_col: u32,
}

impl BdgRange {
    pub fn new(line: u32, start: u32, end: u32) -> Self { Self { line, start_col: start, end_col: end } }
    pub fn len(&self) -> u32 { self.end_col.saturating_sub(self.start_col) }
    pub fn is_empty(&self) -> bool { self.len() == 0 }
    pub fn contains_col(&self, col: u32) -> bool { col >= self.start_col && col <= self.end_col }
}

/// A group of linked editing ranges that change together.
#[derive(Debug, Clone)]
pub struct BdgLinkedGroup {
    pub ranges: Vec<BdgRange>,
    pub word_pattern: Option<String>,
}

impl BdgLinkedGroup {
    pub fn new(ranges: Vec<BdgRange>) -> Self { Self { ranges, word_pattern: None } }
    pub fn with_pattern(mut self, p: &str) -> Self { self.word_pattern = Some(p.to_string()); self }
    pub fn range_count(&self) -> usize { self.ranges.len() }
    pub fn contains_position(&self, line: u32, col: u32) -> bool { self.ranges.iter().any(|r| r.line == line && r.contains_col(col)) }
}

/// Manages linked editing sessions.
#[derive(Debug)]
pub struct BdgLinkedEditingManager {
    active_group: Option<BdgLinkedGroup>,
    enabled: bool,
}

impl BdgLinkedEditingManager {
    pub fn new() -> Self { Self { active_group: None, enabled: true } }

    pub fn set_enabled(&mut self, enabled: bool) { self.enabled = enabled; if !enabled { self.active_group = None; } }
    pub fn is_enabled(&self) -> bool { self.enabled }

    pub fn set_group(&mut self, group: BdgLinkedGroup) {
        if self.enabled { self.active_group = Some(group); }
    }

    pub fn clear_group(&mut self) { self.active_group = None; }

    pub fn active_group(&self) -> Option<&BdgLinkedGroup> { self.active_group.as_ref() }
    pub fn has_active(&self) -> bool { self.active_group.is_some() }

    pub fn ranges_at(&self, line: u32, col: u32) -> Vec<&BdgRange> {
        match &self.active_group {
            Some(g) if g.contains_position(line, col) => g.ranges.iter().collect(),
            _ => Vec::new(),
        }
    }

    pub fn apply_edit(&mut self, line: u32, col: u32, new_text: &str) -> Vec<(BdgRange, String)> {
        let ranges = self.ranges_at(line, col);
        ranges.into_iter().map(|r| (*r, new_text.to_string())).collect()
    }

    pub fn all_lines_affected(&self) -> Vec<u32> {
        match &self.active_group {
            Some(g) => { let mut lines: Vec<_> = g.ranges.iter().map(|r| r.line).collect(); lines.sort(); lines.dedup(); lines }
            None => Vec::new(),
        }
    }
}

