// --- bdh_: Editor sticky scroll model ---

/// A scope entry for sticky scroll.
#[derive(Debug, Clone)]
pub struct BdhStickyEntry {
    pub line: u32,
    pub text: String,
    pub depth: usize,
    pub kind: BdhScopeKind,
}

/// Kind of scope for sticky scroll.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BdhScopeKind { Function, Class, Module, Block, If, Loop, Match }

impl BdhStickyEntry {
    pub fn new(line: u32, text: &str, depth: usize, kind: BdhScopeKind) -> Self {
        Self { line, text: text.to_string(), depth, kind }
    }

    pub fn render(&self) -> String {
        let indent = "  ".repeat(self.depth);
        format!("{}{}", indent, self.text)
    }
}

/// Sticky scroll state.
#[derive(Debug)]
pub struct BdhStickyScroll {
    entries: Vec<BdhStickyEntry>,
    max_lines: usize,
    enabled: bool,
    current_line: u32,
}

impl BdhStickyScroll {
    pub fn new() -> Self { Self { entries: Vec::new(), max_lines: 5, enabled: true, current_line: 0 } }

    pub fn set_enabled(&mut self, e: bool) { self.enabled = e; }
    pub fn is_enabled(&self) -> bool { self.enabled }
    pub fn set_max_lines(&mut self, n: usize) { self.max_lines = n; }

    pub fn update(&mut self, current_line: u32, scopes: Vec<BdhStickyEntry>) {
        self.current_line = current_line;
        self.entries = scopes.into_iter().filter(|e| e.line < current_line).collect();
        self.entries.sort_by_key(|e| e.line);
        if self.entries.len() > self.max_lines {
            let skip = self.entries.len() - self.max_lines;
            self.entries = self.entries.split_off(skip);
        }
    }

    pub fn visible_entries(&self) -> &[BdhStickyEntry] {
        if self.enabled { &self.entries } else { &[] }
    }

    pub fn visible_count(&self) -> usize {
        if self.enabled { self.entries.len() } else { 0 }
    }

    pub fn height(&self) -> usize { self.visible_count() }

    pub fn render_lines(&self) -> Vec<String> {
        self.visible_entries().iter().map(|e| e.render()).collect()
    }

    pub fn entry_at_offset(&self, offset: usize) -> Option<&BdhStickyEntry> {
        self.entries.get(offset)
    }

    pub fn clear(&mut self) { self.entries.clear(); }
}

#[cfg(test)]
mod bdh_tests {
    use super::*;

    #[test]
    fn test_bdh_entry() {
        let e = BdhStickyEntry::new(5, "fn main()", 0, BdhScopeKind::Function);
        assert_eq!(e.line, 5);
        assert!(e.render().contains("fn main()"));
    }

    #[test]
    fn test_bdh_entry_indent() {
        let e = BdhStickyEntry::new(10, "if x > 0", 2, BdhScopeKind::If);
        assert!(e.render().starts_with("    "));
    }

    #[test]
    fn test_bdh_new() {
        let ss = BdhStickyScroll::new();
        assert!(ss.is_enabled());
        assert_eq!(ss.visible_count(), 0);
    }

    #[test]
    fn test_bdh_update() {
        let mut ss = BdhStickyScroll::new();
        ss.update(20, vec![
            BdhStickyEntry::new(1, "mod foo", 0, BdhScopeKind::Module),
            BdhStickyEntry::new(5, "fn bar()", 1, BdhScopeKind::Function),
        ]);
        assert_eq!(ss.visible_count(), 2);
    }

    #[test]
    fn test_bdh_max_lines() {
        let mut ss = BdhStickyScroll::new();
        ss.set_max_lines(2);
        ss.update(100, vec![
            BdhStickyEntry::new(1, "a", 0, BdhScopeKind::Module),
            BdhStickyEntry::new(5, "b", 1, BdhScopeKind::Class),
            BdhStickyEntry::new(10, "c", 2, BdhScopeKind::Function),
        ]);
        assert_eq!(ss.visible_count(), 2);
    }

    #[test]
    fn test_bdh_disabled() {
        let mut ss = BdhStickyScroll::new();
        ss.set_enabled(false);
        ss.update(20, vec![BdhStickyEntry::new(1, "x", 0, BdhScopeKind::Function)]);
        assert_eq!(ss.visible_count(), 0);
    }

    #[test]
    fn test_bdh_render() {
        let mut ss = BdhStickyScroll::new();
        ss.update(20, vec![BdhStickyEntry::new(1, "fn main()", 0, BdhScopeKind::Function)]);
        let lines = ss.render_lines();
        assert_eq!(lines.len(), 1);
        assert!(lines[0].contains("fn main()"));
    }

    #[test]
    fn test_bdh_clear() {
        let mut ss = BdhStickyScroll::new();
        ss.update(20, vec![BdhStickyEntry::new(1, "x", 0, BdhScopeKind::Block)]);
        ss.clear();
        assert_eq!(ss.visible_count(), 0);
    }

    #[test]
    fn test_bdh_entry_at() {
        let mut ss = BdhStickyScroll::new();
        ss.update(20, vec![BdhStickyEntry::new(1, "first", 0, BdhScopeKind::Function)]);
        assert_eq!(ss.entry_at_offset(0).unwrap().text, "first");
    }

    #[test]
    fn test_bdh_height() {
        let mut ss = BdhStickyScroll::new();
        ss.update(20, vec![BdhStickyEntry::new(1, "a", 0, BdhScopeKind::Module), BdhStickyEntry::new(5, "b", 1, BdhScopeKind::Function)]);
        assert_eq!(ss.height(), 2);
    }

    #[test]
    fn test_bdh_filters_future() {
        let mut ss = BdhStickyScroll::new();
        ss.update(10, vec![
            BdhStickyEntry::new(5, "before", 0, BdhScopeKind::Function),
            BdhStickyEntry::new(15, "after", 0, BdhScopeKind::Function), // should be filtered
        ]);
        assert_eq!(ss.visible_count(), 1);
    }
}


// --- bdi_: Editor inline diff / change indicators ---

/// Line change type for gutter indicators.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BdiChangeType { Added, Modified, Deleted }

/// A change indicator on a line range.
#[derive(Debug, Clone)]
pub struct BdiChangeIndicator {
    pub start_line: u32,
    pub end_line: u32,
    pub change_type: BdiChangeType,
}

impl BdiChangeIndicator {
    pub fn new(start: u32, end: u32, ct: BdiChangeType) -> Self { Self { start_line: start, end_line: end, change_type: ct } }
    pub fn added(start: u32, end: u32) -> Self { Self::new(start, end, BdiChangeType::Added) }
    pub fn modified(start: u32, end: u32) -> Self { Self::new(start, end, BdiChangeType::Modified) }
    pub fn deleted(line: u32) -> Self { Self::new(line, line, BdiChangeType::Deleted) }

    pub fn line_count(&self) -> u32 { self.end_line - self.start_line + 1 }
    pub fn contains_line(&self, line: u32) -> bool { line >= self.start_line && line <= self.end_line }

    pub fn gutter_char(&self) -> char {
        match self.change_type { BdiChangeType::Added => '┃', BdiChangeType::Modified => '┃', BdiChangeType::Deleted => '▸' }
    }

    pub fn gutter_color(&self) -> &str {
        match self.change_type { BdiChangeType::Added => "green", BdiChangeType::Modified => "blue", BdiChangeType::Deleted => "red" }
    }
}

/// Inline diff between two text versions.
#[derive(Debug, Clone)]
pub struct BdiInlineDiff {
    pub old_line: Option<String>,
    pub new_line: Option<String>,
    pub change_type: BdiChangeType,
}

impl BdiInlineDiff {
    pub fn added(new: &str) -> Self { Self { old_line: None, new_line: Some(new.to_string()), change_type: BdiChangeType::Added } }
    pub fn deleted(old: &str) -> Self { Self { old_line: Some(old.to_string()), new_line: None, change_type: BdiChangeType::Deleted } }
    pub fn modified(old: &str, new: &str) -> Self { Self { old_line: Some(old.to_string()), new_line: Some(new.to_string()), change_type: BdiChangeType::Modified } }

    pub fn render(&self) -> String {
        match self.change_type {
            BdiChangeType::Added => format!("+ {}", self.new_line.as_deref().unwrap_or("")),
            BdiChangeType::Deleted => format!("- {}", self.old_line.as_deref().unwrap_or("")),
            BdiChangeType::Modified => format!("~ {} → {}", self.old_line.as_deref().unwrap_or(""), self.new_line.as_deref().unwrap_or("")),
        }
    }
}

/// Manages change indicators for a file.
#[derive(Debug)]
pub struct BdiChangeTracker {
    indicators: Vec<BdiChangeIndicator>,
    enabled: bool,
}

impl BdiChangeTracker {
    pub fn new() -> Self { Self { indicators: Vec::new(), enabled: true } }

    pub fn set_indicators(&mut self, indicators: Vec<BdiChangeIndicator>) { self.indicators = indicators; }
    pub fn clear(&mut self) { self.indicators.clear(); }
    pub fn set_enabled(&mut self, e: bool) { self.enabled = e; }

    pub fn change_at_line(&self, line: u32) -> Option<&BdiChangeIndicator> {
        if !self.enabled { return None; }
        self.indicators.iter().find(|i| i.contains_line(line))
    }

    pub fn all_indicators(&self) -> &[BdiChangeIndicator] { &self.indicators }
    pub fn added_count(&self) -> u32 { self.indicators.iter().filter(|i| i.change_type == BdiChangeType::Added).map(|i| i.line_count()).sum() }
    pub fn modified_count(&self) -> u32 { self.indicators.iter().filter(|i| i.change_type == BdiChangeType::Modified).map(|i| i.line_count()).sum() }
    pub fn deleted_count(&self) -> usize { self.indicators.iter().filter(|i| i.change_type == BdiChangeType::Deleted).count() }

    pub fn summary(&self) -> String { format!("+{} ~{} -{}", self.added_count(), self.modified_count(), self.deleted_count()) }

    pub fn next_change(&self, from_line: u32) -> Option<u32> {
        self.indicators.iter().map(|i| i.start_line).filter(|&l| l > from_line).min()
    }

    pub fn prev_change(&self, from_line: u32) -> Option<u32> {
        self.indicators.iter().map(|i| i.start_line).filter(|&l| l < from_line).max()
    }
}

#[cfg(test)]
mod bdi_tests {
    use super::*;

    #[test]
    fn test_bdi_indicator_added() {
        let i = BdiChangeIndicator::added(5, 10);
        assert_eq!(i.line_count(), 6);
        assert!(i.contains_line(7));
    }

    #[test]
    fn test_bdi_indicator_deleted() {
        let i = BdiChangeIndicator::deleted(15);
        assert_eq!(i.gutter_char(), '▸');
    }

    #[test]
    fn test_bdi_gutter_color() {
        assert_eq!(BdiChangeIndicator::added(0, 0).gutter_color(), "green");
        assert_eq!(BdiChangeIndicator::modified(0, 0).gutter_color(), "blue");
    }

    #[test]
    fn test_bdi_inline_diff() {
        let d = BdiInlineDiff::added("new line");
        assert!(d.render().starts_with('+'));
    }

    #[test]
    fn test_bdi_inline_modified() {
        let d = BdiInlineDiff::modified("old", "new");
        assert!(d.render().contains('→'));
    }

    #[test]
    fn test_bdi_tracker() {
        let mut t = BdiChangeTracker::new();
        t.set_indicators(vec![BdiChangeIndicator::added(1, 3), BdiChangeIndicator::deleted(10)]);
        assert!(t.change_at_line(2).is_some());
        assert!(t.change_at_line(5).is_none());
    }

    #[test]
    fn test_bdi_summary() {
        let mut t = BdiChangeTracker::new();
        t.set_indicators(vec![BdiChangeIndicator::added(1, 3), BdiChangeIndicator::modified(5, 5), BdiChangeIndicator::deleted(10)]);
        assert_eq!(t.summary(), "+3 ~1 -1");
    }

    #[test]
    fn test_bdi_next_prev() {
        let mut t = BdiChangeTracker::new();
        t.set_indicators(vec![BdiChangeIndicator::added(5, 5), BdiChangeIndicator::added(15, 15)]);
        assert_eq!(t.next_change(3), Some(5));
        assert_eq!(t.prev_change(20), Some(15));
    }

    #[test]
    fn test_bdi_disabled() {
        let mut t = BdiChangeTracker::new();
        t.set_indicators(vec![BdiChangeIndicator::added(1, 1)]);
        t.set_enabled(false);
        assert!(t.change_at_line(1).is_none());
    }

    #[test]
    fn test_bdi_clear() {
        let mut t = BdiChangeTracker::new();
        t.set_indicators(vec![BdiChangeIndicator::added(1, 1)]);
        t.clear();
        assert!(t.all_indicators().is_empty());
    }
}


// --- bdj_: Editor code lens / action model ---

/// A code lens item.
#[derive(Debug, Clone)]
pub struct BdjCodeLens {
    pub line: u32,
    pub title: String,
    pub command_id: Option<String>,
    pub tooltip: Option<String>,
    pub provider: String,
    pub resolved: bool,
}

impl BdjCodeLens {
    pub fn new(line: u32, title: &str, provider: &str) -> Self {
        Self { line, title: title.to_string(), command_id: None, tooltip: None, provider: provider.to_string(), resolved: false }
    }

    pub fn with_command(mut self, cmd: &str) -> Self { self.command_id = Some(cmd.to_string()); self.resolved = true; self }
    pub fn with_tooltip(mut self, t: &str) -> Self { self.tooltip = Some(t.to_string()); self }

    pub fn is_clickable(&self) -> bool { self.command_id.is_some() }

    pub fn render(&self) -> String {
        if self.resolved { self.title.clone() }
        else { format!("{}...", self.title) }
    }
}

/// Manages code lenses for a file.
#[derive(Debug)]
pub struct BdjCodeLensManager {
    lenses: Vec<BdjCodeLens>,
    enabled: bool,
}

impl BdjCodeLensManager {
    pub fn new() -> Self { Self { lenses: Vec::new(), enabled: true } }

    pub fn set_lenses(&mut self, lenses: Vec<BdjCodeLens>) {
        self.lenses = lenses;
        self.lenses.sort_by_key(|l| l.line);
    }

    pub fn add_lens(&mut self, lens: BdjCodeLens) { self.lenses.push(lens); }

    pub fn lenses_at_line(&self, line: u32) -> Vec<&BdjCodeLens> {
        if !self.enabled { return Vec::new(); }
        self.lenses.iter().filter(|l| l.line == line).collect()
    }

    pub fn all_lenses(&self) -> &[BdjCodeLens] { &self.lenses }
    pub fn lens_count(&self) -> usize { self.lenses.len() }

    pub fn set_enabled(&mut self, e: bool) { self.enabled = e; }
    pub fn is_enabled(&self) -> bool { self.enabled }

    pub fn lines_with_lenses(&self) -> Vec<u32> {
        if !self.enabled { return Vec::new(); }
        let mut lines: Vec<_> = self.lenses.iter().map(|l| l.line).collect();
        lines.sort();
        lines.dedup();
        lines
    }

    pub fn resolve_lens(&mut self, line: u32, title: &str, command: &str) {
        if let Some(l) = self.lenses.iter_mut().find(|l| l.line == line && !l.resolved) {
            l.title = title.to_string();
            l.command_id = Some(command.to_string());
            l.resolved = true;
        }
    }

    pub fn render_line_lenses(&self, line: u32) -> Option<String> {
        let lenses = self.lenses_at_line(line);
        if lenses.is_empty() { return None; }
        Some(lenses.iter().map(|l| l.render()).collect::<Vec<_>>().join(" | "))
    }

    pub fn by_provider(&self, provider: &str) -> Vec<&BdjCodeLens> {
        self.lenses.iter().filter(|l| l.provider == provider).collect()
    }

    pub fn clear(&mut self) { self.lenses.clear(); }
}

#[cfg(test)]
