// bfl_: Editor workspace settings model — settings scope, setting value types,
// setting overrides, language-specific settings, settings merge

/// Settings scope
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub enum BflSettingsScope {
    Default,
    User,
    Workspace,
    WorkspaceFolder,
    Language,
}

/// Setting value type
#[derive(Debug, Clone, PartialEq)]
pub enum BflSettingValue {
    String(String),
    Number(f64),
    Bool(bool),
    Array(Vec<BflSettingValue>),
    Null,
}

impl BflSettingValue {
    pub fn as_str(&self) -> Option<&str> {
        match self { BflSettingValue::String(s) => Some(s), _ => None }
    }
    pub fn as_bool(&self) -> Option<bool> {
        match self { BflSettingValue::Bool(b) => Some(*b), _ => None }
    }
    pub fn as_number(&self) -> Option<f64> {
        match self { BflSettingValue::Number(n) => Some(*n), _ => None }
    }
    pub fn is_null(&self) -> bool { matches!(self, BflSettingValue::Null) }
}

/// A settings layer
#[derive(Debug, Clone, Default)]
pub struct BflSettingsLayer {
    pub scope: BflSettingsScope,
    pub values: std::collections::HashMap<String, BflSettingValue>,
}

impl Default for BflSettingsScope { fn default() -> Self { BflSettingsScope::Default } }

impl BflSettingsLayer {
    pub fn new(scope: BflSettingsScope) -> Self { Self { scope, values: std::collections::HashMap::new() } }

    pub fn set(&mut self, key: &str, value: BflSettingValue) {
        self.values.insert(key.to_string(), value);
    }

    pub fn get(&self, key: &str) -> Option<&BflSettingValue> { self.values.get(key) }
    pub fn has(&self, key: &str) -> bool { self.values.contains_key(key) }
    pub fn count(&self) -> usize { self.values.len() }
}

/// Merged settings with scope priority
#[derive(Debug, Clone, Default)]
pub struct BflMergedSettings {
    pub layers: Vec<BflSettingsLayer>,
}

impl BflMergedSettings {
    pub fn new() -> Self { Self::default() }

    pub fn add_layer(&mut self, layer: BflSettingsLayer) {
        self.layers.push(layer);
        self.layers.sort_by_key(|l| l.scope);
    }

    pub fn get(&self, key: &str) -> Option<&BflSettingValue> {
        self.layers.iter().rev().find_map(|l| l.get(key))
    }

    pub fn get_string(&self, key: &str) -> Option<&str> {
        self.get(key).and_then(|v| v.as_str())
    }

    pub fn get_bool(&self, key: &str) -> Option<bool> {
        self.get(key).and_then(|v| v.as_bool())
    }

    pub fn effective_scope(&self, key: &str) -> Option<BflSettingsScope> {
        self.layers.iter().rev().find(|l| l.has(key)).map(|l| l.scope)
    }
}

#[cfg(test)]
mod tests_bfl {
    use super::*;

    #[test]
    fn test_bfl_setting_value() {
        assert_eq!(BflSettingValue::String("hello".into()).as_str(), Some("hello"));
        assert_eq!(BflSettingValue::Bool(true).as_bool(), Some(true));
        assert_eq!(BflSettingValue::Number(42.0).as_number(), Some(42.0));
        assert!(BflSettingValue::Null.is_null());
    }

    #[test]
    fn test_bfl_layer_set_get() {
        let mut layer = BflSettingsLayer::new(BflSettingsScope::User);
        layer.set("editor.tabSize", BflSettingValue::Number(4.0));
        assert_eq!(layer.get("editor.tabSize").unwrap().as_number(), Some(4.0));
    }

    #[test]
    fn test_bfl_merged_priority() {
        let mut merged = BflMergedSettings::new();
        let mut def = BflSettingsLayer::new(BflSettingsScope::Default);
        def.set("tabSize", BflSettingValue::Number(4.0));
        let mut user = BflSettingsLayer::new(BflSettingsScope::User);
        user.set("tabSize", BflSettingValue::Number(2.0));
        merged.add_layer(def);
        merged.add_layer(user);
        assert_eq!(merged.get("tabSize").unwrap().as_number(), Some(2.0));
    }

    #[test]
    fn test_bfl_merged_scope() {
        let mut merged = BflMergedSettings::new();
        let mut ws = BflSettingsLayer::new(BflSettingsScope::Workspace);
        ws.set("key", BflSettingValue::Bool(true));
        merged.add_layer(ws);
        assert_eq!(merged.effective_scope("key"), Some(BflSettingsScope::Workspace));
    }

    #[test]
    fn test_bfl_merged_missing() {
        let merged = BflMergedSettings::new();
        assert!(merged.get("missing").is_none());
    }

    #[test]
    fn test_bfl_get_string() {
        let mut merged = BflMergedSettings::new();
        let mut l = BflSettingsLayer::new(BflSettingsScope::Default);
        l.set("theme", BflSettingValue::String("dark".into()));
        merged.add_layer(l);
        assert_eq!(merged.get_string("theme"), Some("dark"));
    }

    #[test]
    fn test_bfl_get_bool() {
        let mut merged = BflMergedSettings::new();
        let mut l = BflSettingsLayer::new(BflSettingsScope::Default);
        l.set("mini", BflSettingValue::Bool(false));
        merged.add_layer(l);
        assert_eq!(merged.get_bool("mini"), Some(false));
    }

    #[test]
    fn test_bfl_scope_ordering() {
        assert!(BflSettingsScope::Workspace > BflSettingsScope::User);
        assert!(BflSettingsScope::User > BflSettingsScope::Default);
    }

    #[test]
    fn test_bfl_layer_count() {
        let mut l = BflSettingsLayer::new(BflSettingsScope::Default);
        l.set("a", BflSettingValue::Null);
        assert_eq!(l.count(), 1);
    }

    #[test]
    fn test_bfl_value_array() {
        let arr = BflSettingValue::Array(vec![BflSettingValue::Number(1.0), BflSettingValue::Number(2.0)]);
        assert!(arr.as_str().is_none());
    }
}

// bfm_: Editor extension marketplace model — extension info, versions,
// install/uninstall, enable/disable, extension search, ratings

/// Extension state
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BfmExtensionState {
    Installed,
    Disabled,
    Uninstalled,
    Updating,
}

/// Extension info
#[derive(Debug, Clone)]
pub struct BfmExtensionInfo {
    pub id: String,
    pub display_name: String,
    pub publisher: String,
    pub version: String,
    pub description: String,
    pub state: BfmExtensionState,
    pub install_count: u64,
    pub rating: f64,
    pub categories: Vec<String>,
}

impl BfmExtensionInfo {
    pub fn new(id: &str, name: &str, publisher: &str, version: &str) -> Self {
        Self { id: id.to_string(), display_name: name.to_string(), publisher: publisher.to_string(),
               version: version.to_string(), description: String::new(), state: BfmExtensionState::Uninstalled,
               install_count: 0, rating: 0.0, categories: Vec::new() }
    }

    pub fn full_id(&self) -> String { format!("{}.{}", self.publisher, self.id) }
    pub fn is_installed(&self) -> bool { self.state == BfmExtensionState::Installed }
    pub fn is_enabled(&self) -> bool { self.state == BfmExtensionState::Installed }

    pub fn install(&mut self) { self.state = BfmExtensionState::Installed; }
    pub fn disable(&mut self) { self.state = BfmExtensionState::Disabled; }
    pub fn enable(&mut self) { self.state = BfmExtensionState::Installed; }
    pub fn uninstall(&mut self) { self.state = BfmExtensionState::Uninstalled; }
}

/// Extension marketplace
#[derive(Debug, Clone, Default)]
pub struct BfmMarketplace {
    pub extensions: Vec<BfmExtensionInfo>,
}

impl BfmMarketplace {
    pub fn new() -> Self { Self::default() }

    pub fn add(&mut self, ext: BfmExtensionInfo) { self.extensions.push(ext); }

    pub fn find(&self, id: &str) -> Option<&BfmExtensionInfo> {
        self.extensions.iter().find(|e| e.id == id || e.full_id() == id)
    }

    pub fn find_mut(&mut self, id: &str) -> Option<&mut BfmExtensionInfo> {
        self.extensions.iter_mut().find(|e| e.id == id || e.full_id() == id)
    }

    pub fn installed(&self) -> Vec<&BfmExtensionInfo> {
        self.extensions.iter().filter(|e| e.is_installed()).collect()
    }

    pub fn search(&self, query: &str) -> Vec<&BfmExtensionInfo> {
        let q = query.to_lowercase();
        self.extensions.iter().filter(|e| e.display_name.to_lowercase().contains(&q) || e.id.to_lowercase().contains(&q)).collect()
    }

    pub fn count(&self) -> usize { self.extensions.len() }
}

#[cfg(test)]
mod tests_bfm {
    use super::*;

    #[test]
    fn test_bfm_extension_info() {
        let ext = BfmExtensionInfo::new("rust-analyzer", "Rust Analyzer", "rust-lang", "0.3.0");
        assert_eq!(ext.full_id(), "rust-lang.rust-analyzer");
        assert!(!ext.is_installed());
    }

    #[test]
    fn test_bfm_extension_lifecycle() {
        let mut ext = BfmExtensionInfo::new("ext", "Ext", "pub", "1.0");
        ext.install();
        assert!(ext.is_installed());
        ext.disable();
        assert!(!ext.is_enabled());
        ext.enable();
        assert!(ext.is_enabled());
        ext.uninstall();
        assert!(!ext.is_installed());
    }

    #[test]
    fn test_bfm_marketplace_search() {
        let mut mp = BfmMarketplace::new();
        mp.add(BfmExtensionInfo::new("prettier", "Prettier", "esbenp", "10.0"));
        mp.add(BfmExtensionInfo::new("eslint", "ESLint", "dbaeumer", "2.0"));
        assert_eq!(mp.search("prettier").len(), 1);
        assert_eq!(mp.search("xyz").len(), 0);
    }

    #[test]
    fn test_bfm_marketplace_installed() {
        let mut mp = BfmMarketplace::new();
        let mut ext = BfmExtensionInfo::new("a", "A", "p", "1.0");
        ext.install();
        mp.add(ext);
        mp.add(BfmExtensionInfo::new("b", "B", "p", "1.0"));
        assert_eq!(mp.installed().len(), 1);
    }

    #[test]
    fn test_bfm_marketplace_find() {
        let mut mp = BfmMarketplace::new();
        mp.add(BfmExtensionInfo::new("ext", "Ext", "pub", "1.0"));
        assert!(mp.find("ext").is_some());
        assert!(mp.find("pub.ext").is_some());
    }

    #[test]
    fn test_bfm_marketplace_count() {
        let mp = BfmMarketplace::new();
        assert_eq!(mp.count(), 0);
    }

    #[test]
    fn test_bfm_extension_states() {
        assert_ne!(BfmExtensionState::Installed, BfmExtensionState::Disabled);
    }

    #[test]
    fn test_bfm_extension_rating() {
        let mut ext = BfmExtensionInfo::new("a", "A", "p", "1.0");
        ext.rating = 4.5;
        assert!((ext.rating - 4.5).abs() < 0.01);
    }

    #[test]
    fn test_bfm_extension_categories() {
        let mut ext = BfmExtensionInfo::new("a", "A", "p", "1.0");
        ext.categories.push("Themes".to_string());
        assert_eq!(ext.categories.len(), 1);
    }

    #[test]
    fn test_bfm_marketplace_find_mut() {
        let mut mp = BfmMarketplace::new();
        mp.add(BfmExtensionInfo::new("a", "A", "p", "1.0"));
        mp.find_mut("a").unwrap().install();
        assert!(mp.find("a").unwrap().is_installed());
    }
}

// bfn_: Editor git integration model — git status, staged changes,
// branch info, commit history summary, merge conflicts

/// Git file status
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BfnGitFileStatus {
    Modified,
    Added,
    Deleted,
    Renamed,
    Untracked,
    Conflicted,
    Ignored,
}

/// Git file change
#[derive(Debug, Clone)]
pub struct BfnGitChange {
    pub path: String,
    pub status: BfnGitFileStatus,
    pub staged: bool,
}

impl BfnGitChange {
    pub fn new(path: &str, status: BfnGitFileStatus, staged: bool) -> Self {
        Self { path: path.to_string(), status, staged }
    }

    pub fn is_modified(&self) -> bool { self.status == BfnGitFileStatus::Modified }
    pub fn is_conflict(&self) -> bool { self.status == BfnGitFileStatus::Conflicted }

    pub fn display_icon(&self) -> &str {
        match self.status {
            BfnGitFileStatus::Modified => "M",
            BfnGitFileStatus::Added => "A",
            BfnGitFileStatus::Deleted => "D",
            BfnGitFileStatus::Renamed => "R",
            BfnGitFileStatus::Untracked => "U",
            BfnGitFileStatus::Conflicted => "C",
            BfnGitFileStatus::Ignored => "!",
        }
    }
}

/// Git repository state
#[derive(Debug, Clone)]
pub struct BfnGitState {
    pub branch: String,
    pub ahead: usize,
    pub behind: usize,
    pub changes: Vec<BfnGitChange>,
    pub is_rebasing: bool,
    pub is_merging: bool,
}

impl Default for BfnGitState {
    fn default() -> Self {
        Self { branch: "main".to_string(), ahead: 0, behind: 0, changes: Vec::new(),
               is_rebasing: false, is_merging: false }
    }
}

impl BfnGitState {
    pub fn new() -> Self { Self::default() }

    pub fn staged_changes(&self) -> Vec<&BfnGitChange> { self.changes.iter().filter(|c| c.staged).collect() }
    pub fn unstaged_changes(&self) -> Vec<&BfnGitChange> { self.changes.iter().filter(|c| !c.staged).collect() }
    pub fn conflict_count(&self) -> usize { self.changes.iter().filter(|c| c.is_conflict()).count() }
    pub fn has_changes(&self) -> bool { !self.changes.is_empty() }
    pub fn change_count(&self) -> usize { self.changes.len() }

    pub fn status_text(&self) -> String {
        let mut parts = vec![self.branch.clone()];
        if self.ahead > 0 { parts.push(format!("↑{}", self.ahead)); }
        if self.behind > 0 { parts.push(format!("↓{}", self.behind)); }
        parts.join(" ")
    }
}

#[cfg(test)]
mod tests_bfn {
    use super::*;

    #[test]
    fn test_bfn_change_display() {
        let c = BfnGitChange::new("src/main.rs", BfnGitFileStatus::Modified, false);
        assert_eq!(c.display_icon(), "M");
        assert!(c.is_modified());
    }

    #[test]
    fn test_bfn_state_status() {
        let mut state = BfnGitState::new();
        state.branch = "feature/x".to_string();
        state.ahead = 2;
        assert!(state.status_text().contains("↑2"));
    }

    #[test]
    fn test_bfn_staged_unstaged() {
        let mut state = BfnGitState::new();
        state.changes.push(BfnGitChange::new("a.rs", BfnGitFileStatus::Modified, true));
        state.changes.push(BfnGitChange::new("b.rs", BfnGitFileStatus::Added, false));
        assert_eq!(state.staged_changes().len(), 1);
        assert_eq!(state.unstaged_changes().len(), 1);
    }

    #[test]
    fn test_bfn_conflicts() {
        let mut state = BfnGitState::new();
        state.changes.push(BfnGitChange::new("c.rs", BfnGitFileStatus::Conflicted, false));
        assert_eq!(state.conflict_count(), 1);
    }

    #[test]
    fn test_bfn_no_changes() {
        let state = BfnGitState::new();
        assert!(!state.has_changes());
        assert_eq!(state.change_count(), 0);
    }

    #[test]
    fn test_bfn_rebase_merge() {
        let mut state = BfnGitState::new();
        state.is_rebasing = true;
        assert!(state.is_rebasing);
        assert!(!state.is_merging);
    }

    #[test]
    fn test_bfn_behind() {
        let mut state = BfnGitState::new();
        state.behind = 3;
        assert!(state.status_text().contains("↓3"));
    }

    #[test]
    fn test_bfn_change_conflict() {
        let c = BfnGitChange::new("x", BfnGitFileStatus::Conflicted, false);
        assert!(c.is_conflict());
    }

    #[test]
    fn test_bfn_file_statuses() {
        assert_ne!(BfnGitFileStatus::Modified, BfnGitFileStatus::Added);
        assert_ne!(BfnGitFileStatus::Deleted, BfnGitFileStatus::Renamed);
    }

    #[test]
    fn test_bfn_default_branch() {
        let state = BfnGitState::new();
        assert_eq!(state.branch, "main");
    }
}

// bfo_: Editor testing model — test items, test results, test run,
// test coverage, test discovery, test explorer tree

/// Test result state
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BfoTestState {
    Queued,
    Running,
    Passed,
    Failed,
    Skipped,
    Errored,
}

impl BfoTestState {
    pub fn is_terminal(&self) -> bool {
        matches!(self, BfoTestState::Passed | BfoTestState::Failed | BfoTestState::Skipped | BfoTestState::Errored)
    }

    pub fn icon(&self) -> &str {
        match self {
            BfoTestState::Queued => "○",
            BfoTestState::Running => "◉",
            BfoTestState::Passed => "✓",
            BfoTestState::Failed => "✗",
            BfoTestState::Skipped => "⊘",
            BfoTestState::Errored => "⚠",
        }
    }
}

/// A test item
#[derive(Debug, Clone)]
pub struct BfoTestItem {
    pub id: String,
    pub label: String,
    pub uri: Option<String>,
    pub line: Option<usize>,
    pub state: BfoTestState,
    pub message: Option<String>,
    pub duration_ms: Option<u64>,
    pub children: Vec<BfoTestItem>,
}

impl BfoTestItem {
    pub fn new(id: &str, label: &str) -> Self {
        Self { id: id.to_string(), label: label.to_string(), uri: None, line: None,
               state: BfoTestState::Queued, message: None, duration_ms: None, children: Vec::new() }
    }

    pub fn pass(&mut self, duration_ms: u64) { self.state = BfoTestState::Passed; self.duration_ms = Some(duration_ms); }
    pub fn fail(&mut self, msg: &str) { self.state = BfoTestState::Failed; self.message = Some(msg.to_string()); }

    pub fn is_leaf(&self) -> bool { self.children.is_empty() }
    pub fn child_count(&self) -> usize { self.children.len() }

    pub fn total_count(&self) -> usize {
        1 + self.children.iter().map(|c| c.total_count()).sum::<usize>()
    }
}

/// Test run summary
#[derive(Debug, Clone, Default)]
pub struct BfoTestRun {
    pub items: Vec<BfoTestItem>,
}

impl BfoTestRun {
    pub fn new() -> Self { Self::default() }

    pub fn add(&mut self, item: BfoTestItem) { self.items.push(item); }

    pub fn passed_count(&self) -> usize { self.items.iter().filter(|i| i.state == BfoTestState::Passed).count() }
    pub fn failed_count(&self) -> usize { self.items.iter().filter(|i| i.state == BfoTestState::Failed).count() }
    pub fn total_count(&self) -> usize { self.items.len() }

    pub fn all_passed(&self) -> bool { self.items.iter().all(|i| i.state == BfoTestState::Passed) }
}


// bfp_ Editor Breadcrumb Model

/// Breadcrumb element representing a segment in the file path or symbol hierarchy.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct BfpBreadcrumbElement {
    pub label: String,
    pub kind: BfpBreadcrumbKind,
    pub icon: Option<String>,
    pub uri: Option<String>,
    pub is_active: bool,
}

/// Kind of breadcrumb element.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BfpBreadcrumbKind {
    File,
    Folder,
    Symbol,
    Type,
    Module,
    Namespace,
    Package,
}

/// Breadcrumb navigation bar state.
#[derive(Debug, Clone)]
pub struct BfpBreadcrumbBar {
    pub elements: Vec<BfpBreadcrumbElement>,
    pub focused_index: Option<usize>,
    pub is_visible: bool,
    pub file_path: String,
}

impl BfpBreadcrumbBar {
    pub fn new(file_path: &str) -> Self {
        let segments: Vec<&str> = file_path.split('/').filter(|s| !s.is_empty()).collect();
        let mut elements = Vec::new();
        for (i, seg) in segments.iter().enumerate() {
            let kind = if i == segments.len() - 1 {
                BfpBreadcrumbKind::File
            } else {
                BfpBreadcrumbKind::Folder
            };
            elements.push(BfpBreadcrumbElement {
                label: seg.to_string(),
                kind,
                icon: None,
                uri: None,
                is_active: false,
            });
        }
        Self {
            elements,
            focused_index: None,
            is_visible: true,
            file_path: file_path.to_string(),
        }
    }

    pub fn focus_element(&mut self, index: usize) {
        if index < self.elements.len() {
            if let Some(old) = self.focused_index {
                if old < self.elements.len() {
                    self.elements[old].is_active = false;
                }
            }
            self.elements[index].is_active = true;
            self.focused_index = Some(index);
        }
    }

    pub fn focus_next(&mut self) {
        let next = match self.focused_index {
            Some(i) if i + 1 < self.elements.len() => i + 1,
            None if !self.elements.is_empty() => 0,
            _ => return,
        };
        self.focus_element(next);
    }

    pub fn focus_prev(&mut self) {
        let prev = match self.focused_index {
            Some(i) if i > 0 => i - 1,
            _ => return,
        };
        self.focus_element(prev);
    }

    pub fn add_symbol(&mut self, label: &str, kind: BfpBreadcrumbKind) {
        self.elements.push(BfpBreadcrumbElement {
            label: label.to_string(),
            kind,
            icon: None,
            uri: None,
            is_active: false,
        });
    }

    pub fn depth(&self) -> usize {
        self.elements.len()
    }

    pub fn active_label(&self) -> Option<&str> {
        self.focused_index
            .and_then(|i| self.elements.get(i))
            .map(|e| e.label.as_str())
    }
}


// bfq_ Source Control View Model

/// Source control resource state in SCM view.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BfqScmResourceState {
    Untracked,
    Modified,
    Added,
    Deleted,
    Renamed,
    Copied,
    Conflicting,
    Ignored,
}

/// A single resource in the SCM view.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct BfqScmResource {
    pub path: String,
    pub state: BfqScmResourceState,
    pub original_path: Option<String>,
}

/// SCM resource group (staged, unstaged, untracked, merge changes).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct BfqScmResourceGroup {
    pub id: String,
    pub label: String,
    pub resources: Vec<BfqScmResource>,
    pub hide_when_empty: bool,
}

/// Source control view model.
#[derive(Debug, Clone)]
pub struct BfqScmView {
    pub provider_label: String,
    pub root_uri: Option<String>,
    pub groups: Vec<BfqScmResourceGroup>,
    pub commit_message: String,
    pub count: usize,
    pub selected_index: Option<usize>,
}

impl BfqScmView {
    pub fn new(provider: &str) -> Self {
        Self {
            provider_label: provider.to_string(),
            root_uri: None,
            groups: Vec::new(),
            commit_message: String::new(),
            count: 0,
            selected_index: None,
        }
    }

    pub fn add_group(&mut self, id: &str, label: &str, hide_when_empty: bool) {
        self.groups.push(BfqScmResourceGroup {
            id: id.to_string(),
            label: label.to_string(),
            resources: Vec::new(),
            hide_when_empty,
        });
    }

    pub fn add_resource(&mut self, group_id: &str, path: &str, state: BfqScmResourceState) {
        if let Some(g) = self.groups.iter_mut().find(|g| g.id == group_id) {
            g.resources.push(BfqScmResource {
                path: path.to_string(),
                state,
                original_path: None,
            });
            self.count += 1;
        }
    }

    pub fn stage_resource(&mut self, path: &str) -> bool {
        let mut found = None;
        for g in &mut self.groups {
            if g.id != "staged" {
                if let Some(pos) = g.resources.iter().position(|r| r.path == path) {
                    found = Some(g.resources.remove(pos));
                    break;
                }
            }
        }
        if let Some(res) = found {
            if let Some(staged) = self.groups.iter_mut().find(|g| g.id == "staged") {
                staged.resources.push(res);
                return true;
            }
        }
        false
    }

    pub fn unstage_resource(&mut self, path: &str) -> bool {
        let mut found = None;
        if let Some(staged) = self.groups.iter_mut().find(|g| g.id == "staged") {
            if let Some(pos) = staged.resources.iter().position(|r| r.path == path) {
                found = Some(staged.resources.remove(pos));
            }
        }
        if let Some(res) = found {
            if let Some(changes) = self.groups.iter_mut().find(|g| g.id == "changes") {
                changes.resources.push(res);
                return true;
            }
        }
        false
    }

    pub fn visible_groups(&self) -> Vec<&BfqScmResourceGroup> {
        self.groups.iter().filter(|g| !g.hide_when_empty || !g.resources.is_empty()).collect()
    }

    pub fn total_resources(&self) -> usize {
        self.groups.iter().map(|g| g.resources.len()).sum()
    }

    pub fn set_commit_message(&mut self, msg: &str) {
        self.commit_message = msg.to_string();
    }

    pub fn resources_by_state(&self, state: BfqScmResourceState) -> Vec<&BfqScmResource> {
        self.groups.iter().flat_map(|g| g.resources.iter()).filter(|r| r.state == state).collect()
    }
}


// bfr_ Debug Breakpoint Model

/// Breakpoint kind in the debug model.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BfrBreakpointKind {
    Line,
    Conditional,
    Logpoint,
    Function,
    Data,
    Exception,
    Inline,
}

/// A debug breakpoint.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct BfrBreakpoint {
    pub id: u64,
    pub kind: BfrBreakpointKind,
    pub file: String,
    pub line: usize,
    pub column: Option<usize>,
    pub condition: Option<String>,
    pub hit_condition: Option<String>,
    pub log_message: Option<String>,
    pub enabled: bool,
    pub verified: bool,
    pub hit_count: u64,
}

/// Breakpoint manager that tracks all breakpoints.
#[derive(Debug, Clone)]
pub struct BfrBreakpointManager {
    breakpoints: Vec<BfrBreakpoint>,
    next_id: u64,
}

impl BfrBreakpointManager {
    pub fn new() -> Self {
        Self { breakpoints: Vec::new(), next_id: 1 }
    }

    pub fn add_line_breakpoint(&mut self, file: &str, line: usize) -> u64 {
        let id = self.next_id;
        self.next_id += 1;
        self.breakpoints.push(BfrBreakpoint {
            id, kind: BfrBreakpointKind::Line, file: file.to_string(),
            line, column: None, condition: None, hit_condition: None,
            log_message: None, enabled: true, verified: false, hit_count: 0,
        });
        id
    }

    pub fn add_conditional(&mut self, file: &str, line: usize, condition: &str) -> u64 {
        let id = self.next_id;
        self.next_id += 1;
        self.breakpoints.push(BfrBreakpoint {
            id, kind: BfrBreakpointKind::Conditional, file: file.to_string(),
            line, column: None, condition: Some(condition.to_string()),
            hit_condition: None, log_message: None, enabled: true, verified: false, hit_count: 0,
        });
        id
    }

    pub fn add_logpoint(&mut self, file: &str, line: usize, message: &str) -> u64 {
        let id = self.next_id;
        self.next_id += 1;
        self.breakpoints.push(BfrBreakpoint {
            id, kind: BfrBreakpointKind::Logpoint, file: file.to_string(),
            line, column: None, condition: None, hit_condition: None,
            log_message: Some(message.to_string()), enabled: true, verified: false, hit_count: 0,
        });
        id
    }

    pub fn remove(&mut self, id: u64) -> bool {
        if let Some(pos) = self.breakpoints.iter().position(|b| b.id == id) {
            self.breakpoints.remove(pos);
            true
        } else {
            false
        }
    }

    pub fn toggle(&mut self, id: u64) -> bool {
        if let Some(bp) = self.breakpoints.iter_mut().find(|b| b.id == id) {
            bp.enabled = !bp.enabled;
            true
        } else {
            false
        }
    }

    pub fn verify(&mut self, id: u64) {
        if let Some(bp) = self.breakpoints.iter_mut().find(|b| b.id == id) {
            bp.verified = true;
        }
    }

    pub fn record_hit(&mut self, id: u64) {
        if let Some(bp) = self.breakpoints.iter_mut().find(|b| b.id == id) {
            bp.hit_count += 1;
        }
    }

    pub fn breakpoints_for_file(&self, file: &str) -> Vec<&BfrBreakpoint> {
        self.breakpoints.iter().filter(|b| b.file == file).collect()
    }

    pub fn enabled_breakpoints(&self) -> Vec<&BfrBreakpoint> {
        self.breakpoints.iter().filter(|b| b.enabled).collect()
    }

    pub fn count(&self) -> usize {
        self.breakpoints.len()
    }

    pub fn clear_all(&mut self) {
        self.breakpoints.clear();
    }

    pub fn get(&self, id: u64) -> Option<&BfrBreakpoint> {
        self.breakpoints.iter().find(|b| b.id == id)
    }
}


// bfs_ Debug Call Stack Model

/// A stack frame in the debug call stack.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct BfsStackFrame {
    pub id: u64,
    pub name: String,
    pub source_file: Option<String>,
    pub line: usize,
    pub column: usize,
    pub module_name: Option<String>,
    pub presentation_hint: BfsFrameHint,
}

/// How to present a stack frame.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BfsFrameHint {
    Normal,
    Label,
    Subtle,
    Deemphasize,
}

/// Thread state in the debugger.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BfsThreadState {
    Running,
    Stopped,
    Terminated,
}

/// A thread in the debug session.
#[derive(Debug, Clone)]
pub struct BfsThread {
    pub id: u64,
    pub name: String,
    pub state: BfsThreadState,
    pub frames: Vec<BfsStackFrame>,
}

/// Debug call stack model managing all threads and their frames.
#[derive(Debug, Clone)]
pub struct BfsCallStack {
    pub threads: Vec<BfsThread>,
    pub focused_thread_id: Option<u64>,
    pub focused_frame_id: Option<u64>,
}

impl BfsCallStack {
    pub fn new() -> Self {
        Self { threads: Vec::new(), focused_thread_id: None, focused_frame_id: None }
    }

    pub fn add_thread(&mut self, id: u64, name: &str) {
        self.threads.push(BfsThread {
            id, name: name.to_string(), state: BfsThreadState::Running,
            frames: Vec::new(),
        });
    }

    pub fn stop_thread(&mut self, thread_id: u64, frames: Vec<BfsStackFrame>) {
        if let Some(t) = self.threads.iter_mut().find(|t| t.id == thread_id) {
            t.state = BfsThreadState::Stopped;
            t.frames = frames;
        }
    }

    pub fn continue_thread(&mut self, thread_id: u64) {
        if let Some(t) = self.threads.iter_mut().find(|t| t.id == thread_id) {
            t.state = BfsThreadState::Running;
            t.frames.clear();
        }
    }

    pub fn terminate_thread(&mut self, thread_id: u64) {
        if let Some(t) = self.threads.iter_mut().find(|t| t.id == thread_id) {
            t.state = BfsThreadState::Terminated;
            t.frames.clear();
        }
    }

    pub fn focus_thread(&mut self, thread_id: u64) {
        self.focused_thread_id = Some(thread_id);
        if let Some(t) = self.threads.iter().find(|t| t.id == thread_id) {
            self.focused_frame_id = t.frames.first().map(|f| f.id);
        }
    }

    pub fn focus_frame(&mut self, frame_id: u64) {
        self.focused_frame_id = Some(frame_id);
    }

    pub fn focused_thread(&self) -> Option<&BfsThread> {
        self.focused_thread_id.and_then(|id| self.threads.iter().find(|t| t.id == id))
    }

    pub fn focused_frame(&self) -> Option<&BfsStackFrame> {
        self.focused_thread()
            .and_then(|t| {
                self.focused_frame_id
                    .and_then(|fid| t.frames.iter().find(|f| f.id == fid))
            })
    }

    pub fn thread_count(&self) -> usize {
        self.threads.len()
    }

    pub fn stopped_threads(&self) -> Vec<&BfsThread> {
        self.threads.iter().filter(|t| t.state == BfsThreadState::Stopped).collect()
    }
}


// bft_ Watch Expression Model

/// Value type of a watch expression result.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum BftValueKind {
    String,
    Number,
    Boolean,
    Object,
    Array,
    Null,
    Error,
    Undefined,
}

/// A watch expression in the debug watch panel.
#[derive(Debug, Clone)]
pub struct BftWatchExpression {
    pub id: u64,
    pub expression: String,
    pub value: Option<String>,
    pub value_kind: BftValueKind,
    pub has_children: bool,
    pub children: Vec<BftWatchExpression>,
    pub error_message: Option<String>,
}

/// Watch expression panel model.
#[derive(Debug, Clone)]
pub struct BftWatchPanel {
    expressions: Vec<BftWatchExpression>,
    next_id: u64,
    selected_index: Option<usize>,
}

impl BftWatchPanel {
    pub fn new() -> Self {
        Self { expressions: Vec::new(), next_id: 1, selected_index: None }
    }

    pub fn add_expression(&mut self, expr: &str) -> u64 {
        let id = self.next_id;
        self.next_id += 1;
        self.expressions.push(BftWatchExpression {
            id, expression: expr.to_string(), value: None,
            value_kind: BftValueKind::Undefined, has_children: false,
            children: Vec::new(), error_message: None,
        });
        id
    }

    pub fn remove_expression(&mut self, id: u64) -> bool {
        if let Some(pos) = self.expressions.iter().position(|e| e.id == id) {
            self.expressions.remove(pos);
            true
        } else {
            false
        }
    }

    pub fn update_value(&mut self, id: u64, value: &str, kind: BftValueKind) {
        if let Some(expr) = self.expressions.iter_mut().find(|e| e.id == id) {
            expr.value = Some(value.to_string());
            expr.value_kind = kind;
            expr.error_message = None;
        }
    }

    pub fn set_error(&mut self, id: u64, message: &str) {
        if let Some(expr) = self.expressions.iter_mut().find(|e| e.id == id) {
            expr.value = None;
            expr.value_kind = BftValueKind::Error;
            expr.error_message = Some(message.to_string());
        }
    }

    pub fn set_children(&mut self, id: u64, children: Vec<BftWatchExpression>) {
        if let Some(expr) = self.expressions.iter_mut().find(|e| e.id == id) {
            expr.has_children = !children.is_empty();
            expr.children = children;
        }
    }

    pub fn edit_expression(&mut self, id: u64, new_expr: &str) -> bool {
        if let Some(expr) = self.expressions.iter_mut().find(|e| e.id == id) {
            expr.expression = new_expr.to_string();
            expr.value = None;
            expr.value_kind = BftValueKind::Undefined;
            expr.error_message = None;
            true
        } else {
            false
        }
    }

    pub fn select(&mut self, index: usize) {
        if index < self.expressions.len() {
            self.selected_index = Some(index);
        }
    }

    pub fn selected(&self) -> Option<&BftWatchExpression> {
        self.selected_index.and_then(|i| self.expressions.get(i))
    }

    pub fn count(&self) -> usize {
        self.expressions.len()
    }

    pub fn expressions(&self) -> &[BftWatchExpression] {
        &self.expressions
    }

    pub fn clear_all_values(&mut self) {
        for expr in &mut self.expressions {
            expr.value = None;
            expr.value_kind = BftValueKind::Undefined;
            expr.children.clear();
            expr.has_children = false;
        }
    }

    pub fn move_up(&mut self, id: u64) -> bool {
        if let Some(pos) = self.expressions.iter().position(|e| e.id == id) {
            if pos > 0 {
                self.expressions.swap(pos, pos - 1);
                return true;
            }
        }
        false
    }
}



// bfu_ Variable Inspector Model

/// Scope kind for debug variable inspection.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BfuScopeKind {
    Local,
    Global,
    Closure,
    Catch,
    Block,
    Module,
    Register,
}

/// A debug variable in the variables pane.
#[derive(Debug, Clone)]
pub struct BfuVariable {
    pub name: String,
    pub value: String,
    pub var_type: Option<String>,
    pub evaluatable_name: Option<String>,
    pub children: Vec<BfuVariable>,
    pub has_children: bool,
    pub is_expanded: bool,
}

/// A scope containing variables.
#[derive(Debug, Clone)]
pub struct BfuScope {
    pub name: String,
    pub kind: BfuScopeKind,
    pub variables: Vec<BfuVariable>,
    pub expensive: bool,
    pub is_expanded: bool,
}

/// Variable inspector panel model.
#[derive(Debug, Clone)]
pub struct BfuVariableInspector {
    scopes: Vec<BfuScope>,
    selected_path: Vec<usize>,
}

impl BfuVariableInspector {
    pub fn new() -> Self {
        Self { scopes: Vec::new(), selected_path: Vec::new() }
    }

    pub fn set_scopes(&mut self, scopes: Vec<BfuScope>) {
        self.scopes = scopes;
        self.selected_path.clear();
    }

    pub fn scope_count(&self) -> usize {
        self.scopes.len()
    }

    pub fn toggle_scope(&mut self, index: usize) {
        if let Some(s) = self.scopes.get_mut(index) {
            s.is_expanded = !s.is_expanded;
        }
    }

    pub fn variable_count(&self, scope_index: usize) -> usize {
        self.scopes.get(scope_index).map(|s| s.variables.len()).unwrap_or(0)
    }

    pub fn get_variable(&self, scope_index: usize, var_index: usize) -> Option<&BfuVariable> {
        self.scopes.get(scope_index).and_then(|s| s.variables.get(var_index))
    }

    pub fn set_variable_value(&mut self, scope_index: usize, var_index: usize, new_value: &str) {
        if let Some(scope) = self.scopes.get_mut(scope_index) {
            if let Some(var) = scope.variables.get_mut(var_index) {
                var.value = new_value.to_string();
            }
        }
    }

    pub fn expand_variable(&mut self, scope_index: usize, var_index: usize) {
        if let Some(scope) = self.scopes.get_mut(scope_index) {
            if let Some(var) = scope.variables.get_mut(var_index) {
                var.is_expanded = true;
            }
        }
    }

    pub fn collapse_variable(&mut self, scope_index: usize, var_index: usize) {
        if let Some(scope) = self.scopes.get_mut(scope_index) {
            if let Some(var) = scope.variables.get_mut(var_index) {
                var.is_expanded = false;
            }
        }
    }

    pub fn total_variables(&self) -> usize {
        self.scopes.iter().map(|s| s.variables.len()).sum()
    }

    pub fn scopes(&self) -> &[BfuScope] {
        &self.scopes
    }
}


// bfv_ Terminal Instance Model

/// Terminal shell type.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BfvShellKind {
    Bash,
    Zsh,
    Fish,
    PowerShell,
    Cmd,
    Custom,
}

/// Terminal process state.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BfvTerminalState {
    Starting,
    Running,
    Exited,
    Failed,
}

/// A terminal instance in the integrated terminal.
#[derive(Debug, Clone)]
pub struct BfvTerminalInstance {
    pub id: u64,
    pub title: String,
    pub shell_kind: BfvShellKind,
    pub state: BfvTerminalState,
    pub cwd: String,
    pub exit_code: Option<i32>,
    pub pid: Option<u32>,
    pub cols: u16,
    pub rows: u16,
    pub is_active: bool,
}

/// Terminal instance manager.
#[derive(Debug, Clone)]
pub struct BfvTerminalManager {
    instances: Vec<BfvTerminalInstance>,
    next_id: u64,
    active_id: Option<u64>,
}

impl BfvTerminalManager {
    pub fn new() -> Self {
        Self { instances: Vec::new(), next_id: 1, active_id: None }
    }

    pub fn create_terminal(&mut self, title: &str, shell: BfvShellKind, cwd: &str) -> u64 {
        let id = self.next_id;
        self.next_id += 1;
        self.instances.push(BfvTerminalInstance {
            id, title: title.to_string(), shell_kind: shell,
            state: BfvTerminalState::Starting, cwd: cwd.to_string(),
            exit_code: None, pid: None, cols: 80, rows: 24, is_active: false,
        });
        if self.active_id.is_none() {
            self.set_active(id);
        }
        id
    }

    pub fn set_active(&mut self, id: u64) {
        for inst in &mut self.instances {
            inst.is_active = inst.id == id;
        }
        self.active_id = Some(id);
    }

    pub fn mark_running(&mut self, id: u64, pid: u32) {
        if let Some(inst) = self.instances.iter_mut().find(|i| i.id == id) {
            inst.state = BfvTerminalState::Running;
            inst.pid = Some(pid);
        }
    }

    pub fn mark_exited(&mut self, id: u64, code: i32) {
        if let Some(inst) = self.instances.iter_mut().find(|i| i.id == id) {
            inst.state = BfvTerminalState::Exited;
            inst.exit_code = Some(code);
        }
    }

    pub fn destroy(&mut self, id: u64) -> bool {
        if let Some(pos) = self.instances.iter().position(|i| i.id == id) {
            self.instances.remove(pos);
            if self.active_id == Some(id) {
                self.active_id = self.instances.first().map(|i| i.id);
            }
            true
        } else {
            false
        }
    }

    pub fn resize(&mut self, id: u64, cols: u16, rows: u16) {
        if let Some(inst) = self.instances.iter_mut().find(|i| i.id == id) {
            inst.cols = cols;
            inst.rows = rows;
        }
    }

    pub fn rename(&mut self, id: u64, title: &str) {
        if let Some(inst) = self.instances.iter_mut().find(|i| i.id == id) {
            inst.title = title.to_string();
        }
    }

    pub fn active(&self) -> Option<&BfvTerminalInstance> {
        self.active_id.and_then(|id| self.instances.iter().find(|i| i.id == id))
    }

    pub fn count(&self) -> usize {
        self.instances.len()
    }

    pub fn instances(&self) -> &[BfvTerminalInstance] {
        &self.instances
    }
}


// bfw_ Workspace Edit Model

/// Kind of workspace edit operation.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum BfwEditKind {
    TextEdit { file: String, offset: usize, length: usize, new_text: String },
    CreateFile { path: String, overwrite: bool },
    DeleteFile { path: String, recursive: bool },
    RenameFile { old_path: String, new_path: String, overwrite: bool },
}

/// A workspace edit containing multiple operations.
#[derive(Debug, Clone)]
pub struct BfwWorkspaceEdit {
    edits: Vec<BfwEditKind>,
    label: Option<String>,
    needs_confirmation: bool,
}

impl BfwWorkspaceEdit {
    pub fn new() -> Self {
        Self { edits: Vec::new(), label: None, needs_confirmation: false }
    }

    pub fn with_label(label: &str) -> Self {
        Self { edits: Vec::new(), label: Some(label.to_string()), needs_confirmation: false }
    }

    pub fn add_text_edit(&mut self, file: &str, offset: usize, length: usize, new_text: &str) {
        self.edits.push(BfwEditKind::TextEdit {
            file: file.to_string(), offset, length, new_text: new_text.to_string(),
        });
    }

    pub fn add_create_file(&mut self, path: &str, overwrite: bool) {
        self.edits.push(BfwEditKind::CreateFile { path: path.to_string(), overwrite });
    }

    pub fn add_delete_file(&mut self, path: &str, recursive: bool) {
        self.edits.push(BfwEditKind::DeleteFile { path: path.to_string(), recursive });
    }

    pub fn add_rename_file(&mut self, old: &str, new: &str, overwrite: bool) {
        self.edits.push(BfwEditKind::RenameFile {
            old_path: old.to_string(), new_path: new.to_string(), overwrite,
        });
    }

    pub fn set_needs_confirmation(&mut self, val: bool) {
        self.needs_confirmation = val;
    }

    pub fn edit_count(&self) -> usize {
        self.edits.len()
    }

    pub fn text_edit_count(&self) -> usize {
        self.edits.iter().filter(|e| matches!(e, BfwEditKind::TextEdit { .. })).count()
    }

    pub fn file_operation_count(&self) -> usize {
        self.edits.iter().filter(|e| !matches!(e, BfwEditKind::TextEdit { .. })).count()
    }

    pub fn affected_files(&self) -> Vec<String> {
        let mut files = Vec::new();
        for edit in &self.edits {
            match edit {
                BfwEditKind::TextEdit { file, .. } => { if !files.contains(file) { files.push(file.clone()); } }
                BfwEditKind::CreateFile { path, .. } => { if !files.contains(path) { files.push(path.clone()); } }
                BfwEditKind::DeleteFile { path, .. } => { if !files.contains(path) { files.push(path.clone()); } }
                BfwEditKind::RenameFile { old_path, new_path, .. } => {
                    if !files.contains(old_path) { files.push(old_path.clone()); }
                    if !files.contains(new_path) { files.push(new_path.clone()); }
                }
            }
        }
        files
    }

    pub fn edits(&self) -> &[BfwEditKind] {
        &self.edits
    }

    pub fn label(&self) -> Option<&str> {
        self.label.as_deref()
    }

    pub fn needs_confirmation(&self) -> bool {
        self.needs_confirmation
    }
}


// bfx_ Refactoring Preview Model

/// State of a refactoring preview.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BfxPreviewState {
    Pending,
    Computing,
    Ready,
    Applied,
    Cancelled,
}

/// A change in the refactoring preview.
#[derive(Debug, Clone)]
pub struct BfxPreviewChange {
    pub file: String,
    pub original_text: String,
    pub new_text: String,
    pub line: usize,
    pub is_checked: bool,
}

/// Refactoring preview model.
#[derive(Debug, Clone)]
pub struct BfxRefactoringPreview {
    pub title: String,
    pub state: BfxPreviewState,
    pub changes: Vec<BfxPreviewChange>,
    pub selected_index: Option<usize>,
}

impl BfxRefactoringPreview {
    pub fn new(title: &str) -> Self {
        Self {
            title: title.to_string(),
            state: BfxPreviewState::Pending,
            changes: Vec::new(),
            selected_index: None,
        }
    }

    pub fn set_computing(&mut self) {
        self.state = BfxPreviewState::Computing;
    }

    pub fn set_changes(&mut self, changes: Vec<BfxPreviewChange>) {
        self.changes = changes;
        self.state = BfxPreviewState::Ready;
    }

    pub fn toggle_change(&mut self, index: usize) {
        if let Some(c) = self.changes.get_mut(index) {
            c.is_checked = !c.is_checked;
        }
    }

    pub fn check_all(&mut self) {
        for c in &mut self.changes { c.is_checked = true; }
    }

    pub fn uncheck_all(&mut self) {
        for c in &mut self.changes { c.is_checked = false; }
    }

    pub fn checked_changes(&self) -> Vec<&BfxPreviewChange> {
        self.changes.iter().filter(|c| c.is_checked).collect()
    }

    pub fn apply(&mut self) {
        self.state = BfxPreviewState::Applied;
    }

    pub fn cancel(&mut self) {
        self.state = BfxPreviewState::Cancelled;
    }

    pub fn affected_file_count(&self) -> usize {
        let mut files: Vec<&str> = self.changes.iter().map(|c| c.file.as_str()).collect();
        files.sort();
        files.dedup();
        files.len()
    }

    pub fn total_changes(&self) -> usize {
        self.changes.len()
    }

    pub fn select(&mut self, index: usize) {
        if index < self.changes.len() {
            self.selected_index = Some(index);
        }
    }
}


// bfy_ Inline Values Model

/// Kind of inline value displayed in the editor.
