    pub fn add_item(&mut self, item: BjcLanguageStatusItem) {
        self.items.retain(|i| i.id != item.id);
        self.items.push(item);
    }
    pub fn remove_item(&mut self, id: &str) { self.items.retain(|i| i.id != id); }
