    fn test_bhu_revert() {
        let mut e = BhuCustomEditor::new("hex".into(), "f".into(), BhuContentKind::Text("".into()));
        e.apply_edit(BhuCustomEdit { id: 1, label: "a".into() });
        e.save();
        e.apply_edit(BhuCustomEdit { id: 2, label: "b".into() });
        e.revert();
        assert_eq!(e.edit_count(), 1);
        assert!(!e.is_dirty);
    }
