    fn test_bjd_reject_all() {
        let mut p = BjdWorkspaceEditPreview::new("R".into());
        p.add_change(BjdFileChange { uri: "a.rs".into(), old_text: "x".into(), new_text: "y".into(), is_accepted: None });
        p.reject_all();
        assert_eq!(p.accepted_changes().len(), 0);
    }
